insert into public.nodes (id,perspective,level,parent_id,title,t1,t2,t3,links,sources,dach,ord) values
('k1','k',1,NULL,'Türen','Türen gehören zu den am dichtesten geregelten und zugleich am stärksten wahrgenommenen Bauteilen: Sie werden täglich berührt, tragen Anforderungen von Schall über Brand bis Einbruch und prägen jeden Raumübergang. Dieses Themenfeld gliedert sich nach Einsatzort und Funktion.',NULL,NULL,ARRAY['e1','x3haustuer','kt1']::text[],'[]'::jsonb,NULL,1),
('k2i','k',2,'k1','Innentüren','Innentüren sind das Mengenbauteil des Innenausbaus. Ihre Qualität entscheidet sich an vier Stellen: Türblatt, Zarge, Beschlag und Öffnungsart. Wer hier Standards klug wählt, spart Kosten ohne sichtbaren Verlust; wer gestalten will, findet an jeder der vier Stellen Hebel.','Planungsrelevant ist vor allem das Zusammenspiel: Ein hochwertiges Türblatt in einer schlichten CPL-Zarge wirkt inkonsistent, ein flächenbündiges Konzept scheitert oft nicht am Budget, sondern an der zu spät bedachten Wandtoleranz. Empfehlung: Türliste früh anlegen und je Türtyp Blatt, Zarge, Beschlag und Anforderungen (Schall, Feuchtraum) gemeinsam festlegen.',NULL,'{}'::text[],'[{"t":"DIN 18101 Türen: Türblattgrößen, Bandsitz","u":"https://www.dinmedia.de/de/norm/din-18101/204907014","stand":"2014-08","geprueft":"2026-08-16"},{"t":"Baunetzwissen Fenster und Türen (weiterführend)","u":"https://www.baunetzwissen.de/fenster-und-tueren","geprueft":"2026-08-16"}]'::jsonb,NULL,2),
('k3blatt','k',3,'k2i','Türblatt','Das Türblatt bestimmt Haptik, Schallschutz und Optik der Tür. Die drei Entscheidungen: innerer Aufbau (Einlage), Oberfläche und Kantenausbildung.',NULL,NULL,'{}'::text[],'[]'::jsonb,NULL,3),
('k4aufbau','k',4,'k3blatt','Aufbau: Wabe, Röhrenspan, Vollspan','Die Einlage im Türblatt reicht von der leichten Wabe (hohl klingend, günstig) über Röhrenspan bis zur Vollspanplatte (schwer, schalldämmend, wertige Haptik). Man hört und fühlt den Unterschied bei jedem Schließen.','Faustregel für Wohnbau: Röhrenspan als Minimum, Vollspan wo Wertigkeit oder Schallschutz zählt. Wabe nur bei hartem Budget und untergeordneten Räumen. Der Aufpreis Röhrenspan zu Vollspan ist klein im Verhältnis zum spürbaren Unterschied; hier zu sparen ist die falsch verstandene Kostenstelle.',NULL,'{}'::text[],'[]'::jsonb,NULL,4),
('k4oberfl','k',4,'k3blatt','Oberflächen: CPL, HPL, Furnier, Lack','CPL ist der robuste Standard, HPL die härtere Variante für starke Beanspruchung, Furnier bringt echtes Holz, Lack die homogene, aber empfindlichste Fläche. Die Wahl ist eine Abwägung aus Beanspruchung, Budget und gestalterischem Anspruch.',NULL,NULL,'{}'::text[],'[]'::jsonb,NULL,5),
('k4falz','k',4,'k3blatt','Gefälzt oder stumpf einschlagend','Das gefälzte Türblatt überdeckt die Zarge (gutmütig, Standard), das stumpfe schließt flächig in ihr (präziser, toleranzempfindlicher). Diese kleine Entscheidung prägt die gesamte Anmutung der Tür.',NULL,NULL,ARRAY['e3unsichtbar']::text[],'[]'::jsonb,NULL,6),
('k3zarge','k',3,'k2i','Zarge','Die Zarge verbindet Türblatt und Wand und rahmt die Öffnung. Ihre Bauform (Umfassungs-, Block-, Eckzarge oder verdecktes System) entscheidet über Erscheinung, Montageablauf und Toleranzverhalten.','Die Zargenwahl ist früher zu treffen, als viele denken: Verdeckte Systeme brauchen Entscheidungen vor dem Trockenbau, Umfassungszargen verzeihen fast alles bis zum Schluss. Wer im Bestand arbeitet, prüft zuerst Wanddicken-Streuung; sie bestimmt, ob Standardmaulweiten funktionieren.',NULL,ARRAY['e2artik']::text[],'[]'::jsonb,NULL,7),
('k4umf','k',4,'k3zarge','Umfassungszarge','Die Umfassungszarge umgreift die Wand beidseitig und ist der Standard im Innenausbau: schnell montiert, toleranzverzeihend, in jedem System verfügbar. Ihre sichtbaren Teile sind Zargenspiegel und Falzbekleidung.','Stärke der Umfassungszarge ist die Trennung von Rohbau und Ausbau: Sie wird nach Wandfertigstellung eingeschäumt und überdeckt beidseitig die Anschlussfuge. Grenze: Bei sehr dicken oder stark streuenden Bestandswänden werden Sondermaulweiten nötig; ab da lohnt der Vergleich mit der Blockzarge.',NULL,'{}'::text[],'[]'::jsonb,NULL,8),
('k5spiegel','k',5,'k4umf','Zargenspiegel','Der Zargenspiegel ist der sichtbare, flächige Teil der Umfassungszarge, der die Wandöffnung rahmt. Er bestimmt maßgeblich, wie schwer oder leicht eine Tür im Raum wirkt. Standardbreiten liegen bei etwa 60 bis 70 mm.','Die Spiegelbreite ist eine der wenigen Stellschrauben, mit denen sich Standard-Innentüren gestalterisch differenzieren lassen, ohne das System zu verlassen. Schmale Spiegel (ab ca. 45 mm) wirken präziser, verzeihen aber weniger Wandtoleranz, weil weniger Überdeckung bleibt. Typischer Planungsfehler: Spiegel und Sockelleiste kollidieren in Höhe und Vorsprung; das Aufeinandertreffen beider Profile früh zeichnen.','Übliche Spiegelbreiten 60/70 mm, Sonderbreiten 45 bis 100 mm je nach System. Überdeckung des Wandanschlusses min. 15 mm bei üblichen Trockenbautoleranzen (Ebenheit nach DIN 18202 Tab. 3 prüfen). Ausschreibung: Spiegelbreite, Kantenprofil, Falzbekleidung und Maulweitenbereich getrennt angeben; Maulweite als Toleranzbereich (z. B. 100 +15 mm), nie als Festmaß. Ab hier: Systemunterlagen des Herstellers.',ARRAY['e4spiegelgest']::text[],'[{"t":"DIN 18202 Toleranzen im Hochbau","u":"https://www.dinmedia.de/de/norm/din-18202/307314612","stand":"2019-07","geprueft":"2026-08-16"},{"t":"DIN 18101 Türen: Maßordnung","u":"https://www.dinmedia.de/de/norm/din-18101/204907014","stand":"2014-08","geprueft":"2026-08-16"}]'::jsonb,NULL,9),
('k6breite','k',6,'k5spiegel','Spiegelbreite und Proportion','Je schmaler der Spiegel, desto grafischer und leiser die Tür; je breiter, desto gerahmter und traditioneller. Die Breite sollte im Verhältnis zu Sockelleiste, Türhöhe und Wandabwicklung entschieden werden, nicht isoliert.','Praxisregel: Spiegelbreite und Sockelleistenhöhe aufeinander abstimmen und an einer Musterachse im Maßstab 1:1 prüfen. Bei raumhohen Türen kippt die Wirkung: Der Spiegel wird zur vertikalen Linie und verträgt Schmalheit besser als bei Normhöhen.',NULL,'{}'::text[],'[]'::jsonb,NULL,10),
('k6kante','k',6,'k5spiegel','Kantenausbildung','Gerundet (Standard bei CPL, gutmütig), scharfkantig (präzise, stoßempfindlicher) oder mit Schattennut zur Wand: Die Kante ist ein kleines Detail mit großer Nahwirkung.',NULL,'Rundungen üblich R 2 bis 3 mm. Scharfkantige Ausführung meist nur bei Lack oder Furnier sinnvoll (Kantenstoß bei CPL sichtbar). Schattennut zur Wand als umlaufende Fuge ca. 5 x 5 mm; erfordert erhöhte Putz-/Spachtelqualität (Q3 aufwärts) am Anschluss. Ab hier: Systemunterlagen und Bemusterung.','{}'::text[],'[]'::jsonb,NULL,11),
('k6mat','k',6,'k5spiegel','Materialität und Oberfläche','Zargenspiegel in Blattoberfläche (ruhig, Standard), in Kontrastton (rahmend) oder in Wandfarbe (verschwindet fast): Drei Strategien mit klar unterschiedlicher Raumwirkung.',NULL,NULL,ARRAY['e2artik']::text[],'[]'::jsonb,NULL,12),
('k5maul','k',5,'k4umf','Falzbekleidung und Maulweite','Die Maulweite ist der Wanddickenbereich, den die Zarge aufnehmen kann. Sie ist das kritische Bestellmaß: Falsch gemessen, passt die ganze Zarge nicht.','Wanddicke inklusive aller Beläge messen, nicht die Rohbauwand: Fliesenspiegel, Putzstärken und beidseitige Beplankungsaufbauten wandern in die Maulweite. Im Trockenbau die tatsächliche, nicht die geplante Beplankung prüfen. Bestandsbauten: mehrere Messpunkte je Öffnung, Streuung dokumentieren.',NULL,'{}'::text[],'[]'::jsonb,NULL,13),
('k5wand','k',5,'k4umf','Wandanschluss und Montage','Montiert wird heute fast immer mit Montageschaum und Distanzklötzen. Die Qualität entscheidet sich an der Lage im Anschlag und an der Fuge zur Wand.',NULL,NULL,'{}'::text[],'[]'::jsonb,NULL,14),
('k6trocken','k',6,'k5wand','Anschluss an Trockenbau vs. Massivwand','Trockenbauwände brauchen ausgesteifte Türöffnungen (UA-Profile ab bestimmten Blattgewichten), Massivwände saubere Laibungen. Der Zargentyp bleibt oft gleich, die Vorleistung nicht.','Häufigste Mängelquelle: schwere Türblätter (Vollspan, Schallschutz, raumhoch) an Standard-CW-Ständern. Ab ca. 25 kg Blattgewicht UA-Verstärkung vorsehen und im Trockenbau-LV explizit ausschreiben; die Türenfirma setzt sie nicht, sie findet sie vor oder eben nicht.',NULL,'{}'::text[],'[{"t":"DIN 18183-1 Trennwände und Vorsatzschalen aus Gipsplatten","u":"https://www.dinmedia.de/de/norm/din-18183-1/287703861","stand":"2018-05","geprueft":"2026-08-16"}]'::jsonb,NULL,15);
insert into public.nodes (id,perspective,level,parent_id,title,t1,t2,t3,links,sources,dach,ord) values
('k7fuge','k',7,'k6trocken','Detail: Schattenfuge Zarge/Wand, Toleranzen','Die letzte Ebene: Wie genau trifft der Zargenspiegel auf die Wandfläche? Pressfuge, Acrylfuge oder bewusste Schattenfuge sind die drei Antworten.',NULL,'Pressfuge nur bei Q3/Q4-Flächen realistisch. Acrylfuge ist wartungsanfällig und bei Sichtqualität zu vermeiden. Schattenfuge (ca. 5 mm, ggf. mit Fugenprofil) macht Toleranzen zum Gestaltungsmittel, verlangt aber parallele Kanten: Ebenheits- und Winkeltoleranzen nach DIN 18202 reichen dafür nicht automatisch; erhöhte Anforderung gesondert vereinbaren. Ab hier: Detailzeichnung 1:1 und Bemusterung am Objekt.','{}'::text[],'[{"t":"DIN 18202 Toleranzen im Hochbau","u":"https://www.dinmedia.de/de/norm/din-18202/307314612","stand":"2019-07","geprueft":"2026-08-16"}]'::jsonb,NULL,16),
('k4block','k',4,'k3zarge','Blockzarge','Die Blockzarge sitzt als kompakter Block in der Laibung, ohne die Wand zu umgreifen. Klassisch im Altbau und überall dort, wo Wanddicken stark streuen oder die Laibung sichtbar bleiben soll.',NULL,NULL,'{}'::text[],'[]'::jsonb,NULL,17),
('k4eck','k',4,'k3zarge','Eckzarge','Die Eckzarge umgreift nur eine Wandecke, typisch im Objektbau (Stahlzargen) und bei gefliesten Wänden, wo eine zweite Bekleidungsseite entfallen kann.',NULL,NULL,'{}'::text[],'[]'::jsonb,NULL,18),
('k4verdeckt','k',4,'k3zarge','Verdeckte Zarge, flächenbündige Systeme','Systeme mit eingeputzter Aluminiumzarge lassen Tür und Wand in eine Ebene fallen; die Tür wird zur Fläche in der Fläche. Der Preis: frühe Festlegung, präzise Vorleistungen, höhere Kosten.','Verdeckte Systeme müssen vor dem Verspachteln geplant und geliefert sein und binden früh an einen Hersteller. Anspruchsvoll sind die Übergänge: Sockelleiste (läuft sie durch?), Wandflächenqualität (Q4 sinnvoll) und die Bänderwahl (verdeckt liegend, 3D-verstellbar). Wirtschaftlich fair rechnet man das Gesamtpaket, nicht den Zargenpreis.',NULL,ARRAY['e3unsichtbar']::text[],'[]'::jsonb,NULL,19),
('k3besch','k',3,'k2i','Beschläge','Bänder, Drücker, Schlösser und Schließer: Beschläge sind die Mechanik der Tür und ihr wichtigster Berührungspunkt. Hier treffen Ergonomie, Haltbarkeit und Gestaltung aufeinander.',NULL,NULL,ARRAY['e2hand']::text[],'[]'::jsonb,NULL,20),
('k4band','k',4,'k3besch','Bänder: aufliegend, verdeckt, 3D-verstellbar','Sichtbare Bänder sind robust und justierbar, verdeckt liegende Bänder machen die Tür grafisch ruhig, kosten aber mehr und begrenzen teils den Öffnungswinkel. 3D-Verstellbarkeit ist bei schweren Blättern Pflicht.',NULL,NULL,'{}'::text[],'[]'::jsonb,NULL,21),
('k4drueck','k',4,'k3besch','Drücker und Schlösser','Der Drücker wird tausendfach berührt: Form, Material und Rückstellfeder entscheiden über die gefühlte Qualität des ganzen Ausbaus. Schlösser reichen vom Buntbartschloss bis zum Objektstandard mit Wechselgarnitur.',NULL,NULL,ARRAY['e3druecker']::text[],'[]'::jsonb,NULL,22),
('k4schliess','k',4,'k3besch','Türschließer und Feststellanlagen','Obenliegend, integriert oder als Freilauftürschließer: Bei Funktionstüren oft Pflicht, gestalterisch fast immer ein Kompromiss, der früh mitgedacht werden sollte.',NULL,NULL,'{}'::text[],'[]'::jsonb,NULL,23),
('k3oeff','k',3,'k2i','Öffnungsarten','Anschlag-, Schiebe-, Falt-, Pendel- oder Drehtür: Die Öffnungsart ist zuerst eine Grundriss-Entscheidung (Aufschlagfläche!) und erst danach eine Frage der Technik.',NULL,NULL,'{}'::text[],'[]'::jsonb,NULL,24),
('k4anschlag','k',4,'k3oeff','Anschlagtür, DIN links/rechts','Der Normalfall. DIN-Richtung (links/rechts, definiert von der Bandseite aus gesehen) und Aufschlagrichtung gehören in jeden Grundriss; nachträgliche Änderungen ziehen Zarge, Blatt und Elektro nach sich.',NULL,NULL,'{}'::text[],'[{"t":"DIN 107 Bezeichnung links/rechts im Bauwesen","u":"https://www.dinmedia.de/de/norm/din-107/702361","stand":"1974-04","geprueft":"2026-08-16"}]'::jsonb,NULL,25),
('k4schiebe','k',4,'k3oeff','Schiebetür: vor der Wand, in der Wand','Vor der Wand laufend ist sie ein sichtbares Möbel, in der Wand (Kastensystem) verschwindet sie ganz. Letzteres will früh entschieden sein: Der Kasten ersetzt die Wand.','Ehrliche Beratung gehört dazu: Schiebetüren dichten schlechter (Schall, Geruch, Licht) und die Beschlagsqualität entscheidet über die Freude am Bauteil. In-der-Wand-Systeme kollidieren mit Elektro und Sanitär in derselben Wand; Installationszonen früh koordinieren.',NULL,'{}'::text[],'[]'::jsonb,NULL,26),
('k4sonst','k',4,'k3oeff','Falt-, Pendel-, Drehtür','Sonderöffnungsarten für Sondersituationen: Falttüren für flexible Raumteilung, Pendeltüren für hochfrequente Durchgänge, Drehtüren als raumbildende Geste.',NULL,NULL,'{}'::text[],'[]'::jsonb,NULL,27),
('k2a','k',2,'k1','Außen- und Haustüren','Die Haustür arbeitet härter als jede Innentür: Wärmeschutz, Schlagregen, Einbruchhemmung, Barrierefreiheit und Repräsentation in einem Bauteil. Entsprechend konfliktreich sind die Anforderungen untereinander.',NULL,NULL,ARRAY['x3haustuer','e2schwelle']::text[],'[]'::jsonb,NULL,28),
('k3waerme','k',3,'k2a','Aufbau und Wärmeschutz','Haustürblätter sind heute gedämmte Sandwichkonstruktionen; der energetische Schwachpunkt ist selten das Blatt, sondern Schwelle, Falz und Verglasungsränder.',NULL,NULL,'{}'::text[],'[]'::jsonb,'{"at":"Anforderungen über OIB-Richtlinie 6.","ch":"Anforderungen über MuKEn bzw. kantonale Energiegesetze.","de":"Anforderungswerte über das GEG."}'::jsonb,29),
('k3rc','k',3,'k2a','Einbruchschutz: RC-Klassen','RC 2 ist der übliche Wohnbaustandard. Entscheidend: Die Klasse gilt nur für das geprüfte Gesamtelement samt Montage, nicht für einzelne schöne Komponenten.',NULL,NULL,'{}'::text[],'[{"t":"DIN EN 1627 Einbruchhemmung: Widerstandsklassen","u":"https://www.dinmedia.de/de/norm/din-en-1627/332355073","stand":"2021-11","geprueft":"2026-08-16"}]'::jsonb,NULL,30);
insert into public.nodes (id,perspective,level,parent_id,title,t1,t2,t3,links,sources,dach,ord) values
('k3schwelle','k',3,'k2a','Schwelle und Barrierefreiheit','Hier kollidieren zwei berechtigte Welten: Die Abdichtung will Höhe, die Barrierefreiheit will null. Die Nullschwelle ist deshalb ein eigenes Planungsthema geworden.',NULL,NULL,ARRAY['e2schwelle']::text[],'[]'::jsonb,NULL,31),
('k4null','k',4,'k3schwelle','Nullschwelle: Abdichtung vs. Barrierefreiheit','Die Barrierefreiheits-Normen wollen maximal 2 cm Schwellenhöhe (und eigentlich gar keine), die Abdichtungsregeln wollen klassisch 15 cm Anschlusshöhe. Die Nullschwelle ist der planbare, aber aufwendige Kompromiss.','Funktionierende Nullschwellen sind ein System aus mehreren Verteidigungslinien: Entwässerungsrinne mit freiem Ablauf, Vordach oder Rücksprung als Schlagregenschutz, Gefälle vom Gebäude weg und ein geprüftes Schwellenprofil. Wer nur das Profil kauft und den Rest weglässt, plant den Wasserschaden mit.','Reduzierte Anschlusshöhen unter 15 cm gelten als Sonderkonstruktion und verlangen besondere Maßnahmen (Rinne, Überdachung, Gefälle ≥ 2 % vom Gebäude weg) sowie deren Dokumentation. Rinne mit Anschluss an die Entwässerung, nicht nur als Kiesstreifen. Ab hier: Fachregeln Abdichtung und Systemdetails des Schwellenherstellers.',ARRAY['kt3rampe']::text[],'[{"t":"DIN 18040-2 Barrierefreies Bauen: Wohnungen","u":"https://www.dinmedia.de/de/norm/din-18040-2/142706210","stand":"2011-09","geprueft":"2026-08-16"},{"t":"DIN 18531-1 Abdichtung von Dächern, Balkonen und Loggien","u":"https://www.dinmedia.de/de/norm/din-18531-1/391197155","stand":"2025-08","geprueft":"2026-08-16"},{"t":"DIN 18533-1 Abdichtung von erdberührten Bauteilen","u":"https://www.dinmedia.de/de/norm/din-18533-1/399850897","stand":"2026-06","geprueft":"2026-08-16"},{"t":"Fachregel für Abdichtungen (Flachdachrichtlinie), ZVDH (weiterführend)","u":"https://www.baunetzwissen.de/flachdach/fachwissen/richtlinien-verordnungen/fachregel-fuer-abdichtungen--flachdachrichtlinie-1323705","stand":"Ausgabe Januar 2026","geprueft":"2026-08-16"}]'::jsonb,'{"at":"ÖNORM B 1600 und OIB-Richtlinie 4; 2-cm-Grenze analog.","ch":"SIA 500 „Hindernisfreie Bauten\"; Praxis-Doku der Fachstelle Hindernisfreie Architektur.","de":"DIN 18040, bauordnungsrechtlich je Bundesland eingeführt."}'::jsonb,32),
('k2f','k',2,'k1','Funktionstüren','Brand, Rauch, Schall, Strahlenschutz: Funktionstüren sind geprüfte Systeme, keine konfigurierbaren Möbel. Die wichtigste Planungsregel lautet: erst Anforderung klären, dann gestalten, nie umgekehrt.',NULL,NULL,'{}'::text[],'[]'::jsonb,NULL,33),
('k3t30','k',3,'k2f','Brandschutztüren (T30/T60/T90)','Feuerschutzabschlüsse halten dem Feuer 30, 60 oder 90 Minuten stand und sind als Gesamtsystem zugelassen: Blatt, Zarge, Beschlag und Einbausituation gehören untrennbar zusammen.',NULL,NULL,ARRAY['kt3raum']::text[],'[]'::jsonb,NULL,34),
('k4t30z','k',4,'k3t30','Zulassung und Veränderungsverbot','An zugelassenen Feuerschutzabschlüssen darf nichts verändert werden: kein anderer Drücker, kein Kürzen, kein nachträglicher Anstrich außerhalb der Zulassung. Was verändert wird, verliert die Zulassung.',NULL,'Verwendbarkeitsnachweis (allgemeine bauaufsichtliche Zulassung bzw. europäisch CE mit Klassifizierung nach EN 13501-2, z. B. EI2 30) gehört in die Objektdokumentation. Kennzeichnungsschild am Element muss dauerhaft lesbar bleiben. Zulässiges Zubehör nur aus der Zulassung des Herstellers. Ab hier: Zulassungsbescheid des konkreten Elements lesen, immer.','{}'::text[],'[{"t":"DIN EN 13501-2 Klassifizierung Feuerwiderstand","u":"https://www.dinmedia.de/de/norm/din-en-13501-2/367755282","stand":"2023-12","geprueft":"2026-08-16"},{"t":"DIN 4102-5 (nationale Klassifizierung T30)","u":"https://www.dinmedia.de/de/norm/din-4102-5/684345","stand":"1977-09","geprueft":"2026-08-16"}]'::jsonb,'{"at":"EI2 30 nach OIB-Richtlinie 2; ÜA-Kennzeichnung.","ch":"EI30 nach VKF-Brandschutzvorschriften; VKF-Anerkennung statt DIBt-Zulassung.","de":"T30 nach DIN 4102 bzw. EI2 30 europäisch; abZ/aBG des DIBt."}'::jsonb,35),
('k3rs','k',3,'k2f','Rauchschutztüren (RS)','Rauchschutztüren begrenzen den Rauchdurchtritt (die eigentliche Todesursache bei Bränden) und brauchen dafür umlaufende Dichtungen, Bodendichtung und selbstschließende Beschläge.',NULL,NULL,'{}'::text[],'[{"t":"DIN 18095-1 Rauchschutztüren: Begriffe und Anforderungen","u":"https://www.dinmedia.de/de/norm/din-18095-1/1397160","stand":"1988-10","geprueft":"2026-08-16"},{"t":"DIN EN 1634-3 Prüfungen Rauchschutzabschlüsse","u":"https://www.dinmedia.de/de/norm/din-en-1634-3/75986740","stand":"2005-01","geprueft":"2026-08-16"}]'::jsonb,NULL,36),
('k3schall','k',3,'k2f','Schallschutztüren','Schallschutz entsteht aus Masse plus Dichtung: schweres Blatt, umlaufende Falzdichtungen, absenkbare Bodendichtung. Das Laborniveau erreicht die Baustelle nur bei perfekter Montage.',NULL,NULL,'{}'::text[],'[{"t":"DIN 4109-1 Schallschutz im Hochbau: Mindestanforderungen","u":"https://www.dinmedia.de/de/norm/din-4109-1/280079001","stand":"2018-01","geprueft":"2026-08-16"}]'::jsonb,'{"at":"ÖNORM B 8115.","ch":"SIA 181.","de":"DIN 4109, erhöhter Schallschutz über Beiblatt 2 / VDI 4100."}'::jsonb,37),
('k3kombi','k',3,'k2f','Kombinationsanforderungen','Der Klassiker im Objektbau: T30 + RS + Schallschutz + Barrierefreiheit an derselben Tür. Jede Einzelanforderung ist lösbar; die Kombination entscheidet, ob es das Element überhaupt gibt.','Vorgehen: Anforderungsmatrix je Tür aufstellen (Brand, Rauch, Schall, RC, Barrierefreiheit, Feuchtraum), dann gegen reale Herstellerprogramme prüfen, bevor die Tür im Grundriss fixiert wird. Die teuersten Türen im Projekt sind fast immer Kombinationselemente, die zu spät als solche erkannt wurden. Absenkdichtung vs. Rauchschutz vs. Nullschwelle ist der häufigste Zielkonflikt.','Praxisfalle Barrierefreiheit: DIN 18040 begrenzt Bedienkräfte (Klasse 3 nach EN 12217 empfohlen); Türschließer an T30-RS-Elementen überschreiten das schnell. Lösung meist Freilauftürschließer mit Feststellanlage (dann Rauchmelderpflicht am Sturz). Ab hier: Herstellerberatung mit vollständiger Anforderungsmatrix.','{}'::text[],'[{"t":"DIN 18040-1 Barrierefreies Bauen: öffentlich zugängliche Gebäude","u":"https://www.dinmedia.de/de/norm/din-18040-1/133692028","stand":"2010-10","geprueft":"2026-08-16"},{"t":"DIN 18040-2 Barrierefreies Bauen: Wohnungen","u":"https://www.dinmedia.de/de/norm/din-18040-2/142706210","stand":"2011-09","geprueft":"2026-08-16"},{"t":"DIN EN 12217 Türen: Bedienungskräfte","u":"https://www.dinmedia.de/de/norm/din-en-12217/233402452","stand":"2015-07","geprueft":"2026-08-16"}]'::jsonb,NULL,38),
('k2b','k',2,'k1','Türen im Bestand','Bestandstüren sind Zeitzeugen und Problembauteile zugleich: oft schöner als jeder Neubaustandard, aber ohne Schall-, Brand- oder Einbruchwerte. Die Frage ist fast nie ob, sondern wie viel Ertüchtigung.',NULL,NULL,ARRAY['x1']::text[],'[]'::jsonb,NULL,39),
('k3hist','k',3,'k2b','Aufarbeitung historischer Türen','Aufarbeiten heißt: Substanz sichern, Funktion wiederherstellen, Patina bewahren. Häufig günstiger als gedacht und fast immer nachhaltiger als der Austausch.',NULL,NULL,'{}'::text[],'[]'::jsonb,NULL,40),
('k3ertuecht','k',3,'k2b','Ertüchtigung im Denkmal','Schall- und Brandertüchtigung historischer Türen bewegt sich zwischen Auflagen und Substanzschutz: aufgedoppelte Blätter, eingefräste Dichtungen, Kastentür-Prinzip als zweite Ebene.',NULL,NULL,ARRAY['x4lernen']::text[],'[]'::jsonb,NULL,41),
('e1','e',1,NULL,'Die Tür als Entwurfselement','Bevor die Tür ein Bauteil ist, ist sie eine räumliche Behauptung: Sie entscheidet, wie Übergänge erlebt werden, wie Räume sich zueinander verhalten und wo ein Gebäude seine Bewohner berührt. Diese Perspektive versammelt das gestalterische Wissen zur Tür.',NULL,NULL,ARRAY['k1','x3haustuer']::text[],'[]'::jsonb,NULL,42),
('e2schwelle','e',2,'e1','Schwelle und Übergang','Die Tür markiert den Wechsel zwischen Sphären: außen und innen, öffentlich und privat, laut und still. Wie dieser Wechsel gestaltet ist (abrupt, gestuft, gedehnt), gehört zu den ältesten Themen der Architektur.',NULL,NULL,ARRAY['k3schwelle','x3tor']::text[],'[]'::jsonb,NULL,43),
('e3zaesur','e',3,'e2schwelle','Die Tür als räumliche Zäsur','Türen trennen nicht nur Räume, sie inszenieren den Übergang. Ob ein Wechsel abrupt oder gestuft erfolgt (Tür in der Wandflucht oder in einer Nische), verändert, wie privat sich der Raum dahinter anfühlt.','Entwurflich lässt sich die Zäsur über vier Register steuern: Position (Wandflucht vs. Laibungstiefe), Format (Normhöhe vs. raumhoch), Artikulation (gerahmt vs. flächenbündig) und Material- oder Lichtwechsel am Übergang. Eine tiefe Laibung verlangsamt den Übergang; eine flächenbündige Tür lässt ihn beiläufig werden. Die Entscheidung sollte aus der Raumsequenz begründet sein, nicht aus dem Katalog. Referenzen: Loos’ Raumplan, Zumthors gestufte Schwellen, die Torsituationen der Margarethenhöhe im Siedlungsmaßstab.',NULL,'{}'::text[],'[]'::jsonb,NULL,44),
('e3schwellenr','e',3,'e2schwelle','Schwellenräume: Windfang, Vorraum, Nische','Zwischen draußen und drinnen kann ein eigener Raum liegen: Der Windfang ist Klimapuffer und Zeremonie zugleich. Wo er wegrationalisiert wird, verliert das Ankommen seine Zeit.',NULL,NULL,'{}'::text[],'[]'::jsonb,NULL,45);
insert into public.nodes (id,perspective,level,parent_id,title,t1,t2,t3,links,sources,dach,ord) values
('e2prop','e',2,'e1','Proportion und Format','Ob eine Tür 198,5 cm oder raumhoch ist, entscheidet über die Wand, in der sie steht: Die Normtür bleibt Loch in der Fläche, die raumhohe Tür macht die Wand zur Abfolge von Ebenen.',NULL,NULL,'{}'::text[],'[]'::jsonb,NULL,46),
('e3raumhoch','e',3,'e2prop','Raumhohe Türen und der aufgelöste Sturz','Ohne Sturz verliert die Tür ihr Über-Kopf-Gewicht und der Raum fließt durch die Öffnung weiter. Konstruktiv heißt das: schwerere Blätter, stärkere Bänder, präzisere Toleranzen.','Der Effekt trägt nur, wenn er konsequent ist: Raumhohe Türen verlangen raumhohe Disziplin auch bei Schränken, Verglasungen und Durchgängen derselben Raumfolge. Einzeln eingesetzt wirken sie schnell wie ein Ausstattungsmerkmal. Kostenseitig sind Blattgewicht und Bänderqualität die Treiber, nicht die Blattlänge.',NULL,ARRAY['k6trocken']::text[],'[]'::jsonb,NULL,47),
('e3breite','e',3,'e2prop','Türbreiten zwischen Norm und Geste','88,5 cm Durchgang sind Funktion; 1,20 m sind eine Einladung, zweiflügelig ist ein Ereignis. Breite ist das einfachste Mittel, Hierarchien in einer Raumfolge zu markieren.',NULL,NULL,'{}'::text[],'[]'::jsonb,NULL,48),
('e2artik','e',2,'e1','Artikulation vs. Verschwinden','Die Grundsatzentscheidung der Türgestaltung: Wird die Tür betont (Portal, Rahmung, Gewände) oder zum Verschwinden gebracht (flächenbündig, wandfarbig, schattenfugengeführt)? Beides sind starke Haltungen; nur das Ungefähre dazwischen ist schwach.',NULL,NULL,ARRAY['k3zarge']::text[],'[]'::jsonb,NULL,49),
('e3portal','e',3,'e2artik','Die betonte Tür: Portal, Rahmung, Gewände','Die gerahmte Tür adelt den Durchgang: vom Werksteingewände bis zum farbig abgesetzten Zargenspiegel. Rahmung sagt: Hier passiert etwas Wichtiges.',NULL,NULL,ARRAY['x4bogen']::text[],'[]'::jsonb,NULL,50),
('e4spiegelgest','e',4,'e3portal','Der Zargenspiegel als gestalterisches Mittel','Das kleinste Portal der Welt: Schon mit Breite, Farbe und Kantenprofil des Zargenspiegels lässt sich eine Standardtür betonen oder beruhigen, ohne das Budget zu sprengen.','Drei Strategien: (1) Spiegel in Wandfarbe streichen lassen und die Tür zurücknehmen. (2) Spiegel kontrastieren (dunkler Ton auf heller Wand) und die Öffnung als Rahmen zeigen. (3) Spiegel überbreit als moderne Interpretation des Gewändes einsetzen. Alle drei kosten fast nichts; sie erfordern nur eine frühe Festlegung im Türtypenblatt.',NULL,ARRAY['k5spiegel']::text[],'[]'::jsonb,NULL,51),
('e3unsichtbar','e',3,'e2artik','Die unsichtbare Tür','Flächenbündig, tapezierbar, wandfarbig, ohne sichtbare Bänder: Die Tür als Geheimnis der Wand. Sie funktioniert nur mit hoher Präzision; jede sichtbare Toleranz zerstört die Illusion.',NULL,NULL,ARRAY['k4verdeckt','k4falz']::text[],'[]'::jsonb,NULL,52),
('e2hand','e',2,'e1','Die Tür als Berührungspunkt','Die Tür ist der Ort, an dem Architektur physisch berührt wird, jeden Tag, von jeder Hand. Kein anderes Bauteil rechtfertigt Materialqualität so unmittelbar.',NULL,NULL,ARRAY['k3besch','kt3hand']::text[],'[]'::jsonb,NULL,53),
('e3druecker','e',3,'e2hand','Der Drücker als Handschlag des Gebäudes','Ein Türdrücker ist das Bauteil mit dem intensivsten Körperkontakt im ganzen Haus. Gewicht, Temperatur des Materials und die Rückstellung beim Loslassen bilden zusammen den Charakter dieses Handschlags.','Materiallogik: Messing und Bronze altern mit der Benutzung und erzählen sie weiter; Edelstahl bleibt neutral und dienstbar; beschichtete Leichtmetalle fühlen sich nach wenig an, egal wie sie aussehen. Prominente Fälle (Wittgensteins Türklinke, die Drücker von Chareau) zeigen, wie viel Entwurfsernst in dieses kleinste Element passt.',NULL,ARRAY['k4drueck']::text[],'[]'::jsonb,NULL,54),
('e2folge','e',2,'e1','Türen in der Raumfolge','Türen sind die Gelenke einer Raumsequenz: Ihre Lage entscheidet, ob Räume gereiht, verschachtelt oder verschliffen wirken.',NULL,NULL,'{}'::text[],'[]'::jsonb,NULL,55),
('e3enfilade','e',3,'e2folge','Enfilade und Sichtachse','Liegen Türen mehrerer Räume auf einer Achse, entsteht die Enfilade: Tiefe, Durchblick, Versprechen. Ein barockes Prinzip, das auch im Wohnungsbau funktioniert, wenn man es sich traut.',NULL,NULL,ARRAY['et2prom']::text[],'[]'::jsonb,NULL,56),
('e3position','e',3,'e2folge','Türposition im Raum: Ecke oder Mitte','Die Tür in der Raumecke erschließt effizient und lässt Stellflächen frei; die Tür in der Wandmitte teilt den Raum, macht ihn aber zeremonieller. Eine der stillsten, folgenreichsten Grundrissentscheidungen.',NULL,NULL,'{}'::text[],'[]'::jsonb,NULL,57),
('x1','x',1,NULL,'Margarethenhöhe, Essen','Georg Metzendorfs Gartenstadt (ab 1909, gestiftet von Margarethe Krupp) gilt als eine der schönsten Siedlungen Deutschlands: serielle Typen, handwerkliche Details und ein Städtebau, der Gemeinschaft räumlich formuliert. Hier als Fallstudie erschlossen: vom Siedlungsmaßstab bis zum Türgriff.',NULL,NULL,ARRAY['e1','k1']::text[],'[{"t":"Ruhr Museum: Die Gartenstadt Margarethenhöhe (weiterführend)","u":"https://ruhrmuseum.de/ausstellungen/aktuell/die-gartenstadt-margarethenhoehe","geprueft":"2026-08-16"},{"t":"Rainer Metzendorf: Georg Metzendorf 1874–1934. Siedlungen und Bauten (Literatur)","stand":"Darmstadt/Marburg 1994, ISBN 3-88443-185-4","geprueft":"2026-08-16"}]'::jsonb,NULL,58),
('x2staedt','x',2,'x1','Städtebau der Gartenstadt','Gekrümmte Straßen, gestaffelte Plätze, ein bewusster Bruch mit dem Mietskasernenraster: Die Margarethenhöhe übersetzt die englische Gartenstadtidee in eine rheinisch-westfälische Handschrift.',NULL,NULL,'{}'::text[],'[]'::jsonb,NULL,59),
('x3tor','x',3,'x2staedt','Torhaus und Brückenzugang','Man betritt die Margarethenhöhe über eine Brücke und durch ein Torhaus: Die ganze Siedlung hat eine Tür. Der Schwellenmoment, den ein Hauseingang im Kleinen leistet, wird hier im Maßstab des Quartiers durchgespielt.',NULL,NULL,ARRAY['e2schwelle','e3zaesur']::text[],'[]'::jsonb,NULL,60);
insert into public.nodes (id,perspective,level,parent_id,title,t1,t2,t3,links,sources,dach,ord) values
('x3platz','x',3,'x2staedt','Platzfolgen und Straßenräume','Der kleine Markt als Herzstück, Straßen, die sich weiten und verengen: Raumfolge als städtebauliches Erzählen, lange bevor der Begriff Sequenzierung erfunden war.',NULL,NULL,ARRAY['et2prom']::text[],'[]'::jsonb,NULL,61),
('x2typ','x',2,'x1','Gebäudetypen','Wenige Haustypen, viele Varianten: Metzendorf zeigt, wie Serie und Individualität zusammengehen, eine Frage, die der heutige Wohnungsbau dringlicher stellt als je.',NULL,NULL,'{}'::text[],'[]'::jsonb,NULL,62),
('x3reihe','x',3,'x2typ','Reihenhaustypen und ihre Variation','Gleiche Grundrisse, variierte Giebel, Erker, Dachformen und Eingänge: Die Variation sitzt an den Rändern des Typs, nicht in seinem Kern. Ein ökonomisches Prinzip mit großer Wirkung.',NULL,NULL,'{}'::text[],'[]'::jsonb,NULL,63),
('x2fass','x',2,'x1','Fassadenelemente','Putzflächen, Klinkersockel, Fensterläden, Haustüren: Die Fassaden der Margarethenhöhe arbeiten mit einem kleinen, präzise eingesetzten Vokabular. Das wichtigste Wort darin ist der Hauseingang.',NULL,NULL,'{}'::text[],'[]'::jsonb,NULL,64),
('x3haustuer','x',3,'x2fass','Haustüren der Margarethenhöhe','Die Haustür ist das Schmuckstück der ansonsten sparsamen Fassaden: gerahmt, farbig, handwerklich detailliert. Sie trägt die Identität des einzelnen Hauses innerhalb der Serie.',NULL,NULL,ARRAY['k2a','e3portal']::text[],'[]'::jsonb,NULL,65),
('x4bogen','x',4,'x3haustuer','Rundbogenportale und Türgewände','Metzendorf setzte Haustüren fast nie nackt in die Wand: Rundbogen und Werksteingewände machen den Eingang zum wichtigsten Ereignis der Fassade.','Das Prinzip ist übertragbar: serielle Typen plus individualisierte Schwelle gleich Identifikation ohne Beliebigkeit. Die Portale variieren in wenigen kontrollierten Parametern (Bogenform, Gewändematerial, Türfarbe), während Typengrundriss und Fassadenaufbau konstant bleiben. Für heutige Reihenhaus- und Geschossprojekte ein präzises Rezept gegen die Monotonie-Kritik.',NULL,ARRAY['e3portal']::text[],'[]'::jsonb,NULL,66),
('x4farbe','x',4,'x3haustuer','Farbigkeit und Handwerksdetail','Türblätter in kräftigen Farben, Beschläge als Handwerksstücke: Die Margarethenhöhe zeigt, dass Farbe an der Tür kein Risiko ist, sondern ein System, wenn die Palette siedlungsweit kuratiert wird.',NULL,NULL,'{}'::text[],'[]'::jsonb,NULL,67),
('x4lernen','x',4,'x3haustuer','Was heutige Planung daraus lernt','Drei Lehren: Eingänge sind der richtige Ort für Individualität in der Serie. Wenige Parameter, konsequent variiert, schlagen viele Parameter beliebig gemischt. Und: Handwerkliches Detail am Berührungspunkt zahlt sich über Jahrzehnte aus.','Die Rückübersetzung in heutige Praxis führt direkt zu den Konstruktionsfragen: Wie verträgt sich ein gerahmtes Portal mit RC-2-Anforderung und Nullschwelle? Wie ersetzt man Werkstein durch heutige Budgets (Betonfertigteil, Klinkerrahmung, farbige Laibung)? Die Fallstudie endet dort, wo die Bauteilebene beginnt.',NULL,ARRAY['k2a','k4null','e2artik']::text[],'[]'::jsonb,NULL,68),
('kt1','k',1,NULL,'Treppen','Die Treppe ist das einzige Bauteil, das der Körper vollständig durchmisst: Jede Abweichung im Steigungsverhältnis spürt man im Schritt. Zugleich ist sie Rettungsweg, Tragwerk und oft die teuerste Einzelposition des Rohbaus. Das Themenfeld gliedert sich in Geometrie, Konstruktion, Absturzsicherung und Baurecht.',NULL,NULL,ARRAY['et1','k1']::text[],'[]'::jsonb,NULL,69),
('kt2geo','k',2,'kt1','Laufgeometrie und Podeste','Bevor eine Treppe Material hat, hat sie Geometrie: Steigungsverhältnis, Lauflinie, Podeste, Kopfhöhen. Diese Maße entscheiden über Bequemlichkeit und Genehmigungsfähigkeit, und sie sind später fast nicht mehr korrigierbar.','Der häufigste Planungsfehler ist nicht die falsche Formel, sondern die zu knapp geschnittene Rohbauöffnung: Wer die Treppe erst in der Ausführungsplanung ernst nimmt, verbaut sich Steigungsverhältnis und Kopfhöhe gleichzeitig. Treppenloch und Geschosshöhe gehören in LP 2 zusammen entworfen.',NULL,'{}'::text[],'[]'::jsonb,NULL,70),
('kt3steig','k',3,'kt2geo','Steigungsverhältnis und Schrittmaß','Das Verhältnis von Steigung zu Auftritt bestimmt, ob eine Treppe bequem, sportlich oder gefährlich ist. Die klassische Schrittmaßregel: zwei Steigungen plus ein Auftritt sollen etwa einer Schrittlänge entsprechen. Eine Wohnhaustreppe mit 18/27 geht mühelos, eine mit 20/23 spürt man in den Knien.','Bequemlichkeit entsteht nicht nur aus der Formel: Konstante Steigungen über alle Läufe (auch am Übergang zum Belag!), ausreichende Auftrittstiefe in der Lauflinie bei gewendelten Treppen und ein Antritt ohne Sonderformat zählen mehr als die dritte Nachkommastelle. Der klassische Baufehler ist die abweichende erste oder letzte Steigung, weil der Bodenaufbau zweier Geschosse verschieden ausfiel; das ist auch ein Unfallrisiko.','Schrittmaßregel 2s + a = 59 bis 65 cm. Wohngebäude (notwendige Treppe): Steigung max. ca. 19 cm, Auftritt min. ca. 26 cm; bequemer Wohnstandard 17/29. Öffentliche Gebäude strenger, Auftritt eher ≥ 29 cm. Steigungen innerhalb eines Laufs müssen gleich sein; Toleranz wenige Millimeter. Werte sind länderabhängig (siehe DACH-Kasten). Ab hier: DIN 18065 in aktueller Ausgabe plus Landesbauordnung des Projekts.',ARRAY['et2prom']::text[],'[{"t":"DIN 18065 Gebäudetreppen","u":"https://www.dinmedia.de/de/norm/din-18065/322316050","stand":"2020-08","geprueft":"2026-08-16"},{"t":"Landesbauordnung (DE), exemplarisch BauO NRW 2018","u":"https://recht.nrw.de/lmi/owa/br_bes_text?anw_nr=2&bes_id=39224&aufgehoben=N&keyword=landesbauordnung","stand":"Fassung 2018, zuletzt geändert Juli 2026","geprueft":"2026-08-16"},{"t":"Baunetzwissen Treppen (weiterführend)","u":"https://www.baunetzwissen.de/treppen","geprueft":"2026-08-16"}]'::jsonb,'{"at":"ÖNORM B 5371 und OIB-Richtlinie 4; Hauptreppen 18/27 als Leitwert.","ch":"Keine zwingende Norm-Treppe; SIA 500 für Hindernisfreiheit, bfu-Fachdokumentation als anerkannte Regel; 17/29 üblich.","de":"DIN 18065 plus Landesbauordnung; Maße unterscheiden sich je Bundesland und Gebäudeklasse."}'::jsonb,71),
('kt3form','k',3,'kt2geo','Grundformen: gerade, gewendelt, gewunden','Gerade Läufe sind bequem und möblierbar, gewendelte Treppen sparen Fläche und erkaufen das mit verzogenen Stufen, Spindeltreppen sind das Minimum an Fläche und Komfort. Die Form ist zuerst eine Grundriss-, dann eine Kostenentscheidung.','Beim Verziehen gewendelter Treppen entscheidet die Auftrittsbreite an der schmalen Seite über die reale Begehbarkeit; großzügig verzogene Viertelwendelungen gehen fast wie gerade Läufe. Für Umzüge und Möbeltransport ist die halbgewendelte Treppe ohne Zwischenpodest der heimliche Ärgernis-Klassiker; ein Podest kostet Fläche und rettet Rücken.',NULL,ARRAY['et2skulptur']::text[],'[]'::jsonb,NULL,72),
('kt3podest','k',3,'kt2geo','Podeste, Antritt, Austritt','Podeste sind die Pausen der Treppe: baurechtlich gefordert ab bestimmten Stufenzahlen, entwurflich die Orte, an denen eine Treppe Blickwechsel und Begegnung organisiert.',NULL,'Zwischenpodest üblicherweise nach max. 18 Steigungen (länderabhängig). Podesttiefe mindestens Laufbreite, besser Laufbreite plus ein Auftritt. Türen dürfen nicht in den Lauf aufschlagen; vor Türen am Podest Mindesttiefen freihalten. Ab hier: DIN 18065 und Landesbauordnung.',ARRAY['et2ort']::text[],'[{"t":"DIN 18065 Gebäudetreppen","u":"https://www.dinmedia.de/de/norm/din-18065/322316050","stand":"2020-08","geprueft":"2026-08-16"}]'::jsonb,NULL,73),
('kt3kopf','k',3,'kt2geo','Kopfhöhe und Durchgangshöhe','Zwei Meter lichte Höhe über der Vorderkante jeder Stufe sind das übliche Minimum. Der kritische Punkt liegt fast immer an der Deckenkante des Treppenlochs, und er entscheidet über die Länge der Öffnung.',NULL,'Lichte Durchgangshöhe min. 2,00 m, lotrecht über den Stufenvorderkanten gemessen. Bei Dachgeschossen zusätzlich die Schrägen prüfen; die Kopfhöhe entlang der gesamten Lauflinie, nicht nur am Austritt. Ab hier: DIN 18065 und Maßkontrolle am Rohbau.','{}'::text[],'[{"t":"DIN 18065 Gebäudetreppen","u":"https://www.dinmedia.de/de/norm/din-18065/322316050","stand":"2020-08","geprueft":"2026-08-16"}]'::jsonb,NULL,74),
('kt2konst','k',2,'kt1','Konstruktionen nach Material','Beton trägt und dämpft, Holz erzählt vom Handwerk, Stahl macht Treppen leicht und filigran. Die Materialwahl legt Kosten, Schallschutz, Bauablauf und Ausstrahlung gleichzeitig fest.',NULL,NULL,'{}'::text[],'[]'::jsonb,NULL,75);
insert into public.nodes (id,perspective,level,parent_id,title,t1,t2,t3,links,sources,dach,ord) values
('kt3beton','k',3,'kt2konst','Stahlbetontreppen','Die Ortbeton- oder Fertigteiltreppe ist der Standard im Geschossbau: robust, massearm im Schwingen, früh im Bauablauf begehbar. Ihre kritische Stelle ist nicht die Statik, sondern der Trittschall.','Fertigteilläufe dominieren, weil sie Maßhaltigkeit und Tempo bringen und die Untersicht schalungsglatt liefern. Planungsentscheidend ist früh: sichtbar belassen (dann Fertigteilqualität und Fasen definieren) oder belegt. Der Rohbau muss die Auflagerdetails der Schallentkopplung kennen, bevor die Decke geschalt wird.',NULL,ARRAY['et2skulptur']::text[],'[]'::jsonb,NULL,76),
('kt4schall','k',4,'kt3beton','Trittschallentkopplung','Eine starr angeschlossene Treppe telefoniert jeden Schritt ins Nachbargeschoss. Entkoppelt wird an Auflagern und Podestanschlüssen mit Elastomerlagern, nicht nachträglich mit Belag.',NULL,'Tragende Anschlüsse über geprüfte Trittschalldämmelemente (Elastomer- bzw. bewehrte Lager) an Lauf- und Podestauflagern; Fugen zu Wänden konsequent freihalten, kein Mörtel- oder Estrichkontakt (klassische Schallbrücke). Nachweis im Schallschutzkonzept führen. Ab hier: Systemzulassung des gewählten Lagers und Detailblätter.','{}'::text[],'[{"t":"DIN 4109-1 Schallschutz im Hochbau: Mindestanforderungen","u":"https://www.dinmedia.de/de/norm/din-4109-1/280079001","stand":"2018-01","geprueft":"2026-08-16"}]'::jsonb,'{"at":"ÖNORM B 8115.","ch":"SIA 181, Anforderungen „erhöht\" im Mehrfamilienhaus üblich.","de":"DIN 4109; erhöhter Schallschutz vertraglich klären."}'::jsonb,77),
('kt3holz','k',3,'kt2konst','Holztreppen','Eingestemmt, aufgesattelt oder mit Wangen aus Werkstoffplatten: Die Holztreppe ist die Treppe des Einfamilien- und Bestandsbaus. Sie knarrt nur, wenn sie schlecht gefügt ist.','Die relevanten Entscheidungen: Hartholz für Trittstufen (Buche, Eiche) gegen Weichholz-Charme; geschlossene oder offene Setzstufen (offen wirkt leichter, sammelt aber Anforderungen an die Öffnungsmaße der Absturzsicherung); Verbindung zur Wand (sichtbare Wange oder aufgesattelt frei). Im Bestand ist die knarrende Treppe meist ein Fall für Nachspannen und Verleimen, nicht für Austausch.',NULL,'{}'::text[],'[]'::jsonb,NULL,78),
('kt3stahl','k',3,'kt2konst','Stahl- und Spindeltreppen','Gefaltetes Blech, Wangen aus Flachstahl oder die Spindel um ein Rohr: Stahl kann Treppen, die kaum da sind. Der Preis sind Schwingung, Dröhnen und Brandschutzfragen im Innenraum.','Gegen das Dröhnen helfen ausbetonierte oder mit Holz belegte Stufen und ausreichende Blechstärken; gegen Schwingung ein ehrlicher statischer Nachweis statt Gefühl. Sichtbare Schweißnähte und Kanten definieren die Qualität, deshalb Werkstattfertigung und Musterstück vereinbaren.',NULL,'{}'::text[],'[]'::jsonb,NULL,79),
('kt3fertig','k',3,'kt2konst','System- und Raumspartreppen','Vom Katalogbausatz bis zur Samba-Treppe: Systemtreppen lösen Budget- und Platzprobleme und sind fast nie die schönste Antwort. Raumspartreppen sind baurechtlich nur als Zusatztreppe zulässig, nicht als notwendige.',NULL,NULL,'{}'::text[],'[]'::jsonb,NULL,80),
('kt2gel','k',2,'kt1','Geländer und Handläufe','Das Geländer ist Absturzsicherung mit Rechtsfolgen, der Handlauf ist Ergonomie mit Gestaltungsanspruch. Beide werden regelmäßig verwechselt und beide zu spät geplant.',NULL,NULL,'{}'::text[],'[]'::jsonb,NULL,81),
('kt3gelh','k',3,'kt2gel','Geländerhöhen und Öffnungsmaße','Die Höhe der Absturzsicherung und die maximale Öffnungsweite (Stichwort Kinderkopf) sind harte baurechtliche Werte, die sich zwischen den Ländern unterscheiden. Gestalterische Freiheit beginnt erst innerhalb dieser Maße.',NULL,'Übliche Werte: Geländerhöhe 90 cm bis 12 m Absturzhöhe, darüber 110 cm (DE, je Landesbauordnung); Öffnungen so, dass eine Kugel von 12 cm nicht durchpasst, im Wohnungsbau teils entschärft. Horizontale, bekletterbare Füllungen sind in Kindernutzung zu vermeiden. Werte länderabhängig (siehe DACH-Kasten). Ab hier: Landesbauordnung bzw. nationale Regel des Projektstandorts.','{}'::text[],'[{"t":"Landesbauordnungen (DE), exemplarisch BauO NRW 2018","u":"https://recht.nrw.de/lmi/owa/br_bes_text?anw_nr=2&bes_id=39224&aufgehoben=N&keyword=landesbauordnung","stand":"Fassung 2018, zuletzt geändert Juli 2026","geprueft":"2026-08-16"},{"t":"DIN 18065 Gebäudetreppen","u":"https://www.dinmedia.de/de/norm/din-18065/322316050","stand":"2020-08","geprueft":"2026-08-16"}]'::jsonb,'{"at":"OIB-Richtlinie 4: 100 cm ab 60 cm Absturzhöhe, 110 cm über 12 m.","ch":"SIA 358 „Geländer und Brüstungen\": 100 cm Leitwert, Öffnungsregeln eigenständig.","de":"LBO-abhängig; 90/110-cm-Systematik verbreitet."}'::jsonb,82),
('kt3hand','k',3,'kt2gel','Handlauf: Ergonomie und Pflicht','Der Handlauf ist der Türdrücker der Treppe: das Bauteil, das jede Hand kennt. Greifbarkeit schlägt Grafik; ein schöner Flachstahl, den keine Hand umschließen kann, ist ein Formfehler.','Ergonomisch bewährt: runde oder oval-runde Profile etwa 3 bis 4,5 cm stark, Höhe um 85 bis 90 cm, durchlaufend auch an Podesten und am An- und Austritt waagerecht weitergeführt (etwa 30 cm), Abstand zur Wand ausreichend für die geschlossene Hand. Barrierefreie Gebäude verlangen beidseitige Handläufe und teils taktile Informationen. Material am Griff ehrlich wählen: Holz und Metall altern verschieden schön.',NULL,ARRAY['e2hand']::text[],'[{"t":"DIN 18040-1 Barrierefreies Bauen: öffentlich zugängliche Gebäude","u":"https://www.dinmedia.de/de/norm/din-18040-1/133692028","stand":"2010-10","geprueft":"2026-08-16"},{"t":"DIN 18040-2 Barrierefreies Bauen: Wohnungen","u":"https://www.dinmedia.de/de/norm/din-18040-2/142706210","stand":"2011-09","geprueft":"2026-08-16"}]'::jsonb,'{"at":"ÖNORM B 1600.","ch":"SIA 500.","de":"DIN 18040-1/-2 je Nutzung."}'::jsonb,83),
('kt3fuell','k',3,'kt2gel','Füllungen: Stab, Fläche, Netz','Stabgeländer sind die robuste Klassik, Glas- und Lochblechfüllungen machen Flächen, Seilnetze machen Leichtigkeit. Jede Wahl zieht eigene Befestigungs- und Prüffragen nach sich.',NULL,NULL,'{}'::text[],'[]'::jsonb,NULL,84),
('kt2not','k',2,'kt1','Notwendige Treppen und Fluchtwege','Sobald eine Treppe Rettungsweg ist, wechselt sie die Disziplin: Aus Entwurf wird Baurecht. Laufbreiten, Treppenraum und Türen in den Treppenraum sind dann keine Geschmacksfragen mehr.',NULL,NULL,'{}'::text[],'[]'::jsonb,NULL,85),
('kt3nutz','k',3,'kt2not','Nutzbare Laufbreite','Die nutzbare Breite wird zwischen den fertigen Oberflächen gemessen, Handläufe ragen begrenzt hinein. Notwendige Treppen brauchen mehr Breite als Komforttreppen im eigenen Haus.',NULL,'Notwendige Treppen im Wohnungsbau üblich min. 100 cm nutzbar (länderabhängig, teils 90), innerhalb einer Wohnung ca. 80 cm zulässig; Versammlungs- und Sonderbauten nach eigener Systematik (Bemessung nach Personenzahl). Einengungen durch Handläufe nur in definiertem Maß. Ab hier: Landesbauordnung bzw. Sonderbauvorschrift.','{}'::text[],'[{"t":"DIN 18065 Gebäudetreppen","u":"https://www.dinmedia.de/de/norm/din-18065/322316050","stand":"2020-08","geprueft":"2026-08-16"},{"t":"Landesbauordnungen / Sonderbauvorschriften (DE), exemplarisch BauO NRW 2018","u":"https://recht.nrw.de/lmi/owa/br_bes_text?anw_nr=2&bes_id=39224&aufgehoben=N&keyword=landesbauordnung","stand":"Fassung 2018, zuletzt geändert Juli 2026","geprueft":"2026-08-16"}]'::jsonb,'{"at":"OIB-Richtlinie 4.","ch":"VKF-Brandschutzvorschriften und kantonale Regeln.","de":"LBO-abhängig."}'::jsonb,86),
('kt3raum','k',3,'kt2not','Der notwendige Treppenraum','Der Treppenraum ist die vertikale Brandschutzzone des Hauses: eigene Wände, definierte Türen, Rauchableitung. Seine Logik bestimmt ganze Grundrisse, lange bevor über Stufen geredet wird.','Entwurflich ist der Treppenraum die Stelle, an der Brandschutz Grundrisse formt: Lage an der Außenwand (Fenster zur Rauchableitung) gegen innenliegend (Druckbelüftung oder RWA über Dach), Abschlüsse zu Nutzungseinheiten als klassifizierte Türen, keine Brandlasten im Raum. Wer den Treppenraum früh richtig setzt, erspart sich später die teuren Kompensationen.',NULL,ARRAY['k3t30']::text[],'[]'::jsonb,NULL,87),
('kt3aussen','k',3,'kt2not','Außentreppen als Rettungsweg','Die außenliegende Stahltreppe ist der pragmatische zweite Rettungsweg des Bestands: baurechtlich dankbar, gestalterisch selten geliebt, und im Winter ein Rutschthema mit Wartungspflicht.',NULL,NULL,'{}'::text[],'[]'::jsonb,NULL,88),
('kt2rampe','k',2,'kt1','Rampen und Aufzüge','Wo Stufen sind, braucht es für die barrierefreie Erschließung eine zweite Antwort: Rampe oder Aufzug. Beide sind eigene Gewerke mit eigener Geometrie, hier als Schnittstellenwissen erschlossen.',NULL,NULL,'{}'::text[],'[]'::jsonb,NULL,89),
('kt3rampe','k',3,'kt2rampe','Rampen','Sechs Prozent Steigung fühlen sich zu Fuß nach nichts an und sind im Rollstuhl bereits Arbeit. Rampen brauchen überraschend viel Länge, und genau daran scheitern nachträgliche Lösungen.',NULL,'Barrierefreie Rampen: max. 6 % Längsgefälle, kein Quergefälle, Zwischenpodest (min. 150 cm) nach max. 600 cm Lauf, beidseitige Handläufe und Radabweiser, Bewegungsflächen an Anfang und Ende. Kürzere steilere Rampen sind keine barrierefreien Rampen, sondern Schiebehilfen. Ab hier: DIN 18040 bzw. nationale Regel plus Entwässerungsdetail bei Außenrampen.',ARRAY['k4null']::text[],'[{"t":"DIN 18040-1 Barrierefreies Bauen: öffentlich zugängliche Gebäude","u":"https://www.dinmedia.de/de/norm/din-18040-1/133692028","stand":"2010-10","geprueft":"2026-08-16"},{"t":"DIN 18040-2 Barrierefreies Bauen: Wohnungen","u":"https://www.dinmedia.de/de/norm/din-18040-2/142706210","stand":"2011-09","geprueft":"2026-08-16"}]'::jsonb,'{"at":"ÖNORM B 1600: gleiche Systematik, teils abweichende Maße.","ch":"SIA 500: Leitwert ebenfalls 6 %, Details eigenständig.","de":"DIN 18040."}'::jsonb,90);
insert into public.nodes (id,perspective,level,parent_id,title,t1,t2,t3,links,sources,dach,ord) values
('kt3aufzug','k',3,'kt2rampe','Aufzüge: Schacht und Schnittstellen','Für den Architekten ist der Aufzug vor allem ein Rohbauthema: Schachtmaße, Schachtkopf, Grube, Türlage und die Schallschutzfuge zum Wohnraum. Die Kabine wählt man aus dem Katalog, den Schacht nicht.','Früh festzulegen: Durchgangs- oder Übereck-Ladung, Türbreite (barrierefreie Kabinenmaße!), Schachtkopf- und Grubenhöhen des gewählten Systems, Maschinenraumlos ja/nein, und die Entkopplung des Schachts von schutzbedürftigen Räumen. Der Klassiker unter den Konflikten: Aufzug direkt an Schlafzimmerwand.',NULL,'{}'::text[],'[]'::jsonb,NULL,91),
('et1','e',1,NULL,'Die Treppe als Entwurfselement','Keine andere Bewegung durchs Haus wird so choreographiert wie das Steigen: Die Treppe verteilt nicht nur Geschosse, sie inszeniert Ankommen, Sehen und Gesehenwerden. Diese Perspektive versammelt das gestalterische Wissen zur Treppe.',NULL,NULL,ARRAY['kt1','e1']::text[],'[]'::jsonb,NULL,92),
('et2skulptur','e',2,'et1','Die Treppe als Raumskulptur','Frei in den Raum gestellt, wird die Treppe vom Verkehrsbauwerk zum Möbel des Hauses: ein gefaltetes Band, eine Spindel, eine schwebende Läuferfolge. Der Auftritt kostet Fläche und will sie wert sein.','Die skulpturale Treppe funktioniert nur mit konstruktiver Disziplin: Untersicht, Kantenradius und Materialstoß sind ihre eigentlichen Entwurfsthemen, nicht die große Geste. Wer die Untersicht nicht zeichnet, bekommt eine Schalungsdokumentation statt einer Skulptur. Und sie braucht Luft: Eine Skulptur an drei Wänden ist ein Flurmöbel.',NULL,ARRAY['kt3beton','kt3stahl']::text[],'[]'::jsonb,NULL,93),
('et2prom','e',2,'et1','Promenade: Steigen als Sequenz','Die Rampe im Zentrum, die Treppe am Licht entlang, der Umweg mit Aussicht: Steigen kann ein Erzählstrang durchs Gebäude sein, nicht nur seine schnellste Vertikale.','Die klassische Referenz ist Corbusiers promenade architecturale, aber das Prinzip ist älter und alltagstauglicher: Wer beim Steigen etwas sieht (einen Hof, ein Oberlicht, die Straße), erlebt Geschosse als Abfolge von Orten statt als Etagen. Praktisch heißt das: Treppen an Fassaden und Lufträume legen, Podeste als Blickpunkte schneiden, und den Aufzug bewusst unattraktiver machen als den Weg.',NULL,ARRAY['kt3steig','e3enfilade','x3tor']::text[],'[]'::jsonb,NULL,94),
('et2ort','e',2,'et1','Die Treppe als Ort','Sitzstufen, Tribünen, das breite Podest mit Fenster: Treppen können Aufenthaltsorte sein, an denen man verabredet ist, wartet, zuschaut. Dann gelten zwei Regelwerke gleichzeitig: das des Steigens und das des Bleibens.','Sitzstufen brauchen andere Maße als Gehstufen (doppelte bis dreifache Steigung, tiefe Auftritte) und eine saubere Trennung oder Überlagerungslogik zur begehbaren Zone, sonst kollidieren Aufenthalt und Rettungsweg. Der Erfolg solcher Orte hängt an Licht, Blickrichtung und daran, ob dort wirklich jemand sitzen will; die Tribüne ohne Programm ist die teuerste Leerfläche des Hauses.',NULL,ARRAY['kt3podest','x3platz']::text[],'[]'::jsonb,NULL,95),
('et2licht','e',2,'et1','Treppe und Licht','Das Treppenauge unterm Oberlicht ist der älteste Lichtschacht der Baugeschichte: Steigen zum Licht ist eine körperliche Erfahrung, die kein Flur ersetzen kann. Umgekehrt bleibt die dunkle Treppe der unbeliebteste Raum des Hauses.',NULL,NULL,ARRAY['kt3kopf']::text[],'[]'::jsonb,NULL,96),
('et2zeigen','e',2,'et1','Treppen zeigen oder verbergen','Die repräsentative Treppe in der Halle und die dienende im Kern sind zwei Haltungen zur gleichen Funktion. Brandschutz drängt Treppen in geschlossene Räume; Entwurfskunst holt sie wieder heraus oder inszeniert das Verschwinden.','Der reale Zielkonflikt: Offene Verbindungstreppen über mehrere Geschosse kollidieren schnell mit der Treppenraum-Logik und sind nur als zusätzliche Treppen oder über Sonderlösungen machbar. Robust ist die Doppelstrategie: der notwendige Treppenraum als ruhige Pflicht, die offene Treppe als Kür innerhalb einer Nutzungseinheit.',NULL,ARRAY['kt3raum']::text[],'[]'::jsonb,NULL,97),
('kgr1','k',1,NULL,'Gründung und erdberührte Bauteile','Die Gründung überträgt die Lasten des Gebäudes in den Baugrund und ist zugleich die erste Abdichtungsebene gegen Bodenfeuchte und Wasser. Fehler hier sind später kaum korrigierbar, weil jede Nachbesserung durch massives Erdreich hindurch muss. Das Themenfeld reicht von der Wahl des Gründungssystems über die wasserdichte Wanne bis zur Dämmung und Sockelausbildung am Übergang zum aufgehenden Bauteil.',NULL,NULL,'{}'::text[],'[]'::jsonb,NULL,98),
('kgr2fund','k',2,'kgr1','Flach- und Tiefgründungen','Ob ein Gebäude flach oder tief gegründet wird, entscheidet der Baugrund, nicht der Architekt allein: Tragfähigkeit, Grundwasserstand und Nachbarbebauung setzen die Randbedingungen. Flachgründungen sind der Regelfall im Hochbau, Tiefgründungen kommen bei schlechtem Baugrund oder hohen Lasten ins Spiel. Die Entscheidung fällt gemeinsam mit dem Tragwerksplaner, meist schon in der Vorplanung.',NULL,NULL,'{}'::text[],'[]'::jsonb,NULL,99),
('kgr3streifen','k',3,'kgr2fund','Streifen- und Einzelfundamente','Streifenfundamente unter tragenden Wänden und Einzelfundamente unter Stützen sind die einfachste Form der Flachgründung: flach, robust, in fast jedem Baugrund wirtschaftlich. Ihre Tiefe richtet sich nach der Frostgrenze, ihre Breite nach der zulässigen Bodenpressung. Bei ungleichmäßigem Baugrund drohen Setzungsunterschiede, denen mit einer durchgehenden Bodenplatte oft besser zu begegnen ist.',NULL,NULL,'{}'::text[],'[]'::jsonb,NULL,100),
('kgr3platte','k',3,'kgr2fund','Bodenplatte','Die Bodenplatte gründet flächig statt linear und verteilt die Last gleichmäßiger als einzelne Streifen: Sie ist heute bei Wohn- und Kleingebäuden der Regelfall, oft kombiniert mit Fußbodenheizung im Aufbau. Bewehrung und Dicke richten sich nach Lastabtrag und Baugrund, die Ebenheit nach den Anforderungen des folgenden Bodenaufbaus.',NULL,NULL,'{}'::text[],'[]'::jsonb,NULL,101),
('kgr3pfahl','k',3,'kgr2fund','Pfahlgründung','Wo der tragfähige Baugrund erst in mehreren Metern Tiefe liegt, leiten Pfähle die Last an der schlechten Bodenschicht vorbei: Sie tragen über Mantelreibung, Spitzendruck oder beides. Pfahlgründungen sind aufwendig und teuer, aber oft die einzige Lösung bei weichen Böden, hohen Lasten oder strengen Setzungsvorgaben in dichter Nachbarschaft.',NULL,NULL,'{}'::text[],'[]'::jsonb,NULL,102),
('kgr3wahl','k',3,'kgr2fund','Baugrunduntersuchung und Gründungswahl','Das Baugrundgutachten ist die Grundlage jeder Gründungsentscheidung und gehört früh beauftragt, nicht erst zur Ausführungsplanung: Es liefert Tragfähigkeit, Grundwasserstand und Hinweise auf Altlasten oder Hohlräume. Wer hier spart, riskiert teure Umplanungen mitten in der Bauausführung.',NULL,NULL,'{}'::text[],'[]'::jsonb,NULL,103),
('kgr2keller','k',2,'kgr1','Kellerwände und Weiße Wanne','Kellerwände tragen nicht nur, sie müssen zugleich dem Wasserdruck des umgebenden Bodens standhalten. Die Weiße Wanne aus wasserundurchlässigem Beton hat die klassische Außenabdichtung in vielen Projekten abgelöst, weil sie Tragwerk und Abdichtung in einem Bauteil vereint. Die Wahl zwischen weißer und schwarzer Wanne fällt früh und ist später kaum revidierbar.',NULL,NULL,'{}'::text[],'[]'::jsonb,NULL,104),
('kgr3wu','k',3,'kgr2keller','Weiße Wanne: Konstruktionsprinzip','Wasserundurchlässiger Beton (WU-Beton) dichtet nicht durch eine Membran, sondern durch das Material selbst: dichtes Gefüge, kontrollierte Rissbreite, durchdachte Fugenausbildung. Das Prinzip funktioniert nur, wenn Bewehrung, Betonrezeptur und Fugenplanung als Gesamtsystem gedacht werden, nicht als Summe von Einzelentscheidungen.',NULL,NULL,'{}'::text[],'[]'::jsonb,NULL,105);
insert into public.nodes (id,perspective,level,parent_id,title,t1,t2,t3,links,sources,dach,ord) values
('kgr3schwarz','k',3,'kgr2keller','Schwarze und Braune Wanne im Vergleich','Die schwarze Wanne dichtet mit Bitumenbahnen von außen ab, die braune Wanne mit Bentonit, das bei Wasserkontakt aufquillt: Beide sind Alternativen zur weißen Wanne, wenn WU-Beton konstruktiv oder wirtschaftlich nicht passt. Schwäche beider Systeme ist die Durchdringung, jede Leitung und jeder Anker durch die Abdichtungsebene ist eine potenzielle Schwachstelle.',NULL,NULL,'{}'::text[],'[]'::jsonb,NULL,106),
('kgr3ziegel','k',3,'kgr2keller','Kellerwand aus Mauerwerk','Gemauerte Kellerwände mit nachträglicher Außenabdichtung sind der traditionelle Weg und im kleinvolumigen Bau noch verbreitet: einfach zu handwerken, aber auf eine zuverlässige, separate Abdichtungsebene angewiesen. Anders als die Weiße Wanne trennt dieses System Tragfunktion und Dichtfunktion sauber, was Reparaturen erschwert, sobald die Wand hinterfüllt ist.',NULL,NULL,'{}'::text[],'[]'::jsonb,NULL,107),
('kgr3durchdring','k',3,'kgr2keller','Durchdringungen der Weißen Wanne','Jede Leitung, jeder Anker und jede Arbeitsfuge durchbricht die Dichtheit des WU-Betons und muss mit eigens dafür entwickelten Systemen abgedichtet werden: Fugenbändern, Injektionsschläuchen, Dichtmanschetten. In der Praxis entstehen die meisten Wasserschäden nicht in der Fläche, sondern genau an diesen Stellen.',NULL,NULL,'{}'::text[],'[]'::jsonb,NULL,108),
('kgr2abdicht','k',2,'kgr1','Abdichtung erdberührter Bauteile','Abdichtung erdberührter Bauteile schützt vor Bodenfeuchte, aufstauendem und drückendem Wasser, drei Belastungsklassen mit sehr unterschiedlichen Anforderungen an das Abdichtungssystem. Welche Klasse vorliegt, entscheidet die Wasserbeanspruchung am Standort, nicht die Bauteilart allein. Wer die Klasse falsch einschätzt, dichtet entweder unnötig aufwendig oder zu knapp.',NULL,NULL,'{}'::text[],'[]'::jsonb,NULL,109),
('kgr3weklasse','k',3,'kgr2abdicht','Wassereinwirkungsklassen im Überblick','Bodenfeuchte, aufstauendes Sickerwasser und drückendes Wasser sind die drei zentralen Belastungsfälle, denen eine Abdichtung standhalten muss, jeweils mit eigenem Anforderungsprofil an Material und Ausführung. Die Einstufung erfolgt über Baugrundgutachten und Grundwasserstand und bestimmt praktisch alles Weitere an der Abdichtung.',NULL,NULL,'{}'::text[],'[]'::jsonb,NULL,110),
('kgr3bitumen','k',3,'kgr2abdicht','Bitumen- und Kunststoffbahnen','Bahnenabdichtungen werden mehrlagig verschweißt oder verklebt und sind das traditionelle System für drückendes Wasser: robust, aber auf handwerklich saubere Nähte und Anschlüsse angewiesen. Jede Durchdringung, jede Ecke und jede Bauteilfuge ist ein Detail, das in der Ausführung über die gesamte Lebensdauer entscheidet.',NULL,NULL,'{}'::text[],'[]'::jsonb,NULL,111),
('kgr3fluessig','k',3,'kgr2abdicht','Flüssigabdichtung','Flüssig aufgetragene Abdichtungen bilden eine fugenlose Membran und eignen sich besonders für komplexe Geometrien, Anschlüsse und Nachträge im Bestand, wo Bahnen schwer zu verlegen wären. Die Qualität hängt stark von Schichtdicke und Untergrundvorbereitung ab, beides ist auf der Baustelle schwerer zu kontrollieren als eine im Werk vorgefertigte Bahn.',NULL,NULL,'{}'::text[],'[]'::jsonb,NULL,112),
('kgr3drainage','k',3,'kgr2abdicht','Drainage und Sickerwasser','Eine Drainage nimmt drückendes Wasser vom Gebäude weg, bevor es die Abdichtung überhaupt belastet, und kann so aus einer aufwendigen Abdichtung gegen drückendes Wasser eine einfachere gegen Bodenfeuchte machen. Sie funktioniert aber nur mit Gefälle zum Vorfluter oder Sickerschacht und braucht regelmäßige Wartung, sonst versagt sie unbemerkt unter der Erde.',NULL,NULL,'{}'::text[],'[]'::jsonb,NULL,113),
('kgr2perim','k',2,'kgr1','Perimeterdämmung und Sockelausbildung','Am Übergang vom erdberührten zum aufgehenden Bauteil treffen Abdichtung, Dämmung und Sockelausbildung auf engstem Raum aufeinander, und genau hier entstehen die meisten Wärmebrücken und Feuchteschäden am Gebäude. Perimeterdämmung muss druckwasserbeständig und dauerhaft feuchteunempfindlich sein, ganz andere Anforderungen als Dämmung im aufgehenden Mauerwerk.',NULL,NULL,'{}'::text[],'[]'::jsonb,NULL,114),
('kgr3perimmat','k',3,'kgr2perim','Perimeterdämmung: Materialwahl','Nur wenige Dämmstoffe vertragen dauerhaften Erdkontakt und Feuchte ohne Leistungsverlust: extrudiertes Polystyrol (XPS) und Schaumglas sind die gängigen Systeme, geschlossenzellig und druckfest genug für die Hinterfüllung. Mineralische Dämmstoffe scheiden hier aus, sie verlieren bei Durchfeuchtung ihre Dämmwirkung dauerhaft.',NULL,NULL,'{}'::text[],'[]'::jsonb,NULL,115),
('kgr3sockel','k',3,'kgr2perim','Sockelausbildung und Spritzwasserschutz','Der Sockel nimmt Spritzwasser und mechanische Belastung auf und bildet oft auch die sichtbare Materialgrenze zwischen Fassade und Erdreich, ein bauphysikalisches ebenso wie ein gestalterisches Detail. Die Höhe der Abdichtung über Gelände steht dabei in ständiger Spannung zur barrierefreien, schwellenlosen Erschließung an Eingängen.',NULL,NULL,ARRAY['k4null','k3schwelle']::text[],'[]'::jsonb,NULL,116),
('kgr3waermebr','k',3,'kgr2perim','Wärmebrücke am Gebäudesockel','Am Sockel läuft die Dämmebene der Fassade selten bruchlos in die Perimeterdämmung über, ein klassischer Ort für geometrische und materialbedingte Wärmebrücken. Sorgfältige Detailplanung mit durchlaufender Dämmebene reduziert hier spürbar den Energieverlust und verhindert Tauwasser an der Innenoberfläche.',NULL,NULL,ARRAY['kfa2wdvs']::text[],'[]'::jsonb,NULL,117),
('kro1','k',1,NULL,'Tragwerk und Rohbau','Das Tragwerk trägt nicht nur die Lasten, es legt auch fest, was später noch änderbar ist: Spannweiten, Stützenraster und Wandstellungen aus der Rohbauphase begleiten ein Gebäude über seine gesamte Nutzungsdauer. Die Wahl des Baustoffs, Mauerwerk, Stahlbeton, Holz oder Stahl, ist deshalb eine der folgenreichsten Entscheidungen im Entwurf, weit über die Statik hinaus.',NULL,NULL,'{}'::text[],'[]'::jsonb,NULL,118),
('kro2mauer','k',2,'kro1','Mauerwerksbau','Mauerwerk trägt und dämmt zugleich in einem Bauteil, was es zur wirtschaftlichsten Lösung für viele Wohngebäude macht, solange Spannweiten und Geschosszahl moderat bleiben. Die Vielfalt der Steinformate von Ziegel über Kalksandstein bis Porenbeton erlaubt eine feine Abstimmung von Tragfähigkeit, Dämmwert und Schallschutz auf die jeweilige Wand.',NULL,NULL,ARRAY['kfa2sicht']::text[],'[]'::jsonb,NULL,119),
('kro3steine','k',3,'kro2mauer','Mauerwerksarten und Steinformate','Ziegel, Kalksandstein und Porenbeton unterscheiden sich in Rohdichte, Wärmeleitfähigkeit und Druckfestigkeit erheblich, und diese Eigenschaften stehen meist im Zielkonflikt: Ein leichter, gut dämmender Stein trägt weniger als ein schwerer, dichter. Die Wandstärke gleicht diesen Konflikt aus, weshalb monolithische Wände aus leichten Steinen oft dicker ausfallen als gedämmte Verblendkonstruktionen.',NULL,NULL,'{}'::text[],'[]'::jsonb,NULL,120);
insert into public.nodes (id,perspective,level,parent_id,title,t1,t2,t3,links,sources,dach,ord) values
('kro3tragend','k',3,'kro2mauer','Tragende und aussteifende Wände','Nicht jede Wand trägt vertikale Lasten ab, aber fast jede aussteifende Wand übernimmt eine strukturelle Aufgabe: Sie leitet Horizontallasten aus Wind in die Fundamente. Wer im Bestand eine Wand entfernen will, muss deshalb beide Funktionen prüfen, nicht nur die offensichtliche Traglast.',NULL,NULL,'{}'::text[],'[]'::jsonb,NULL,121),
('kro3knick','k',3,'kro2mauer','Schlankheit und Knicklänge im Mauerwerk','Eine schlanke Mauerwerkswand kann knicken, bevor sie ihre rechnerische Druckfestigkeit erreicht, ähnlich wie ein zu dünner Stab unter Last ausweicht. Das Verhältnis von Wandhöhe zu Wanddicke begrenzt deshalb die zulässige Schlankheit und damit indirekt auch die minimale Wandstärke bei hohen Räumen.',NULL,NULL,'{}'::text[],'[]'::jsonb,NULL,122),
('kro2beton','k',2,'kro1','Stahlbetonbau: Ortbeton und Fertigteile','Stahlbeton verbindet die Druckfestigkeit des Betons mit der Zugfestigkeit der Bewehrung und ermöglicht damit Spannweiten und Formen, die Mauerwerk nicht leisten kann. Die Grundsatzentscheidung fällt zwischen Ortbeton, vor Ort geschalt und gegossen, und Fertigteilen, im Werk produziert und montiert: Ortbeton ist flexibler in der Form, Fertigteile sind schneller und präziser auf der Baustelle.',NULL,NULL,ARRAY['kfa2sichtbeton']::text[],'[]'::jsonb,NULL,123),
('kro3ortbeton','k',3,'kro2beton','Ortbeton: Schalung und Bewehrung','Ortbeton entsteht vor Ort in einer Schalung, die die endgültige Oberfläche mitbestimmt, glatt, strukturiert oder als Sichtbeton behandelt. Bewehrungsführung und Betonierabschnitte müssen früh mit dem Tragwerksplaner abgestimmt werden, weil sie Bauablauf und spätere Fugenlage festlegen.',NULL,NULL,ARRAY['kt3beton']::text[],'[]'::jsonb,NULL,124),
('kro3fertig','k',3,'kro2beton','Betonfertigteile und Elementbauweise','Fertigteile werden im Werk unter kontrollierten Bedingungen hergestellt und liefern gleichbleibende Qualität, verkürzen aber die Planungsfreiheit vor Ort: Änderungen nach der Fertigung sind aufwendig bis unmöglich. Die Fugen zwischen den Elementen sind konstruktiv und gestalterisch entscheidend und verdienen eigene Aufmerksamkeit in der Planung.',NULL,NULL,'{}'::text[],'[]'::jsonb,NULL,125),
('kro2holz','k',2,'kro1','Holzbau: Massivholz, Skelett, Rahmen','Holzbau hat sich von der Nische zur ernsthaften Alternative im mehrgeschossigen Bau entwickelt, getrieben von Vorfertigung, Bauzeit und dem Wunsch nach einem nachwachsenden Baustoff. Drei Grundsysteme prägen das Feld: Massivholz aus großformatigen Platten, Skelettbau mit Stützen und Trägern, und Rahmenbau mit stabverstärkten Wänden.',NULL,NULL,'{}'::text[],'[]'::jsonb,NULL,126),
('kro3massiv','k',3,'kro2holz','Massivholzbau (Brettsperrholz)','Brettsperrholz, kreuzweise verleimte Bretterlagen, verhält sich wie eine flächige Massivscheibe und trägt in beide Richtungen: Wände und Decken übernehmen Trag- und Raumabschlussfunktion in einem Bauteil. Der sichtbare Holzcharakter ist gestalterisch gewollt, verlangt aber besondere Sorgfalt beim Brand- und Schallschutz.',NULL,NULL,ARRAY['kt3holz']::text[],'[]'::jsonb,NULL,127),
('kro3skelett','k',3,'kro2holz','Holzskelettbau','Stützen und Träger aus Holz oder Brettschichtholz tragen die Lasten, während die Wände von der Tragfunktion befreit sind und frei gestaltet werden können: viel Licht, große Öffnungen, flexible Grundrisse. Das System eignet sich besonders für Hallen und öffentliche Bauten mit großen Spannweiten.',NULL,NULL,'{}'::text[],'[]'::jsonb,NULL,128),
('kro3rahmen','k',3,'kro2holz','Holzrahmenbau','Im Holzrahmenbau übernehmen schlanke, dicht gestellte Ständer die Tragfunktion, die Zwischenräume nehmen Dämmung auf: eine sehr materialsparende, hoch vorfertigbare Bauweise, verbreitet im Ein- und Zweifamilienhausbau. Die Luftdichtheit entscheidet über die Bauphysik der Wand und muss handwerklich präzise ausgeführt werden.',NULL,NULL,'{}'::text[],'[]'::jsonb,NULL,129),
('kro2stahl','k',2,'kro1','Stahl- und Hybridbau','Stahl trägt bei geringem Eigengewicht enorme Lasten und erlaubt die größten Spannweiten aller gängigen Baustoffe, verlangt dafür aber konsequenten Brand- und Korrosionsschutz. Hybridbauweisen kombinieren Stahl gezielt mit Beton oder Holz und nutzen die jeweiligen Stärken der Materialien in einem Bauteil.',NULL,NULL,'{}'::text[],'[]'::jsonb,NULL,130),
('kro3profile','k',3,'kro2stahl','Stahlskelettbau und Profile','Genormte Walzprofile wie I- und H-Träger stehen als Halbzeug bereit und werden im Werk vorkonfektioniert, was Stahlbau zur schnellsten Rohbauweise macht. Die Verbindungen, geschweißt oder geschraubt, prägen dabei ebenso die Tragwirkung wie die Profile selbst.',NULL,NULL,ARRAY['kt3stahl']::text[],'[]'::jsonb,NULL,131),
('kro3verbund','k',3,'kro2stahl','Verbundbau: Stahl und Beton kombiniert','Verbundkonstruktionen lassen Beton auf Druck und Stahl auf Zug arbeiten, jeweils dort, wo sie es am besten können, etwa als Verbundträger mit Betonplatte auf Stahlprofil. Das Ergebnis sind schlankere Bauteile als bei reiner Stahl- oder Betonbauweise, bei etwas höherem Planungsaufwand für die Verbundmittel.',NULL,NULL,'{}'::text[],'[]'::jsonb,NULL,132),
('kro3brand','k',3,'kro2stahl','Brandschutz im Stahlbau','Stahl verliert bei Brandtemperaturen rasch seine Tragfähigkeit, anders als Beton oder Holz, das langsamer abbrennt und dabei eine schützende Kohleschicht bildet. Brandschutzbekleidungen, Dämmschichtsysteme oder das bewusste Überdimensionieren der Profile kompensieren diese Schwäche, jede Lösung mit eigenen Kosten- und Gestaltungsfolgen.',NULL,NULL,'{}'::text[],'[]'::jsonb,NULL,133),
('kro2decken','k',2,'kro1','Decken und Unterzüge','Decken trennen Geschosse und tragen gleichzeitig horizontale Lasten in die aussteifenden Bauteile ab, eine Doppelrolle, die bei jeder Deckenöffnung neu durchdacht werden muss. Unterzüge fangen dabei punktuelle oder linienförmige Lasten ab, wo die Decke allein die Spannweite nicht bewältigt.',NULL,NULL,'{}'::text[],'[]'::jsonb,NULL,134),
('kro3decksys','k',3,'kro2decken','Deckensysteme im Vergleich','Ortbetondecken sind monolithisch und frei formbar, Fertigteildecken schneller montiert und präziser, Holzbalkendecken leicht und schnell, aber schalltechnisch anspruchsvoller: Jedes System bringt eigene Anforderungen an Spannweite, Bauzeit und Schallschutz mit. Die Wahl hängt oft stärker vom übrigen Tragwerk ab als von der Decke selbst.',NULL,NULL,'{}'::text[],'[]'::jsonb,NULL,135);
insert into public.nodes (id,perspective,level,parent_id,title,t1,t2,t3,links,sources,dach,ord) values
('kro3unterzug','k',3,'kro2decken','Unterzüge und Spannweiten','Ein Unterzug erlaubt größere Deckenspannweiten, kostet dafür aber Raumhöhe oder verlangt eine abgehängte Decke, die ihn verdeckt: ein klassischer Zielkonflikt zwischen Tragwerk und lichter Raumhöhe. Wo Unterzüge in Stützenachsen fallen, verschwinden sie fast, außerhalb dieser Achsen werden sie zum sichtbaren Entwurfsthema.',NULL,NULL,'{}'::text[],'[]'::jsonb,NULL,136),
('kro2aussteif','k',2,'kro1','Aussteifung und Fugen','Ein Gebäude braucht neben der vertikalen Tragfähigkeit auch Stabilität gegen Wind und Erdbeben, die Aussteifung: Wände, Kerne oder Verbände leiten diese Horizontallasten kontrolliert ab. Bauwerksfugen wiederum trennen bewusst, wo unterschiedliche Bewegungen, aus Temperatur, Setzung oder Gebäudehöhe, sonst Risse erzwingen würden.',NULL,NULL,'{}'::text[],'[]'::jsonb,NULL,137),
('kro3ausstbau','k',3,'kro2aussteif','Aussteifende Bauteile','Treppenhauskerne, massive Wandscheiben oder diagonale Verbände übernehmen die Aussteifung eines Gebäudes gegen Wind und andere Horizontallasten und müssen deshalb früh im Grundriss verortet werden, nicht nachträglich eingefügt. Wo sie fehlen oder zu knapp bemessen sind, wird das gesamte Tragwerk instabil, unabhängig von der Festigkeit der Einzelbauteile.',NULL,NULL,'{}'::text[],'[]'::jsonb,NULL,138),
('kro3fugen','k',3,'kro2aussteif','Bauwerksfugen: Dehnung, Setzung, Trennung','Dehnungsfugen nehmen Temperaturbewegungen auf, Setzungsfugen trennen Gebäudeteile mit unterschiedlicher Gründung, und Gebäudetrennfugen grenzen ganze Bauwerke gegeneinander ab: Alle drei verhindern Risse, indem sie Bewegung gezielt zulassen, statt sie zu unterdrücken. Fugenabstand und Fugenbreite folgen dabei aus Material, Bauteillänge und Temperaturspanne.',NULL,NULL,'{}'::text[],'[]'::jsonb,NULL,139),
('kro3schwinden','k',3,'kro2aussteif','Schwinden und Kriechen im Tragwerk','Beton verkürzt sich nach dem Erhärten messbar durch Schwinden, und unter Dauerlast verformt er sich weiter durch Kriechen, beides Vorgänge, die erst Monate bis Jahre nach der Fertigstellung abgeschlossen sind. Wer das ignoriert, riskiert Risse an Anschlüssen zu steiferen Bauteilen, die eigentlich nur unterschiedlich stark schwinden.',NULL,NULL,'{}'::text[],'[]'::jsonb,NULL,140),
('kfa1','k',1,NULL,'Außenwand und Fassade','Die Fassade ist die Schnittstelle zwischen innen und außen, sie muss zugleich tragen oder verkleiden, dämmen, entwässern und über Jahrzehnte wettergerecht bleiben. Kein anderes Bauteil vereint so viele bauphysikalische Anforderungen mit so hoher gestalterischer Wirkung. Die Wahl des Fassadenprinzips, monolithisch, gedämmt, vorgehängt oder als Elementfassade, entscheidet früh über Erscheinung, Kosten und Wartungsaufwand.',NULL,NULL,'{}'::text[],'[]'::jsonb,NULL,141),
('kfa2mono','k',2,'kfa1','Monolithische Außenwände','Eine monolithische Wand dämmt allein durch ihre Materialstärke, ohne zusätzliche Dämmschicht: einschalig, aber massiv genug, um heutige Wärmeschutzanforderungen zu erfüllen. Der Verzicht auf ein mehrschaliges System vereinfacht die Konstruktion, verlangt aber Wandstärken, die andere Systeme nicht brauchen.',NULL,NULL,'{}'::text[],'[]'::jsonb,NULL,142),
('kfa3ziegelmono','k',3,'kfa2mono','Hochlochziegel und Leichtbeton','Hochlochziegel mit feiner Lochgeometrie und porosierte Leichtbetonsteine erreichen ihren Dämmwert über den Luftanteil im Stein selbst, nicht über eine zusätzliche Schicht. Beide Baustoffe verlangen sorgfältige Verarbeitung, weil jede Wärmebrücke durch Mörtelfugen oder Anker den rechnerischen Dämmwert der ganzen Wand schmälert.',NULL,NULL,'{}'::text[],'[]'::jsonb,NULL,143),
('kfa3grenzmono','k',3,'kfa2mono','Grenzen der monolithischen Bauweise','Je strenger die Wärmeschutzanforderungen, desto dicker muss eine monolithische Wand werden, irgendwann auf Kosten der Nutzfläche: Ab einem bestimmten Dämmstandard wird eine gedämmte, mehrschalige Wand wirtschaftlicher als noch mehr Wandstärke. Wo dieser Punkt liegt, verschiebt sich mit jeder Verschärfung der Energievorschriften.',NULL,NULL,'{}'::text[],'[]'::jsonb,NULL,144),
('kfa2wdvs','k',2,'kfa1','WDVS','Das Wärmedämmverbundsystem (WDVS) klebt oder dübelt eine Dämmschicht außen auf die tragende Wand und trägt einen Putz als Witterungsschutz, die verbreitetste Fassadenlösung im deutschsprachigen Neubau. Es ist wirtschaftlich und gut dämmend, aber empfindlich an Details wie Sockel, Fensteranschluss und Brandriegel, wo die Systemdicke an Grenzen stößt.',NULL,NULL,ARRAY['kgr3waermebr']::text[],'[]'::jsonb,NULL,145),
('kfa3daemmwdvs','k',3,'kfa2wdvs','Dämmstoffe im WDVS','Expandiertes Polystyrol (EPS) ist der wirtschaftliche Standard, Mineralwolle bringt besseren Brand- und Schallschutz, Holzfaser überzeugt bei ökologischer Bilanz und sommerlichem Wärmeschutz: Die Materialwahl im WDVS ist immer ein Kompromiss zwischen diesen drei Eigenschaften. Brennbare Dämmstoffe brauchen ab bestimmten Gebäudehöhen zusätzliche Brandriegel aus Mineralwolle.',NULL,NULL,'{}'::text[],'[]'::jsonb,NULL,146),
('kfa3schwachwdvs','k',3,'kfa2wdvs','Schwachstellen am WDVS','Am Sockel, am Fensteranschluss und an jedem Durchbruch verliert das WDVS seine gleichmäßige Dämmwirkung, genau dort häufen sich Wärmebrücken und Rissbildung im Putz. Die Detailplanung dieser Übergänge entscheidet stärker über die Lebensdauer der Fassade als die Wahl des Dämmstoffs in der Fläche.',NULL,NULL,'{}'::text[],'[]'::jsonb,NULL,147),
('kfa2vhf','k',2,'kfa1','Vorgehängte hinterlüftete Fassade','Bei der vorgehängten hinterlüfteten Fassade (VHF) trennt ein Luftspalt die Bekleidung konstruktiv von der Dämmebene: Feuchte kann abtrocknen, statt in der Konstruktion zu verbleiben, was das System besonders dauerhaft macht. Die Unterkonstruktion aus Metall oder Holz trägt dabei sowohl die Bekleidung als auch die Anschlusspunkte an die tragende Wand.',NULL,NULL,'{}'::text[],'[]'::jsonb,NULL,148),
('kfa3ukonvhf','k',3,'kfa2vhf','Unterkonstruktion und Hinterlüftung','Die Unterkonstruktion überbrückt die Dämmebene mit möglichst wenigen, punktuellen Befestigungen und muss dabei Eigengewicht, Windsog und Wärmebrücken gleichzeitig im Griff behalten. Der Hinterlüftungsspalt braucht eine Mindestbreite und durchgehende Öffnungen unten und oben, sonst funktioniert die Trocknung nicht.',NULL,NULL,'{}'::text[],'[]'::jsonb,NULL,149),
('kfa3bekleidvhf','k',3,'kfa2vhf','Bekleidungsmaterialien im Überblick','Von Faserzementplatten über Metallpaneele bis zu Naturstein oder Keramik lässt die VHF nahezu jedes plattenförmige Material als sichtbare Fassadenhaut zu, weil die Bekleidung keine tragende oder dämmende Funktion übernehmen muss. Das macht das System gestalterisch flexibel und beliebt bei Sanierungen mit hohen Ansprüchen an die Optik.',NULL,NULL,'{}'::text[],'[]'::jsonb,NULL,150);
insert into public.nodes (id,perspective,level,parent_id,title,t1,t2,t3,links,sources,dach,ord) values
('kfa3befestvhf','k',3,'kfa2vhf','Befestigung und Wärmebrücken','Jeder Befestigungspunkt der Unterkonstruktion durchdringt die Dämmebene und wird damit zur punktuellen Wärmebrücke: Konsolen aus Edelstahl oder thermisch getrennte Systeme reduzieren diesen Effekt, ganz vermeiden lässt er sich nicht. Die Zahl und Anordnung der Befestigungspunkte ist deshalb eine bauphysikalische, nicht nur eine statische Entscheidung.',NULL,NULL,'{}'::text[],'[]'::jsonb,NULL,151),
('kfa2sicht','k',2,'kfa1','Sichtmauerwerk und Verblendschalen','Sichtmauerwerk zeigt den Stein als fertige Oberfläche, ohne Putz oder Verkleidung, und verlangt deshalb höchste Verarbeitungsqualität, jede Fuge bleibt sichtbar. Als vorgesetzte Verblendschale übernimmt es dabei meist keine tragende Funktion mehr, sondern schützt und gestaltet die dahinterliegende, gedämmte Tragschale.',NULL,NULL,'{}'::text[],'[]'::jsonb,NULL,152),
('kfa3verblend','k',3,'kfa2sicht','Verblendschale und Luftschicht','Zwischen tragender Wand und Verblendschale bleibt eine belüftete Luftschicht, damit eindringende Feuchte wieder abtrocknen kann, ähnlich dem Prinzip der hinterlüfteten Fassade, nur mit Mauerwerk als Bekleidung. Öffnungen am Wandfuß für Entwässerung und Belüftung sind dabei kein optionales Detail, sondern Bedingung für die Funktion.',NULL,NULL,'{}'::text[],'[]'::jsonb,NULL,153),
('kfa3anker','k',3,'kfa2sicht','Ankertechnik und Mauerwerksanker','Mauerwerksanker aus nichtrostendem Stahl halten die Verblendschale an der Tragschale und müssen Windlast, Eigengewicht und die freie Bewegung beider Schalen gegeneinander gleichzeitig ermöglichen. Falsch dimensionierte oder korrodierte Anker sind eine der häufigsten Ursachen für nachträgliche Verformungen an Verblendmauerwerk.',NULL,NULL,ARRAY['kro2mauer']::text[],'[]'::jsonb,NULL,154),
('kfa2pfriegel','k',2,'kfa1','Pfosten-Riegel- und Elementfassaden','Pfosten-Riegel-Fassaden bauen ein Tragraster aus vertikalen Pfosten und horizontalen Riegeln vor Ort zusammen, Elementfassaden liefern ganze, im Werk vorgefertigte Module zur Montage: beide Systeme sind die Standardlösung für großflächig verglaste Fassaden im Geschossbau. Die Wahl zwischen beiden ist vor allem eine Frage von Bauzeit, Fassadengröße und Kostenrahmen.',NULL,NULL,'{}'::text[],'[]'::jsonb,NULL,155),
('kfa3pfsystem','k',3,'kfa2pfriegel','Pfosten-Riegel-Systeme','Pfosten tragen vertikal, Riegel horizontal, dazwischen sitzen Glas- oder Paneelfüllungen in Dichtprofilen: ein flexibles Baukastenprinzip, das sich an fast jede Gebäudegeometrie anpassen lässt. Die Montage vor Ort macht das System langsamer als Elementfassaden, aber unempfindlicher gegenüber Maßabweichungen im Rohbau.',NULL,NULL,'{}'::text[],'[]'::jsonb,NULL,156),
('kfa3element','k',3,'kfa2pfriegel','Elementfassaden: Vorfertigung und Montage','Elementfassaden entstehen geschossweise vorgefertigt im Werk und werden als komplette Module samt Verglasung, Dämmung und Anschlüssen an der Baustelle eingehängt: schnell montiert, aber mit engen Toleranzanforderungen an den Rohbau. Fehler im Rohbaumaß rächen sich hier deutlich schneller als bei vor Ort gefertigten Systemen.',NULL,NULL,'{}'::text[],'[]'::jsonb,NULL,157),
('kfa3dicht','k',3,'kfa2pfriegel','Dichtungsebenen und Entwässerung','Elementfassaden arbeiten meist mit zwei getrennten Dichtungsebenen, einer äußeren Wetterschale gegen Schlagregen und einer inneren Luftdichtheitsebene, dazwischen liegt eine drucklose Entwässerungskammer. Dieses Prinzip verzeiht kleine Undichtigkeiten der äußeren Ebene, solange die Entwässerung nach außen funktioniert.',NULL,NULL,'{}'::text[],'[]'::jsonb,NULL,158),
('kfa2sichtbeton','k',2,'kfa1','Sichtbeton als Fassade','Sichtbeton macht die Schalhaut zur Gestaltungsebene: Jede Schalungsfuge, jeder Ankerpunkt bleibt sichtbar und muss deshalb von Anfang an geplant, nicht nachträglich kaschiert werden. Als Fassadenmaterial verlangt Sichtbeton eine Präzision im Bauablauf, die weit über statische Anforderungen hinausgeht.',NULL,NULL,ARRAY['kro2beton']::text[],'[]'::jsonb,NULL,159),
('kfa3schaltech','k',3,'kfa2sichtbeton','Schalungstechnik für Sichtbeton','Die Schalhaut, ob Holz, Kunststoff oder Stahl, prägt Textur und Porenbild der fertigen Oberfläche und muss über den gesamten Betoniervorgang absolut dicht und formstabil bleiben. Ein Ausbessern nach dem Ausschalen ist bei Sichtbeton kaum möglich, ohne den Flicken sichtbar zu machen.',NULL,NULL,'{}'::text[],'[]'::jsonb,NULL,160),
('kfa3fugenbild','k',3,'kfa2sichtbeton','Fugenbild und Ansichtsplanung','Schalungsfugen und Ankerlöcher sind bei Sichtbeton kein technisches Nebenprodukt, sondern Teil der Gestaltung und gehören deshalb in einen eigenen Ansichtsplan, lange vor der ersten Schalungsbestellung. Nachträglich geänderte Fugenraster sind der häufigste Grund für unbefriedigende Sichtbetonfassaden.',NULL,NULL,'{}'::text[],'[]'::jsonb,NULL,161),
('kfa2gruen','k',2,'kfa1','Fassadenbegrünung und Solarfassade','Begrünte und aktive Fassaden verwandeln die Außenwand von einer passiven Hülle in ein Bauteil mit ökologischer oder energetischer Zusatzfunktion, sei es Verdunstungskühlung und Biodiversität bei Begrünung oder Stromertrag bei Photovoltaik. Beide Ansätze stellen zusätzliche Anforderungen an Statik, Wartungszugang und Anschlussdetails, die bei klassischen Fassaden nicht anfallen.',NULL,NULL,'{}'::text[],'[]'::jsonb,NULL,162),
('kfa3boden','k',3,'kfa2gruen','Bodengebundene und wandgebundene Begrünung','Bodengebundene Begrünung wächst aus dem Erdreich an der Fassade hoch und braucht Rankhilfen, wandgebundene Systeme tragen Substrat oder Pflanztaschen direkt an der Wand und benötigen dafür eine eigene Bewässerungstechnik. Wandgebundene Systeme sind aufwendiger und wartungsintensiver, wirken dafür unabhängig von der Gebäudehöhe sofort.',NULL,NULL,'{}'::text[],'[]'::jsonb,NULL,163),
('kfa3pv','k',3,'kfa2gruen','Photovoltaik und Solarthermie in der Fassade','Als vorgehängte Fassadenbekleidung übernehmen Photovoltaikmodule zugleich Witterungsschutz und Stromerzeugung, allerdings mit geringerem Ertrag als auf dem Dach, weil die vertikale Ausrichtung weniger Einstrahlung sammelt. Solarthermische Fassaden sind seltener, folgen aber demselben Prinzip für die Wärmeerzeugung statt für Strom.',NULL,NULL,'{}'::text[],'[]'::jsonb,NULL,164),
('kda1','k',1,NULL,'Dach','Das Dach schützt das Gebäude vor Wasser, Kälte und Sonne und ist zugleich fünfte Fassade und oft ungenutzte Fläche mit Potenzial. Es vereint mehr bauphysikalische Anforderungen auf kleinem Raum als fast jedes andere Bauteil: Wärmeschutz, Abdichtung, Entwässerung und zunehmend auch Energieerzeugung und Regenrückhalt. Dieses Themenfeld gliedert sich nach Dachform, Entwässerung, Öffnungen und Nutzung der Dachfläche.',NULL,NULL,ARRAY['kfe1']::text[],'[]'::jsonb,NULL,165);
insert into public.nodes (id,perspective,level,parent_id,title,t1,t2,t3,links,sources,dach,ord) values
('kda2geneigt','k',2,'kda1','Geneigtes Dach','Das geneigte Dach ist die häufigste Dachform im mitteleuropäischen Wohnungsbau und leitet Wasser allein über Neigung und Schwerkraft ab. Seine Qualität entscheidet sich in zwei Schichten: dem tragenden und dämmenden Aufbau darunter und der sichtbaren Deckung darüber. Beide Schichten müssen aufeinander abgestimmt sein, sonst drohen Feuchteschäden, die erst Jahre später sichtbar werden.',NULL,NULL,'{}'::text[],'[]'::jsonb,NULL,166),
('kda3aufbau','k',3,'kda2geneigt','Kaltdach und Warmdach','Beim Kaltdach trennt eine belüftete Luftschicht die Dämmung von der Dachdeckung, beim Warmdach liegt die Dämmung direkt unter der Abdichtung ohne Belüftung. Die Wahl entscheidet über Aufbauhöhe, Diffusionsverhalten und wie fehlertolerant die Konstruktion gegenüber kleinen Ausführungsmängeln ist. Im Neubau dominiert heute das Warmdach, das Kaltdach bleibt vor allem bei der Sanierung im Bestand relevant.',NULL,NULL,'{}'::text[],'[]'::jsonb,NULL,167),
('kda3deckung','k',3,'kda2geneigt','Deckungsarten: Ziegel, Schiefer, Metall','Die Deckung ist die einzige Schicht des geneigten Dachs, die man tatsächlich sieht, und prägt damit das Erscheinungsbild eines Hauses fast so stark wie die Fassade. Ziegel und Schiefer stehen für Masse und regionale Tradition, Metalldeckungen für flache Neigungen und eine klare, moderne Anmutung. Jede Deckungsart verlangt eine eigene Mindestneigung, unterhalb derer Wasser nicht mehr sicher abgeführt wird.',NULL,NULL,'{}'::text[],'[]'::jsonb,NULL,168),
('kda3daemm','k',3,'kda2geneigt','Dämmebenen im Sparrenfeld','Zwischensparrendämmung ist günstig, lässt aber Wärmebrücken an jedem Sparren zu, Aufsparrendämmung liegt durchgängig über der Tragkonstruktion und vermeidet das, kostet aber mehr Aufbauhöhe und Geld. Untersparrendämmung ergänzt meist nur nachträglich, wenn eine der beiden anderen Ebenen nicht ausreicht. Die Entscheidung fällt am besten schon in der Statik, weil sie die Sparrenhöhe mitbestimmt.',NULL,NULL,'{}'::text[],'[]'::jsonb,NULL,169),
('kda2flach','k',2,'kda1','Flachdach','Das Flachdach hat keine Deckung im klassischen Sinn, sondern eine durchgehende Abdichtungsschicht, die dauerhaft dicht bleiben muss, denn es gibt keine zweite Verteidigungslinie. Es gewinnt nutzbare Fläche, verlangt dafür aber höchste Sorgfalt bei Gefälle, Anschlüssen und Durchdringungen. Wo am geneigten Dach ein kleiner Fehler abtropft, staut er sich hier.',NULL,NULL,'{}'::text[],'[]'::jsonb,NULL,170),
('kda3warmdach','k',3,'kda2flach','Warmdach und Umkehrdach','Beim klassischen Warmdach liegt die Dämmung unter der Abdichtung und ist vor Witterung geschützt, beim Umkehrdach liegt sie darüber und schützt umgekehrt die Abdichtung vor Temperaturwechseln und mechanischer Beanspruchung. Umkehrdächer brauchen dafür diffusionsoffene, wasserunempfindliche Dämmstoffe und eine Auflastschicht, die die Platten gegen Aufschwimmen sichert. Die Wahl hängt stark von der geplanten Nutzung der Fläche ab.',NULL,NULL,'{}'::text[],'[]'::jsonb,NULL,171),
('kda3abdicht','k',3,'kda2flach','Abdichtungsbahnen und Systeme','Bitumenbahnen, Kunststoffbahnen und Flüssigabdichtungen unterscheiden sich in Verarbeitung, Nahttechnik und Verhalten an komplizierten Details wie Durchdringungen oder Attikaecken. Die Systemwahl entscheidet mit über die Zahl der kritischen Nähte, denn jede Naht ist eine potenzielle Schwachstelle. Wichtiger als das Material ist oft, dass ein durchgängiges System von einem einzigen Verarbeiter kommt.',NULL,NULL,'{}'::text[],'[]'::jsonb,NULL,172),
('kda3gefaelle','k',3,'kda2flach','Gefälledämmung und Entwässerungsgefälle','Ein Flachdach ist selten wirklich flach: Eine Gefälledämmung aus keilförmig zugeschnittenen Dämmplatten formt das nötige Mindestgefälle zum Ablauf hin, ohne die Rohdecke schräg betonieren zu müssen. Ohne ausreichendes Gefälle bilden sich Pfützen, die die Abdichtung dauerhaft belasten und im Winter zur zusätzlichen Traglast werden. Die Gefällerichtung gehört deshalb schon in die frühe Entwurfsplanung, nicht erst ins Ausführungsdetail.',NULL,NULL,'{}'::text[],'[]'::jsonb,NULL,173),
('kda2entw','k',2,'kda1','Dachentwässerung','Jedes Dach muss Regenwasser kontrolliert ableiten, sonst sucht es sich seinen eigenen Weg, meist durch die Konstruktion hindurch. Außen liegende Rinnen und innen liegende Gullys folgen unterschiedlichen Regeln und werden nach Dachform und Gebäudehöhe gewählt. Zur Entwässerung gehört immer auch der Störfall: Was passiert, wenn der reguläre Abfluss verstopft.',NULL,NULL,'{}'::text[],'[]'::jsonb,NULL,174),
('kda3rinne','k',3,'kda2entw','Außenliegende Rinne und Fallrohr','Die klassische Dachrinne sammelt Wasser an der Traufe und führt es über Fallrohre am Gebäude entlang nach unten, sichtbar und einfach zu warten. Sie ist die günstigste und robusteste Lösung für geneigte Dächer, verlangt aber eine ausreichende Dimensionierung nach Dachfläche und Regenmenge der Region. Vereisung im Winter ist der häufigste Grund für Rinnenschäden.',NULL,NULL,'{}'::text[],'[]'::jsonb,NULL,175),
('kda3innen','k',3,'kda2entw','Innenliegende Entwässerung und Gully','Flachdächer und viele moderne Baukörper ohne sichtbare Traufe entwässern über Gullys, die durch die Dachfläche selbst führen und in die Gebäudetechnik einbinden. Das hält die Fassade ruhig, macht aber jeden Gully zu einer sensiblen Durchdringung der Abdichtung, die besonders sorgfältig angeschlossen werden muss. Die Zahl der Gullys richtet sich nach Dachfläche und den zulässigen Fließweglängen.',NULL,NULL,'{}'::text[],'[]'::jsonb,NULL,176),
('kda3notabl','k',3,'kda2entw','Notentwässerung und Überflutungsnachweis','Für den Fall, dass der reguläre Ablauf verstopft oder ein Starkregen seine Kapazität übersteigt, braucht jedes Flachdach einen zweiten, unabhängigen Wasserweg, etwa einen Notüberlauf durch die Attika. Ohne diese zweite Ebene wird die Dachhaut selbst zum Rückhaltebecken, mit entsprechender Last und Überflutungsrisiko für die darunterliegenden Geschosse. Der Nachweis der Notentwässerung gehört zur Tragwerksplanung, nicht nur zur Haustechnik.',NULL,NULL,'{}'::text[],'[]'::jsonb,NULL,177),
('kda2gauben','k',2,'kda1','Gauben, Öffnungen, Durchdringungen','Jede Öffnung im Dach, ob Gaube, Fenster oder Technikdurchführung, unterbricht die durchgehende Dämm- und Dichtebene und ist damit automatisch eine Detailaufgabe. Gauben schaffen zusätzlichen Raum und Licht im Dachgeschoss, verlangen dafür aber eine eigene kleine Dachkonstruktion mit eigenen Anschlüssen. Je mehr Durchdringungen ein Dach hat, desto mehr potenzielle Schwachstellen trägt es.',NULL,NULL,'{}'::text[],'[]'::jsonb,NULL,178),
('kda3gaubenform','k',3,'kda2gauben','Gaubenformen','Die Schleppgaube ist konstruktiv am einfachsten und fügt sich am ruhigsten ins Dach, die Satteldachgaube wirkt eigenständiger und kostet mehr Anschlussdetails, die Fledermausgaube verzichtet ganz auf senkrechte Wangen und verlangt handwerkliches Können in der Deckung. Die Formwahl ist damit auch eine Entscheidung über den Grad, in dem sich die Gaube dem Hauptdach unterordnet oder von ihm absetzt.',NULL,NULL,'{}'::text[],'[]'::jsonb,NULL,179),
('kda3lichtkuppel','k',3,'kda2gauben','Dachflächenfenster und Lichtkuppeln','Wo eine Gaube zu aufwendig ist, bringt ein in die Dachfläche eingebautes Fenster Licht ins Geschoss, ohne die Dachform zu verändern. Lichtkuppeln erweitern dieses Prinzip auf Flachdächer und größere, oft gewölbte Verglasungen für fensterlose Innenräume. Beide Bauteile verlangen einen eigenen, werkseitig geprüften Anschluss an die Dachabdichtung, improvisierte Lösungen sind hier die häufigste Leckagequelle.',NULL,NULL,ARRAY['kfe2glas']::text[],'[]'::jsonb,NULL,180);
insert into public.nodes (id,perspective,level,parent_id,title,t1,t2,t3,links,sources,dach,ord) values
('kda3durchdring','k',3,'kda2gauben','Durchdringungen der Dachfläche','Schornsteine, Lüftungsrohre, Antennenmasten und zunehmend Photovoltaikanlagen durchstoßen die Dachhaut an frei wählbaren Stellen, jede davon braucht ein eigenes Anschlussdetail. Photovoltaik verändert die Aufgabe zusätzlich: Sie liegt meist nicht durchdringend, sondern aufgeständert auf der Dachfläche und bringt zusätzliche Lasten und Wartungswege mit. Am wirtschaftlichsten ist es, alle Durchdringungen schon in der Planung zu bündeln, statt sie nachträglich zu verteilen.',NULL,NULL,'{}'::text[],'[]'::jsonb,NULL,181),
('kda2gruen','k',2,'kda1','Gründach und Retentionsdach','Ein begrüntes Dach ersetzt Regenwasserabfluss durch Rückhalt und Verdunstung und wird damit vom reinen Schutzbauteil zum aktiven Baustein im Umgang mit Starkregen. Extensive und intensive Begrünung unterscheiden sich vor allem in Aufbauhöhe, Pflegeaufwand und Lasten, die die Tragkonstruktion aufnehmen muss. Das Retentionsdach geht noch einen Schritt weiter und speichert Wasser gezielt, um städtische Kanalnetze zu entlasten.',NULL,NULL,'{}'::text[],'[]'::jsonb,NULL,182),
('kda3extensiv','k',3,'kda2gruen','Extensive Begrünung','Die extensive Begrünung ist eine dünne, pflegearme Schicht aus Substrat und robusten Pflanzen wie Sedum, die nach dem Anwachsen kaum noch Wartung braucht. Sie ist der wirtschaftliche Standard für Flachdächer ohne Nutzungsanspruch und lässt sich fast überall nachrüsten, wo die Statik eine geringe Zusatzlast erlaubt. Begehbar ist sie in der Regel nur zur Pflege, nicht als Aufenthaltsfläche.',NULL,NULL,'{}'::text[],'[]'::jsonb,NULL,183),
('kda3intensiv','k',3,'kda2gruen','Intensive Begrünung und Dachgarten','Intensive Begrünung erlaubt echte Gartenanlagen mit Stauden, Sträuchern und teils sogar Bäumen, verlangt dafür aber deutlich mehr Aufbauhöhe, Bewässerung und vor allem Tragreserven in der Decke. Sie verwandelt das Dach in eine nutzbare Freifläche und wird deshalb meist gemeinsam mit der Frage nach Terrassenflächen geplant. Die Lastannahmen für den Dachgarten gehören von Anfang an in die Tragwerksplanung, nicht als nachträgliche Ergänzung.',NULL,NULL,'{}'::text[],'[]'::jsonb,NULL,184),
('kda3retention','k',3,'kda2gruen','Retentionsdach und Regenwassermanagement','Das Retentionsdach hält Regenwasser gezielt für Stunden oder Tage zurück und gibt es gedrosselt an die Kanalisation ab, statt es sofort abzuleiten. Damit wird das Dach zum Teil der städtischen Regenwasserbewirtschaftung und kann in dicht bebauten Lagen sogar Voraussetzung für eine Baugenehmigung sein. Kombiniert mit Begrünung oder Photovoltaik entstehen Mehrfachnutzungen, die eine Dachfläche heute leisten muss.',NULL,NULL,'{}'::text[],'[]'::jsonb,NULL,185),
('kda2terrasse','k',2,'kda1','Dachterrassen und begehbare Flächen','Eine Dachterrasse stellt an dieselbe Abdichtung, die sonst nur Wasser abhalten muss, zusätzlich die Anforderung, dauerhaft begehbar und oft auch möbliert zu sein. Der Nutzbelag liegt dabei fast immer über einer separaten, geschützten Abdichtungsebene, niemals direkt auf ihr. Der Übergang von innen nach außen an der Terrassentür ist dabei eine der anspruchsvollsten Stellen der ganzen Gebäudehülle.',NULL,NULL,ARRAY['e2schwelle']::text[],'[]'::jsonb,NULL,186),
('kda3belag','k',3,'kda2terrasse','Belagsaufbau: Plattenlager und Holz','Terrassenplatten auf Stelzlagern liegen schwimmend über der Abdichtung, lassen sich einzeln aufnehmen und ermöglichen kontrollierte Wasserführung darunter. Holzbeläge auf Unterkonstruktion wirken wärmer, brauchen aber eine durchdachte Hinterlüftung, damit die Feuchtigkeit unter den Dielen wieder abtrocknen kann. Beide Systeme haben gemeinsam, dass die eigentliche Dichtheit unsichtbar darunter liegt und nie durch den Belag selbst hergestellt wird.',NULL,NULL,'{}'::text[],'[]'::jsonb,NULL,187),
('kda3abdichtterrasse','k',3,'kda2terrasse','Abdichtung unter der Nutzschicht','Unter jedem begehbaren Belag liegt eine hoch belastete Abdichtung, die zusätzlich zum Wasser auch mechanischen Verschleiß, Möbeldruck und punktuelle Lasten aushalten muss. Schutzlagen und Trennvliese verhindern, dass der Belag die Abdichtung direkt beschädigt, und müssen bei jeder Sanierung des Belags mitgedacht werden. Wer diese Ebene beim Entwurf vernachlässigt, saniert später die ganze Terrasse statt nur den Bodenbelag.',NULL,NULL,'{}'::text[],'[]'::jsonb,NULL,188),
('kda3attika','k',3,'kda2terrasse','Attika und Geländeranschluss','Die Attika schließt die Dachfläche nach oben ab, führt die Abdichtung hochkant weiter und ist zugleich meist der Ort, an dem ein aus Sicherheitsgründen nötiges Geländer befestigt wird. Beide Aufgaben, Dichtheit und Absturzsicherung, treffen an derselben Kante aufeinander und müssen ein gemeinsames Detail ergeben, keine zwei getrennten. Durchdringende Geländerpfosten sind dabei die häufigste Ursache für Undichtigkeiten an der Attika.',NULL,NULL,ARRAY['kt3gelh']::text[],'[]'::jsonb,NULL,189),
('kfe1','k',1,NULL,'Fenster und Verglasung','Fenster entscheiden über Licht, Aussicht, Lüftung und den Wärmehaushalt eines Gebäudes zugleich und sind damit eines der konfliktreichsten Bauteile der Planung. Kaum ein anderes Element verbindet so viele Gewerke: Rahmenbau, Glasindustrie, Sonnenschutz und die handwerkliche Montage am Baukörper. Dieses Themenfeld gliedert sich nach Konstruktion, Verglasung, Anschluss, Verschattung und den flankierenden Bauteilen.',NULL,NULL,ARRAY['k1','kda1']::text[],'[]'::jsonb,NULL,190),
('kfe2konstr','k',2,'kfe1','Fensterkonstruktionen und Rahmenmaterialien','Der Rahmen trägt das Glas, dichtet gegen Wind und Wetter und bestimmt zugleich, wie schlank oder massiv ein Fenster wirkt. Holz, Kunststoff, Aluminium und ihre Kombinationen unterscheiden sich in Wärmeleitung, Wartungsaufwand und der möglichen Profilschlankheit, nicht nur im Preis. Öffnungsart und Rahmenwahl zusammen entscheiden am Ende über Bedienkomfort, Dichtheit und Lebensdauer des ganzen Fensters.',NULL,NULL,'{}'::text[],'[]'::jsonb,NULL,191),
('kfe3rahmen','k',3,'kfe2konstr','Rahmenmaterialien','Holzrahmen dämmen von Natur aus gut und altern sichtbar, brauchen dafür regelmäßige Pflege der Oberfläche. Kunststoffrahmen sind wartungsarm und günstig, wirken aber massiver in der Ansichtsbreite. Aluminium ist formstabil und schlank, leitet Wärme jedoch stark und braucht deshalb eine thermische Trennung im Profil, Holz-Alu-Fenster verbinden die warme Innenseite mit der robusten Außenschale.',NULL,NULL,'{}'::text[],'[]'::jsonb,NULL,192),
('kfe3fluegel','k',3,'kfe2konstr','Flügeltypen und Öffnungsarten','Dreh- und Kippflügel sind der Wohnbaustandard und lassen sich sowohl weit öffnen als auch spaltlüften, Hebeschiebetüren und große Schiebeelemente öffnen raumhohe Fassaden fast schwellenlos zum Außenraum. Je größer und schwerer der Flügel, desto anspruchsvoller werden Beschlag und Rahmenstatik. Die Öffnungsart ist deshalb auch eine Frage der Elementgröße, nicht nur des Bedienkomforts.',NULL,NULL,ARRAY['k4null','k4schiebe']::text[],'[]'::jsonb,NULL,193),
('kfe3profil','k',3,'kfe2konstr','Profilsysteme und Bautiefe','Die Bautiefe eines Profils bestimmt, wie viele Dichtungsebenen und Kammern für Wärmedämmung Platz finden, und damit indirekt den erreichbaren Wärmeschutz. Schlanke, historisch anmutende Profile und hochgedämmte Passivhausprofile stehen deshalb in einem echten Zielkonflikt zwischen Optik und Energiebilanz. Bei der Sanierung denkmalgeschützter Fassaden ist dieser Konflikt oft die zentrale Planungsfrage.',NULL,NULL,'{}'::text[],'[]'::jsonb,NULL,194),
('kfe2glas','k',2,'kfe1','Verglasung (Wärme-, Sonnen-, Schallschutz)','Die Verglasung leistet heute den größten Teil dessen, was früher allein der Rahmen tragen musste: Wärmedämmung, Schallschutz, Sonnenschutz und Sicherheit stecken alle im Glasaufbau selbst. Mehrfachverglasungen mit Gasfüllung und beschichteten Scheiben haben den U-Wert von Glas in wenigen Jahrzehnten drastisch gesenkt. Die Herausforderung liegt heute weniger im einzelnen Glas als in der Kombination mehrerer, teils gegenläufiger Anforderungen in derselben Scheibe.',NULL,NULL,'{}'::text[],'[]'::jsonb,NULL,195);
insert into public.nodes (id,perspective,level,parent_id,title,t1,t2,t3,links,sources,dach,ord) values
('kfe3waermeglas','k',3,'kfe2glas','Wärmeschutzverglasung','Zwei oder drei Scheiben mit Gasfüllung im Zwischenraum und einer unsichtbaren, wärmereflektierenden Beschichtung bilden heute den Standard der Wärmeschutzverglasung. Je niedriger der U-Wert, desto weniger Heizenergie geht über das Fenster verloren, aber auch desto schwerer wird die Scheibe, was wiederum Rahmen und Beschlag stärker fordert. Die Wahl der Verglasung ist damit auch eine Frage der zulässigen Flügelgröße.',NULL,NULL,'{}'::text[],'[]'::jsonb,NULL,196),
('kfe3sonnenglas','k',3,'kfe2glas','Sonnenschutzverglasung und g-Wert','Der g-Wert beschreibt, wie viel Sonnenenergie eine Scheibe durchlässt, und ist damit das Gegenstück zum Wärmeschutz: Ein niedriger Wert hält im Sommer die Hitze draußen, schluckt im Winter aber auch willkommene Sonnenwärme. Sonnenschutzglas wirkt permanent und lässt sich, anders als ein bewegliches Verschattungssystem, nicht tageszeitabhängig steuern. Deshalb ersetzt es selten den mechanischen Sonnenschutz, sondern ergänzt ihn.',NULL,NULL,'{}'::text[],'[]'::jsonb,NULL,197),
('kfe3schallglas','k',3,'kfe2glas','Schallschutzverglasung','Schallschutz im Glas entsteht vor allem durch unterschiedlich dicke Scheiben im selben Element, denn gleiche Dicken schwingen im selben Frequenzbereich und schwächen sich gegenseitig kaum. Sonderfolien und breitere Scheibenzwischenräume verbessern die Dämmung zusätzlich, gehen aber zulasten von Gewicht und manchmal des Lichtdurchlasses. An lauten Lagen entscheidet oft weniger das Glas als die Fugendichtheit der gesamten Fensterkonstruktion über das tatsächliche Ergebnis.',NULL,NULL,ARRAY['k3schall']::text[],'[]'::jsonb,NULL,198),
('kfe2montage','k',2,'kfe1','Baukörperanschluss und Montage (RAL)','Ein Fenster ist nur so gut wie sein Anschluss an die Wand: Selbst das beste Element mit falscher Montage wird zur Schwachstelle für Wärme, Luft und Feuchte. Die RAL-Montage beschreibt drei getrennte Dichtebenen, innen luftdicht, außen schlagregendicht, dazwischen wärmegedämmt, die nie miteinander vertauscht werden dürfen. Weil die Montage nach der Rohbauöffnung, aber vor dem Innenausbau passiert, ist sie ein Nadelöhr im Bauablauf.',NULL,NULL,'{}'::text[],'[]'::jsonb,NULL,199),
('kfe3raldicht','k',3,'kfe2montage','Die drei Dichtungsebenen der RAL-Montage','Innen muss die Fuge luftdichter sein als außen, sonst wandert warme Innenluft in die Fuge, kühlt ab und die enthaltene Feuchte kondensiert in der Dämmebene. Diese Reihenfolge, innen dichter als außen, ist die wichtigste Regel der Montage und lässt sich nicht durch bessere Materialien allein reparieren, wenn die Prinzipien vertauscht werden. Vorkomprimierte Dichtbänder, Folien und Klebesysteme sind nur Werkzeuge, um dieses eine Prinzip umzusetzen.',NULL,NULL,'{}'::text[],'[]'::jsonb,NULL,200),
('kfe3laibung','k',3,'kfe2montage','Laibung, Sturz und Brüstung','Jede Fensteröffnung hat vier Anschlusskanten, Sturz, Brüstung und zwei seitliche Laibungen, und jede davon verlangt ein eigenes, sorgfältig durchdachtes Detail. Innenseitig treffen diese Anschlüsse häufig auf Trockenbau oder Putz, außenseitig auf WDVS oder eine hinterlüftete Fassade, mit jeweils eigenen Anschlussregeln. Wer die Laibung erst auf der Baustelle löst statt in der Planung, riskiert sichtbare Risse an genau dieser Stelle.',NULL,NULL,ARRAY['k6trocken','kiw3beplank']::text[],'[]'::jsonb,NULL,201),
('kfe3daemmkeil','k',3,'kfe2montage','Montagelage in der Dämmebene','Ein Fenster, das mittig in der Wärmedämmung statt in der tragenden Wand sitzt, vermeidet Wärmebrücken deutlich besser als die klassische Montage in der Mauerwerksebene. Diese vorgesetzte oder vorgemauerte Montage braucht dafür eine tragfähige Konsole oder einen Montagerahmen, der die Lasten zusätzlich in die Wand einleitet. Bei WDVS-Fassaden ist die vorgesetzte Montage inzwischen fast Standard, bei tragenden Vormauerschalen bleibt sie eine Sonderlösung.',NULL,NULL,'{}'::text[],'[]'::jsonb,NULL,202),
('kfe2sonnenschutz','k',2,'kfe1','Sonnenschutz und Verschattung','Verschattung ist der bewegliche, tageszeitlich steuerbare Teil des sommerlichen Wärmeschutzes und ergänzt die feste Sonnenschutzverglasung dort, wo Flexibilität gefragt ist. Außen liegender Sonnenschutz wirkt bauphysikalisch am wirksamsten, weil er die Wärme vor der Scheibe abfängt statt dahinter. Die Wahl des Systems ist zugleich eine Fassadenentscheidung, denn Kästen, Führungsschienen und Antriebe wollen von Anfang an mitgeplant sein.',NULL,NULL,'{}'::text[],'[]'::jsonb,NULL,203),
('kfe3aussenliegend','k',3,'kfe2sonnenschutz','Außenliegender Sonnenschutz','Raffstoren mit neigbaren Lamellen erlauben Verschattung bei gleichzeitigem Ausblick, Rollläden blocken vollständig und übernehmen nebenbei Einbruch- und Sichtschutz in der Nacht. Weil die Sonnenwärme hier vor dem Glas abgefangen wird, bevor sie überhaupt in den Raum gelangt, ist außen liegender Sonnenschutz dem innen liegenden bauphysikalisch klar überlegen. Der Preis dafür ist ein Fassadenelement, das Wind, Wetter und Wartungszugang aushalten muss.',NULL,NULL,'{}'::text[],'[]'::jsonb,NULL,204),
('kfe3innenliegend','k',3,'kfe2sonnenschutz','Innenliegender und integrierter Sonnenschutz','Innen liegende Systeme wie Vorhänge oder Jalousien sind einfach nachzurüsten und ungeschützt gegen Wind, verhindern die Aufheizung des Raumes aber erst, nachdem die Sonnenwärme bereits durch das Glas gedrungen ist. Zwischen den Scheiben integrierte Lamellen verbinden beide Welten: geschützt wie innen liegende Systeme, aber näher an der Wirksamkeit außen liegender. Sie sind allerdings bei Defekt kaum zugänglich, ein Kompromiss, der früh mitentschieden werden muss.',NULL,NULL,'{}'::text[],'[]'::jsonb,NULL,205),
('kfe3steuerung','k',3,'kfe2sonnenschutz','Steuerung und Verschattungsautomation','Manuell bedienter Sonnenschutz wird in der Praxis selten optimal genutzt, weil niemand ständig nachjustiert, automatisierte Steuerung nach Sonnenstand, Helligkeit oder Windgeschwindigkeit hält den Ertrag konstanter. Die Automation ist zugleich ein Sicherheitsthema, denn Windwächter müssen Lamellen bei Sturm rechtzeitig einfahren, bevor sie beschädigt werden. Je mehr Fensterflächen ein Gebäude hat, desto stärker rechtfertigt sich der Aufwand einer zentralen Steuerung.',NULL,NULL,'{}'::text[],'[]'::jsonb,NULL,206),
('kfe2bank','k',2,'kfe1','Fensterbänke innen/außen','Die Fensterbank ist ein kleines Bauteil mit großer Wirkung: außen schützt sie die Fassade unter dem Fenster vor Schlagregen, innen bildet sie die Möbelkante des Raumes. Beide Bänke werden oft getrennt betrachtet, gehören aber zum selben Anschluss und sollten gemeinsam geplant werden. Fehler an der äußeren Fensterbank zeigen sich meist erst Jahre später als Fassadenschaden.',NULL,NULL,'{}'::text[],'[]'::jsonb,NULL,207),
('kfe3bankaussen','k',3,'kfe2bank','Außenfensterbank und Entwässerung','Die äußere Fensterbank führt Schlagregen von der Fassade weg und braucht dafür ein durchgängiges Gefälle sowie hochgezogene, wasserdichte Seitenteile, sogenannte Aufkantungen, an den Laibungen. Wird dieser seitliche Anschluss vernachlässigt, läuft Wasser genau dort in die Fassade, wo man es am wenigsten erwartet. Material und Farbe der Bank sind eine Fassadenentscheidung, ihre Funktion aber ist reine Bauphysik.',NULL,NULL,'{}'::text[],'[]'::jsonb,NULL,208),
('kfe3bankinnen','k',3,'kfe2bank','Innenfensterbank als Möbel und Übergang','Innen wird die Fensterbank zur Ablage, Sitzfläche oder Heizkörperabdeckung und damit zu einem Möbelstück, das gleichzeitig eine bauliche Anschlussaufgabe löst. Ihre Tiefe entscheidet mit über die nutzbare Fensterlaibung als Sitzplatz, ihre Höhe über das Zusammenspiel mit einem darunterliegenden Heizkörper. Ohne Innenbank bleibt die Laibung roh, mit ihr wird sie Teil der Rauminszenierung.',NULL,NULL,'{}'::text[],'[]'::jsonb,NULL,209),
('kfe3bankmat','k',3,'kfe2bank','Materialwahl der Fensterbank','Naturstein und Kunststein sind robust und pflegeleicht und deshalb der Standard für die wetterexponierte Außenbank, Holz und Kunststoff dominieren innen, wo Haptik und Wärme zählen. Metallbänke tauchen an beiden Seiten auf, außen als schlanke, moderne Alternative, innen selten wegen der geringen Wärmedämmung im Kontakt. Die Materialwahl folgt damit weniger dem Geschmack als der jeweiligen Beanspruchung.',NULL,NULL,'{}'::text[],'[]'::jsonb,NULL,210);
insert into public.nodes (id,perspective,level,parent_id,title,t1,t2,t3,links,sources,dach,ord) values
('kfe2absturz','k',2,'kfe1','Absturzsicherung am Fenster','Sobald ein Fenster tief genug herunterreicht, dass ein Sturz aus ihm möglich ist, wird Absturzsicherung zur Pflichtaufgabe, nicht zur gestalterischen Kür. Die Lösung reicht vom einfachen Geländer über absturzsichernde Verglasung bis zur festen Brüstungshöhe, die den Konflikt gar nicht erst entstehen lässt. Bei raumhohen Fenstern und Balkontüren wird dieses Thema besonders häufig übersehen, weil es im Entwurf spät auftaucht.',NULL,NULL,'{}'::text[],'[]'::jsonb,NULL,211),
('kfe3absturzhoehe','k',3,'kfe2absturz','Brüstungshöhen und Sicherungspflicht','Ab welcher Absturzhöhe eine Sicherung Pflicht wird und wie hoch sie mindestens sein muss, hängt von der Nutzung des Raumes und der Fallhöhe dahinter ab und ist eines der wenigen Fenstermaße mit direkter Sicherheitsrelevanz. Bei Fenstern mit geringer Brüstungshöhe, etwa raumhohen Elementen, wird die Absturzsicherung zur zentralen Entwurfsaufgabe statt zur Nachkontrolle. Die genauen Höhen unterscheiden sich zwischen den DACH-Ländern und gehören früh geklärt.',NULL,NULL,ARRAY['kt3gelh']::text[],'[]'::jsonb,NULL,212),
('kfe3absturzglas','k',3,'kfe2absturz','Absturzsichernde Verglasung','Verbundsicherheitsglas kann die Funktion eines Geländers übernehmen, wenn es als geprüftes System für Absturzsicherung ausgelegt ist, und macht dann ein zusätzliches Geländer überflüssig. Das setzt eine bestimmte Scheibendicke und einen eigens geprüften Nachweis voraus, ein normales Isolierglas reicht dafür nicht. Gestalterisch verspricht die Lösung freie Sicht ohne Brüstung, konstruktiv bleibt sie anspruchsvoll in der Befestigung.',NULL,NULL,'{}'::text[],'[]'::jsonb,NULL,213),
('kfe3absturzgel','k',3,'kfe2absturz','Vorgesetzte Geländer und Fenstergitter','Wo Verglasung allein nicht ausreicht oder nicht gewollt ist, sichert ein vor das Fenster gesetztes Geländer oder Gitter die Öffnung, innen oder außen montiert. Innen liegende Geländer beanspruchen Raumfläche und müssen mit der Fensterbank koordiniert werden, außen liegende werden Teil der Fassadenoptik. Beide Varianten müssen dieselben Kräfte aufnehmen wie ein Treppengeländer, nur horizontal statt entlang eines Laufs.',NULL,NULL,ARRAY['kt3fuell']::text[],'[]'::jsonb,NULL,214),
('kiw1','k',1,NULL,'Innenwände und Trockenbau','Innenwände organisieren den Grundriss, oft lange nach dem Rohbau und mit deutlich mehr Freiheit als tragende Wände. Ob massiv gemauert oder als Trockenbaukonstruktion errichtet, entscheidet über Schallschutz, Montagefreiheit und wie leicht ein Grundriss sich später noch verändern lässt. Dieses Themenfeld gliedert sich nach Bauweise, Installation und besonderen Anforderungen wie Feuchte- und Brandschutz.',NULL,NULL,ARRAY['k1']::text[],'[]'::jsonb,NULL,215),
('kiw2massiv','k',2,'kiw1','Massive Innenwände','Massive Innenwände aus Mauerwerk oder Beton sind schwer, formstabil und bringen von Natur aus Schallschutz mit, den Trockenbau erst technisch nachbilden muss. Sie eignen sich, wo Wände tragend sind, wo hohe Lasten angehängt werden oder wo massive Bauweise ohnehin die Struktur des Gebäudes prägt. Der Preis dieser Robustheit ist geringere Flexibilität: Eine massive Wand versetzt man nicht mehr in einem Wochenende.',NULL,NULL,'{}'::text[],'[]'::jsonb,NULL,216),
('kiw3mauerwerk','k',3,'kiw2massiv','Mauerwerk als Innenwand','Kalksandstein und Ziegel sind die klassischen Innenwandbaustoffe und liefern schon durch ihre Masse gute Schalldämmwerte, ganz ohne zusätzliche Dämmschicht. Sie eignen sich besonders für tragende Innenwände und für Bereiche mit hohen Anforderungen an Schall oder Brandschutz, etwa zwischen Wohnungen. Nachteil ist die deutlich längere Trocknungs- und Bauzeit gegenüber dem Trockenbau.',NULL,NULL,'{}'::text[],'[]'::jsonb,NULL,217),
('kiw3beton','k',3,'kiw2massiv','Stahlbetoninnenwände','Betoninnenwände werden meist dort eingesetzt, wo sie ohnehin tragend oder aussteifend wirken, etwa als Treppenhauswand oder Kern eines Gebäudes. Ihre Masse macht sie akustisch fast unschlagbar, ihre Herstellung im Ortbeton bindet aber Schalung und Bauzeit, die eine Trockenbauwand nicht braucht. Sichtbetonoberflächen können die Wand zugleich zur fertigen Ansichtsfläche machen, ganz ohne weiteren Ausbau.',NULL,NULL,'{}'::text[],'[]'::jsonb,NULL,218),
('kiw3porenbeton','k',3,'kiw2massiv','Porenbeton und Trennwandplatten','Porenbeton und großformatige Gips-Trennwandplatten liegen zwischen Mauerwerk und Trockenbau: leichter und schneller zu verarbeiten als klassisches Mauerwerk, aber massiver und schwerer als eine Ständerwand. Sie eignen sich für nichttragende Innenwände mit moderatem Schallschutzanspruch, etwa im Wohnungsbau zwischen Zimmern derselben Nutzungseinheit. Wegen ihrer Maßgenauigkeit brauchen sie oft nur eine dünne Spachtelschicht statt vollflächigen Putz.',NULL,NULL,'{}'::text[],'[]'::jsonb,NULL,219),
('kiw2trocken','k',2,'kiw1','Trockenbauwände (Ständerwerk, Beplankung)','Die Trockenbauwand baut Schallschutz, Brandschutz und Formstabilität nicht aus Masse, sondern aus dem Zusammenspiel von Metallständerwerk, Beplankung und Dämmung im Hohlraum. Sie ist leicht, schnell montiert und im Grundriss vergleichsweise einfach zu verändern, solange keine Installation im Weg ist. Ihre Qualität hängt fast vollständig von der korrekten Ausführung ab, nicht vom Material allein.',NULL,NULL,'{}'::text[],'[]'::jsonb,NULL,220),
('kiw3staender','k',3,'kiw2trocken','Ständerwerk: Profile und Dimensionierung','CW-Profile bilden die vertikalen Ständer, UW-Profile die horizontalen Anschlüsse an Boden und Decke, ihre Breite bestimmt vor allem die spätere Wanddicke und den möglichen Dämmstoffquerschnitt. Die Statik des Ständerwerks wird schnell unterschätzt: Wandhöhe, Beplankungsgewicht und angehängte Lasten wie Waschbecken oder Regale bestimmen, welches Profil und welcher Ständerabstand nötig sind. Wo schwere Türen oder Lasten geplant sind, braucht das Ständerwerk zusätzliche Verstärkung.',NULL,NULL,'{}'::text[],'[]'::jsonb,NULL,221),
('kiw3beplank','k',3,'kiw2trocken','Beplankung: Gipskarton, Gipsfaser, Zement','Gipskartonplatten sind der Standard für trockene Räume, Gipsfaserplatten sind robuster und eignen sich für höhere mechanische Beanspruchung, Zementplatten übernehmen Feuchträume und Außenbereiche. Die Zahl der Plattenlagen, einfach oder doppelt beplankt, beeinflusst Schall- und Brandschutz direkt und ist eine der wenigen Stellschrauben, die sich ohne Mehrkosten am Ständerwerk selbst realisieren lässt. Die Plattenwahl folgt also der Beanspruchung, nicht der Optik, denn sichtbar wird ohnehin nur der Anstrich darüber.',NULL,NULL,'{}'::text[],'[]'::jsonb,NULL,222),
('kiw3daemmung','k',3,'kiw2trocken','Dämmung im Ständerhohlraum','Die Mineralwolle im Hohlraum zwischen den Ständern übernimmt bei der Trockenbauwand die Aufgabe, die bei der massiven Wand allein die Masse leistet: Sie schluckt Schall und verbessert nebenbei den Brandschutz. Wie gut sie wirkt, hängt stark vom lückenlosen Einbau ab, denn schon kleine Fugen oder Hohlräume mindern die Dämmwirkung überproportional. Eine ungedämmte Trockenbauwand ist akustisch fast wertlos, egal wie gut die Beplankung ist.',NULL,NULL,'{}'::text[],'[]'::jsonb,NULL,223),
('kiw3tuerintegr','k',3,'kiw2trocken','Türöffnungen und Aussteifung im Ständerwerk','Jede Türöffnung unterbricht das Ständerwerk und muss die fehlende Aussteifung durch verstärkte Profile am Rahmen wieder ausgleichen, besonders bei schweren Türblättern. Wird diese Verstärkung vergessen, zeigt sich das Problem oft erst nach Jahren als schiefe Zarge oder klemmendes Blatt. Die Abstimmung zwischen Türenplanung und Trockenbau-Ausschreibung gehört deshalb an den Anfang der Planung, nicht ans Ende.',NULL,NULL,ARRAY['k6trocken']::text[],'[]'::jsonb,NULL,224),
('kiw2vorsatz','k',2,'kiw1','Vorsatzschalen und Installationswände','Vorsatzschalen und Installationswände sind Trockenbauwände mit einer zweiten Aufgabe: Sie verbergen Leitungen und Rohre oder verbessern den Schallschutz einer bestehenden massiven Wand, ohne diese selbst zu verändern. Der Hohlraum dahinter wird zur Installationsebene, die Wartungszugänge und Revisionsöffnungen braucht, sonst ist jede Reparatur ein Wandaufbruch. Wo Sanitärobjekte hängen, ist die Installationswand meist wirtschaftlicher als das Verlegen von Leitungen im massiven Mauerwerk.',NULL,NULL,'{}'::text[],'[]'::jsonb,NULL,225);
insert into public.nodes (id,perspective,level,parent_id,title,t1,t2,t3,links,sources,dach,ord) values
('kiw3vorsatz','k',3,'kiw2vorsatz','Vorsatzschale vor Massivwand','Eine entkoppelte, auf eigenem Ständerwerk stehende Vorsatzschale verbessert den Schallschutz einer bestehenden Wand oft wirksamer als jede Dämmmaßnahme an der Wand selbst, weil sie die Schwingung mechanisch trennt. Wichtig ist die tatsächliche Entkopplung: Berührt die Vorsatzschale die massive Wand an nur einer Stelle, geht ein Großteil der Wirkung verloren. Sie eignet sich besonders zur nachträglichen Ertüchtigung im Bestand, wo die massive Wand nicht angetastet werden soll oder darf.',NULL,NULL,'{}'::text[],'[]'::jsonb,NULL,226),
('kiw3installwand','k',3,'kiw2vorsatz','Installationswand für Sanitärobjekte','Die Installationswand nimmt Spülkästen, Anschlüsse und Befestigungen für Waschbecken, WC und Bidet auf und macht Sanitärräume unabhängig von der Lage tragender Wände. Sie muss so verstärkt sein, dass hängende Objekte die vollen Nutzlasten sicher aufnehmen, ein reiner Standard-Ständer reicht dafür nicht. Weil sie Sanitär- und Trockenbaugewerk direkt verbindet, ist sie ein klassischer Ort für Schnittstellenfehler, wenn die Gewerke nicht abgestimmt planen.',NULL,NULL,'{}'::text[],'[]'::jsonb,NULL,227),
('kiw3schacht','k',3,'kiw2vorsatz','Schächte und Revisionsöffnungen','Installationsschächte bündeln vertikale Leitungsführung über mehrere Geschosse und brauchen an jeder Etage kontrollierten, zugänglichen Zugriff für Wartung und Reparatur. Eine vergessene Revisionsöffnung bedeutet im Schadensfall, dass eine fertige Wand wieder aufgestemmt werden muss. Brandschutztechnisch sind Schachtabschottungen an jeder Geschossdecke Pflicht, damit sich Feuer nicht ungehindert vertikal ausbreitet.',NULL,NULL,'{}'::text[],'[]'::jsonb,NULL,228),
('kiw2schall','k',2,'kiw1','Schallschutz im Innenausbau','Schallschutz im Innenausbau entscheidet sich selten an der Wand allein, sondern an ihren Rändern: Anschlussfugen, Türen und flankierende Bauteile leiten Schall oft stärker weiter als die Wandfläche selbst. Wer nur die Wandkonstruktion optimiert und die Details ringsherum vernachlässigt, verschenkt einen Großteil der möglichen Dämmwirkung. Bewohner bemerken diesen Unterschied unmittelbar, lange bevor sie ihn benennen können.',NULL,NULL,'{}'::text[],'[]'::jsonb,NULL,229),
('kiw3trennwand','k',3,'kiw2schall','Trennwände zwischen Nutzungseinheiten','Wände zwischen fremden Wohnungen oder Nutzungseinheiten tragen die höchsten Schallschutzanforderungen im Innenausbau, weil hier fremder Lärm besonders störend empfunden wird. Erhöhter Schallschutz über dem gesetzlichen Mindestmaß ist längst Erwartungshaltung im Wohnungsbau, auch wenn er selten ausdrücklich beauftragt wird. Zweischalige, entkoppelte Konstruktionen erreichen hier deutlich mehr als jede einschalige Wand, egal wie dick.',NULL,NULL,'{}'::text[],'[]'::jsonb,NULL,230),
('kiw3flankierend','k',3,'kiw2schall','Flankierende Bauteile und Schallnebenwege','Schall umgeht eine noch so gut gedämmte Trennwand über die angrenzenden Bauteile, Decke, Fassade und Nachbarwände, wenn diese schallhart durchgekoppelt sind. Dieser Nebenweg heißt Flankenübertragung und ist der Grund, warum eine rechnerisch perfekte Wand in der Praxis oft schlechter abschneidet als geplant. Vorsatzschalen an den flankierenden Bauteilen sind das Standardmittel, diesen Nebenweg zu unterbrechen.',NULL,NULL,'{}'::text[],'[]'::jsonb,NULL,231),
('kiw3tuerfuge','k',3,'kiw2schall','Türen und Fugen als Schallschwäche','Selbst in einer schallschutzoptimierten Wand bleibt die Tür fast immer die schwächste Stelle, weil jede bewegliche Fuge Kompromisse gegenüber einer festen Wand eingeht. Absenkdichtungen am Boden und umlaufende Falzdichtungen kompensieren das, erreichen aber nur mit exakter Montage die Werte, die eine spezielle Schallschutztür verspricht. Wer im Grundriss eine leise Wand plant und dann eine Standardtür einsetzt, hat die Wand umsonst optimiert.',NULL,NULL,ARRAY['k3schall']::text[],'[]'::jsonb,NULL,232),
('kiw2sonder','k',2,'kiw1','Trennwände in Sonderfunktion','Manche Innenwände lösen mehr als nur eine Aufgabe: Sie trennen Räume und schützen gleichzeitig vor Feuchte, Feuer oder Rauch. Diese Sonderfunktionen verlangen geprüfte Systemaufbauten statt freier Materialwahl, weil ihre Wirksamkeit nachgewiesen sein muss. Wer hier improvisiert, verliert nicht nur Qualität, sondern oft auch die bauaufsichtliche Zulassung der gesamten Konstruktion.',NULL,NULL,'{}'::text[],'[]'::jsonb,NULL,233),
('kiw3nasszelle','k',3,'kiw2sonder','Wände im Nassraum','Wände in Bad und Dusche brauchen eine durchgängige Abdichtungsebene, bevor die erste Fliese verlegt wird, denn Fliesen selbst sind nicht wasserdicht, nur die Fugen zwischen ihnen. Im Trockenbau übernehmen zementgebundene oder beschichtete Platten diese Aufgabe, im Massivbau eine separate Verbundabdichtung. Besonders kritisch sind Ecken, Durchdringungen für Armaturen und der Übergang zum Bodenbelag, denn dort versagt Abdichtung am häufigsten.',NULL,NULL,'{}'::text[],'[]'::jsonb,NULL,234),
('kiw3brandwand','k',3,'kiw2sonder','Brandwände und Trennwände','Brandwände müssen ein Feuer für eine definierte Zeit vollständig aufhalten und dürfen dabei auch bei einseitigem Einsturz der angrenzenden Konstruktion nicht versagen, eine der härtesten Anforderungen im Innenausbau. Jede Öffnung in einer solchen Wand, ob Tür oder Leitungsdurchführung, braucht ein eigenes geprüftes System, das den Feuerwiderstand der Wand fortsetzt statt zu unterbrechen. Die Wand ist also nur so gut wie ihre schwächste Durchdringung.',NULL,NULL,ARRAY['k3t30']::text[],'[]'::jsonb,NULL,235),
('kiw3rauch','k',3,'kiw2sonder','Rauchschutzwände in Fluchtwegen','Rauch tötet bei Bränden häufiger als Feuer selbst, deshalb sichern Rauchschutzwände Fluchtwege gegen das Eindringen von Rauch ab, auch wenn sie keinen vollen Feuerwiderstand leisten müssen. Entscheidend sind dichte Anschlussfugen und selbstschließende Öffnungen, denn schon eine dauerhaft offenstehende Rauchschutztür macht die ganze Wand wirkungslos. Diese Wände sind deshalb organisatorisch so anspruchsvoll wie konstruktiv.',NULL,NULL,ARRAY['k3rs']::text[],'[]'::jsonb,NULL,236),
('kbo1','k',1,NULL,'Böden und Beläge','Böden sind die am stärksten benutzte Fläche im Gebäude: Sie tragen Lasten, dämmen Schall, führen Heizwärme und entscheiden allein durch Material und Fuge über die Anmutung eines Raums. Dieses Themenfeld gliedert sich vom tragenden Estrich über die Fußbodenheizung bis zum sichtbaren Belag und seinen Übergängen.',NULL,NULL,'{}'::text[],'[]'::jsonb,NULL,237),
('kbo2estrich','k',2,'kbo1','Estriche und Bodenaufbauten','Der Estrich ist die tragende, ebene Schicht zwischen Rohdecke und Belag; er nimmt Lasten auf, gleicht Unebenheiten aus und bettet oft die Fußbodenheizung ein. Seine Wahl entscheidet über Trocknungszeit, den Zeitpunkt, ab dem der Belag aufgebracht werden darf, und die zulässige Belastung des gesamten Aufbaus.',NULL,NULL,'{}'::text[],'[]'::jsonb,NULL,238),
('kbo3zement','k',3,'kbo2estrich','Zementestrich','Zementestrich ist der robuste Standard: unempfindlich gegen Feuchte während der Bauphase, gut für Nassräume geeignet, aber mit vergleichsweise langer Trocknungszeit. Er verträgt raue Baustellenbedingungen besser als jede Alternative und bleibt deshalb im Rohbau die sichere Wahl.',NULL,NULL,'{}'::text[],'[]'::jsonb,NULL,239),
('kbo3calcium','k',3,'kbo2estrich','Calciumsulfatestrich (Anhydrit)','Anhydritestrich fließt beim Einbau selbstnivellierend, trocknet schneller als Zementestrich und eignet sich besonders gut für Fußbodenheizungen, weil er die Wärme gleichmäßig überträgt. Seine Schwäche ist die Feuchteempfindlichkeit: Schon kurzer Wasserkontakt vor der Belegung kann die Festigkeit dauerhaft schädigen.',NULL,NULL,'{}'::text[],'[]'::jsonb,NULL,240);
insert into public.nodes (id,perspective,level,parent_id,title,t1,t2,t3,links,sources,dach,ord) values
('kbo3daemm','k',3,'kbo2estrich','Schwimmender Estrich und Trittschall','Beim schwimmenden Estrich liegt die Estrichplatte auf einer Dämmschicht, vollständig von Wänden und Rohdecke akustisch getrennt. Diese Entkopplung ist die wirksamste bauliche Maßnahme gegen Trittschall, den Schall, den Gehen und Stöße auf dem Boden ins Geschoss darunter übertragen, und verzeiht keine Nebenwege wie eine mitgegossene Randfuge.',NULL,NULL,ARRAY['kt4schall']::text[],'[]'::jsonb,NULL,241),
('kbo2fbh','k',2,'kbo1','Fußbodenheizung im Aufbau','Die Fußbodenheizung liegt im oder unter dem Estrich und verwandelt die gesamte Fläche in eine Heizfläche mit niedriger Vorlauftemperatur. Für die Planung zählt weniger das Heizsystem selbst als sein Zusammenspiel mit Aufbauhöhe, Belag und Regelung, denn nachträgliche Korrekturen sind praktisch unmöglich.',NULL,NULL,'{}'::text[],'[]'::jsonb,NULL,242),
('kbo3nassfbh','k',3,'kbo2fbh','Nasssystem: Rohre im Estrich','Beim Nasssystem werden die Heizrohre direkt in den Estrich eingegossen, der dadurch selbst zum Wärmespeicher wird. Das ergibt ein träges, aber gleichmäßiges Raumklima, verlangt jedoch die größte Aufbauhöhe aller Fußbodenheizungssysteme.',NULL,NULL,'{}'::text[],'[]'::jsonb,NULL,243),
('kbo3trockenfbh','k',3,'kbo2fbh','Trockensystem im Bestand und Holzbau','Trockene Fußbodenheizungssysteme betten die Rohre in vorgefertigte Dämm- und Wärmeleitplatten statt in nassen Estrich und sparen dadurch Aufbauhöhe und Trocknungszeit. Sie sind die typische Lösung bei der Sanierung von Holzbalkendecken, reagieren wegen der geringeren Speichermasse aber auch schneller und unruhiger auf die Regelung.',NULL,NULL,'{}'::text[],'[]'::jsonb,NULL,244),
('kbo3fbhbelag','k',3,'kbo2fbh','Belagseignung über Fußbodenheizung','Nicht jeder Belag leitet Wärme gleich gut: Fliese und Naturstein geben sie fast ungebremst ab, dicker Teppich oder unpassendes Parkett dämmen sie spürbar. Wer den Belag erst nach der Heizlastberechnung wählt, riskiert eine Anlage, die ihre Leistung nie erreicht.',NULL,NULL,'{}'::text[],'[]'::jsonb,NULL,245),
('kbo2belag','k',2,'kbo1','Beläge','Der Belag ist die einzige Schicht des Bodenaufbaus, die man sieht und spürt, entsprechend groß ist seine Bandbreite von Parkett über Naturstein bis zu elastischen und gegossenen Systemen. Jede Gattung bringt ein eigenes Verhältnis aus Haptik, Pflegeaufwand und Belastbarkeit mit.',NULL,NULL,'{}'::text[],'[]'::jsonb,NULL,246),
('kbo3parkett','k',3,'kbo2belag','Parkett und Holzböden','Parkett bringt als einziger Bodenbelag ein natürlich gewachsenes Material in die Fläche, mit allen Vorzügen wie Wärme und Reparierbarkeit durch Abschliff und den Empfindlichkeiten von Massivholz gegenüber Feuchte und Kratzern. Verlegeart und Holzart entscheiden gemeinsam über Optik und Lebensdauer.',NULL,NULL,'{}'::text[],'[]'::jsonb,NULL,247),
('kbo3stein','k',3,'kbo2belag','Naturstein und Fliese','Naturstein und keramische Fliese sind die unempfindlichsten Beläge gegenüber Feuchte, Hitze und Nutzung und deshalb der Standard in Bad, Küche und stark frequentierten Flächen. Der Unterschied liegt im Detail: Naturstein streut in Maß und Farbe, Fliese ist normiert und beliebig nachbestellbar.',NULL,NULL,'{}'::text[],'[]'::jsonb,NULL,248),
('kbo3elast','k',3,'kbo2belag','Elastische und textile Beläge','Vinyl, Linoleum und Teppich sind elastische beziehungsweise textile Beläge, die leiser und wärmer unter dem Fuß sowie günstiger im Unterhalt sind als harte Beläge, dafür aber empfindlicher gegen Punktlasten und mechanische Beschädigung. Sie werden meist vollflächig verklebt oder lose verlegt, selten geschraubt oder genagelt.',NULL,NULL,'{}'::text[],'[]'::jsonb,NULL,249),
('kbo3giess','k',3,'kbo2belag','Gegossene Böden','Gegossene Böden aus Epoxidharz oder Zement werden flüssig aufgetragen und ergeben eine fugenlose, homogene Fläche, die gestalterisch reizvoll, aber reparaturaufwendig ist: Ein Riss oder ein Fleck lässt sich kaum unsichtbar ausbessern. Sie verlangen einen tragfähigen, absolut ebenen Untergrund, jede Unebenheit zeichnet sich ab.',NULL,NULL,'{}'::text[],'[]'::jsonb,NULL,250),
('kbo2sockel','k',2,'kbo1','Sockel- und Übergangsdetails','Am Wandfuß und an jedem Belagwechsel trifft der Boden auf eine andere Fläche oder ein anderes Material, und genau dort entscheidet sich, ob ein Bodenaufbau sauber wirkt. Sockelleisten, Übergangsprofile und Türanschlüsse sind klein im Material, aber groß in der Wirkung auf den Gesamteindruck.',NULL,NULL,'{}'::text[],'[]'::jsonb,NULL,251),
('kbo3sockelleiste','k',3,'kbo2sockel','Sockelleisten und Wandanschluss','Die Sockelleiste kaschiert die Bewegungsfuge zwischen Boden und Wand und schützt die Wandfläche vor Stößen, ihre Höhe und ihr Vorsprung sollten früh mit Zargenspiegel und Türanschlägen abgestimmt werden. Alternativen wie die Schattenfuge verzichten bewusst auf die Leiste zugunsten einer ruhigeren Fläche.',NULL,NULL,ARRAY['k5spiegel']::text[],'[]'::jsonb,NULL,252),
('kbo3belagwechsel','k',3,'kbo2sockel','Übergangsprofile zwischen Belägen','Wo zwei Beläge unterschiedlicher Dicke oder Härte aufeinandertreffen, braucht es ein Übergangsprofil, das den Höhenversatz auffängt und die Kante vor Ausbrüchen schützt. Die unauffälligste Lösung ist die exakt gleiche Aufbauhöhe beider Beläge, die aber selten ohne Zusatzaufwand gelingt.',NULL,NULL,'{}'::text[],'[]'::jsonb,NULL,253),
('kbo3tuerueberg','k',3,'kbo2sockel','Bodenübergang an der Tür','Unter jeder Tür trifft der Bodenaufbau auf die Schwelle, und genau hier addieren sich die Toleranzen aus Estrich, Belag und Zargenmaß. Wer die Belagsstärke erst nach der Zargenbestellung kennt, riskiert eine Schwelle, die zu hoch, zu niedrig oder schief sitzt.',NULL,NULL,ARRAY['k3schwelle','k5maul']::text[],'[]'::jsonb,NULL,254),
('kbo2doppel','k',2,'kbo1','Doppel- und Hohlraumböden','Doppel- und Hohlraumböden schaffen einen zugänglichen Raum unter der Nutzfläche für Kabel, Leitungen und Klimatechnik und lösen damit ein Problem, das ein klassischer Estrichaufbau gar nicht kennt: die spätere Änderung der Installation ohne Aufstemmen. Der Unterschied zwischen beiden Systemen liegt vor allem im Grad der Zugänglichkeit.',NULL,NULL,'{}'::text[],'[]'::jsonb,NULL,255);
insert into public.nodes (id,perspective,level,parent_id,title,t1,t2,t3,links,sources,dach,ord) values
('kbo3doppelboden','k',3,'kbo2doppel','Doppelboden: Aufbau und Zugänglichkeit','Der Doppelboden besteht aus einzelnen Platten auf höhenverstellbaren Stützen und lässt sich an jeder Stelle öffnen, ohne Nachbarflächen zu berühren. Diese vollständige Zugänglichkeit macht ihn zum Standard im Büro- und Rechenzentrumsbau, wo Installationen häufig geändert werden.',NULL,NULL,'{}'::text[],'[]'::jsonb,NULL,256),
('kbo3hohlraum','k',3,'kbo2doppel','Hohlraumboden: Nassestrich mit Kanälen','Der Hohlraumboden trägt eine geschlossene Estrichplatte auf Stützen, unter der Kabel in Kanälen statt frei im Raum liegen, geöffnet wird nur punktuell an vorgesehenen Revisionsstellen. Er ist ruhiger im Trittschall und günstiger als der Doppelboden, aber deutlich weniger flexibel nachrüstbar.',NULL,NULL,'{}'::text[],'[]'::jsonb,NULL,257),
('kbo3doppelwahl','k',3,'kbo2doppel','Systementscheidung Doppel- vs. Hohlraumboden','Die Wahl zwischen beiden Systemen ist selten eine Geschmacksfrage, sondern eine Nutzungsfrage: Wie oft ändert sich die Belegung, wie viel Aufbauhöhe steht zur Verfügung, wie wichtig ist Trittschall gegenüber Flexibilität. Wer das früh klärt, vermeidet einen teuren Systemwechsel mitten in der Ausführungsplanung.',NULL,NULL,'{}'::text[],'[]'::jsonb,NULL,258),
('kde1','k',1,NULL,'Deckenbekleidungen und Akustik','Die Decke ist die am wenigsten berührte, aber oft am meisten unterschätzte Fläche im Raum: Sie prägt Akustik, Lichtverteilung und die Sicht auf die technische Gebäudeausrüstung. Dieses Themenfeld reicht von der abgehängten Unterdecke über gezielte Raumakustik bis zur bewusst gezeigten Rohdecke.',NULL,NULL,'{}'::text[],'[]'::jsonb,NULL,259),
('kde2unterdecke','k',2,'kde1','Unterdecken und Abhangsysteme','Unterdecken hängen an einer eigenen Unterkonstruktion unter der Rohdecke und schaffen dort Raum für Leitungen, Dämmung und Akustik, den eine Sichtdecke nicht bieten kann. Material und Abhanghöhe entscheiden gemeinsam, wie viel Technik sich verstecken lässt und wie tief der Raum dadurch wirklich wird.',NULL,NULL,'{}'::text[],'[]'::jsonb,NULL,260),
('kde3gipskarton','k',3,'kde2unterdecke','Gipskarton-Unterdecke','Die Gipskartondecke ist die geschlossene, flächige Variante der Unterdecke: fugenlos verspachtelt wirkt sie wie eine massive Decke, erlaubt aber kaum punktuelle Revisionsöffnungen. Sie ist die Standardlösung überall dort, wo Ruhe in der Fläche wichtiger ist als spätere Zugänglichkeit.',NULL,NULL,'{}'::text[],'[]'::jsonb,NULL,261),
('kde3metall','k',3,'kde2unterdecke','Metall-Rasterdecke','Die Rasterdecke aus einzelnen, in ein Traggerüst eingelegten Platten macht jedes Feld einzeln zugänglich und ist deshalb Standard im Büro- und Objektbau, wo Leuchten, Sprinkler und Lüftung regelmäßig gewartet werden müssen. Der sichtbare Raster prägt die Deckenoptik so stark wie sonst kaum ein Bauteil.',NULL,NULL,'{}'::text[],'[]'::jsonb,NULL,262),
('kde3akustikplatte','k',3,'kde2unterdecke','Mineralfaser- und Akustikplatten','Poröse Mineralfaserplatten schlucken Schall, statt ihn zu reflektieren, und verbinden damit die Funktion der Unterdecke gleich mit der Raumakustik. Sie sind der einfachste Weg, ein akustisches Problem in einem Bestandsraum zu lösen, ohne die Wände anzufassen.',NULL,NULL,'{}'::text[],'[]'::jsonb,NULL,263),
('kde2akustik','k',2,'kde1','Raumakustik-Maßnahmen','Raumakustik regelt, wie lange und wie klar ein Schall im Raum nachklingt, unabhängig davon, wie gut der Raum gegen den Nachbarraum gedämmt ist. Wo Schallschutz Grenzen zwischen Räumen zieht, sorgt Raumakustik für Verständlichkeit innerhalb eines einzigen Raums, ein oft verwechseltes Begriffspaar.',NULL,NULL,'{}'::text[],'[]'::jsonb,NULL,264),
('kde3nachhall','k',3,'kde2akustik','Nachhallzeit als Planungsziel','Die Nachhallzeit beschreibt, wie lange ein Ton im Raum hörbar nachklingt, bis er verklungen ist, und ist die zentrale Zielgröße jeder Raumakustikplanung. Ein Klassenzimmer und ein Konzertsaal brauchen bewusst unterschiedliche Nachhallzeiten, weil Sprachverständlichkeit und musikalische Fülle gegensätzliche Anforderungen stellen.',NULL,NULL,'{}'::text[],'[]'::jsonb,NULL,265),
('kde3absorber','k',3,'kde2akustik','Absorber: Platten, Baffles, Wolken','Absorber wandeln Schallenergie in Wärme um, statt sie zu reflektieren, und kommen als Deckenplatte, als hängender Baffle oder als frei schwebende Wolke zum Einsatz, je nachdem wie viel Fläche zur Verfügung steht. Ihre Wirkung hängt stark von der Frequenz ab: Tiefe Töne brauchen deutlich mehr Material als hohe.',NULL,NULL,'{}'::text[],'[]'::jsonb,NULL,266),
('kde3akustikputz','k',3,'kde2akustik','Akustikputz und -spachtel','Akustikputz wirkt schallschluckend über eine mikroporöse Oberfläche und lässt sich dabei fugenlos wie eine gewöhnliche Putzdecke gestalten, ein Vorteil überall dort, wo sichtbare Platten oder Raster nicht gewünscht sind. Seine Absorptionswirkung bleibt jedoch meist hinter der von dickeren Faserabsorbern zurück.',NULL,NULL,'{}'::text[],'[]'::jsonb,NULL,267),
('kde2sicht','k',2,'kde1','Sichtdecken','Die Sichtdecke verzichtet bewusst auf jede Bekleidung und zeigt Beton oder Holz als tragendes Material zugleich als Oberfläche. Das spart eine ganze Bauschicht, verlangt aber von Rohbau und Ausbau eine Präzision, die eine verdeckte Decke nie beweisen müsste.',NULL,NULL,'{}'::text[],'[]'::jsonb,NULL,268),
('kde3sichtbeton','k',3,'kde2sicht','Sichtbetondecke','Bei der Sichtbetondecke wird die Schalhaut selbst zur gestalterischen Entscheidung, denn jede Fuge, jeder Ankerpunkt bleibt für immer sichtbar. Nachträgliche Leitungsführung ist praktisch ausgeschlossen, weshalb Elektro- und Lüftungsplanung schon vor dem Betonieren feststehen müssen.',NULL,NULL,'{}'::text[],'[]'::jsonb,NULL,269),
('kde3sichtholz','k',3,'kde2sicht','Sichtholzdecke: Balken- und Massivholz','Holzbalken- oder Massivholzdecken zeigen ihre Konstruktion als Oberfläche und bringen damit Wärme und Struktur in den Raum, verlangen aber wie die Sichtbetondecke eine früh festgelegte Haustechnik. Zusätzlich braucht die sichtbare Holzoberfläche Nachweise zu Brand- und, je nach Nutzung, Schallschutz, die bei einer bekleideten Decke entfallen würden.',NULL,NULL,'{}'::text[],'[]'::jsonb,NULL,270);
insert into public.nodes (id,perspective,level,parent_id,title,t1,t2,t3,links,sources,dach,ord) values
('kde3akustiksicht','k',3,'kde2sicht','Akustisch wirksame Sichtdecken','Perforierter Sichtbeton oder genutete Holzoberflächen lösen den scheinbaren Widerspruch zwischen offener Rohdecke und Raumakustik: Die Öffnungen an der Oberfläche führen zu einer dahinterliegenden Absorberschicht, unsichtbar für das Auge, wirksam für das Ohr. Diese Systeme sind aufwendiger in der Planung, aber die einzige Antwort, wenn Sichtdecke und Nachhallzeit gleichzeitig gefordert sind.',NULL,NULL,'{}'::text[],'[]'::jsonb,NULL,271),
('kde2technik','k',2,'kde1','Integration von Technik in die Decke','Kaum eine Fläche im Gebäude bündelt so viel Haustechnik wie die Decke: Beleuchtung, Lüftung, Sprinkler und zunehmend auch Heizung und Kühlung laufen hier zusammen. Die Deckenplanung entscheidet deshalb wesentlich mit über die Koordination aller technischen Gewerke.',NULL,NULL,'{}'::text[],'[]'::jsonb,NULL,272),
('kde3integration','k',3,'kde2technik','Leuchten, Sprinkler und Lüftung in der Decke','Jedes technische Element in der Decke braucht seinen eigenen Freiraum über der sichtbaren Fläche, und diese Freiräume konkurrieren miteinander um dieselbe Abhanghöhe. Eine frühe Abstimmung im Deckenspiegel, der zeichnerischen Übersicht aller Deckeneinbauten, verhindert, dass Lüftungskanal und Sprinklerleitung erst auf der Baustelle aufeinandertreffen.',NULL,NULL,'{}'::text[],'[]'::jsonb,NULL,273),
('kde3revision','k',3,'kde2technik','Revisionsöffnungen und Zugänglichkeit','Jede Anlage hinter der Decke, die gewartet werden muss, braucht eine erreichbare Öffnung, und diese Öffnungen sollten von Anfang an in ein Rastermaß der Deckengestaltung eingeplant werden statt später nachträglich eingeschnitten. Eine geschlossene Gipskartondecke ohne geplante Revisionsstellen ist eine spätere Baustelle, die noch niemand sieht.',NULL,NULL,'{}'::text[],'[]'::jsonb,NULL,274),
('kde3kuehldecke','k',3,'kde2technik','Kühl- und Heizdecken','Thermoaktive Decken heizen oder kühlen über eine im Deckenaufbau geführte Wasserleitung und nutzen dafür die große Fläche der Decke für niedrige Vorlauf- beziehungsweise hohe Kühlwassertemperaturen. Sie verlangen eine glatte, gut wärmeleitende Oberfläche und vertragen sich deshalb schlecht mit dicken Akustikabsorbern an derselben Stelle.',NULL,NULL,'{}'::text[],'[]'::jsonb,NULL,275),
('kab1','k',1,NULL,'Abdichtung und Bauphysik im Detail','Abdichtung und Bauphysik entscheiden nicht an der großen Linie, sondern im Detail: an der Fuge, am Anschluss, an der Durchdringung. Dieses Themenfeld versammelt das Wissen, das Schäden durch Feuchte, Wärmeverlust und Bewegung verhindert, oft unsichtbar, aber folgenreich, wenn es fehlt.',NULL,NULL,'{}'::text[],'[]'::jsonb,NULL,276),
('kab2luft','k',2,'kab1','Luftdichtheit und Dampfdiffusion','Die luftdichte Ebene verhindert, dass warme, feuchte Innenluft unkontrolliert durch die Gebäudehülle strömt und dort auskühlt, während die Dampfdiffusion den viel langsameren Weg des Wasserdampfs durch das Bauteil selbst beschreibt. Werden beide Mechanismen verwechselt, entstehen genau dort Feuchteschäden, wo man sie am wenigsten erwartet.',NULL,NULL,'{}'::text[],'[]'::jsonb,NULL,277),
('kab3luftdicht','k',3,'kab2luft','Die luftdichte Ebene im Bauteilaufbau','Die luftdichte Ebene muss als durchgehende Linie im Schnitt nachweisbar sein, von der Bodenplatte bis zum First, ohne eine einzige Lücke an Anschlüssen, Durchdringungen oder Bauteilwechseln. Schon eine vergessene Steckdose in der Außenwand kann die gesamte Luftdichtheit des Hauses messbar verschlechtern.',NULL,NULL,'{}'::text[],'[]'::jsonb,NULL,278),
('kab3dampfbremse','k',3,'kab2luft','Dampfbremse und Dampfsperre','Die Dampfbremse lässt Wasserdampf kontrolliert und langsam hindurch, die Dampfsperre praktisch gar nicht, welche der beiden richtig ist, hängt vom restlichen Bauteilaufbau und der Rücktrocknungsfähigkeit nach außen ab. Die falsche Wahl kann Tauwasser im Bauteilinneren einschließen, wo es niemand sieht, bis der Schaden längst da ist.',NULL,NULL,'{}'::text[],'[]'::jsonb,NULL,279),
('kab3blowerdoor','k',3,'kab2luft','Blower-Door-Test und Leckageortung','Beim Blower-Door-Test erzeugt ein Gebläse einen Unter- oder Überdruck im Gebäude, sodass sich undichte Stellen der Hülle als spürbarer Luftzug oder mit Nebel und Wärmebildkamera sichtbar aufspüren lassen. Der Test lohnt sich schon während des Rohbaus, denn dann sind gefundene Lecks noch mit vertretbarem Aufwand zu schließen.',NULL,NULL,'{}'::text[],'[]'::jsonb,NULL,280),
('kab2waermebruecke','k',2,'kab1','Wärmebrücken','Eine Wärmebrücke ist eine Stelle in der Gebäudehülle, an der mehr Wärme nach außen entweicht als in der umgebenden Fläche, meist erkennbar an einer niedrigeren Oberflächentemperatur innen. Neben dem Energieverlust ist die eigentliche Gefahr das Tauwasser- und Schimmelrisiko, das an dieser kälteren Stelle zuerst entsteht.',NULL,NULL,'{}'::text[],'[]'::jsonb,NULL,281),
('kab3konstruktiv','k',3,'kab2waermebruecke','Konstruktive Wärmebrücken','Konstruktive Wärmebrücken entstehen, wo ein durchgehendes Bauteil, etwa eine Balkonplatte oder ein Ringanker, die Dämmebene unterbricht und Wärme gewissermaßen an der Dämmung vorbeileitet. Sie lassen sich meist nur durch eine gezielte thermische Trennung im Bauteil selbst lösen, nicht durch dickere Dämmung an anderer Stelle.',NULL,NULL,'{}'::text[],'[]'::jsonb,NULL,282),
('kab3geometrisch','k',3,'kab2waermebruecke','Geometrische Wärmebrücken','Geometrische Wärmebrücken entstehen allein durch die Form des Bauteils, zum Beispiel an einer Außenecke, wo die kalte Außenfläche im Verhältnis zur warmen Innenfläche besonders groß ist. Sie lassen sich nicht wegkonstruieren, nur durch ausreichende Dämmstärke in ihrer Wirkung entschärfen.',NULL,NULL,'{}'::text[],'[]'::jsonb,NULL,283),
('kab3vermeidung','k',3,'kab2waermebruecke','Wärmebrückenfreies Konstruieren','Wärmebrückenfreies Konstruieren bedeutet, die Dämmebene im Schnitt als durchgehende, ungestörte Linie zu zeichnen und jeden Materialwechsel des Bauteils schon im Entwurf an dieser Linie zu prüfen. Wer Wärmebrücken erst in der Ausführungsplanung sucht, findet sie meist dort, wo eine Korrektur am teuersten ist.',NULL,NULL,'{}'::text[],'[]'::jsonb,NULL,284),
('kab2schlagregen','k',2,'kab1','Schlagregen und Spritzwasserschutz','Schlagregen trifft die Fassade nicht senkrecht, sondern schräg und mit Druck, und genau deshalb versagen an dieser Stelle Anschlüsse, die einem ruhigen Regen ohne Wind durchaus standhalten würden. Fenster-, Tür- und Sockelanschlüsse sind die typischen Schwachstellen, weil hier mehrere Bauteile und Gewerke aufeinandertreffen.',NULL,NULL,'{}'::text[],'[]'::jsonb,NULL,285);
insert into public.nodes (id,perspective,level,parent_id,title,t1,t2,t3,links,sources,dach,ord) values
('kab3fassade','k',3,'kab2schlagregen','Schlagregenschutz an der Fassade','Der Schlagregenschutz einer Fassade entsteht aus dem Zusammenspiel mehrerer Verteidigungslinien: einer wasserabweisenden Oberfläche, einer dahinterliegenden Ebene, die eindringendes Wasser kontrolliert ableitet, und Anschlüssen, die keine wassersammelnden Kanten bilden. Eine einzelne perfekte Schicht reicht nicht, wenn die Fuge daneben offen bleibt.',NULL,NULL,'{}'::text[],'[]'::jsonb,NULL,286),
('kab3fenster','k',3,'kab2schlagregen','Fenster- und Türanschluss an die Abdichtung','Fenster- und Türanschlüsse sind die am dichtesten regulierten Stellen der Fassade, weil hier innen die luftdichte Ebene, außen die schlagregendichte Ebene und dazwischen die Wärmedämmung sauber ineinandergreifen müssen. Innen wird traditionell dichter ausgeführt als außen, damit anfallende Feuchte nach außen entweichen kann, doch das gelingt nur mit handwerklich sauberer Ausführung.',NULL,NULL,ARRAY['k4null']::text[],'[]'::jsonb,NULL,287),
('kab3sockel','k',3,'kab2schlagregen','Spritzwasserzone am Sockel','Der Sockelbereich eines Gebäudes wird durch aufspritzendes Regenwasser deutlich stärker beansprucht als die Fassade darüber und braucht deshalb eigene, robustere Materialien und eine eigene Abdichtungsebene. Wer hier mit dem Fassadenaufbau der oberen Geschosse spart, riskiert Feuchteschäden schon im ersten Winter.',NULL,NULL,'{}'::text[],'[]'::jsonb,NULL,288),
('kab2fuge','k',2,'kab1','Bauwerksfugen und Bewegung','Gebäude bewegen sich ständig geringfügig, durch Temperatur, Schwinden des Betons oder Setzung des Baugrunds, und Bauwerksfugen sind die geplanten Stellen, an denen diese Bewegung stattfinden darf, statt unkontrolliert einen Riss zu erzeugen. Eine fehlende oder falsch bemessene Fuge zeigt sich fast immer erst Jahre später als Schaden.',NULL,NULL,'{}'::text[],'[]'::jsonb,NULL,289),
('kab3bewegungsfuge','k',3,'kab2fuge','Bewegungsfugen im Hochbau','Bewegungsfugen trennen große Bauteile in Abschnitte, die sich unabhängig voneinander ausdehnen oder zusammenziehen können, üblich bei langen Fassaden, großen Bodenplatten oder am Übergang zwischen Neubau und Bestand. Ihre Lage folgt der Statik, nicht der Architektur, weshalb sie früh mit dem Tragwerksplaner abgestimmt werden muss.',NULL,NULL,'{}'::text[],'[]'::jsonb,NULL,290),
('kab3abdichtfuge','k',3,'kab2fuge','Abdichten von Fugen: Fugenband und Fugenmasse','Eine Bewegungsfuge muss trotz ständiger Bewegung dicht bleiben, wofür entweder ein elastisches Fugenband einbetoniert oder eine dauerelastische Fugenmasse nachträglich eingebracht wird. Beide Systeme haben eine begrenzte Lebensdauer und gehören deshalb zu den wenigen Bauteilen, deren Wartung von Anfang an mitgeplant werden sollte.',NULL,NULL,'{}'::text[],'[]'::jsonb,NULL,291),
('kab3anschlussfuge','k',3,'kab2fuge','Anschlussfugen an Bauteilübergängen','Anders als die Bewegungsfuge trennt die Anschlussfuge keine gleichartigen Bauteile, sondern verbindet unterschiedliche, etwa ein Fensterelement mit dem Mauerwerk, und muss deren unterschiedliches Bewegungsverhalten ausgleichen. Sie ist die eigentliche Belastungsprobe jeder Fassadenabdichtung, weil hier die meisten Materialwechsel zusammenkommen.',NULL,NULL,'{}'::text[],'[]'::jsonb,NULL,292),
('kab2nassraum','k',2,'kab1','Feuchteschutz im Bad und Nassraum','Im Bad trifft ständige Wasserbelastung auf empfindliche Bauteile wie Trockenbauwände und Holzdecken darunter, weshalb hier eine eigene, geprüfte Abdichtungsebene unter dem sichtbaren Belag liegt. Diese Ebene sieht man nie, ihr Fehlen aber irgendwann umso deutlicher.',NULL,NULL,'{}'::text[],'[]'::jsonb,NULL,293),
('kab3verbund','k',3,'kab2nassraum','Verbundabdichtung unter Fliesenbelag','Die Verbundabdichtung ist eine flüssig aufgetragene oder bahnenförmige Schicht direkt unter dem Fliesenbelag, die das Wasser stoppt, bevor es in den Untergrund eindringt. Sie ist in bestimmten Beanspruchungsklassen zwingend vorgeschrieben und trotzdem eine der am häufigsten mangelhaft ausgeführten Schichten am Bau.',NULL,NULL,ARRAY['kbo3stein']::text[],'[]'::jsonb,NULL,294),
('kab3ablauf','k',3,'kab2nassraum','Bodenablauf und Gefälle','Ein Bodenablauf funktioniert nur mit einem sauber ausgeführten Gefälle im gesamten umgebenden Belag, sonst bleibt Wasser stehen, statt abzulaufen. Besonders bei bodengleichen Duschen ist das Gefälle eines der planerisch anspruchsvollsten Details, weil es mit der Barrierefreiheit der Fläche konkurriert.',NULL,NULL,ARRAY['k4null']::text[],'[]'::jsonb,NULL,295),
('kab3feuchtraum','k',3,'kab2nassraum','Feuchträume außerhalb des Bads','Küchen, Hauswirtschaftsräume und bestimmte Kellerbereiche gelten bauphysikalisch ebenfalls als feuchtebelastet, auch wenn sie im Alltag nicht als Nassraum wahrgenommen werden. Wer hier den Feuchteschutz auf das Niveau eines trockenen Wohnraums reduziert, unterschätzt eine Beanspruchung, die sich erst nach Jahren als Schimmel zeigt.',NULL,NULL,'{}'::text[],'[]'::jsonb,NULL,296),
('ktg1','k',1,NULL,'Technische Gebäudeausrüstung','Technische Gebäudeausrüstung ist in diesem Ast bewusst nicht als eigene Fachplanung aufbereitet, sondern als das Wissen, das ein Architekt braucht, um mit Fachplanern zu koordinieren: wo welches Gewerk Platz, Höhe oder einen Schacht braucht. Wer diese Schnittstellen ignoriert, plant Schächte zu knapp und Decken zu niedrig und merkt es erst, wenn die Fachplanung die Ausführungsplanung zurückwirft. Der Ast versammelt Heizung und Kühlung, Lüftung, Elektro, Sanitär und Gebäudeautomation aus genau dieser koordinierenden Perspektive.',NULL,NULL,'{}'::text[],'[]'::jsonb,NULL,297),
('ktg2heiz','k',2,'ktg1','Heizung und Kühlung','Ob Wärmepumpe, Fernwärme oder Kessel: Die Wahl des Wärmeerzeugers entscheidet über Flächenbedarf, Aufstellort und oft auch über die Fassadengestaltung, etwa bei Außengeräten. Architekten müssen früh wissen, welches System welchen Raum braucht, nicht wie es im Detail funktioniert. Kühlung rückt zunehmend gleichrangig neben die Heizung, weil sommerlicher Wärmeschutz zur Pflichtaufgabe geworden ist.',NULL,NULL,'{}'::text[],'[]'::jsonb,NULL,298),
('ktg3erzeug','k',3,'ktg2heiz','Wärmeerzeugung: System und Raumbedarf','Wärmepumpe, Fernwärme, Pelletkessel oder Hybridlösung: Jedes System stellt andere Anforderungen an Technikraum, Aufstellort im Freien und Schallschutz zum Nachbarn. Die Grundsatzentscheidung fällt oft schon in der Vorplanung und bindet Flächen, die später kaum verschiebbar sind. Für den Architekten zählt weniger die Heiztechnik selbst als die Fläche, die Zuleitung und das Betriebsgeräusch, das sie mitbringt.',NULL,NULL,'{}'::text[],'[]'::jsonb,NULL,299),
('ktg3verteil','k',3,'ktg2heiz','Wärmeverteilung: Leitungsführung und Höhen','Vom Erzeuger bis zum Raum braucht die Wärme Leitungen, und die brauchen Platz: in Schächten, unter Decken, in Wandschlitzen. Wie diese Verteilung geführt wird, entscheidet mit über die lichte Raumhöhe und darüber, ob abgehängte Decken nötig werden. Wer die Trassenführung erst nach der Grundrissplanung klärt, verliert regelmäßig Deckenhöhe genau dort, wo sie am meisten fehlt.',NULL,NULL,'{}'::text[],'[]'::jsonb,NULL,300);
insert into public.nodes (id,perspective,level,parent_id,title,t1,t2,t3,links,sources,dach,ord) values
('ktg3flaeche','k',3,'ktg2heiz','Flächenheizung und Flächenkühlung','Fußbodenheizung, Wandheizung oder Deckenkühlung verteilen Wärme und Kälte über große, träge Flächen statt über einzelne Heizkörper. Das verändert den Grundriss kaum, aber Bodenaufbau und Regelverhalten spürbar: Ein Raum mit Flächenheizung reagiert langsamer auf Sonneneinstrahlung oder eine volle Wohnung. Die Entscheidung dafür fällt am besten zusammen mit der Wahl des Bodenbelags, nicht danach.',NULL,NULL,'{}'::text[],'[]'::jsonb,NULL,301),
('ktg3kuehl','k',3,'ktg2heiz','Kühlung: Bauteilaktivierung und Klimageräte','Passive Kühlung über aktivierte Betondecken braucht Speichermasse und eine Nachtauskühlung, die architektonisch mitgedacht werden will, etwa über Lüftungsflügel oder ein Nachtlüftungskonzept. Aktive Klimageräte lösen das schneller, aber mit Außeneinheiten, die einen Platz an der Fassade oder auf dem Dach brauchen und dort selten schön sind. Je später die Kühlung mitgedacht wird, desto sichtbarer wird sie am Ende.',NULL,NULL,'{}'::text[],'[]'::jsonb,NULL,302),
('ktg2lueft','k',2,'ktg1','Lüftung: Geräte, Führung, Auslässe','Kontrollierte Wohnraumlüftung ist inzwischen eher Standard als Ausnahme, weil dichte Gebäudehüllen ohne sie zu Feuchteschäden neigen. Für den Architekten zählt vor allem, ob die Anlage zentral mit einem Gerät und Kanalnetz arbeitet oder dezentral mit vielen kleinen Geräten in der Fassade, denn das entscheidet über Schachtbedarf, Deckenhöhe und Fassadenbild. Die Entscheidung sollte in der Vorplanung fallen, nicht als Reaktion auf einen bereits gezeichneten Grundriss.',NULL,NULL,'{}'::text[],'[]'::jsonb,NULL,303),
('ktg3anlagentyp','k',3,'ktg2lueft','Lüftungsanlagen: zentral, dezentral, hybrid','Die zentrale Anlage sitzt mit einem Gerät im Technikraum und verteilt Luft über ein Kanalnetz, leise im Raum, aber flächenintensiv in der Decke. Dezentrale Geräte sitzen einzeln in der Außenwand jedes Raums, sparen Kanäle, brauchen aber Fassadendurchbrüche und sind im Betrieb hörbarer. Hybridlösungen mischen beides und verlangen von Anfang an eine klare Zuordnung, welcher Raum wie belüftet wird.',NULL,NULL,'{}'::text[],'[]'::jsonb,NULL,304),
('ktg3fuehr','k',3,'ktg2lueft','Luftführung und Schachtbedarf','Zuluft, Abluft, Außenluft und Fortluft brauchen jeweils eigene Kanäle, deren Querschnitte größer ausfallen, als die meisten Grundrisse auf den ersten Blick hergeben. Wo Schächte gebündelt werden können, spart das Fläche, verlangt aber eine frühe Festlegung, denn Lüftungskanäle sind kaum nachträglich zu verlegen. Die Koordination mit anderen vertikalen Leitungen entscheidet oft über die Wirtschaftlichkeit des ganzen Schachtkonzepts.',NULL,NULL,ARRAY['ktg3schacht','kt3aufzug']::text[],'[]'::jsonb,NULL,305),
('ktg3auslass','k',3,'ktg2lueft','Auslässe und ihr Platz im Deckenraster','Lüftungsauslässe wollen in ein Deckenraster passen, das oft schon von Beleuchtung und Akustikdecke besetzt ist. Wer Auslässe erst nach der Deckenplanung platziert, findet selten die elegante Lösung, sondern verteilt Ventile dort, wo noch Platz ist. Ein gemeinsames Deckenraster für Licht, Lüftung und Akustik früh mit allen Beteiligten abzustimmen, erspart genau diese Verlegenheitslösung.',NULL,NULL,'{}'::text[],'[]'::jsonb,NULL,306),
('ktg3fassade','k',3,'ktg2lueft','Außenluftdurchlässe an der Fassade','Jede dezentrale Lüftung und jeder Abluftventilator braucht eine Öffnung in der Fassade, klein, aber gestalterisch heikel, weil sie Regen, Schall und Einbruch gleichzeitig abwehren muss. Serienmäßige Lüftungsgitter sind selten das, was der Entwurf verspricht, wenn sie erst am Bau auftauchen. Wer die Durchlässe früh im Fassadenraster mitzeichnet, vermeidet nachträgliche Kompromisse.',NULL,NULL,'{}'::text[],'[]'::jsonb,NULL,307),
('ktg2elektro','k',2,'ktg1','Elektro: Installationszonen und Verteiler','Elektroplanung beginnt für den Architekten nicht bei der Steckdose, sondern bei den Zonen in der Wand, in denen Leitungen liegen dürfen, und beim Platz für Verteiler und Hausanschluss. Wer diese Zonen im Grundriss nicht reserviert, verliert die Kontrolle über Schlitze und Stemmarbeiten, sobald auf der Baustelle improvisiert wird. Mit Photovoltaik und Ladeinfrastruktur wächst der Koordinationsbedarf zusätzlich, weil beide auf den Baukörper selbst wirken.',NULL,NULL,'{}'::text[],'[]'::jsonb,NULL,308),
('ktg3zonen','k',3,'ktg2elektro','Installationszonen im Grundriss','Elektroinstallation folgt üblichen Installationszonen, waagerecht und senkrecht gemessene Streifen an Wänden, in denen Leitungen erwartet werden dürfen. Wer davon abweicht, etwa mit frei diagonal geführten Leitungen, riskiert später jeden Nagel und jede Dübelbohrung. Für den Architekten heißt das vor allem, Möblierung und Elektroplanung gemeinsam zu denken, nicht nacheinander.',NULL,NULL,'{}'::text[],'[]'::jsonb,NULL,309),
('ktg3verteiler','k',3,'ktg2elektro','Verteiler und Technikräume','Zählerschrank, Unterverteiler und zunehmend auch Speicher oder Wechselrichter brauchen einen eigenen, meist unterschätzten Platz, oft in der Nähe des Hausanschlusses. Wird dieser Raum zu knapp geplant, wächst er später auf Kosten eines Abstellraums oder einer Garderobe. Bei größeren Gebäuden kommt die Frage nach Zugänglichkeit für Ablesung und Wartung dazu, ohne dass fremde Personen die Wohnung betreten müssen.',NULL,NULL,'{}'::text[],'[]'::jsonb,NULL,310),
('ktg3pv','k',3,'ktg2elektro','Photovoltaik und Ladeinfrastruktur','Photovoltaik ist längst keine Zutat mehr, sondern eine Fassaden- oder Dachentscheidung, die Statik, Verschattung und Kabelführung von Anfang an mitbestimmt. Ladeinfrastruktur für Fahrzeuge verlangt Leitungsreserven vom Zählerschrank bis zum Stellplatz, die im Rohbau günstig und im Nachhinein teuer sind. Beides gehört in die frühe Leitungsplanung, nicht in die Ausstattungsliste am Ende.',NULL,NULL,'{}'::text[],'[]'::jsonb,NULL,311),
('ktg2sanitaer','k',2,'ktg1','Sanitär: Schächte, Vorwände, Entwässerung','Sanitärinstallation ist das Gewerk, das am stärksten auf gestapelte Grundrisse angewiesen ist: Nassräume übereinander sparen Schächte und Kosten, seitlich verschobene kosten beides. Vorwandinstallationen verändern Wandstärken, Entwässerung verlangt Gefälle, das im Bodenaufbau Platz braucht. Wer Sanitärachsen erst nach der Grundrissplanung sucht, findet sie selten dort, wo sie hinpassen.',NULL,NULL,'{}'::text[],'[]'::jsonb,NULL,312),
('ktg3schacht','k',3,'ktg2sanitaer','Sanitärschächte: Dimensionierung und Lage','Fallstränge für Abwasser brauchen Gefälle und damit Querschnitt, der größer ausfällt, als ein einzelner Anschluss vermuten lässt. Am wirtschaftlichsten liegen Bäder und Küchen übereinander an einem gemeinsamen Schacht, jede Verschiebung dagegen kostet zusätzliche Leitungslängen und Deckenabhängungen. Die Schachtlage gehört deshalb zu den Entscheidungen, die im Idealfall vor der ersten Grundrissvariante feststehen.',NULL,NULL,'{}'::text[],'[]'::jsonb,NULL,313),
('ktg3vorwand','k',3,'ktg2sanitaer','Vorwandinstallation und Wandaufbau','Vorwandsysteme verstecken Spülkästen und Anschlussleitungen hinter einer zusätzlichen Wandschale und verändern damit die tatsächliche Raumtiefe gegenüber der gezeichneten Wand spürbar. Wird diese Aufbaustärke im Grundriss nicht berücksichtigt, schrumpft der Nassraum um mehrere Zentimeter, die an anderer Stelle fehlen. Die Vorwand ist konstruktiv einfach, aber im Maßkonzept eine der häufigsten Fehlerquellen kleiner Bäder.',NULL,NULL,'{}'::text[],'[]'::jsonb,NULL,314),
('ktg3entwaesser','k',3,'ktg2sanitaer','Entwässerung: Gefälle und Rückstau','Abwasser fließt nur mit Gefälle, und dieses Gefälle summiert sich über lange Leitungswege zu spürbarer Aufbauhöhe, die im Bodenaufbau eingeplant sein will. Tiefliegende Räume brauchen zusätzlich eine Rückstausicherung, damit bei überlasteter Kanalisation kein Abwasser zurück ins Gebäude drückt. Beide Themen wirken unscheinbar, bis ein Keller nach dem ersten Starkregen beweist, dass sie fehlten.',NULL,NULL,'{}'::text[],'[]'::jsonb,NULL,315);
insert into public.nodes (id,perspective,level,parent_id,title,t1,t2,t3,links,sources,dach,ord) values
('ktg3trinkwasser','k',3,'ktg2sanitaer','Trinkwasserhygiene und Leitungslänge','Stehendes Wasser in überlangen oder selten genutzten Leitungen ist das Haupteinfallstor für Keimbildung, weshalb kurze Leitungswege schon in der Planung Hygiene bedeuten. Die Bündelung von Bädern hilft nicht nur der Wirtschaftlichkeit, sondern auch der Wasserqualität. Wer Bäder weit auseinanderzieht, plant im Zweifel eine Zirkulationsleitung mit, die selbst wieder Platz und Dämmung braucht.',NULL,NULL,'{}'::text[],'[]'::jsonb,NULL,316),
('ktg2automation','k',2,'ktg1','Gebäudeautomation und Smart Building','Bussysteme vernetzen Licht, Beschattung, Heizung und Sicherheitstechnik über eine gemeinsame Steuerungsebene und ersetzen viele einzelne Schalterkreise durch wenige zentrale Leitungen. Für den Architekten verschiebt sich die Frage von der einzelnen Schalterstelle hin zur Bedienlogik im ganzen Haus: Wer steuert was, von wo, und was passiert, wenn die Technik ausfällt. Automation ist keine Zugabe am Ende der Planung, sondern eine Entscheidung, die Verkabelung und Bedienstellen von Anfang an prägt.',NULL,NULL,'{}'::text[],'[]'::jsonb,NULL,317),
('ktg3bus','k',3,'ktg2automation','Bussysteme und Verkabelung im Rohbau','Ein Bussystem braucht eigene, meist zweiadrige Leitungen zu jedem Teilnehmer, zusätzlich zur klassischen Stromleitung, und diese Leitungen müssen im Rohbau mitgedacht werden, sonst fehlen sie beim Innenausbau unwiderruflich. Nachrüstung ist möglich, aber deutlich teurer und sichtbarer als geplante Verkabelung. Die Grundsatzentscheidung für oder gegen Automation gehört deshalb in eine sehr frühe Planungsphase.',NULL,NULL,'{}'::text[],'[]'::jsonb,NULL,318),
('ktg3schnittstelle','k',3,'ktg2automation','Schnittstelle zu den TGA Gewerken','Heizung, Lüftung, Beschattung und Licht kommen aus getrennten Gewerken, sollen aber am Ende aus einer Hand bedienbar sein, und genau dort entstehen Zuständigkeitslücken. Der Architekt übernimmt in der Praxis oft die koordinierende Rolle, weil er als einziger alle Gewerke im Blick hat. Eine früh festgelegte Automationsmatrix, wer welches Signal liefert und wer es verarbeitet, verhindert teuren Streit in der Ausführungsphase.',NULL,NULL,'{}'::text[],'[]'::jsonb,NULL,319),
('ktg3bedien','k',3,'ktg2automation','Bedienstellen und ihre Platzierung im Raum','Ob Schalter, Taster oder Display: Jede Bedienstelle ist auch ein gestalterisches Element, das mit Türanschlag, Möblierung und Blickachsen zusammenpasst oder eben nicht. Zentrale Bedienpanels reduzieren die Zahl der Schalterstellen, verlangen aber, dass Bewohner sich in einer Menüstruktur zurechtfinden statt einen Lichtschalter zu ertasten. Die beste Automationstechnik scheitert an einer Bedienung, die niemand intuitiv findet.',NULL,NULL,ARRAY['k4drueck']::text[],'[]'::jsonb,NULL,320),
('kma1','k',1,NULL,'Material- und Produktkunde','Dieser Ast bündelt das Wissen zu Baustoffen und Materialien, das in den Bauteil-Ästen sonst an jeder Ecke wiederkehren würde: was Holz kann, was Naturstein kann, wie Kupfer altert, wie sich ein Putzsystem mit dem nächsten verträgt. Bauteile wie Fassade, Fenster oder Boden verweisen von hier aus auf die Materialeigenschaften, statt sie jedes Mal neu zu erklären. Wer Material zuerst versteht, wählt Bauteile nicht nach Katalogbild, sondern nach Eignung.',NULL,NULL,'{}'::text[],'[]'::jsonb,NULL,321),
('kma2holz','k',2,'kma1','Holz und Holzwerkstoffe','Holz ist der einzige tragende Baustoff, der nachwächst, und genau deshalb so unterschiedlich in Qualität und Verhalten wie die Bäume, aus denen er stammt. Vollholz und die vielen Holzwerkstoffe, verleimt, gepresst oder geschichtet, unterscheiden sich stark in Tragfähigkeit, Maßhaltigkeit und Sichtbarkeit. Die Wahl zwischen beiden ist selten eine reine Optik, sondern meist eine Konstruktionsfrage.',NULL,NULL,'{}'::text[],'[]'::jsonb,NULL,322),
('kma3vollholz','k',3,'kma2holz','Vollholz und Holzarten im Ausbau','Nadelhölzer wie Fichte und Kiefer sind der wirtschaftliche Standard, Laubhölzer wie Eiche oder Buche härter, schwerer und im Ausbau meist teurer, aber langlebiger in der sichtbaren Nutzung. Jede Holzart bringt ihre eigene Maserung, Farbe und Neigung zum Vergrauen im Freien mit, die sich nicht wegbehandeln, nur begleiten lässt. Wer Holz unbehandelt einsetzt, entscheidet sich bewusst für ein Material, das sichtbar altert.',NULL,NULL,ARRAY['kt3holz']::text[],'[]'::jsonb,NULL,323),
('kma3werkstoff','k',3,'kma2holz','Holzwerkstoffe: Platten und Verbundstoffe','Sperrholz, OSB, MDF oder Brettschichtholz entstehen aus verleimten oder gepressten Holzanteilen und gewinnen dadurch Maßhaltigkeit und Formate, die Vollholz nicht liefert. Der Verleimungsgrad entscheidet über Feuchtebeständigkeit und Einsatzort, von der unsichtbaren Beplankung bis zur sichtbaren Möbelplatte. Für den Architekten zählt vor allem, welche Emissions- und Feuchtebeständigkeitsklasse ein Werkstoff mitbringt, bevor er in den Innenraum kommt.',NULL,NULL,'{}'::text[],'[]'::jsonb,NULL,324),
('kma2beton','k',2,'kma1','Beton und Betonoberflächen','Beton ist formbar und tragfähig, und im Rohzustand längst nicht mehr nur grau: Die Oberfläche entscheidet, ob er als reine Konstruktion verschwindet oder als Sichtbeton zum gestalterischen Statement wird. Die Ausführungsqualität dieser Oberfläche hängt fast vollständig von der Schalung ab, nicht von der Betonrezeptur allein. Wer Sichtbeton will, plant die Schalung wie ein eigenes Bauteil.',NULL,NULL,'{}'::text[],'[]'::jsonb,NULL,325),
('kma3sichtbeton','k',3,'kma2beton','Sichtbeton: Schalung und Ausführungsklassen','Sichtbeton wird durch die gewählte Schalhaut geprägt: glatte Stahlschalung, strukturiertes Holz oder Sonderschalungen hinterlassen jeweils eine eigene Handschrift auf der Fläche. Die Ausführungsklasse, mit der Fugenbild, Porigkeit und Farbtongleichheit vereinbart werden, gehört früh in die Ausschreibung, nicht erst zur Bemusterung. Nachträgliche Korrekturen an Sichtbeton sind aufwendig und selten unsichtbar.',NULL,NULL,'{}'::text[],'[]'::jsonb,NULL,326),
('kma3fertigteil','k',3,'kma2beton','Betonfertigteile, Oberflächen und Fugen','Fertigteile bringen werkseitige Maßgenauigkeit und glatte Untersichten auf die Baustelle, verlangen dafür aber eine frühe, verbindliche Planung, denn Änderungen nach der Produktion sind kaum mehr möglich. Die Fuge zwischen zwei Fertigteilen ist nie unsichtbar zu bekommen und sollte deshalb als gestalterisches Element behandelt werden, nicht als notwendiges Übel. Oberflächen reichen von werkroh bis gestrahlt oder geschliffen und werden am besten am Musterelement entschieden.',NULL,NULL,ARRAY['kt3beton']::text[],'[]'::jsonb,NULL,327),
('kma2naturstein','k',2,'kma1','Naturstein und Keramik','Naturstein und Keramik sind mineralische Oberflächen mit gegensätzlicher Herkunft, gewachsen und einzigartig der eine, industriell gebrannt und wiederholbar die andere, aber beide langlebig und alterungsarm. Die Wahl zwischen ihnen ist oft eine zwischen Unikat mit Streuung und Industrieprodukt mit Gleichmaß. Beide verlangen eine sorgfältige Prüfung von Frostverhalten, Rutschfestigkeit und Verlegeart vor dem ersten Einsatz.',NULL,NULL,'{}'::text[],'[]'::jsonb,NULL,328),
('kma3gestein','k',3,'kma2naturstein','Natursteinarten und ihre Eignung','Granit ist hart und frostbeständig, Marmor edel, aber empfindlich gegen Säure, Sandstein porös und pflegeintensiv: Jede Gesteinsart bringt ihr eigenes Anforderungsprofil an Ort und Nutzung mit. Die Herkunft der Platten beeinflusst nicht nur den Farbton, sondern auch die zu erwartende Streuung innerhalb einer Lieferung. Wer Naturstein plant, bemustert immer am realen Los, nie am Katalogbild.',NULL,NULL,ARRAY['x4bogen']::text[],'[]'::jsonb,NULL,329),
('kma3keramik','k',3,'kma2naturstein','Keramik und Feinsteinzeug','Feinsteinzeug wird bei hohen Temperaturen dicht gebrannt und dadurch besonders wasseraufnahmearm und robust, glasierte Keramik bleibt empfindlicher gegenüber Stößen, aber vielseitiger in Farbe und Glanz. Großformate verändern die Verlegelogik: Sie brauchen ebenere Untergründe und eine andere Klebetechnik als kleinformatige Fliesen. Rutschhemmung und Wasseraufnahme sind die beiden Kennwerte, die vor jeder Verlegung im Nassbereich zu klären sind.',NULL,NULL,'{}'::text[],'[]'::jsonb,NULL,330);
insert into public.nodes (id,perspective,level,parent_id,title,t1,t2,t3,links,sources,dach,ord) values
('kma2metall','k',2,'kma1','Metalle im Ausbau','Stahl trägt und schützt, Edelstahl bleibt beständig, Aluminium ist leicht, Messing und Kupfer altern sichtbar mit Patina: Metalle im Ausbau sind selten reine Konstruktion, sondern fast immer auch Oberfläche. Die Legierung entscheidet über Korrosionsverhalten, Gewicht und Kosten, die Oberflächenbehandlung über das Erscheinungsbild über Jahrzehnte. Wer Metall sichtbar einsetzt, plant seine Alterung mit, nicht nur seinen Neuzustand.',NULL,NULL,'{}'::text[],'[]'::jsonb,NULL,331),
('kma3stahl','k',3,'kma2metall','Stahl, Edelstahl und ihre Oberflächen','Unlegierter Stahl braucht einen Korrosionsschutz, meist Beschichtung oder Feuerverzinkung, Edelstahl trägt seinen Schutz in der Legierung selbst und bleibt deshalb pflegearm sichtbar. Die Oberflächengüte, von gebürstet bis hochglanzpoliert, verändert nicht nur die Optik, sondern auch die Fingerabdruck- und Kratzempfindlichkeit im Alltag. Für Außenbauteile entscheidet die Legierungsklasse darüber, ob Edelstahl an der Küste überhaupt bestehen bleibt.',NULL,NULL,ARRAY['kt3stahl']::text[],'[]'::jsonb,NULL,332),
('kma3ne','k',3,'kma2metall','NE-Metalle: Aluminium, Messing, Kupfer, Zink','Aluminium ist leicht und formstabil, läuft aber unbehandelt schnell matt an. Messing und Kupfer verändern ihre Farbe mit der Zeit sichtbar zu einer Patina, die viele bewusst suchen, aber selten in ihrer Geschwindigkeit vorhersehen. Zink deckt Dächer seit Generationen und bildet dabei eine eigene, selbstschützende Oberflächenschicht aus.',NULL,NULL,ARRAY['e3druecker']::text[],'[]'::jsonb,NULL,333),
('kma2glas','k',2,'kma1','Glas','Glas ist längst kein einfaches Fensterprodukt mehr, sondern ein Baustoff mit eigener Typenvielfalt: Wärmeschutz, Sonnenschutz, Schallschutz und Sicherheit lassen sich einzeln oder kombiniert in den Glasaufbau einbringen. Jede zusätzliche Funktion verändert Aufbau, Gewicht und Lichtdurchlässigkeit der Scheibe. Die Glasauswahl ist deshalb immer eine Abwägung zwischen Funktion und der gewünschten Transparenz.',NULL,NULL,'{}'::text[],'[]'::jsonb,NULL,334),
('kma3glasart','k',3,'kma2glas','Glasarten und ihre Eigenschaften','Floatglas ist die Basis fast jeder Verglasung, Verbundsicherheitsglas hält im Bruchfall zusammen, Einscheibensicherheitsglas zerfällt in kleine, stumpfe Krümel. Isolierglas kombiniert mehrere Scheiben mit Zwischenraum zu einem Wärmeschutzpaket, dessen Dicke mit jeder zusätzlichen Funktion wächst. Welche Kombination nötig ist, ergibt sich aus Einbauort, Absturzsicherung und den Anforderungen an Wärme oder Schall.',NULL,NULL,'{}'::text[],'[]'::jsonb,NULL,335),
('kma3glasoberfl','k',3,'kma2glas','Glasveredelung und Bedruckung','Beschichtungen machen Glas reflektierend, entspiegelt oder selbstreinigend, ohne dass man ihnen das auf den ersten Blick ansieht. Siebdruck, Ätzung oder Folierung machen aus der transparenten Scheibe ein blickdichtes oder gemustertes Bauteil, oft zur Sichtschutz- oder Absturzsicherungslösung zugleich. Jede Veredelung verändert Lichtdurchlässigkeit und Farbwirkung und sollte deshalb am Musterelement geprüft werden, nicht am Datenblatt.',NULL,NULL,'{}'::text[],'[]'::jsonb,NULL,336),
('kma2putz','k',2,'kma1','Putze, Farben, Beschichtungen','Putz, Farbe und Beschichtung sind die Materialien, die ein Gebäude am Ende tatsächlich zeigt, unabhängig davon, was darunterliegt. Mineralische Systeme regulieren Feuchte, organische Systeme sind robuster gegen Risse, und beide vertragen sich schlecht miteinander, wenn man sie mischt. Die Systementscheidung, mineralisch oder organisch, gehört deshalb an den Anfang der Fassaden- oder Innenraumplanung, nicht ans Ende.',NULL,NULL,'{}'::text[],'[]'::jsonb,NULL,337),
('kma3putz','k',3,'kma2putz','Putzsysteme innen und außen','Kalk- und Kalkzementputze sind diffusionsoffen und regulieren Raumfeuchte, Kunstharzputze sind widerstandsfähiger, aber dichter und daher anfälliger für Feuchteschäden im falschen Untergrund. Außen entscheidet zusätzlich die Körnung über die Robustheit gegenüber Verschmutzung und Regen. Ein Putzsystem funktioniert nur als Ganzes: Grundputz, Armierung und Oberputz müssen aufeinander abgestimmt sein, nicht einzeln ausgewählt.',NULL,NULL,'{}'::text[],'[]'::jsonb,NULL,338),
('kma3farbe','k',3,'kma2putz','Anstriche und Beschichtungen','Ein Anstrich ist selten nur Farbe, sondern immer auch eine bauphysikalische Entscheidung: diffusionsoffen oder dicht, matt oder glänzend, jede Eigenschaft wirkt auf den Untergrund darunter zurück. Fassadenfarben müssen zusätzlich UV-Beständigkeit und Algenresistenz mitbringen, Innenfarben vor allem Deckkraft und Abriebfestigkeit. Farbtonkonstanz über eine ganze Fassadenfläche ist ein eigenes Qualitätsthema, das mit der Ausschreibung beginnt.',NULL,NULL,ARRAY['x4farbe']::text[],'[]'::jsonb,NULL,339),
('kma2kunststoff','k',2,'kma1','Kunststoffe und Membranen','Kunststoffe und Membranen übernehmen im Bau oft unsichtbare, aber entscheidende Aufgaben: abdichten, dämmen, trennen. Ihre Funktion hängt stark von der genauen molekularen Zusammensetzung ab, weshalb zwei ähnlich aussehende Bahnen völlig unterschiedlich diffusionsoffen sein können. Der Umgang mit ihnen verlangt Sorgfalt gerade dort, wo sie nach dem Einbau nicht mehr sichtbar sind.',NULL,NULL,'{}'::text[],'[]'::jsonb,NULL,340),
('kma3kunststoff','k',3,'kma2kunststoff','Kunststoffe im Bauteilaufbau','PVC, Polyethylen oder Polycarbonat unterscheiden sich stark in Härte, UV-Beständigkeit und Brandverhalten, obwohl sie äußerlich oft ähnlich wirken. Im Innenausbau punkten Kunststoffe mit Pflegeleichtigkeit, im Freien mit Wetterbeständigkeit, aber selten mit derselben Alterungswürde wie klassische Materialien. Recyclingfähigkeit wird zum zunehmend wichtigen Auswahlkriterium neben der reinen Funktion.',NULL,NULL,'{}'::text[],'[]'::jsonb,NULL,341),
('kma3membran','k',3,'kma2kunststoff','Membranen und Foliensysteme','Dampfbremsen, Dampfsperren und diffusionsoffene Unterdeckbahnen unterscheiden sich in einem einzigen, aber entscheidenden Wert: wie viel Feuchte sie durchlassen. Verwechslungen zwischen diesen Bahnen sind eine der häufigsten Ursachen für Feuchteschäden in Dach- und Wandaufbauten. Membranen wirken nur luftdicht verklebt: eine Naht zu wenig macht die ganze Ebene wirkungslos.',NULL,NULL,'{}'::text[],'[]'::jsonb,NULL,342),
('kma2lehm','k',2,'kma1','Lehm und alternative Baustoffe','Lehm dämmt kaum, speichert aber Feuchte und Wärme und reguliert damit das Raumklima auf eine Weise, die viele mineralische Baustoffe nicht leisten. Neben Lehm rücken weitere nachwachsende oder recycelte Baustoffe in den Fokus, weil sie graue Energie sparen, wo Beton oder Ziegel viel davon binden. Der Umgang mit diesen Materialien verlangt oft ein Umdenken bei Detailausbildung und Zeitplan, nicht nur beim Material selbst.',NULL,NULL,'{}'::text[],'[]'::jsonb,NULL,343),
('kma3lehmbau','k',3,'kma2lehm','Lehmbaustoffe und ihre Anwendung','Stampflehm, Lehmsteine oder Lehmputz unterscheiden sich in Verarbeitung und Tragfähigkeit stark, eint sie aber die Fähigkeit, Feuchte aufzunehmen und wieder abzugeben, ohne Schaden zu nehmen. Tragende Lehmwände brauchen andere Fundament- und Feuchteschutzdetails als klassisches Mauerwerk, weil aufsteigende Nässe den Baustoff direkt angreift. Lehm verlangt zudem längere Trocknungszeiten im Bauablauf, die früh im Terminplan berücksichtigt werden müssen.',NULL,NULL,'{}'::text[],'[]'::jsonb,NULL,344),
('kma3alternativ','k',3,'kma2lehm','Weitere alternative Baustoffe','Stroh, Hanf, Schilf oder recycelte Materialien wie aufbereiteter Abbruchbeton erweitern die Palette jenseits der etablierten, nachwachsenden Baustoffe, oft mit dem Argument geringerer grauer Energie. Viele dieser Baustoffe haben noch keine breite bauaufsichtliche Zulassung und verlangen deshalb Sonderprüfungen oder Einzelfallzustimmungen im Projekt. Wer sie einsetzt, plant den Zulassungsweg von Anfang an mit, nicht als nachträgliche Hürde.',NULL,NULL,'{}'::text[],'[]'::jsonb,NULL,345);
insert into public.nodes (id,perspective,level,parent_id,title,t1,t2,t3,links,sources,dach,ord) values
('kbe1','k',1,NULL,'Bauen im Bestand','Der größte Teil der Bauaufgaben liegt heute nicht im Neubau, sondern in vorhandener Substanz: Umbauen, Ertüchtigen, Weiterbauen. Wer im Bestand plant, arbeitet gegen Unbekannte wie verdeckte Konstruktionen, undokumentierte Änderungen und gewachsene Toleranzen und muss Anforderungen erfüllen, die beim ursprünglichen Bau noch niemand kannte. Dieses Themenfeld sammelt das Handwerkszeug von der Aufnahme über die Ertüchtigung bis zur Umnutzung.',NULL,NULL,ARRAY['k2b','x1']::text[],'[]'::jsonb,NULL,346),
('kbe2aufnahme','k',2,'kbe1','Bestandsaufnahme und Schadensbilder','Jede Bestandsplanung beginnt mit einem ehrlichen Blick auf das, was wirklich da ist, nicht auf das, was der Bestandsplan behauptet. Aufmaß, Bauteilöffnungen und die Lektüre von Schadensbildern liefern die Grundlage, auf der alle späteren Entscheidungen stehen. Wer hier spart, zahlt später in Nachträgen.',NULL,NULL,'{}'::text[],'[]'::jsonb,NULL,347),
('kbe3aufmass','k',3,'kbe2aufnahme','Aufmaß, Bauteilöffnung und Bestandspläne','Vorhandene Baupläne sind ein Startpunkt, kein Beweis, denn sie zeigen selten spätere Umbauten oder tatsächlich ausgeführte Abweichungen. Ein belastbares Aufmaß und gezielte Bauteilöffnungen an kritischen Stellen wie Deckenauflagern, Wandaufbauten oder Leitungsführung ersetzen Vermutungen durch Fakten, bevor die Planung darauf aufbaut.',NULL,NULL,'{}'::text[],'[]'::jsonb,NULL,348),
('kbe3schad','k',3,'kbe2aufnahme','Schadensbilder lesen: Ursache vor Symptom','Ein Riss, ein feuchter Fleck oder abplatzender Putz sind Symptome, keine Diagnosen. Wer nur das Symptom kaschiert, sieht den Schaden in wenigen Jahren wieder, oft größer. Die eigentliche Aufgabe ist, aus dem Schadensbild auf die Ursache zurückzuschließen, etwa auf eine gestörte Feuchtebalance oder eine überlastete Konstruktion.',NULL,NULL,'{}'::text[],'[]'::jsonb,NULL,349),
('kbe3schadstoff','k',3,'kbe2aufnahme','Schadstoffe im Bestand erkennen','Asbest, teerhaltige Kleber oder alte Holzschutzmittel stecken oft dort, wo man sie nicht vermutet, etwa in Fliesenklebern, Bodenbelägen oder Dämmstoffen der Baujahre bis in die 1990er. Eine Schadstofferkundung vor Abbruch oder Rückbau ist keine Formalie, sondern schützt Gesundheit und Bauablauf gleichermaßen.',NULL,NULL,'{}'::text[],'[]'::jsonb,NULL,350),
('kbe3zustand','k',3,'kbe2aufnahme','Bauzustandsbewertung und Beweissicherung','Vor jedem Eingriff in ein Nachbargebäude oder eine gemeinsame Wand lohnt eine dokumentierte Zustandsaufnahme, sie ist die beste Versicherung gegen spätere Streitigkeiten über Rissursachen. Auch für die eigene Planung liefert die systematische Bewertung von Tragwerk, Hülle und Ausbau die Prioritätenliste, an der sich Budget und Bauabschnitte orientieren.',NULL,NULL,'{}'::text[],'[]'::jsonb,NULL,351),
('kbe2ertuecht','k',2,'kbe1','Ertüchtigung: Statik, Brandschutz, Energie','Bestehende Gebäude erfüllen fast nie die heutigen Anforderungen an Tragfähigkeit, Brandschutz oder Energieeffizienz, wurden aber für eine andere Zeit und oft für einen anderen Zweck gebaut. Ertüchtigung heißt, diese Lücke zu schließen, ohne die Substanz zu zerstören, die den Bestand überhaupt erhaltenswert macht.',NULL,NULL,'{}'::text[],'[]'::jsonb,NULL,352),
('kbe3statik','k',3,'kbe2ertuecht','Statisch ertüchtigen statt ersetzen','Ob Kohlefaserlamelle, aufgedoppelte Decke oder zusätzliche Stütze: Die statische Ertüchtigung sucht meist den kleinsten Eingriff, der eine geforderte Tragfähigkeit sicherstellt. Entscheidend ist, das Bestandstragwerk erst zu verstehen, bevor man es verstärkt, denn viele Konstruktionen tragen anders, als der ursprüngliche Plan vermuten lässt.',NULL,NULL,'{}'::text[],'[]'::jsonb,NULL,353),
('kbe3brand','k',3,'kbe2ertuecht','Brandschutzertüchtigung im laufenden Betrieb','Fluchtwege, Brandabschnitte und Feuerwiderstände lassen sich im Bestand selten nach Neubaulogik lösen, weil Treppenräume, Wanddicken und Deckenaufbauten bereits feststehen. Häufig entscheidet sich die Lösung zwischen der Ertüchtigung vorhandener Bauteile und der Kompensation über Anlagentechnik wie Rauchmelder oder Sprinkler.',NULL,NULL,ARRAY['k3t30']::text[],'[]'::jsonb,NULL,354),
('kbe3energ','k',3,'kbe2ertuecht','Energetische Ertüchtigung und ihre Grenzen','Eine nachträgliche Dämmung verändert das Feuchteverhalten der ganzen Wand, deshalb ist energetische Ertüchtigung nie nur eine Frage der Dämmstärke. Wer außen dämmt, ohne Innendämmfälle und Wärmebrücken am Bestand mitzudenken, riskiert neue Schäden an alter Substanz.',NULL,NULL,'{}'::text[],'[]'::jsonb,NULL,355),
('kbe3install','k',3,'kbe2ertuecht','Haustechnik im Bestand nachrüsten','Neue Leitungen, Lüftung oder Fußbodenheizung wollen durch eine Konstruktion, die dafür nicht vorgesehen war. Vorwandinstallationen, Sockelleistenkanäle oder dezentrale Lüftungsgeräte sind die üblichen Antworten, wenn Schlitzen und Stemmen die Substanz zu sehr angreifen würden.',NULL,NULL,'{}'::text[],'[]'::jsonb,NULL,356),
('kbe2denkmal','k',2,'kbe1','Denkmalpflege: Prinzipien und Praxis','Denkmalpflege ist kein Bauen von gestern, sondern eine eigene Entwurfsdisziplin mit eigenen Regeln: Substanzschutz vor Neuerung, Lesbarkeit der Eingriffe, Reversibilität wo möglich. Wer diese Prinzipien versteht, kann auch in denkmalgeschützter Substanz zeitgemäß planen, statt nur zu verwalten.',NULL,NULL,'{}'::text[],'[]'::jsonb,NULL,357),
('kbe3prinz','k',3,'kbe2denkmal','Substanzschutz und Reversibilität als Prinzip','Der Grundsatz der Denkmalpflege lautet, so wenig wie möglich und so viel wie nötig einzugreifen und Eingriffe nach Möglichkeit rückbaubar zu gestalten. Das schließt moderne Ertüchtigung nicht aus, verlangt aber, sie als erkennbare, ablösbare Schicht zu denken statt als Fälschung des Originals.',NULL,NULL,ARRAY['k3ertuecht']::text[],'[]'::jsonb,NULL,358),
('kbe3ansatz','k',3,'kbe2denkmal','Rekonstruktion, Ergänzung oder Kontrast','Fehlt ein Bauteil, stehen drei Haltungen zur Wahl: originalgetreu rekonstruieren, sinngemäß ergänzen oder bewusst zeitgenössisch kontrastieren. Keine Haltung ist grundsätzlich richtiger, aber jede erzeugt eine andere Lesbarkeit des Gebäudes und muss zur jeweiligen Bedeutung des Denkmals passen.',NULL,NULL,'{}'::text[],'[]'::jsonb,NULL,359),
('kbe3verfahren','k',3,'kbe2denkmal','Genehmigungsverfahren und Denkmalbehörde','Bei denkmalgeschützten Objekten läuft die Genehmigung parallel zum Bauantrag über eine eigene Fachbehörde, deren frühe Einbindung über Erfolg oder Verzögerung des Projekts entscheidet. Wer die Denkmalbehörde erst mit fertiger Planung konfrontiert, riskiert, wesentliche Teile davon wieder zu verlieren.',NULL,NULL,'{}'::text[],'[]'::jsonb,NULL,360);
insert into public.nodes (id,perspective,level,parent_id,title,t1,t2,t3,links,sources,dach,ord) values
('kbe3material','k',3,'kbe2denkmal','Historische Materialien und Handwerk','Kalkputz, historisches Glas oder handgestrichene Ziegel verhalten sich physikalisch anders als ihre modernen Pendants, und genau darin liegt oft die Ursache, warum ein Altbau bis heute funktioniert. Reparaturen mit zu dichtem oder zu hartem Ersatzmaterial gehören zu den häufigsten Schadensursachen im Baubestand.',NULL,NULL,ARRAY['k3hist']::text[],'[]'::jsonb,NULL,361),
('kbe2umbau','k',2,'kbe1','Anbauen, Aufstocken, Umnutzen','Die wirtschaftlichste Erweiterung eines Gebäudes ist oft nicht der Neubau daneben, sondern die Weiterentwicklung des Vorhandenen. Anbau, Aufstockung und Umnutzung teilen die gleiche Grundfrage: Wie viel trägt der Bestand noch, und wo endet seine Belastbarkeit, konstruktiv wie gestalterisch?',NULL,NULL,'{}'::text[],'[]'::jsonb,NULL,362),
('kbe3anbau','k',3,'kbe2umbau','Anbau: Fügung an den Bestand','Ein Anbau muss sich entscheiden, ob er sich unterordnet, gleichwertig anschließt oder bewusst als eigene Zeitschicht auftritt. Konstruktiv entscheidend ist die Fuge selbst: Setzungsunterschiede, unterschiedliche Gründungstiefen und abweichende Wärmedehnung verlangen ein Anschlussdetail, das Bewegung zulässt, statt sie zu verhindern.',NULL,NULL,'{}'::text[],'[]'::jsonb,NULL,363),
('kbe3aufstock','k',3,'kbe2umbau','Aufstockung: Lastreserven und Leichtbau','Ob ein Gebäude eine weitere Etage tragen kann, entscheidet sich an Fundament und Bestandstragwerk, nicht am Wunsch der Planung. Leichtbaukonstruktionen aus Holz oder Stahl sind deshalb die typische Antwort, wenn die Lastreserve knapp, die zusätzliche Nutzfläche aber attraktiv ist.',NULL,NULL,'{}'::text[],'[]'::jsonb,NULL,364),
('kbe3umnutz','k',3,'kbe2umbau','Umnutzung: neue Funktion, altes Tragwerk','Ein Fabrikgebäude wird Wohnhaus, eine Kirche wird Bibliothek: Umnutzung stellt neue Anforderungen an Erschließung, Brandschutz und Belichtung an eine Struktur, die für einen anderen Zweck gebaut wurde. Der Reiz liegt oft genau in der Spannung zwischen alter Großzügigkeit und neuer, kleinteiligerer Nutzung.',NULL,NULL,'{}'::text[],'[]'::jsonb,NULL,365),
('kbe3ruecksb','k',3,'kbe2umbau','Rückbau und Bauteilrecycling','Was nicht weiterverwendet werden kann, muss zumindest sortenrein zurückgebaut werden, denn ungetrennter Abbruch verschenkt Material und erzeugt vermeidbaren Deponieraum. Sichtbare Bauteile wie Balken, Türen oder Fliesen finden zunehmend über spezialisierte Handelsplätze ein zweites Leben in anderen Projekten.',NULL,NULL,'{}'::text[],'[]'::jsonb,NULL,366),
('kau1','k',1,NULL,'Außenanlagen und Übergänge','Wo das Gebäude endet, beginnt die Außenanlage, und genau an dieser Naht entscheiden sich viele der hartnäckigsten Mängel: Feuchte am Sockel, stolpernde Übergänge, unwirtliche Wege. Dieses Themenfeld versammelt das Wissen zu Belägen, Einfriedungen und dem Anschluss des Gebäudes an sein Gelände, immer mit Blick auf Entwässerung und Barrierefreiheit als durchgängige Themen.',NULL,NULL,ARRAY['k4null','kt3rampe']::text[],'[]'::jsonb,NULL,367),
('kau2belag','k',2,'kau1','Beläge und Entwässerung außen','Außenbeläge tragen mehr Verantwortung, als ihre Optik vermuten lässt: Sie lenken Wasser, tragen Lasten und altern sichtbar unter freiem Himmel. Die Wahl von Material, Verlegeart und Gefälle entscheidet, ob eine Fläche in zehn Jahren noch eben und trocken ist.',NULL,NULL,'{}'::text[],'[]'::jsonb,NULL,368),
('kau3pflaster','k',3,'kau2belag','Pflasterbeläge: Aufbau und Fugenbild','Unter jedem Pflaster liegt ein Tragschichtaufbau, der die eigentliche Lebensdauer bestimmt, das sichtbare Steinformat ist nur die oberste Schicht. Fugenbreite und Fugenmaterial steuern zusätzlich, wie viel Wasser versickert und wie leicht sich die Fläche später instand setzen lässt.',NULL,NULL,'{}'::text[],'[]'::jsonb,NULL,369),
('kau3wasser','k',3,'kau2belag','Wassergebundene und sickerfähige Beläge','Rasengittersteine, Splittdecken oder wassergebundene Wegedecken lassen Regenwasser vor Ort versickern, statt es in den Kanal zu leiten, ein Vorteil, der bei zunehmender Flächenversiegelung an Gewicht gewinnt. Der Kompromiss liegt in der Pflege: Diese Beläge brauchen regelmäßige Nacharbeit, um eben und stabil zu bleiben.',NULL,NULL,'{}'::text[],'[]'::jsonb,NULL,370),
('kau3entw','k',3,'kau2belag','Entwässerung: Gefälle, Rinnen, Versickerung','Wasser folgt dem Gefälle, nicht dem Wunsch der Planung, deshalb beginnt jede Außenanlagenplanung mit der Frage, wohin das Regenwasser tatsächlich abfließt. Rinnen, Drainagen und Versickerungsflächen sind die sichtbaren Werkzeuge einer Logik, die schon in der Geländemodellierung angelegt sein muss.',NULL,NULL,'{}'::text[],'[]'::jsonb,NULL,371),
('kau3terrasse','k',3,'kau2belag','Terrassenbeläge und Plattenlager','Auf Stelzlagern verlegte Platten lösen Gefälle und Belag voneinander, das darunterliegende Abdichtungsgefälle bleibt unabhängig von der sichtbar ebenen Nutzfläche. Diese Entkopplung erleichtert spätere Kontrolle und Austausch erheblich gegenüber vollflächig verklebten Aufbauten.',NULL,NULL,'{}'::text[],'[]'::jsonb,NULL,372),
('kau2einfried','k',2,'kau1','Einfriedungen und Stützmauern','Zaun, Hecke oder Mauer markieren die Grenze eines Grundstücks und prägen die Straßenansicht oft stärker als das Gebäude selbst. Stützmauern übernehmen dazu eine tragende Aufgabe: Sie halten Erdreich, wo das Gelände springt, und unterliegen deshalb eigenen statischen Regeln.',NULL,NULL,'{}'::text[],'[]'::jsonb,NULL,373),
('kau3zaun','k',3,'kau2einfried','Zäune und Hecken als Grundstücksgrenze','Eine Hecke braucht Jahre, um ihre Wirkung zu entfalten, ein Zaun steht sofort, dafür bleibt er immer sichtbares Bauteil statt gewachsene Grenze. Die Entscheidung ist selten nur gestalterisch, sie hat auch mit Pflegeaufwand, Sichtschutz und Nachbarschaftsrecht zu tun.',NULL,NULL,'{}'::text[],'[]'::jsonb,NULL,374),
('kau3mauer','k',3,'kau2einfried','Stützmauern: Erddruck und Material','Eine Stützmauer hält nicht nur ihr eigenes Gewicht, sondern den Erddruck des dahinterliegenden Geländes, weshalb Fundamentierung und Entwässerung hinter der Mauer über ihre Standsicherheit entscheiden. Gabionen, Betonwinkelsteine oder klassisches Mauerwerk unterscheiden sich vor allem darin, wie viel Handarbeit und wie viel System im Aufbau steckt.',NULL,NULL,'{}'::text[],'[]'::jsonb,NULL,375);
insert into public.nodes (id,perspective,level,parent_id,title,t1,t2,t3,links,sources,dach,ord) values
('kau3sockelmauer','k',3,'kau2einfried','Sockelmauerwerk und Spritzwasserschutz','Der unterste Meter jeder Fassade ist der am meisten beanspruchte: Spritzwasser, Tausalz und mechanischer Stoß treffen hier zusammen. Ein eigenes, robusteres Sockelmaterial oberhalb der Erdanschlusshöhe schützt die eigentliche Fassade davor, diesen Verschleiß mittragen zu müssen.',NULL,NULL,'{}'::text[],'[]'::jsonb,NULL,376),
('kau3tor','k',3,'kau2einfried','Einfahrtstore und Zugangssituationen','Ein Tor ist die Haustür des Grundstücks und verdient entsprechende Sorgfalt bei Antrieb, Anschlag und Übergang zum Belag. Elektrische Antriebe verlangen früh geklärte Leitungswege, sonst endet die Automatisierung als nachträglich sichtbares Kabel auf dem Pflaster.',NULL,NULL,'{}'::text[],'[]'::jsonb,NULL,377),
('kau2uebergang','k',2,'kau1','Der Übergang Gebäude/Gelände','Am Fußpunkt der Fassade treffen zwei Systeme aufeinander, die unterschiedlichen Regeln folgen: die trockene Gebäudehülle und das feuchte, bewegliche Gelände. Wie sauber dieser Übergang gelöst ist, entscheidet über Jahrzehnte, ob Feuchte im Sockel eine Ausnahme oder ein Dauerzustand ist.',NULL,NULL,ARRAY['x3platz']::text[],'[]'::jsonb,NULL,378),
('kau3sockelanschl','k',3,'kau2uebergang','Sockelanschluss und Spritzwasserschutz','Direkt am Gebäude braucht die Abdichtung ausreichend Anschlusshöhe über dem fertigen Gelände, klassisch etwa 15 Zentimeter, sonst dringt Feuchte über Spritzwasser und Kapillarwirkung in die Wand. Dieser Wert steht in ständiger Spannung zur Forderung nach schwellenlosen Zugängen und wird dort zum eigentlichen Planungsproblem.',NULL,NULL,ARRAY['k4null']::text[],'[]'::jsonb,NULL,379),
('kau3gefaelle','k',3,'kau2uebergang','Gefälle vom Gebäude weg als Grundregel','Die einfachste und wirksamste Regel der Außenanlagenplanung lautet, das Gelände unmittelbar am Gebäude immer fallend anzulegen, nie eben und niemals zum Haus hin geneigt. Wird diese Grundregel missachtet, hilft auch die beste Abdichtung nur begrenzt, weil Wasser dauerhaft am Bauwerk steht, statt abzulaufen.',NULL,NULL,'{}'::text[],'[]'::jsonb,NULL,380),
('kau3vordach','k',3,'kau2uebergang','Vordach und Rücksprung als Wetterschutz','Ein Vordach oder ein zurückgesetzter Eingang hält Schlagregen von Fassade und Schwelle fern, bevor überhaupt eine Abdichtung gefordert ist. Diese vorbeugende Wirkung wird in der Planung oft unterschätzt, dabei ist sie meist günstiger als jede nachträgliche technische Lösung am selben Problem.',NULL,NULL,'{}'::text[],'[]'::jsonb,NULL,381),
('kau2barriere','k',2,'kau1','Barrierefreie Außenerschließung','Barrierefreiheit endet nicht an der Haustür, sie beginnt am Straßenrand: Stellplatz, Weg und Rampe müssen ebenso durchdacht sein wie der Eingang selbst. Wer die Außenerschließung erst nach dem Gebäude plant, verbaut sich oft die Fläche, die eine stufenlose Lösung eigentlich braucht.',NULL,NULL,'{}'::text[],'[]'::jsonb,NULL,382),
('kau3rampenweg','k',3,'kau2barriere','Rampen und Wege im Freien','Ein barrierefreier Weg im Freien braucht nicht nur die richtige Neigung, sondern auch einen griffigen, ebenen Belag, der bei Nässe und Laub nicht zur Rutschbahn wird. Wo eine durchgehende Rampe zu lang würde, sind Zwischenpodeste zum Ausruhen kein Komfortdetail, sondern Voraussetzung für die Nutzbarkeit.',NULL,NULL,ARRAY['kt3rampe']::text[],'[]'::jsonb,NULL,383),
('kau3stellplatz','k',3,'kau2barriere','Barrierefreie Stellplätze und Absenkung','Ein barrierefreier Stellplatz braucht Bewegungsfläche neben dem Fahrzeug für den Umstieg in einen Rollstuhl, das ist mehr als nur eine breitere Markierung. Die Bordsteinabsenkung zum Gehweg gehört als durchgehende Linie mitgeplant, sonst endet die Barrierefreiheit genau an der Stelle, wo sie beginnen sollte.',NULL,NULL,'{}'::text[],'[]'::jsonb,NULL,384),
('kau3leitsystem','k',3,'kau2barriere','Taktile Leitsysteme im Außenraum','Rillen- und Noppenplatten führen sehbehinderte Menschen ertastbar durch den Außenraum, ihre Wirkung hängt aber vollständig von einer durchgängigen, unterbrechungsfreien Linienführung ab. Ein Leitsystem, das an einer Kreuzung einfach endet, ist gefährlicher als gar keines, weil es Orientierung verspricht, die es nicht hält.',NULL,NULL,'{}'::text[],'[]'::jsonb,NULL,385),
('erp1','e',1,NULL,'Raum und Proportion','Raum wird nicht über seine Fläche erlebt, sondern über das Verhältnis seiner Maße zueinander: Länge zu Breite, Breite zu Höhe. Dieses Verhältnis entscheidet, ob ein Zimmer beengt, großzügig, intim oder repräsentativ wirkt, oft unabhängig von der reinen Quadratmeterzahl. Diese Perspektive versammelt das Wissen um Maßsysteme, Proportion und die Frage, wie offen oder gefasst sich ein Raum anfühlt.',NULL,NULL,'{}'::text[],'[]'::jsonb,NULL,386),
('erp2mass','e',2,'erp1','Raumproportionen und Maßsysteme','Von den klassischen Raumproportionen der Renaissance bis zum Modulor: Architekten haben immer wieder versucht, angenehme Raummaße in Zahlenverhältnisse zu fassen. Keines dieser Systeme ist Naturgesetz, aber jedes schärft den Blick für das Zusammenspiel von Länge, Breite und Höhe.',NULL,NULL,'{}'::text[],'[]'::jsonb,NULL,387),
('erp3verhaeltnis','e',3,'erp2mass','Seitenverhältnisse und Raumcharakter','Ein quadratischer Grundriss wirkt ruhig und zentriert, ein stark gestrecktes Zimmer lenkt Blick und Bewegung in eine Richtung. Schon geringe Verschiebungen im Verhältnis von Länge zu Breite verändern, ob ein Raum als Aufenthaltsort oder als Durchgang gelesen wird.',NULL,NULL,'{}'::text[],'[]'::jsonb,NULL,388),
('erp3modulor','e',3,'erp2mass','Maßsysteme: vom Goldenen Schnitt zum Modulor','Der Goldene Schnitt, der Modulor Le Corbusiers oder das japanische Tatami Raster sind Versuche, den menschlichen Körper zur Grundlage von Raummaßen zu machen. Ihr Wert liegt weniger in der exakten Zahl als in der Disziplin, Maße nicht beliebig zu setzen, sondern aus einer Logik heraus zu entwickeln.',NULL,NULL,'{}'::text[],'[]'::jsonb,NULL,389),
('erp3achsmass','e',3,'erp2mass','Konstruktionsraster und Achsmaß','Viele Raumproportionen sind keine freie Entwurfsentscheidung, sondern Folge eines Konstruktionsrasters: Stützenabstände, Fertigteilbreiten oder serielle Bauweisen setzen ein Achsmaß, dem die Räume folgen müssen. Wer das Raster kennt, entwirft Proportion mit der Konstruktion statt gegen sie.',NULL,NULL,'{}'::text[],'[]'::jsonb,NULL,390);
insert into public.nodes (id,perspective,level,parent_id,title,t1,t2,t3,links,sources,dach,ord) values
('erp3wahrnehm','e',3,'erp2mass','Proportion als Wahrnehmungssache','Zwei Räume mit identischer Fläche können völlig unterschiedlich wirken, weil das Auge Verhältnisse liest, keine Quadratmeterzahlen. Diese Wahrnehmungslogik ist der Grund, warum eine Proportionsstudie im Schnitt oder am Modell oft ehrlicher ist als die reine Flächenbilanz.',NULL,NULL,'{}'::text[],'[]'::jsonb,NULL,391),
('erp2hoehe','e',2,'erp1','Raumhöhe als Entwurfsmittel','Die Raumhöhe ist das am leichtesten unterschätzte Entwurfsmittel: Sie kostet Volumen und damit Geld, wirkt aber unmittelbar auf Stimmung und Maßstab. Wechselnde Höhen innerhalb eines Hauses gehören zu den wirksamsten Mitteln, eine Raumfolge zu gliedern, ohne eine einzige zusätzliche Wand zu ziehen.',NULL,NULL,'{}'::text[],'[]'::jsonb,NULL,392),
('erp3standard','e',3,'erp2hoehe','Normalhöhe und ihre Wirkung','Die übliche Geschosshöhe im Wohnungsbau ist ein wirtschaftliches Optimum, kein gestalterisches Ideal: Sie ist so knapp bemessen, dass sie Räume neutral, aber selten großzügig wirken lässt. Wer bewusst darüber oder darunter geht, verlässt diesen neutralen Grundton mit Absicht.',NULL,NULL,'{}'::text[],'[]'::jsonb,NULL,393),
('erp3hochraum','e',3,'erp2hoehe','Hohe Räume: Geste und Konsequenz','Ein Raum, der deutlich höher ist als üblich, wird allein dadurch zum Höhepunkt einer Raumfolge, noch bevor eine weitere Geste dazukommt. Die Kehrseite ist konstruktiv und energetisch spürbar: Mehr Volumen bedeutet mehr Fassadenfläche, mehr Heizvolumen und oft eine andere Statik.',NULL,NULL,ARRAY['e3raumhoch']::text[],'[]'::jsonb,NULL,394),
('erp3niedrig','e',3,'erp2hoehe','Niedrige Zonen als Kompression','Eine bewusst abgesenkte Decke vor einem hohen Raum steigert dessen Wirkung, weil der Körper den Wechsel spürt, bevor der Kopf ihn versteht. Diese Kompression ist ein günstiges und oft unterschätztes Mittel, um Übergänge im Grundriss überhaupt erst spürbar zu machen.',NULL,NULL,ARRAY['esw3sockel']::text[],'[]'::jsonb,NULL,395),
('erp3schnitt','e',3,'erp2hoehe','Höhenstaffelung im Schnitt','Split Level, Galerien oder abgehängte Zonen erzeugen Höhenunterschiede innerhalb eines Geschosses und damit Blickbeziehungen, die ein durchgehend gleich hohes Haus nicht kennt. Der Schnitt wird damit zum eigentlichen Entwurfswerkzeug, nicht allein der Grundriss.',NULL,NULL,ARRAY['et2skulptur']::text[],'[]'::jsonb,NULL,396),
('erp2offen','e',2,'erp1','Offenheit und Fassung','Ein Raum kann als klar gefasster Körper gebaut sein oder als offene Zone, die in Nachbarräume ausläuft. Zwischen diesen Polen liegt die Frage, wie viel Begrenzung ein Grundriss überhaupt noch braucht, um als eigener Raum lesbar zu bleiben.',NULL,NULL,'{}'::text[],'[]'::jsonb,NULL,397),
('erp3fassung','e',3,'erp2offen','Der gefasste Raum','Vier Wände, eine Decke, eine erkennbare Mitte: Der gefasste Raum ist die älteste und robusteste Raumidee überhaupt, weil er unabhängig von Möblierung und Nutzung funktioniert. Seine Stärke ist die Eindeutigkeit, seine Schwäche die Unflexibilität gegenüber wechselnden Ansprüchen.',NULL,NULL,'{}'::text[],'[]'::jsonb,NULL,398),
('erp3fliess','e',3,'erp2offen','Der fließende Raum','Wo Wände zu Möbeln, Nischen oder bloßen Andeutungen werden, entsteht der fließende Raum: Zonen statt Zimmer, definiert durch Licht, Bodenbelag oder Möblierung statt durch Mauerwerk. Die offene Fläche verlangt dafür eine umso genauere Regie von Blickachsen und Nutzungszonen.',NULL,NULL,ARRAY['e2artik']::text[],'[]'::jsonb,NULL,399),
('erp3zonier','e',3,'erp2offen','Zonierung ohne Wand','Ein Niveauwechsel, ein Deckensprung, ein anderer Bodenbelag oder ein freistehendes Möbel können einen Bereich ebenso deutlich abgrenzen wie eine Wand, ohne die Durchlässigkeit des Raums zu verlieren. Diese Werkzeuge sind das eigentliche Handwerk des offenen Grundrisses.',NULL,NULL,ARRAY['eer3nutzflur']::text[],'[]'::jsonb,NULL,400),
('erp3massstab','e',3,'erp2offen','Maßstab im offenen Raum','Ein großer offener Raum verliert schnell seinen menschlichen Maßstab, wenn ihn keine kleineren, gefassten Zonen rhythmisieren. Die eigentliche Aufgabe ist, Weite zuzulassen und trotzdem Orte zu schaffen, an denen man sich aufhalten will.',NULL,NULL,ARRAY['et2ort']::text[],'[]'::jsonb,NULL,401),
('eli1','e',1,NULL,'Licht','Licht ist das einzige Baumaterial, das sich nicht einbauen, sondern nur einladen oder verwehren lässt: Es kommt durch Öffnungen, wird von Oberflächen reflektiert und verändert sich über Tag und Jahreszeit. Kein anderes Entwurfsmittel prägt die Stimmung eines Raums so unmittelbar und so kostenlos.',NULL,NULL,'{}'::text[],'[]'::jsonb,NULL,402),
('eli2tag','e',2,'eli1','Tageslichtführung','Tageslicht lässt sich lenken, filtern, stauen oder gezielt an einen Ort führen, über Fensterposition, Raumtiefe, Oberlichter oder reflektierende Flächen. Gute Tageslichtführung ist selten die größte Öffnung, sondern die am klügsten platzierte.',NULL,NULL,'{}'::text[],'[]'::jsonb,NULL,403),
('eli3seite','e',3,'eli2tag','Einseitiges Licht und Raumtiefe','Licht von nur einer Seite erzeugt einen klaren Hell-Dunkel-Verlauf im Raum, der die hintere Zone spürbar abwertet, sobald die Raumtiefe das Zwei- bis Dreifache der Fensterhöhe überschreitet. Diese einfache Faustregel entscheidet oft schon in der Grundrissphase über die Möblierbarkeit eines Zimmers.',NULL,NULL,'{}'::text[],'[]'::jsonb,NULL,404),
('eli3zwei','e',3,'eli2tag','Licht von zwei Seiten und Eckfenster','Zwei gegenüberliegende oder über Eck stehende Lichtquellen heben Schlagschatten auf und lassen einen Raum gleichmäßiger und größer wirken, als es seine Fläche hergibt. Das Eckfenster ist dabei das wirkungsvollste, aber auch konstruktiv anspruchsvollste Mittel.',NULL,NULL,'{}'::text[],'[]'::jsonb,NULL,405);
insert into public.nodes (id,perspective,level,parent_id,title,t1,t2,t3,links,sources,dach,ord) values
('eli3oben','e',3,'eli2tag','Oberlicht und Zenitlicht','Licht von oben erreicht auch fensterferne Raumtiefen und Innenzonen ohne Außenwand, verhält sich aber im Jahresverlauf und bei direkter Sonne anders als seitliches Licht und braucht deshalb ein eigenes Blendschutzkonzept.',NULL,NULL,ARRAY['et2licht']::text[],'[]'::jsonb,NULL,406),
('eli3lenk','e',3,'eli2tag','Lichtlenkung durch Material und Farbe','Helle, matte Oberflächen streuen Licht tief in den Raum, dunkle oder glänzende schlucken oder spiegeln es gezielt. Wände und Decken sind damit ein ebenso wirksames Lichtwerkzeug wie das Fenster selbst, und ein deutlich günstigeres.',NULL,NULL,'{}'::text[],'[]'::jsonb,NULL,407),
('eli3jahreszeit','e',3,'eli2tag','Lichteinfall im Jahresverlauf','Sonnenstand und Tageslänge verändern Lichtqualität und Schattenwurf eines Raums über das Jahr erheblich: Ein Fenster, das im Winter blendet, kann im Sommer beschatten, oder umgekehrt. Wer nur den bequemsten Zeitpunkt prüft, plant am eigentlich kritischen vorbei.',NULL,NULL,'{}'::text[],'[]'::jsonb,NULL,408),
('eli2verh','e',2,'eli1','Öffnung und Wand: das Verhältnis','Zwischen der geschlossenen Wand und der ganzflächigen Verglasung liegt ein breites Feld an Möglichkeiten, in dem Öffnungsanteil, Format und Position der Fenster über Lichtqualität, Energiebilanz und Privatheit zugleich entscheiden.',NULL,NULL,'{}'::text[],'[]'::jsonb,NULL,409),
('eli3anteil','e',3,'eli2verh','Öffnungsanteil und Fassadencharakter','Der Anteil verglaster Fläche an der Fassade ist nicht nur eine Energiefrage, er bestimmt auch, ob eine Fassade als massiv oder als leicht gelesen wird. Ein hoher Glasanteil ist keine automatische Qualität, wenn er Blendung und sommerliche Überhitzung erst nachträglich lösen muss.',NULL,NULL,'{}'::text[],'[]'::jsonb,NULL,410),
('eli3format','e',3,'eli2verh','Fensterformat: liegend, stehend, raumhoch','Ein liegendes Format betont die Horizontale und den Ausblick auf Augenhöhe, ein stehendes Format wirkt zurückhaltender und lässt mehr Wandfläche für Möblierung, ein raumhohes Element löst die Grenze zwischen innen und außen fast auf.',NULL,NULL,'{}'::text[],'[]'::jsonb,NULL,411),
('eli3wandanteil','e',3,'eli2verh','Die geschlossene Wand als Gegenpart','Wo eine Fassade nur noch aus Öffnungen bestünde, verliert sie ihre Fähigkeit, Rückzug und Geborgenheit anzubieten: Die geschlossene Wandfläche ist kein Rest, sondern eine eigenständige Entscheidung neben dem Fenster.',NULL,NULL,ARRAY['erp3fassung']::text[],'[]'::jsonb,NULL,412),
('eli3privat','e',3,'eli2verh','Öffnung und Einsichtnahme','Je größer und tiefer eine Öffnung, desto genauer muss geklärt sein, wer von außen hineinsieht und wann. Brüstungshöhe, Verglasungsart und Ausrichtung sind die eigentlichen Stellschrauben, lange bevor ein Vorhang gebraucht wird.',NULL,NULL,ARRAY['esw3transparenz']::text[],'[]'::jsonb,NULL,413),
('eli2kunst','e',2,'eli1','Kunstlicht als Architektur','Kunstlicht ist kein Ersatz für Tageslicht, sondern ein eigenes Entwurfsthema: Es kann Architektur nachts neu erzählen, Wege markieren oder Material sichtbar machen, das bei Tag selbstverständlich wirkt.',NULL,NULL,'{}'::text[],'[]'::jsonb,NULL,414),
('eli3grundlicht','e',3,'eli2kunst','Grundlicht und Akzentlicht','Eine gleichmäßige Grundhelligkeit macht einen Raum benutzbar, aber selten interessant: Erst gezielt gesetztes Akzentlicht auf Wand, Material oder Objekt gibt einem Kunstlichtkonzept eine eigene Architektur.',NULL,NULL,'{}'::text[],'[]'::jsonb,NULL,415),
('eli3indirekt','e',3,'eli2kunst','Indirektes Licht','Licht, das über eine Fläche reflektiert statt direkt zu blenden, wirkt weicher und lässt die Lichtquelle selbst verschwinden. Dieses Prinzip verlangt aber Disziplin in der Detailplanung, sonst wird aus der eleganten Lichtvoute ein sichtbarer Blechkasten.',NULL,NULL,'{}'::text[],'[]'::jsonb,NULL,416),
('eli3fassnacht','e',3,'eli2kunst','Fassaden und Wege bei Nacht','Ein Gebäude, das bei Nacht nur seine Fenster zeigt, verschwindet im Stadtraum; gezielt beleuchtete Eingänge, Wege oder Fassadenausschnitte geben Orientierung und Sicherheit, ohne den Nachthimmel zu fluten.',NULL,NULL,ARRAY['eer2ankommen']::text[],'[]'::jsonb,NULL,417),
('eer1','e',1,NULL,'Erschließung und Bewegung','Erschließung ist mehr als der kürzeste Weg von A nach B: Wie ein Gebäude betreten, durchquert und im Inneren verteilt wird, prägt Adresse, Orientierung und Aufenthaltsqualität gleichermaßen. Zwei Bauteile tragen dieses Thema so stark, dass sie eigene Äste bekommen haben: die Tür als Schwelle jeder Bewegung, die Treppe als deren vertikale Choreographie. Diese Perspektive versammelt das übrige Wissen um Ankommen, Wegeführung und die Räume dazwischen.',NULL,NULL,ARRAY['e1','et1']::text[],'[]'::jsonb,NULL,418),
('eer2ankommen','e',2,'eer1','Ankommen und Adressbildung','Bevor ein Besucher einen Raum betritt, hat er sich längst eine Meinung über das Haus gebildet: Wegeführung, Vorplatz und die Lesbarkeit des Eingangs entscheiden, ob ein Gebäude eine erkennbare Adresse hat oder gesucht werden muss.',NULL,NULL,'{}'::text[],'[]'::jsonb,NULL,419),
('eer3vorplatz','e',3,'eer2ankommen','Vorplatz und Ankunftszone','Der Bereich unmittelbar vor dem Eingang ist die letzte Außenzone und die erste Geste des Hauses zugleich: Seine Größe, Überdachung und Möblierung signalisieren, ob Besucher willkommen oder nur geduldet sind.',NULL,NULL,ARRAY['x3tor']::text[],'[]'::jsonb,NULL,420);
insert into public.nodes (id,perspective,level,parent_id,title,t1,t2,t3,links,sources,dach,ord) values
('eer3lesbar','e',3,'eer2ankommen','Die Lesbarkeit des Eingangs','Ein Eingang, den man erst suchen muss, ist ein gescheiterter Entwurf, egal wie elegant die Tür selbst gestaltet ist. Materialwechsel, Vordach, Hausnummer oder ein einfacher Wegeknick zum Haus hin reichen oft, um Orientierung ohne Beschilderung herzustellen.',NULL,NULL,ARRAY['e3portal']::text[],'[]'::jsonb,NULL,421),
('eer3adresse','e',3,'eer2ankommen','Adressbildung im Geschosswohnungsbau','Wo viele Wohnungen einen gemeinsamen Eingang teilen, verlangt Adressbildung eine eigene Choreographie: Vom Haupteingang über Briefkastenwand und Treppenhaus bis zur eigenen Tür muss jede Station erkennbar zur eigenen Adresse gehören, sonst bleibt der Weg anonym.',NULL,NULL,'{}'::text[],'[]'::jsonb,NULL,422),
('eer3barriere','e',3,'eer2ankommen','Ankommen ohne Hindernis','Ein einladender Eingang, der nur über Stufen erreichbar ist, lädt nicht alle ein: Barrierefreies Ankommen ist kein nachträglicher Rampenanbau, sondern eine Frage, die schon in der Wegeführung zum Gebäude beantwortet werden sollte.',NULL,NULL,ARRAY['kt3rampe','esw1']::text[],'[]'::jsonb,NULL,423),
('eer2weg','e',2,'eer1','Wegeführung, Sequenz, Promenade','Ein Weg durch ein Gebäude kann die schnellste Verbindung sein oder eine Erzählung in Etappen: Was man sieht, wann man es sieht, und wo der Weg sich verengt oder weitet, lässt sich ebenso entwerfen wie ein Grundriss selbst.',NULL,NULL,'{}'::text[],'[]'::jsonb,NULL,424),
('eer3sequenz','e',3,'eer2weg','Raumfolge als Sequenz','Eine Abfolge von Räumen wirkt völlig unterschiedlich, je nachdem, ob sie sich stufenlos steigert, abrupt wechselt oder bewusst Umwege einbaut. Sequenzplanung heißt, den Weg selbst zum Entwurfsgegenstand zu machen, nicht nur sein Ziel.',NULL,NULL,ARRAY['e2folge']::text[],'[]'::jsonb,NULL,425),
('eer3umweg','e',3,'eer2weg','Der bewusste Umweg','Der kürzeste Weg ist selten der beste: Ein gezielter Umweg an einem Hof, einer Aussicht oder einem Lichtraum vorbei kann ein Gebäude reicher erleben lassen, ohne die Funktion zu stören. Voraussetzung ist, dass man den Grund des Umwegs unterwegs auch versteht.',NULL,NULL,ARRAY['et2prom']::text[],'[]'::jsonb,NULL,426),
('eer3blick','e',3,'eer2weg','Blickachsen entlang des Wegs','Wer beim Gehen etwas sieht, ein Oberlicht, einen Hof, eine ferne Wand, erlebt den Weg als Ziel und nicht nur als Verbindung. Blickachsen entstehen selten zufällig, sie werden im Schnitt und im Grundriss gemeinsam gezeichnet.',NULL,NULL,ARRAY['x3platz']::text[],'[]'::jsonb,NULL,427),
('eer3tempo','e',3,'eer2weg','Wegbreite und Bewegungstempo','Ein enger Gang beschleunigt den Schritt, ein breiter Weg lädt zum Verweilen ein: Die Breite einer Erschließung ist damit auch eine Aussage darüber, ob hier gegangen oder verweilt werden soll.',NULL,NULL,ARRAY['kt3nutz']::text[],'[]'::jsonb,NULL,428),
('eer2flure','e',2,'eer1','Flure, die keine Flure sind','Der reine Verteilerflur ist die am schlechtesten genutzte Fläche vieler Grundrisse: schmal, fensterlos, ohne eigene Funktion. Wo Erschließungsfläche zusätzlich Aufenthalt, Stauraum oder Ausblick bietet, verliert sie ihren Charakter als bloßer Verkehrsweg.',NULL,NULL,'{}'::text[],'[]'::jsonb,NULL,429),
('eer3verteiler','e',3,'eer2flure','Der reine Verteilerflur','Ein Flur, der nur verbindet, ist oft das Ergebnis eines Grundrisses, der zuerst die Räume und erst danach die Wege verteilt hat. Wird die Erschließung von Anfang an mitentworfen, verschwindet ein Teil dieser Restfläche von selbst.',NULL,NULL,'{}'::text[],'[]'::jsonb,NULL,430),
('eer3nutzflur','e',3,'eer2flure','Erschließung mit Zusatznutzen','Ein verbreiterter Gang mit Regal, Sitznische oder Arbeitsplatz verwandelt reine Bewegungsfläche in nutzbaren Raum, ohne die Wohnfläche formal zu erhöhen. Schon wenig zusätzliche Breite reicht oft aus, um aus einem Flur eine Zone zu machen.',NULL,NULL,ARRAY['erp3zonier']::text[],'[]'::jsonb,NULL,431),
('eer3flurlicht','e',3,'eer2flure','Licht im Flur','Ein fensterloser Innenflur bleibt auch mit bester Kunstlichtplanung ein Angstraum ohne Aufenthaltsqualität; ein Oberlicht, ein verglaster Durchblick zum Nachbarraum oder ein Fenster an der Stirnseite verändert seinen Charakter grundlegend.',NULL,NULL,ARRAY['eli3oben']::text[],'[]'::jsonb,NULL,432),
('eer3galerie','e',3,'eer2flure','Der Flur als Galerie','In mehrgeschossigen Häusern kann die Erschließungsebene selbst zum Erlebnis werden, wenn sie sich zu einem Luftraum öffnet oder Ausblick auf angrenzende Ebenen bietet. Aus dem Weg wird dann ein Ort, an dem man sich aufhält, nicht nur vorbeigeht.',NULL,NULL,ARRAY['et2ort']::text[],'[]'::jsonb,NULL,433),
('esw1','e',1,NULL,'Schwelle und Übergang','Jeder Wechsel zwischen zwei Zuständen, draußen und drinnen, öffentlich und privat, laut und still, braucht einen Ort, an dem dieser Wechsel stattfindet: die Schwelle. Diese Perspektive behandelt die Schwelle als allgemeines Entwurfsthema, von der Grundstücksgrenze bis zum Übergang zwischen zwei Innenräumen. Das türspezifische Schwellenwissen ist bereits im eigenen Ast vertieft; hier geht es um das Prinzip dahinter.',NULL,NULL,ARRAY['e2schwelle','x3tor']::text[],'[]'::jsonb,NULL,434),
('esw2innen','e',2,'esw1','Innen und außen','Der Übergang zwischen innen und außen ist die älteste und folgenreichste Schwelle der Architektur: Er entscheidet über Klima, Sicherheit und die Frage, wie sehr sich ein Gebäude der Umgebung öffnet oder von ihr abschottet.',NULL,NULL,'{}'::text[],'[]'::jsonb,NULL,435);
insert into public.nodes (id,perspective,level,parent_id,title,t1,t2,t3,links,sources,dach,ord) values
('esw3abrupt','e',3,'esw2innen','Der abrupte Übergang','Eine Wand, eine Tür, ein Schritt, und man ist drin: Der abrupte Übergang ist konstruktiv am einfachsten und klimatisch am sparsamsten, verzichtet aber bewusst auf jede Vermittlung zwischen den Sphären.',NULL,NULL,'{}'::text[],'[]'::jsonb,NULL,436),
('esw3gestuft','e',3,'esw2innen','Der gestufte Übergang','Vorzone, Windfang, Diele: Wird der Wechsel von außen nach innen in mehrere Stationen zerlegt, entsteht Zeit für das Ankommen und ein klimatischer Puffer, der sich energetisch auszahlt.',NULL,NULL,ARRAY['e3schwellenr']::text[],'[]'::jsonb,NULL,437),
('esw3fliess','e',3,'esw2innen','Der fließende Übergang','Große Verglasungen, Terrassentüren ohne Schwelle oder ein durchlaufender Bodenbelag lassen innen und außen ineinander übergehen. Der Effekt trägt nur, wenn Abdichtung, Wärmeschutz und Barrierefreiheit ihn technisch mittragen, sonst bleibt es eine Geste mit Folgeschäden.',NULL,NULL,ARRAY['k4null']::text[],'[]'::jsonb,NULL,438),
('esw3klima','e',3,'esw2innen','Klimapuffer als Übergangszone','Wintergarten, Loggia oder überdachter Vorbereich sind keine bloßen Vorräume, sie sind klimatische Zwischenzonen, die den Wechsel abfedern und zusätzlich nutzbaren Raum schaffen, wenn man sie nicht nur als Restfläche behandelt.',NULL,NULL,'{}'::text[],'[]'::jsonb,NULL,439),
('esw2oeffprivat','e',2,'esw1','Öffentlich und privat','Nicht jede Grenze zwischen öffentlich und privat ist eine Wand: Ein Vorgarten, eine Stufe, ein anderer Belag können ebenso deutlich signalisieren, wo die Öffentlichkeit endet und das Private beginnt.',NULL,NULL,'{}'::text[],'[]'::jsonb,NULL,440),
('esw3vorgarten','e',3,'esw2oeffprivat','Der Vorgarten als weiche Grenze','Ein schmaler Vorgarten zwischen Gehweg und Haus ist selten eine Nutzfläche, aber eine wirksame Distanzzone: Er signalisiert Privatbesitz, ohne die Straße auszuschließen, und ist damit eine der ältesten Formen sanfter Abgrenzung.',NULL,NULL,'{}'::text[],'[]'::jsonb,NULL,441),
('esw3sockel','e',3,'esw2oeffprivat','Sockel und Niveauwechsel als Grenze','Ein leicht erhöhtes Erdgeschoss oder eine einzelne Stufe zur Haustür markiert Privatheit, ohne dass eine sichtbare Mauer nötig wäre. Der Körper registriert den Niveauwechsel als Grenze, lange bevor der Kopf ihn als solche benennt.',NULL,NULL,ARRAY['erp3niedrig']::text[],'[]'::jsonb,NULL,442),
('esw3transparenz','e',3,'esw2oeffprivat','Transparenz als Kontrolle der Öffentlichkeit','Wie viel Einblick ein Gebäude von der Straße aus zulässt, ist eine bewusste Entscheidung zwischen Repräsentation und Rückzug: Ein einsehbares Erdgeschoss belebt die Straße, ein blickdichtes schützt die Bewohner, beides ist legitim, solange es gewollt ist.',NULL,NULL,ARRAY['eli3privat']::text[],'[]'::jsonb,NULL,443),
('esw3gemeinschaft','e',3,'esw2oeffprivat','Gemeinschaftliche Schwellen im Wohnungsbau','Hauseingang, Treppenhaus und Wohnungstür sind drei gestaffelte Schwellen zwischen Stadt und privater Wohnung. Wird eine dieser Stufen übersprungen oder unklar gestaltet, kippt entweder die Sicherheit oder die Gastfreundschaft der Adresse.',NULL,NULL,ARRAY['kt3raum']::text[],'[]'::jsonb,NULL,444),
('esw2raum','e',2,'esw1','Schwellenräume','Manche Übergänge brauchen keinen Punkt, sondern einen eigenen Raum: Windfang, Loggia, Laube oder Wintergarten sind Zwischenräume, die weder ganz drinnen noch ganz draußen sind und gerade darin ihren Wert haben.',NULL,NULL,'{}'::text[],'[]'::jsonb,NULL,445),
('esw3windfang','e',3,'esw2raum','Windfang und Klimaschleuse','Der Windfang ist die pragmatischste Form des Schwellenraums: Er hält Zugluft, Kälte und Lärm vom eigentlichen Innenraum fern und schafft nebenbei eine erste Ablagefläche für Schuhe, Schirme und Pakete.',NULL,NULL,ARRAY['e3schwellenr']::text[],'[]'::jsonb,NULL,446),
('esw3loggia','e',3,'esw2raum','Loggia und Laube','Anders als der Balkon liegt die Loggia im Baukörper und ist von drei Seiten gefasst: ein Außenraum mit der Geborgenheit eines Innenraums. Sie eignet sich deshalb besonders als Übergang zwischen privater Wohnung und öffentlicher Fassade.',NULL,NULL,'{}'::text[],'[]'::jsonb,NULL,447),
('esw3innenhof','e',3,'esw2raum','Der Innenhof als introvertierte Schwelle','Ein Innenhof kehrt die übliche Schwellenlogik um: Er liegt innerhalb des Gebäudes, ist aber Außenraum, und schafft damit einen geschützten Übergang, der von der Straße aus unsichtbar bleibt.',NULL,NULL,'{}'::text[],'[]'::jsonb,NULL,448),
('esw3temp','e',3,'esw2raum','Saisonale Schwellenräume','Ein offener Wintergarten oder eine unbeheizte Veranda ist im Sommer Aufenthaltsraum und im Winter nur noch Pufferzone: Schwellenräume müssen nicht das ganze Jahr gleich funktionieren, um das ganze Jahr sinnvoll zu sein.',NULL,NULL,'{}'::text[],'[]'::jsonb,NULL,449),
('ema1','e',1,NULL,'Material und Fügung','Wie ein Gebäude aus seinen Teilen zusammenwächst, entscheidet über mehr als die Konstruktion: Material und Fügung sind die Sprache, in der Architektur ihre eigene Herstellung erzählt. Dieser Ast versammelt das gestalterische Wissen zur Materialwahl, zur sichtbaren Konstruktion und zum Detail als kleinster Entwurfseinheit. Wer Material nur als Farbe und Textur begreift, übersieht die eigentliche Entwurfsfrage: wie die Teile zueinander finden.',NULL,NULL,'{}'::text[],'[]'::jsonb,NULL,450);
insert into public.nodes (id,perspective,level,parent_id,title,t1,t2,t3,links,sources,dach,ord) values
('ema2mat','e',2,'ema1','Materialität und Alterung','Kein Material bleibt, wie es geliefert wurde: Holz vergraut, Kupfer wird grün, Sichtbeton zeichnet Wasser nach. Wer Alterung von Anfang an mitentwirft, gewinnt ein Gebäude, das mit der Zeit gewinnt statt verliert. Diese Gruppe fragt, welche Materialien Patina vertragen und welche Pflege gegen Verfall kämpfen muss.',NULL,NULL,'{}'::text[],'[]'::jsonb,NULL,451),
('ema3patina','e',3,'ema2mat','Patina als Entwurfsabsicht','Manche Materialien sind erst im gealterten Zustand fertig: Cortenstahl braucht seine Rostschicht, unbehandeltes Holz seine Vergrauung, um die geplante Wirkung zu erreichen. Wer Patina als Ziel entwirft statt als Mangel zu fürchten, muss die Anfangsphase mitdenken, in der das Material noch unfertig aussieht.',NULL,NULL,'{}'::text[],'[]'::jsonb,NULL,452),
('ema3haptik','e',3,'ema2mat','Haptik und Sinneserfahrung','Architektur wird nicht nur gesehen, sie wird berührt: Die Temperatur von Stein, die Griffigkeit von Holz, die Kühle von Metall prägen, wie ein Raum in Erinnerung bleibt. Ein Türdrücker zeigt das im Kleinsten, im gesamten Verlauf einer Treppe wiederholt sich dasselbe Prinzip an jedem Handlauf.',NULL,NULL,ARRAY['e3druecker']::text[],'[]'::jsonb,NULL,453),
('ema3lebensdauer','e',3,'ema2mat','Materialalterung und Lebenszyklus','Manche Fassaden sehen am Tag der Übergabe am besten aus und danach nur noch schlechter, andere brauchen Jahre, um ihre eigentliche Qualität zu zeigen. Diese Lebenszykluslogik gehört in jede frühe Materialentscheidung, nicht erst in die Wartungsplanung.',NULL,NULL,'{}'::text[],'[]'::jsonb,NULL,454),
('ema3rohbau','e',3,'ema2mat','Rohe vs. veredelte Oberfläche','Sichtbeton, unverputztes Mauerwerk oder rohes Holz zeigen den Bauprozess selbst als Oberfläche, Putz, Anstrich und Verkleidung glätten ihn zur neutralen Fläche. Die Entscheidung ist selten nur ästhetisch, sie legt fest, wie viel Toleranz die Ausführung verträgt, bevor ein Fehler sichtbar bleibt.',NULL,NULL,'{}'::text[],'[]'::jsonb,NULL,455),
('ema2tekt','e',2,'ema1','Tektonik: Konstruktion zeigen','Tektonik meint die Kunst, die tragende Logik eines Gebäudes im Bild ablesbar zu machen: Was trägt, was hängt, was nur schließt, soll man sehen können, ohne einen Statiker zu fragen. Diese Gruppe versammelt die Mittel, mit denen Architektur ihre eigene Konstruktion erzählt.',NULL,NULL,'{}'::text[],'[]'::jsonb,NULL,456),
('ema3lastfluss','e',3,'ema2tekt','Lastfluss sichtbar machen','Eine Stütze, die genau dort steht, wo die Last ankommt, erzählt Statik auf den ersten Blick, eine verdeckte oder verschobene Stütze verwirrt selbst geübte Betrachter. Lastfluss sichtbar zu machen ist eine bewusste Entscheidung gegen das bequeme Verstecken der Struktur in der Decke.',NULL,NULL,'{}'::text[],'[]'::jsonb,NULL,457),
('ema3fuegung','e',3,'ema2tekt','Die Fuge als Aussage','Wo zwei Materialien oder zwei Bauteile aufeinandertreffen, entscheidet die Fuge über Ehrlichkeit oder Kaschierung: Eine offene Fuge zeigt die Trennung, ein bündiger Übergang verwischt sie. Am Zargenspiegel einer gewöhnlichen Innentür lässt sich dieses Prinzip im Kleinen studieren.',NULL,NULL,ARRAY['k6kante']::text[],'[]'::jsonb,NULL,458),
('ema3schichten','e',3,'ema2tekt','Schichtenaufbau zeigen oder verbergen','Fassaden bestehen aus vielen Schichten, von der Tragstruktur über Dämmung bis zur Bekleidung, doch nur wenige davon werden bewusst sichtbar gehalten. Wer die Schichtung offenlegt, statt sie hinter einer glatten Ebene zu verstecken, macht Konstruktion selbst zum Thema der Fassade.',NULL,NULL,'{}'::text[],'[]'::jsonb,NULL,459),
('ema3massiv','e',3,'ema2tekt','Massivbau vs. Skelettbau','Die dicke, tragende Wand erzählt von Masse und Schutz, das schlanke Stützenraster von Leichtigkeit und Offenheit: Beide Bauweisen sind auch eine gestalterische Haltung, nicht nur eine statische Entscheidung. Wo beide Systeme in einem Gebäude gemischt werden, muss der Übergang bewusst artikuliert sein, sonst wirkt er wie ein Kompromiss.',NULL,NULL,'{}'::text[],'[]'::jsonb,NULL,460),
('ema2detail','e',2,'ema1','Das Detail als Haltung','Im Anschlussdetail entscheidet sich, ob ein Entwurf hält, was seine große Geste verspricht: Jede Fuge, jede Kante und jeder Übergang ist eine Miniatur des gesamten architektonischen Anspruchs. Diese Gruppe fragt, wie aus handwerklicher Präzision Haltung wird.',NULL,NULL,'{}'::text[],'[]'::jsonb,NULL,461),
('ema3masssystem','e',3,'ema2detail','Das Detail als Maßsystem','Ein gutes Detail wiederholt die Proportionslogik des ganzen Gebäudes im Kleinen: Fugenbreiten, Kantenprofile und Rahmenmaße stehen in Beziehung zueinander, nicht zufällig nebeneinander. Wer diese Beziehung konsequent durchzieht, macht selbst den unscheinbarsten Türanschlag lesbar.',NULL,NULL,'{}'::text[],'[]'::jsonb,NULL,462),
('ema3anschluss','e',3,'ema2detail','Der Anschluss als Entwurfsmoment','Wo ein Bauteil endet und ein anderes beginnt, wird jede Entwurfsabsicht auf die Probe gestellt: Der Zargenspiegel einer Standardtür kann mit wenigen Millimetern Breite und Kantenprofil betonen oder beruhigen. Solche kleinen Stellschrauben entscheiden oft mehr über die Raumwirkung als das große Konzept.',NULL,NULL,ARRAY['k6kante']::text[],'[]'::jsonb,NULL,463),
('ema3reduktion','e',3,'ema2detail','Reduktion und das Weglassen','Nicht jedes Detail gewinnt durch mehr Bearbeitung: Manchmal ist die konsequenteste Lösung, eine Kante roh zu lassen oder eine Fuge ganz verschwinden zu lassen. Reduktion verlangt dabei mehr Disziplin als Dekoration, weil jeder verbleibende Übergang präziser sitzen muss.',NULL,NULL,'{}'::text[],'[]'::jsonb,NULL,464),
('ema3handwerk','e',3,'ema2detail','Handwerkliche Präzision','Ein sauber gearbeiteter Gehrungsstoß oder eine exakt sitzende Fuge sind mit bloßem Auge kaum zu beschreiben, aber sofort zu spüren. Handwerkliche Präzision ist oft der eigentliche Unterschied zwischen einem Gebäude, das gut geplant wirkt, und einem, das es tatsächlich ist.',NULL,NULL,'{}'::text[],'[]'::jsonb,NULL,465);
insert into public.nodes (id,perspective,level,parent_id,title,t1,t2,t3,links,sources,dach,ord) values
('ema2farbe','e',2,'ema1','Farbe','Farbe ist das schnellste und zugleich am meisten unterschätzte Entwurfsmittel: Sie verändert Maßstab, Stimmung und Lesbarkeit eines Gebäudes, ohne eine einzige Wand zu verschieben. Diese Gruppe unterscheidet Materialfarbe von Anstrich und fragt, wie aus einzelnen Farbentscheidungen eine Palette wird.',NULL,NULL,'{}'::text[],'[]'::jsonb,NULL,466),
('ema3materialfarbe','e',3,'ema2farbe','Materialfarbe vs. Anstrich','Ziegel, Holz und Naturstein bringen ihre Farbe aus dem Material selbst mit, Putz und Anstrich fügen sie nachträglich hinzu. Materialeigene Farbe altert meist gutmütiger als Anstrich, verlangt dafür aber, schon bei der Materialwahl über die Farbwirkung zu entscheiden.',NULL,NULL,'{}'::text[],'[]'::jsonb,NULL,467),
('ema3kontrast','e',3,'ema2farbe','Farbe als Kontrast und Rahmung','Ein dunkel abgesetzter Rahmen um eine helle Fläche lenkt den Blick, ohne die Form zu verändern: Farbe kann Öffnungen betonen, Fugen sichtbar machen oder ganze Bauteile in den Hintergrund treten lassen. Die Margarethenhöhe zeigt, wie wirkungsvoll ein knappes, kontrolliertes Farbvokabular sein kann.',NULL,NULL,ARRAY['x4farbe']::text[],'[]'::jsonb,NULL,468),
('ema3licht','e',3,'ema2farbe','Farbe im Licht über den Tag','Dieselbe Fassadenfarbe wirkt im flachen Morgenlicht anders als in der Mittagssonne oder im Regen: Farbe ist nie eine feste Größe, sondern verändert sich mit Tageszeit, Wetter und Lichteinfall. Wer Farbmuster nur im Innenraum unter Kunstlicht beurteilt, erlebt am Bau oft eine Überraschung.',NULL,NULL,'{}'::text[],'[]'::jsonb,NULL,469),
('ema3palette','e',3,'ema2farbe','Die kuratierte Farbpalette','Wo mehrere Farben an einem Gebäude oder einer Siedlung zusammenkommen, entscheidet die Palette über Ruhe oder Unruhe: Wenige, aufeinander abgestimmte Töne wirken oft reicher als viele beliebig kombinierte. Serielle Bauvorhaben profitieren besonders von einer siedlungsweit kuratierten Farbwahl.',NULL,NULL,ARRAY['x4farbe']::text[],'[]'::jsonb,NULL,470),
('ety1','e',1,NULL,'Typologie und Programm','Jede Bauaufgabe bringt eine eigene Logik mit: Wie Menschen wohnen, arbeiten, lernen oder sich versammeln, prägt Grundriss und Erschließung, lange bevor die erste Fassade entworfen wird. Dieser Ast ordnet das Entwurfswissen nach Nutzungstyp und fragt zugleich, wie viel Wandel ein Gebäudetyp verträgt, ohne seine Identität zu verlieren.',NULL,NULL,'{}'::text[],'[]'::jsonb,NULL,471),
('ety2wohn','e',2,'ety1','Wohnungsbau: Typen und Grundriss','Der Wohnungsbau ist die Bauaufgabe mit der größten Wiederholung und dem größten gesellschaftlichen Gewicht zugleich: Wie ein Grundriss geschnitten ist, entscheidet über Alltag, Privatheit und Nachbarschaft von tausenden Menschen. Diese Gruppe versammelt die immer wiederkehrenden Grundrissfragen des Wohnens.',NULL,NULL,'{}'::text[],'[]'::jsonb,NULL,472),
('ety3grundriss','e',3,'ety2wohn','Grundrisstypen: Zeile, Punkt, Hof','Zeilenbau, Punkthaus und Hofhaus erschließen dieselbe Wohnfläche auf grundverschiedene Weise: Die Zeile maximiert Belichtung und Wiederholung, das Punkthaus reagiert auf den freien Standort, das Hofhaus schützt einen eigenen Außenraum nach innen. Die Wahl des Grundtyps bindet fast alle folgenden Entwurfsentscheidungen.',NULL,NULL,ARRAY['x2typ']::text[],'[]'::jsonb,NULL,473),
('ety3zimmer','e',3,'ety2wohn','Zimmerlogik vs. offene Wohnform','Die klassische Zimmerwohnung teilt Nutzungen in feste Räume, die offene Wohnform verschmilzt Kochen, Essen und Wohnen zu einer durchgehenden Fläche. Beides sind vollwertige Antworten auf dieselbe Frage, wie viel der Grundriss vorgeben und wie viel er dem Alltag der Bewohner überlassen soll.',NULL,NULL,'{}'::text[],'[]'::jsonb,NULL,474),
('ety3erschl','e',3,'ety2wohn','Erschließungstypen im Wohnungsbau','Wie eine Wohnung erreicht wird, prägt so viel Wohnqualität wie ihr Grundriss selbst. Der Laubengang erschließt viele Wohnungen wirtschaftlich, verlangt aber Nähe zu Nachbarn, der Zweispänner bleibt diskret, braucht aber mehr Treppenhausfläche je Wohnung.',NULL,NULL,'{}'::text[],'[]'::jsonb,NULL,475),
('ety3flex','e',3,'ety2wohn','Flexible und teilbare Grundrisse','Ein Grundriss, der sich später teilen, zusammenlegen oder umnutzen lässt, verlangt schon beim Entwurf tragende Wände an den richtigen Stellen und Installationsschächte, die mitdenken. Diese Vorsorge kostet in der ersten Bauphase kaum etwas, erspart aber jeden späteren Umbau, der sonst an einer falsch gesetzten tragenden Wand scheitert.',NULL,NULL,ARRAY['eor3flexibel']::text[],'[]'::jsonb,NULL,476),
('ety3aussenraum','e',3,'ety2wohn','Private Freiräume: Loggia, Garten','Loggia, Balkon und Mietergarten sind kein Zubehör zur Wohnung, sondern deren wichtigste Erweiterung nach draußen. Ihre Lage zur Sonne, ihre Tiefe und ihr Sichtschutz entscheiden, ob sie tatsächlich genutzt werden oder nur als Abstellfläche enden.',NULL,NULL,'{}'::text[],'[]'::jsonb,NULL,477),
('ety2programm','e',2,'ety1','Arbeiten, Bildung, Kultur','Büro, Schule und Kulturbau folgen jeweils eigenen Raumlogiken, die sich aus ihrer Nutzung ableiten: Konzentration, Gruppenarbeit oder öffentlicher Auftritt verlangen unterschiedliche Antworten auf dieselbe Grundfrage nach Zellen und Gemeinschaftsfläche. Diese Gruppe stellt die Grundtypen jenseits des Wohnens nebeneinander.',NULL,NULL,'{}'::text[],'[]'::jsonb,NULL,478),
('ety3buero','e',3,'ety2programm','Bürotypologien: Zelle bis Open Space','Das Zellenbüro, ein Raum je Mitarbeitendem oder kleine Gruppe, schützt Konzentration, der offen gestaltete Open Space fördert Austausch, das Kombibüro versucht beides zu verbinden. Keine dieser Typologien ist grundsätzlich überlegen, jede passt zu einer bestimmten Arbeitskultur und scheitert an einer anderen.',NULL,NULL,'{}'::text[],'[]'::jsonb,NULL,479),
('ety3bildung','e',3,'ety2programm','Schulbau: Cluster statt Flur','Der klassische Flurschultyp weicht zunehmend dem Clusterprinzip, bei dem mehrere Klassenräume um eine gemeinsame Mitte gruppiert sind. Das verändert nicht nur die Pädagogik, sondern auch Brandschutz und Fluchtwegkonzept grundlegend.',NULL,NULL,'{}'::text[],'[]'::jsonb,NULL,480);
insert into public.nodes (id,perspective,level,parent_id,title,t1,t2,t3,links,sources,dach,ord) values
('ety3kultur','e',3,'ety2programm','Kulturbauten: Bühne und Foyer','Ein Kulturbau muss zwei widersprüchliche Räume gleichzeitig bedienen: die hochtechnische, oft fensterlose Bühnen- oder Ausstellungsfläche und das einladende, öffentliche Foyer davor. Der Übergang zwischen beiden ist fast immer die anspruchsvollste Entwurfsstelle des Gebäudes.',NULL,NULL,'{}'::text[],'[]'::jsonb,NULL,481),
('ety3gesundheit','e',3,'ety2programm','Gesundheitsbau: Funktion und Atmosphäre','Kaum eine Bauaufgabe stellt so viele funktionale Zwänge, von Hygienezonen bis zu Rettungswegen, und verlangt zugleich so dringend eine unbedrückende Atmosphäre für kranke Menschen. Gesundheitsbau ist ein Dauerkonflikt zwischen Funktionsplan und Aufenthaltsqualität.',NULL,NULL,'{}'::text[],'[]'::jsonb,NULL,482),
('ety2hybrid','e',2,'ety1','Hybride und Umnutzbarkeit','Reine Nutzungstypen werden seltener: Wohnen über Gewerbe, Bildung neben Kultur, ein Haus, das im Lauf seines Lebens mehrfach die Funktion wechselt. Diese Gruppe fragt, wie ein Gebäude von Anfang an für diesen Wandel gebaut werden kann, statt ihn nachträglich zu erzwingen.',NULL,NULL,'{}'::text[],'[]'::jsonb,NULL,483),
('ety3mischnutz','e',3,'ety2hybrid','Mischnutzung im selben Haus','Wohnen, Arbeiten und Gewerbe in einem Gebäude zu stapeln, klingt nach einfacher Addition, verlangt aber sorgfältig getrennte Erschließungen, Schallschutz zwischen den Nutzungen und oft unterschiedliche Geschosshöhen, die im Schnitt zusammengeführt werden müssen. Wer diese Trennung erst auf der Baustelle löst, verliert Zeit, die im Entwurf kaum etwas gekostet hätte.',NULL,NULL,'{}'::text[],'[]'::jsonb,NULL,484),
('ety3umnutz','e',3,'ety2hybrid','Umnutzbarkeit als Entwurfsprinzip','Ein Gebäude, das für seine zweite Nutzung mitgeplant wird, braucht großzügigere Geschosshöhen, ein neutraleres Stützenraster und Erschließungskerne, die auch mit veränderter Raumaufteilung noch funktionieren. Diese Vorsorge wirkt im Bauantrag unwirtschaftlich und zahlt sich erst Jahrzehnte später aus.',NULL,NULL,ARRAY['eor3sekundaer']::text[],'[]'::jsonb,NULL,485),
('ety3strukturoffen','e',3,'ety2hybrid','Strukturelle Offenheit','Je neutraler das tragende Raster, desto mehr Nutzungswechsel übersteht ein Gebäude, ohne dass Wände fallen müssen. Strukturelle Offenheit ist deshalb eine der wirksamsten, aber unauffälligsten Entscheidungen im Entwurf für die Lebensdauer eines Hauses.',NULL,NULL,ARRAY['eor3primaer']::text[],'[]'::jsonb,NULL,486),
('eko1','e',1,NULL,'Kontext und Ort','Kein Gebäude entsteht im leeren Raum: Es reagiert auf Nachbarn, Straßenraum, Topographie und die Geschichte eines Ortes, ob bewusst oder nicht. Dieser Ast versammelt das Entwurfswissen zum Weiterbauen im Bestehenden, zur städtebaulichen Figur und zur Lage im Gelände.',NULL,NULL,ARRAY['x1']::text[],'[]'::jsonb,NULL,487),
('eko2einfuegen','e',2,'eko1','Einfügen, Absetzen, Weiterbauen','Ein Neubau kann sich anpassen, bewusst abheben oder die Logik seiner Nachbarn fortschreiben: Alle drei sind legitime Entwurfshaltungen, solange sie als Entscheidung erkennbar bleiben und nicht aus Gleichgültigkeit entstehen. Diese Gruppe ordnet die Strategien, mit denen Architektur auf ihre bauliche Umgebung reagiert.',NULL,NULL,'{}'::text[],'[]'::jsonb,NULL,488),
('eko3kontinuitaet','e',3,'eko2einfuegen','Weiterbauen als Entwurfshaltung','Traufhöhe, Fassadenmaterial oder Fensterrhythmus des Nachbarn aufzunehmen ist kein Verzicht auf eigene Haltung, sondern eine eigene Disziplin. Weiterbauen verlangt, die Regeln eines Ortes zuerst zu lesen, bevor man sie fortschreibt oder gezielt bricht.',NULL,NULL,ARRAY['x2staedt']::text[],'[]'::jsonb,NULL,489),
('eko3kontrast','e',3,'eko2einfuegen','Bewusster Kontrast zum Bestand','Manche Orte vertragen und brauchen den klaren Bruch: ein neues Material, eine andere Höhe, eine eigene Geometrie, die sich als Ergänzung zu erkennen gibt, statt sich zu tarnen. Kontrast funktioniert nur, wenn er begründet ist, sonst wird er zur bloßen Behauptung.',NULL,NULL,'{}'::text[],'[]'::jsonb,NULL,490),
('eko3massstab','e',3,'eko2einfuegen','Maßstabssprung und Nachbarschaft','Ein Gebäude, das deutlich größer ist als seine Nachbarn, braucht Strategien gegen die Erdrückung: Gliederung der Fassade, Rücksprünge zur Straße, ein kleinteiliger Sockel. Der Maßstabssprung selbst ist selten das Problem, der unbearbeitete Übergang zur kleineren Nachbarschaft ist es.',NULL,NULL,'{}'::text[],'[]'::jsonb,NULL,491),
('eko3materialbezug','e',3,'eko2einfuegen','Materialbezug zur Umgebung','Ein Neubau kann das Material seiner Umgebung aufnehmen, ohne sie zu imitieren: denselben Ziegelton in anderem Format, dieselbe Putzstruktur in anderer Farbe. Dieser indirekte Bezug ist oft überzeugender als die wörtliche Kopie eines Nachbargebäudes.',NULL,NULL,'{}'::text[],'[]'::jsonb,NULL,492),
('eko3fassadenlinie','e',3,'eko2einfuegen','Baulinie, Rücksprung, Vorgarten','Ob ein Gebäude exakt an der Straße steht, zurückspringt oder einen Vorgarten vorschaltet, bestimmt die Disziplin des ganzen Straßenraums. Eine einzelne abweichende Baulinie stört das Straßenbild stärker, als es die Gebäudegröße vermuten lässt.',NULL,NULL,'{}'::text[],'[]'::jsonb,NULL,493),
('eko2koernung','e',2,'eko1','Städtebauliche Figur und Körnung','Körnung meint die Größe und Anzahl der Parzellen und Gebäude in einem Stadtgefüge: Feine Körnung erzeugt Vielfalt und Kleinteiligkeit, grobe Körnung Ruhe und Monumentalität. Diese Gruppe untersucht, wie sich diese Figur lesen und fortschreiben lässt.',NULL,NULL,'{}'::text[],'[]'::jsonb,NULL,494),
('eko3parzelle','e',3,'eko2koernung','Parzellenlogik und Blockrand','Die Parzelle ist die kleinste städtebauliche Einheit, an der sich Eigentum, Erschließung und Bebauungstiefe entscheiden. Der geschlossene Blockrand entsteht aus der Addition vieler einzelner Parzellenlösungen, nicht aus einem einzigen großen Entwurf.',NULL,NULL,ARRAY['x2staedt']::text[],'[]'::jsonb,NULL,495);
insert into public.nodes (id,perspective,level,parent_id,title,t1,t2,t3,links,sources,dach,ord) values
('eko3dichte','e',3,'eko2koernung','Dichte, Höhe, Körnung im Vergleich','Hohe Dichte lässt sich mit grober oder feiner Körnung erreichen, mit wenigen großen Gebäuden oder vielen kleinen. Beide Wege erzeugen dieselbe Ausnutzung, aber ein völlig unterschiedliches Erleben der Straße.',NULL,NULL,'{}'::text[],'[]'::jsonb,NULL,496),
('eko3fuge','e',3,'eko2koernung','Der Straßenraum als räumliche Fuge','Die Straße ist nicht nur Verkehrsfläche, sondern die Fuge zwischen zwei Bebauungskanten. Ihre Breite im Verhältnis zur Gebäudehöhe entscheidet, ob ein Straßenraum eng und geborgen oder weit und anonym wirkt.',NULL,NULL,'{}'::text[],'[]'::jsonb,NULL,497),
('eko3dachlandschaft','e',3,'eko2koernung','Dachlandschaft und Silhouette','Von oben oder aus der Ferne betrachtet, entsteht die Identität vieler Orte aus der Dachlandschaft: einheitliche Neigung, wiederkehrende Materialien, eine gemeinsame Traufhöhe. Ein einzelnes abweichendes Flachdach kann diese Silhouette stärker stören als jede Fassade darunter.',NULL,NULL,'{}'::text[],'[]'::jsonb,NULL,498),
('eko2landschaft','e',2,'eko1','Landschaft und Topographie','Ein Gebäude im Hang, am Wasser oder in offener Landschaft verhandelt mit Kräften, die kein Bebauungsplan festlegt: Geländehöhen, Sichtachsen, Vegetation. Diese Gruppe fragt, wie Topographie zum aktiven Entwurfsmaterial wird statt zum bloßen Hindernis.',NULL,NULL,'{}'::text[],'[]'::jsonb,NULL,499),
('eko3topografie','e',3,'eko2landschaft','Bauen im Hang: Sockel, Terrasse','Ein Hanggrundstück lässt sich mit einem hohen Sockel überspielen, in Terrassen auffächern oder mit einem Einschnitt in den Berg fast verschwinden lassen. Jede Strategie verändert das Verhältnis von Erdaushub, Belichtung und Erschließung grundlegend.',NULL,NULL,'{}'::text[],'[]'::jsonb,NULL,500),
('eko3ausblick','e',3,'eko2landschaft','Ausblick als Entwurfsparameter','Ein guter Ausblick ist selten Zufall: Fensterformat, Raumtiefe und Blickachse werden gezielt auf einen Fixpunkt in der Landschaft ausgerichtet, lange bevor die erste Fassadenlinie feststeht. Wo diese Ausrichtung fehlt, wirkt selbst die schönste Lage verschenkt.',NULL,NULL,'{}'::text[],'[]'::jsonb,NULL,501),
('eko3freiraum','e',3,'eko2landschaft','Freiraum zwischen den Häusern','Der Raum zwischen den Häusern ist so entworfen wie die Häuser selbst, auch wenn er oft als Restfläche behandelt wird. Wegeführung, Topographie und Bepflanzung entscheiden, ob dieser Zwischenraum genutzt wird oder nur übrig bleibt.',NULL,NULL,ARRAY['x3platz']::text[],'[]'::jsonb,NULL,502),
('eko3wasser','e',3,'eko2landschaft','Wasser und Topographie','Ein Bach, ein Teich oder auch nur eine Geländemulde für Regenwasser prägen die Lage eines Gebäudes stärker, als es auf den ersten Blick scheint. Wasser verlangt Abstand, Gefälle und oft eine eigene, sichtbare Führung durch das Grundstück.',NULL,NULL,'{}'::text[],'[]'::jsonb,NULL,503),
('eor1','e',1,NULL,'Ordnung und Struktur','Raster, Achse und Symmetrie sind die stillen Werkzeuge, mit denen Architektur Ordnung herstellt, oft unsichtbar für den Laien, aber überall spürbar. Dieser Ast fragt, wie viel Ordnung ein Entwurf braucht und wo bewusste Störung mehr Qualität schafft als strenge Regel.',NULL,NULL,'{}'::text[],'[]'::jsonb,NULL,504),
('eor2raster','e',2,'eor1','Raster, Achse, Reihung','Ein Raster ordnet Bauteile, Räume und Fassaden nach einem wiederkehrenden Maß und macht ein Gebäude dadurch lesbar, ohne es zu vereinheitlichen: Die Achse setzt einen einzelnen Bezugspunkt, die Reihung wiederholt ein Element im Takt. Diese Gruppe versammelt die Grundwerkzeuge geometrischer Ordnung.',NULL,NULL,'{}'::text[],'[]'::jsonb,NULL,505),
('eor3konstrraster','e',3,'eor2raster','Konstruktions- und Entwurfsraster','Das Konstruktionsraster folgt der Statik, also Stützenabstand und Spannweite, das Entwurfsraster kann darüberliegend feiner unterteilen, etwa für Fassade oder Möblierung. Beide Raster müssen aufeinander abgestimmt sein, sonst kollidiert die Fassadengliederung mit einer Stütze.',NULL,NULL,'{}'::text[],'[]'::jsonb,NULL,506),
('eor3achse','e',3,'eor2raster','Die Achse als Ordnungsmittel','Eine Achse verbindet zwei Punkte über den Raum hinweg, oft unsichtbar bis auf ihre Wirkung: Sie kann einen Eingang mit einem Turm verbinden oder eine ganze Raumfolge auf ein Ziel ausrichten. Wo eine Achse gebrochen wird, spürt man das, bevor man es erklären kann.',NULL,NULL,'{}'::text[],'[]'::jsonb,NULL,507),
('eor3reihung','e',3,'eor2raster','Reihung und Rhythmus','Ein Fenster allein ist ein Loch in der Wand, aber dieselbe Öffnung im gleichmäßigen Takt wiederholt wird zum Rhythmus. Reihung erzeugt aus einem einzelnen Element eine übergeordnete Ordnung, die stärker wirkt als jedes Einzelteil.',NULL,NULL,'{}'::text[],'[]'::jsonb,NULL,508),
('eor3modul','e',3,'eor2raster','Modulares Bauen und Wiederholung','Ein durchgängiges Modul, von der Fassadenachse bis zum Bauteilkatalog, macht Vorfertigung und Wiederholung wirtschaftlich, verlangt aber Disziplin an jeder Stelle, an der eine Ausnahme verlockend wäre. Der wirtschaftliche Vorteil verschwindet mit der ersten Sonderlösung.',NULL,NULL,'{}'::text[],'[]'::jsonb,NULL,509),
('eor2symmetrie','e',2,'eor1','Symmetrie und ihre Brüche','Symmetrie verspricht Ruhe, Repräsentation und leichte Lesbarkeit, doch die strenge Achsenspiegelung ist selten die letzte Antwort: Fast jede überzeugende symmetrische Anlage lebt von einem gezielten Bruch. Diese Gruppe untersucht, wann Symmetrie trägt und wann ihre Störung die eigentliche Entwurfsleistung ist.',NULL,NULL,'{}'::text[],'[]'::jsonb,NULL,510);
insert into public.nodes (id,perspective,level,parent_id,title,t1,t2,t3,links,sources,dach,ord) values
('eor3achsensymm','e',3,'eor2symmetrie','Achsensymmetrie und Repräsentation','Ein Gebäude, das exakt auf eine Mittelachse gespiegelt ist, wirkt fast automatisch bedeutsam. Öffentliche und repräsentative Bauten greifen deshalb häufig zur Achsensymmetrie, auch wenn sie im Inneren längst nicht mehr symmetrisch funktionieren.',NULL,NULL,'{}'::text[],'[]'::jsonb,NULL,511),
('eor3bruch','e',3,'eor2symmetrie','Der bewusste Bruch der Symmetrie','Ein einzelnes verschobenes Fenster oder ein asymmetrischer Erker in einer sonst gespiegelten Fassade lenkt den Blick genau dorthin und macht die Symmetrie erst als Regel sichtbar, die gebrochen wird. Der Bruch funktioniert nur, wenn die Regel vorher klar erkennbar war.',NULL,NULL,'{}'::text[],'[]'::jsonb,NULL,512),
('eor3asymm','e',3,'eor2symmetrie','Asymmetrische Komposition','Asymmetrie heißt nicht Regellosigkeit: Auch eine unsymmetrische Fassade sucht ein Gleichgewicht aus Fläche, Öffnung und Gewicht, nur ohne die Spiegelachse als Hilfsmittel. Dieses Gleichgewicht zu treffen ist entwurflich anspruchsvoller als die einfache Spiegelung.',NULL,NULL,'{}'::text[],'[]'::jsonb,NULL,513),
('eor2struktur','e',2,'eor1','Struktur und Freiheit','Primärstruktur trägt, Sekundärstruktur teilt: Wo diese beiden Ebenen sauber getrennt sind, gewinnt ein Gebäude Freiheit für spätere Veränderung, ohne dass die tragende Ordnung angetastet werden muss. Diese Gruppe verbindet Ordnung als Entwurfsthema mit ihrer praktischen Konsequenz für Umbau und Wandel.',NULL,NULL,'{}'::text[],'[]'::jsonb,NULL,514),
('eor3primaer','e',3,'eor2struktur','Primärstruktur als Ordnungsgeber','Die Primärstruktur, also Stützen, tragende Wände und Decken, legt die Grundordnung eines Gebäudes für seine gesamte Lebensdauer fest: Sie zu ändern bedeutet fast immer einen Eingriff, der das ganze Haus betrifft. Wer sie großzügig und regelmäßig plant, kauft Freiheit für alles, was später kommt.',NULL,NULL,ARRAY['ety3strukturoffen']::text[],'[]'::jsonb,NULL,515),
('eor3sekundaer','e',3,'eor2struktur','Sekundärstruktur und Ausbaufreiheit','Nichttragende Wände, Einbauten und Installationen bilden die Sekundärstruktur: Sie lässt sich, anders als die Primärstruktur, ohne großen Aufwand versetzen oder entfernen. Ein Gebäude, das diese Trennung konsequent durchhält, bleibt über Jahrzehnte anpassungsfähig.',NULL,NULL,ARRAY['ety3umnutz']::text[],'[]'::jsonb,NULL,516),
('eor3traeger','e',3,'eor2struktur','Das tragende Raster als Freiheit','Wenige, weit gespannte Stützen schaffen im Inneren stützenfreie Fläche, die sich beliebig unterteilen lässt. Dieses Prinzip, in der Moderne oft als offene Grundrissstruktur gefeiert, tauscht höheren konstruktiven Aufwand gegen maximale Nutzungsfreiheit.',NULL,NULL,'{}'::text[],'[]'::jsonb,NULL,517),
('eor3flexibel','e',3,'eor2struktur','Strukturelle Reserve für Umnutzung','Wer beim Entwurf zusätzliche Geschosshöhe, ein neutrales Raster oder überzählige Stützkapazität einplant, baut eine Reserve ein, die sich erst Jahre später auszahlt, wenn ein Umbau ohne Verstärkung möglich wird. Diese Reserve ist selten teuer, wird aber selten aktiv gefordert.',NULL,NULL,ARRAY['ety3flex']::text[],'[]'::jsonb,NULL,518),
('xws1','x',1,NULL,'Weißenhofsiedlung, Stuttgart','Die Weißenhofsiedlung entstand 1927 als Bauausstellung des Deutschen Werkbunds unter künstlerischer Leitung von Mies van der Rohe, mit Beiträgen von Architekten wie Le Corbusier, Walter Gropius und Hans Scharoun. Sie versammelte auf engem Raum die Programmatik des Neuen Bauens: flache Dächer, weiße Putzfassaden, offene Grundrisse und serielle Bauweisen als Antwort auf die Wohnungsnot der Zeit. Als Fallstudie zeigt sie, wie unterschiedlich verschiedene Architekten dieselbe Haltung in Städtebau, Grundriss und Fassade übersetzten. Wer verstehen will, wie aus einem Manifest gebaute Architektur wird, findet hier die dichteste Versammlung der klassischen Moderne.',NULL,NULL,'{}'::text[],'[]'::jsonb,NULL,519),
('xha1','x',1,NULL,'Siedlung Halen, Bern','Die Siedlung Halen bei Bern, ab Mitte der 1950er Jahre vom Architektenteam Atelier 5 entwickelt, verdichtet Reihenhäuser terrassenartig in den Hang und schafft dabei private Höfe ebenso wie gemeinschaftliche Wege und Plätze. Sie gilt als Gegenentwurf zum freistehenden Einfamilienhaus und als früher Beweis, dass verdichtetes Wohnen nicht zwangsläufig beengt wirken muss. Als Fallstudie lohnt sie wegen der klaren Regeln, mit denen private und gemeinschaftliche Räume ineinander verschränkt werden. Wer heute an verdichtetem Flachbau arbeitet, findet hier ein Grundmuster, das kaum gealtert ist.',NULL,NULL,'{}'::text[],'[]'::jsonb,NULL,520),
('xbs1','x',1,NULL,'Borneo-Sporenburg, Amsterdam','Borneo-Sporenburg ist ein ehemaliges Hafenareal in Amsterdam, das in den 1990er Jahren nach einem Masterplan von West 8 zu einem dicht bebauten Wohnquartier aus schmalen Einzelparzellen umgebaut wurde. Statt Geschosswohnungsbau setzt das Quartier auf verdichteten Flachbau mit individuellen Patiohäusern, jedes von einem eigenen Architekten entworfen, aber einem strengen städtebaulichen Regelwerk unterworfen. Als Fallstudie zeigt es, wie hohe Dichte und architektonische Vielfalt sich nicht ausschließen, wenn der Städtebau die Regeln setzt und die Häuser die Freiheit bespielen. Wer nach Alternativen zum Geschosswohnungsbau für urbane Dichte sucht, findet hier ein durchgerechnetes Modell.',NULL,NULL,'{}'::text[],'[]'::jsonb,NULL,521),
('xun1','x',1,NULL,'Unité d''habitation, Marseille','Die Unité d''habitation in Marseille, 1947 bis 1952 von Le Corbusier gebaut, ist ein Wohnhochhaus für rund 1600 Bewohner mit innenliegenden Erschließungsstraßen, Maisonette-Wohnungen und einem Dach, das Laufbahn, Kindergarten und Gemeinschaftsflächen trägt. Sie setzt den Anspruch um, ein ganzes Dorf vertikal zu stapeln, komplett mit Läden, Kita und Freiraum. Als Fallstudie ist sie zentral, weil sie den Sichtbeton als eigenständige Ausdrucksform etabliert und das Prinzip der Wohnmaschine radikal zu Ende denkt. Wer die Herkunft des Wohnhochhauses als soziale Idee verstehen will, kommt an diesem Bau nicht vorbei.',NULL,NULL,'{}'::text[],'[]'::jsonb,NULL,522),
('xga1','x',1,NULL,'Gallaratese, Mailand','Der Wohnblock Gallaratese in Mailand, den Aldo Rossi im Rahmen des größeren, von Carlo Aymonino koordinierten Monte-Amiata-Komplexes entwarf, reiht sich als langer Riegel mit durchlaufender Arkade und strengem Fensterraster in die Stadt ein. Rossi setzt hier seine Theorie der Stadt als Sammlung typologischer Grundformen in gebaute Form um, reduziert und fast abstrakt. Als Fallstudie ist der Bau ein Schlüsselwerk des italienischen Rationalismus und zeigt, wie Wiederholung und Strenge selbst zu einem Ausdrucksmittel werden können. Wer verstehen will, wie Typologie als Entwurfsmethode funktioniert, findet hier ihre konsequenteste gebaute Form.',NULL,NULL,'{}'::text[],'[]'::jsonb,NULL,523),
('xwr1','x',1,NULL,'Wohnregal und Baugruppenprojekte Berlin','Das Wohnregal in Berlin und die Welle privater Baugruppenprojekte, die sich seit den 2000er Jahren vor allem in Prenzlauer Berg und Kreuzberg entwickelte, stehen für eine andere Bauherrenschaft: Nutzer planen und finanzieren gemeinsam, statt fertige Wohnungen von Investoren zu kaufen. Typisch sind Rohbaustrukturen, die individuell ausgebaut werden, und Grundrisse, die erst in der Nutzung fertig werden. Als Fallstudie interessiert diese Bewegung, weil sie zeigt, wie ein verändertes Finanzierungsmodell direkt auf Grundriss, Fassade und Ausbaustandard durchschlägt. Wer verstehen will, wie Beteiligung zu Architektur wird und nicht nur zu Prozess, findet hier ein aktuelles, sehr berlinerisches Beispiel.',NULL,NULL,'{}'::text[],'[]'::jsonb,NULL,524),
('xnn1','x',1,NULL,'Neue Nationalgalerie, Berlin','Die Neue Nationalgalerie in Berlin, 1968 von Mies van der Rohe als eines seiner letzten Werke vollendet, stellt eine stützenfreie Glashalle auf acht schlanken Stahlstützen über einen eingegrabenen Sockel mit den eigentlichen Ausstellungsräumen. Das Dach schwebt als eigenständiges Element über der komplett verglasten Halle und macht den Bau selbst zum Ausstellungsstück, noch bevor ein Kunstwerk gezeigt wird. Als Fallstudie zeigt sie die Konsequenz des Stahlskelettbaus im Museumsbau und die Frage, wie viel technische Perfektion ein Ausstellungshaus verträgt. Wer über die Spannung zwischen universeller Halle und musealer Nutzung nachdenkt, findet hier den Referenzbau schlechthin.',NULL,NULL,'{}'::text[],'[]'::jsonb,NULL,525);
insert into public.nodes (id,perspective,level,parent_id,title,t1,t2,t3,links,sources,dach,ord) values
('xtv1','x',1,NULL,'Therme Vals','Die Therme Vals im Schweizer Kanton Graubünden, 1996 von Peter Zumthor fertiggestellt, ist ein Thermalbad, das fast vollständig aus dem lokalen Valser Quarzit gemauert und in den Hang eingegraben ist. Schichtungen aus Naturstein, gedämpftes Licht aus schmalen Deckenschlitzen und der Wechsel aus engen und weiten Raumfolgen machen Baden zu einem sinnlichen, fast archaischen Erlebnis. Als Fallstudie ist sie zentral für den kritischen Regionalismus, weil sie zeigt, wie ein einziges, lokal verwurzeltes Material einen ganzen Bau trägt, konstruktiv wie atmosphärisch. Wer verstehen will, wie Material zu Architektur wird, ganz ohne Umweg über Dekoration, findet hier das Standardwerk.',NULL,NULL,'{}'::text[],'[]'::jsonb,NULL,526),
('xkl1','x',1,NULL,'Kolumba, Köln','Das Kunstmuseum Kolumba in Köln, 2007 von Peter Zumthor für das Erzbistum Köln über den Ruinen der im Krieg zerstörten gotischen Kirche St. Kolumba errichtet, verbindet archäologischen Bestand, eine Kapelle und neue Ausstellungsräume in einem einzigen, grau changierenden Ziegelbau. Ein perforiertes Ziegelmauerwerk überspannt die Ruine, lässt Licht und Wetter herein und macht die Grenze zwischen Alt und Neu bewusst erlebbar statt sie zu verstecken. Als Fallstudie zeigt der Bau einen Umgang mit Bestand und Verlust, der weder rekonstruiert noch verdrängt, sondern beides sichtbar übereinanderlegt. Wer nach einem Vorbild für Weiterbauen im hochsensiblen Bestand sucht, findet hier eine der konsequentesten Antworten.',NULL,NULL,'{}'::text[],'[]'::jsonb,NULL,527),
('xph1','x',1,NULL,'Philharmonie, Berlin','Die Berliner Philharmonie, 1963 von Hans Scharoun fertiggestellt, bricht mit dem klassischen Schuhkarton-Konzertsaal und staffelt das Publikum in unregelmäßigen, terrassierten Blöcken rings um das zentral platzierte Orchester. Das gefaltete, zeltartige Dach folgt von außen der inneren Raumdramaturgie und macht die ungewöhnliche Form sofort ablesbar. Als Fallstudie steht sie für das organische Bauen der Nachkriegsmoderne und für die Idee, dass Akustik und Gemeinschaftserlebnis den Grundriss bestimmen sollten, nicht die Symmetrie. Wer verstehen will, wie ein Saal aus der Musik heraus entworfen wird und nicht aus der Geometrie, findet hier das prägende Beispiel.',NULL,NULL,'{}'::text[],'[]'::jsonb,NULL,528),
('xre1','x',1,NULL,'Reformarchitektur und Gartenstadt','Um 1900 wächst in Europa eine Bewegung, die der engen, spekulativ verdichteten Industriestadt ein anderes Bild entgegensetzt: durchgrünte Siedlungen mit Reihenhäusern, eigenem Garten und einer bewusst handwerklich wirkenden Architektur. Vorbild ist Ebenezer Howards englische Gartenstadtidee, in Deutschland verbindet sie sich mit der Reformarchitektur des Deutschen Werkbunds und mit sozialreformerischen Wohnungsbauträgern. Der Ast versammelt das Übergangswissen zwischen Historismus und Moderne: noch giebelig und heimatlich in der Form, aber bereits modern in Städtebau, Erschließung und sozialem Anspruch. Wer die Wurzeln des deutschen Siedlungsbaus verstehen will, findet sie hier, nicht erst im Neuen Bauen der 1920er Jahre.',NULL,NULL,ARRAY['x1']::text[],'[]'::jsonb,NULL,529),
('xre2howard','x',2,'xre1','Die englische Gartenstadtidee','Ebenezer Howards 1898 formulierte Idee der Gartenstadt schlägt eigenständige, begrenzte Siedlungen zwischen Stadt und Land vor: kompakt genug für Nachbarschaft, grün genug für Gesundheit, genossenschaftlich organisiert gegen Bodenspekulation. Deutsche Planer übernehmen vor allem das räumliche Bild, kurvige Straßen, Vorgärten, niedrige Dichte, seltener das genossenschaftliche Bodenmodell dahinter. Der Import ist deshalb immer auch eine Übersetzung, die entscheidet, was von der ursprünglichen Idee tatsächlich ankommt.',NULL,NULL,'{}'::text[],'[]'::jsonb,NULL,530),
('xre2werkbund','x',2,'xre1','Deutscher Werkbund und Formreform','Der 1907 gegründete Deutsche Werkbund verbindet Industrie, Handwerk und Architektur mit dem Ziel, Qualität in die serielle Produktion zu bringen, von der Türklinke bis zum Siedlungshaus. Aus dieser Programmatik wachsen sowohl die Reformarchitektur der Vorkriegszeit als auch, eine Generation später, das Neue Bauen. Für Studierende lohnt der Blick auf den Werkbund, weil er zeigt, wie eng Formfragen und Wirtschaftsfragen von Anfang an zusammengehören.',NULL,NULL,'{}'::text[],'[]'::jsonb,NULL,531),
('xre2heimat','x',2,'xre1','Heimatschutzstil und regionales Bauen','Parallel zur Gartenstadtbewegung entsteht der Heimatschutzstil, der regionale Bauformen, Materialien und Handwerkstraditionen gegen eine als entwurzelt empfundene Großstadtarchitektur verteidigt. Steildächer, Fachwerk- und Putzbauten, kleinteilige Fenster: Das Vokabular wirkt rückwärtsgewandt, war aber im Kern eine frühe Kritik an Beliebigkeit und Maßstabsverlust. Die Nähe zu Kitsch und später zu völkischer Ideologie macht den Stil bis heute zum Streitfall, seine städtebauliche Substanz bleibt davon unabhängig lesbar.',NULL,NULL,'{}'::text[],'[]'::jsonb,NULL,532),
('xre2siedlung','x',2,'xre1','Genossenschaftlicher Wohnungsbau vor 1914','Bau- und Wohnungsgenossenschaften errichten vor dem Ersten Weltkrieg zahlreiche Werkssiedlungen und Arbeiterkolonien, oft von Industrieunternehmen mitfinanziert, um Fachkräfte zu binden und soziale Konflikte zu entschärfen. Diese Siedlungen sind die eigentlichen Testfelder der Reformarchitektur: Hier werden Reihenhaustypen, Grundrissvarianten und Freiraumkonzepte im großen Maßstab erprobt, lange bevor die Moderne der 1920er Jahre sie radikalisiert. Der soziale Auftrag, nicht die Form, ist hier oft der eigentliche Fortschritt.',NULL,NULL,ARRAY['x2staedt']::text[],'[]'::jsonb,NULL,533),
('xre2kritik','x',2,'xre1','Kritik an der Mietskaserne','Die Reformbewegung definiert sich wesentlich über ihren Gegner: die spekulativ verdichtete Mietskaserne der Gründerzeit mit dunklen Hinterhöfen und schlechter Belichtung. Aus dieser Kritik entstehen die zentralen Forderungen, die den Siedlungsbau bis weit ins 20. Jahrhundert prägen, nämlich Licht, Luft und ein eigener Gartenanteil für jede Wohnung. Wer die spätere Moderne verstehen will, muss diesen Gegner kennen, gegen den sie weiterhin argumentiert.',NULL,NULL,'{}'::text[],'[]'::jsonb,NULL,534),
('xkm1','x',1,NULL,'Klassische Moderne','Zwischen 1919 und 1933 formuliert das Neue Bauen einen radikalen Bruch mit Ornament, Symmetrie und Massivbauweise: der weiße Kubus, das Flachdach, die freie Fassade und der offene Grundriss werden zum internationalen Programm. Bauhaus, Werkbund und einzelne Pioniere wie Gropius, Mies van der Rohe, Le Corbusier und Taut bündeln technische Neuerungen im Stahlbeton- und Skelettbau mit einem sozialen Anspruch auf gesundes, bezahlbares Wohnen für alle. Der Ast versammelt das Wissen zu dieser kurzen, folgenreichen Epoche, die bis heute als Referenzpunkt jeder Debatte über funktionales Bauen dient. Wer die Grammatik der Moderne verstehen will, Fläche statt Wand, Konstruktion statt Fassade, findet hier ihre reinste Formulierung.',NULL,NULL,ARRAY['xws1','xun1']::text[],'[]'::jsonb,NULL,535),
('xkm2neuesbauen','x',2,'xkm1','Prinzipien des Neuen Bauens','Flaches Dach statt Satteldach, Stahlbeton- oder Stahlskelett statt tragender Wand, freie Fassade und offener Grundriss: Aus diesen wenigen Prinzipien entwickelt die klassische Moderne ein Formenvokabular, das sich bewusst von jedem historischen Stilzitat abgrenzt. Funktion soll die Form erzeugen, nicht umgekehrt, auch wenn die Praxis oft komplizierter war als das Manifest. Das Vokabular wirkt bis heute nach, meist unbemerkt, weil es zum Normalfall des Bauens geworden ist.',NULL,NULL,'{}'::text[],'[]'::jsonb,NULL,536),
('xkm2bauhaus','x',2,'xkm1','Bauhaus als Schule und Netzwerk','Das 1919 in Weimar gegründete Bauhaus verbindet Kunst, Handwerk und Industrie in einer neuen Ausbildung und wird, mehr als jeder Einzelbau, zum Multiplikator der Moderne. Seine Lehrer und Absolventen tragen die Ideen nach dem Umzug über Dessau und der Schließung 1933 in die ganze Welt, von den USA bis in die Sowjetunion. Für die Architekturgeschichte ist das Bauhaus deshalb weniger ein Baustil als ein Netzwerk, das die klassische Moderne globalisiert hat.',NULL,NULL,'{}'::text[],'[]'::jsonb,NULL,537),
('xkm2existenz','x',2,'xkm1','Existenzminimum und serielles Bauen','Angesichts akuter Wohnungsnot entwickelt die Moderne das Konzept des Existenzminimums: die kleinste Wohnung, die trotzdem menschenwürdig funktioniert, durchdacht bis auf den Möbelgriff. Serielle Fertigung, Typengrundrisse und die neue Zeilenbauweise sollen Wohnraum in der nötigen Masse und zu erschwinglichen Kosten liefern. Der Ansatz ist bis heute doppeldeutig, gleichermaßen Vorbild für effizientes Bauen und Warnung vor zu kleinem Zuschnitt.',NULL,NULL,'{}'::text[],'[]'::jsonb,NULL,538),
('xkm2ciam','x',2,'xkm1','CIAM und die funktionale Stadt','Die 1928 gegründeten Congrès Internationaux d''Architecture Moderne bündeln die Bewegung international und formulieren mit der Charta von Athen das Leitbild der funktional getrennten Stadt: Wohnen, Arbeiten, Erholung und Verkehr sauber sortiert statt gemischt. Diese Trennung prägt den Städtebau jahrzehntelang und wird erst spät als Ursache vieler monofunktionaler, autoabhängiger Quartiere erkannt. Die Kenntnis der Charta ist deshalb Pflicht, auch und gerade um ihre Grenzen zu verstehen.',NULL,NULL,'{}'::text[],'[]'::jsonb,NULL,539),
('xkm2ende','x',2,'xkm1','Bruch 1933 und Weiterleben im Exil','Die Machtübernahme der Nationalsozialisten 1933 beendet die klassische Moderne in Deutschland abrupt: Bauhaus, Werkbund und viele ihrer Protagonisten werden verboten, entlassen oder vertrieben. Im Exil, vor allem in den USA, setzt sich die Formensprache fort und prägt dort die Nachkriegsmoderne mit, oft entpolitisiert und zur reinen Stilfrage verkürzt. Diese Brucherfahrung gehört zur Geschichte der Moderne dazu, nicht als Fußnote, sondern als Erklärung ihrer zwiespältigen Rezeption nach 1945.',NULL,NULL,'{}'::text[],'[]'::jsonb,NULL,540);
insert into public.nodes (id,perspective,level,parent_id,title,t1,t2,t3,links,sources,dach,ord) values
('xnb1','x',1,NULL,'Nachkriegsmoderne und Brutalismus','In den Jahrzehnten nach 1945 muss Europa in großem Maßstab und unter Materialknappheit wieder aufgebaut werden: Sichtbeton wird vom Sparzwang zum eigenen Ausdrucksmittel, Großstrukturen und Trabantenstädte sollen die Wohnungsnot lösen. Der Brutalismus, benannt nach dem französischen béton brut, radikalisiert diese Haltung zur rohen, unverkleideten Materialehrlichkeit, während andere Architekten organische oder rationalistische Gegenentwürfe suchen. Der Ast versammelt diese Vielfalt der Nachkriegsantworten, von der Philharmonie bis zur Großsiedlung, die heute zwischen Denkmalschutz und Abrissdruck steht. Wer die schwierige Wertschätzung des Betonerbes verstehen will, findet hier die Grundlagen dieser Debatte.',NULL,NULL,ARRAY['xnn1','xph1','xga1']::text[],'[]'::jsonb,NULL,541),
('xnb2wiederaufbau','x',2,'xnb1','Wiederaufbau und Wohnungsnot','Nach 1945 fehlen in den zerstörten Städten Millionen Wohnungen, die Antwort ist industrialisiertes, serielles Bauen im großen Maßstab, oft in Plattenbauweise oder mit vorgefertigten Betonelementen. Tempo und Menge stehen vor Individualität, was den Großsiedlungen dieser Zeit bis heute den Ruf der Monotonie einträgt, obwohl viele städtebaulich sorgfältig durchdacht waren. Die Bewertung dieser Siedlungen verändert sich gerade deutlich, vom Sanierungsfall zum schützenswerten Zeitdokument.',NULL,NULL,'{}'::text[],'[]'::jsonb,NULL,542),
('xnb2brutalismus','x',2,'xnb1','Brutalismus und Sichtbeton','Der Brutalismus zeigt Beton als das, was er ist, mit Schalungsstruktur, Kanten und Fugen, statt ihn hinter Putz oder Verkleidung zu verstecken. Aus wirtschaftlicher Notwendigkeit wird eine ästhetische Haltung, die Ehrlichkeit über Behaglichkeit stellt und damit bis heute polarisiert. Gerade weil der Stil so unbeliebt war, ist seine Wiederentdeckung heute auch eine Lektion in Geschmackswandel.',NULL,NULL,'{}'::text[],'[]'::jsonb,NULL,543),
('xnb2grossstruktur','x',2,'xnb1','Megastrukturen und Großformen','Parallel zum Brutalismus entstehen Entwürfe, die ganze Stadtstrukturen als ein einziges, wachstumsfähiges Gebäude denken, mit eigenen Straßen, Plätzen und Versorgungssystemen im Bauwerk selbst. Nur wenige dieser Megastrukturen werden je vollständig gebaut, ihr Einfluss auf die Vorstellung, was ein Gebäude leisten kann, reicht aber weit über die gebauten Beispiele hinaus. Als Denkfigur bleibt die Megastruktur bis in heutige Debatten über Mischnutzung und Flexibilität lesbar.',NULL,NULL,'{}'::text[],'[]'::jsonb,NULL,544),
('xnb2organisch','x',2,'xnb1','Organische Gegenentwürfe','Nicht alle Nachkriegsarchitekten setzen auf Raster und rohen Beton: Architekten wie Hans Scharoun entwickeln eine organische Formensprache, die vom Innenraum und seiner Nutzung her denkt statt von der geometrischen Ordnung. Geschwungene Grundrisse, gestaffelte Volumen und eine bewusst asymmetrische Komposition setzen sich damit von der strengen Geometrie der klassischen Moderne ab. Diese Linie bleibt eine Minderheitenposition, aber eine einflussreiche.',NULL,NULL,'{}'::text[],'[]'::jsonb,NULL,545),
('xnb2erbe','x',2,'xnb1','Umgang mit dem Betonerbe heute','Viele Bauten der Nachkriegsmoderne stehen heute vor derselben Frage, sanieren, umnutzen oder abreißen, verschärft durch echte bauphysikalische Probleme wie Carbonatisierung und schlechte Wärmedämmung. Der Denkmalschutz tut sich mit dieser Generation schwerer als mit älteren Epochen, weil ihr Wert erst spät und oft gegen öffentliche Widerstände anerkannt wird. Der Umgang mit diesem Erbe ist deshalb auch ein Testfall dafür, wie ernst Weiterbauen statt Abriss tatsächlich gemeint ist.',NULL,NULL,'{}'::text[],'[]'::jsonb,NULL,546),
('xkr1','x',1,NULL,'Kritischer Regionalismus','Als Antwort auf die zunehmend austauschbare, globalisierte Architektur der Nachkriegszeit fordert der kritische Regionalismus ab den 1980er Jahren eine Architektur, die auf Ort, Klima, Licht und lokale Materialien reagiert, ohne in folkloristische Nachahmung zurückzufallen. Der Begriff, von Kenneth Frampton geprägt, beschreibt keinen Stil, sondern eine Haltung: modern in der Konstruktion, aber verwurzelt in der Wahrnehmung des Ortes. Architekten wie Peter Zumthor oder Álvaro Siza stehen exemplarisch für diese Position. Der Ast versammelt das Wissen zu einer Haltung, die bis heute eine der stärksten Gegenpositionen zur globalisierten Architektur bildet.',NULL,NULL,ARRAY['xtv1','xkl1']::text[],'[]'::jsonb,NULL,547),
('xkr2frampton','x',2,'xkr1','Kenneth Framptons Theorie','Kenneth Frampton beschreibt den kritischen Regionalismus 1983 als vermittelnde Position zwischen einer bodenständigen, aber rückwärtsgewandten Regionalarchitektur und einer universellen, aber ortlosen Moderne. Zentral ist der Begriff der Tektonik, die sinnliche Erfahrbarkeit von Konstruktion, Material und Licht, statt bloß visueller Bildwirkung. Die Theorie liefert bis heute das begriffliche Werkzeug, um ortsbezogene Architektur von reiner Regionalfolklore zu unterscheiden.',NULL,NULL,'{}'::text[],'[]'::jsonb,NULL,548),
('xkr2material','x',2,'xkr1','Lokales Material als Prinzip','Statt globaler Kataloge greift der kritische Regionalismus auf Materialien zurück, die am Ort verfügbar sind oder eine lange Bautradition dort haben, Stein, Ziegel, Holz, jeweils in ihrer regionalen Ausprägung. Das Material wird damit selbst zum Träger von Bedeutung und Ortsbezug, nicht nur zur technischen Notwendigkeit. Diese Haltung verlangt handwerkliches Wissen und oft engen Kontakt zu lokalen Betrieben, was sie zu einem bewussten Gegenmodell zur globalisierten Bauwirtschaft macht.',NULL,NULL,'{}'::text[],'[]'::jsonb,NULL,549),
('xkr2klima','x',2,'xkr1','Klima und Topografie als Entwurfsgrundlage','Sonnenstand, Windrichtung, Geländeform und Mikroklima werden im kritischen Regionalismus zu primären Entwurfsparametern erhoben, nicht zu nachträglich einzurechnenden Randbedingungen. Ein Gebäude, das aus diesen Faktoren entwickelt wird, sieht an unterschiedlichen Orten zwangsläufig unterschiedlich aus, selbst bei ähnlicher Aufgabe. Das steht in bewusstem Gegensatz zum international beliebig wiederholbaren Gebäudetyp.',NULL,NULL,'{}'::text[],'[]'::jsonb,NULL,550),
('xkr2vertreter','x',2,'xkr1','Wichtige Vertreter und Positionen','Peter Zumthor in der Schweiz, Álvaro Siza in Portugal oder Glenn Murcutt in Australien entwickeln, unabhängig voneinander, sehr eigene, aber verwandte Antworten auf dieselbe Grundfrage, wie Architektur ohne Ortsbezug ihre Bedeutung verliert. Ihre Bauten unterscheiden sich stark in Material und Form, teilen aber die Sorgfalt im Umgang mit Licht, Handwerk und Landschaft. Der Vergleich dieser Positionen zeigt, dass kritischer Regionalismus kein einheitlicher Stil, sondern eine gemeinsame Haltung mit vielen Gesichtern ist.',NULL,NULL,'{}'::text[],'[]'::jsonb,NULL,551),
('xkr2kritik','x',2,'xkr1','Grenzen und Kritik','Kritiker werfen dem kritischen Regionalismus vor, selbst zu einer globalen Marke geworden zu sein: Ein bestimmter Umgang mit Sichtbeton, Holz und gedämpftem Licht wird international kopiert, gerade weil er als Gegenmodell zur Beliebigkeit gilt. Das Paradox zeigt, wie schwer es ist, Ortsbezug zu formulieren, ohne selbst wieder zum reproduzierbaren Rezept zu werden. Diese Selbstkritik gehört zum ehrlichen Bild der Bewegung dazu.',NULL,NULL,'{}'::text[],'[]'::jsonb,NULL,552),
('xzp1','x',1,NULL,'Zeitgenössische Positionen','Seit etwa 2000 verschieben sich die Leitfragen der Architektur: Klimakrise, Ressourcenknappheit und die Kritik am Abriss prägen die zeitgenössischen Positionen stärker als reine Formfragen. Büros wie Lacaton und Vassal stellen radikal die Frage, ob ein Gebäude überhaupt neu gebaut werden muss, wenn Umbau, Erweiterung und Weiternutzung möglich sind. Der Ast versammelt diese jüngeren Haltungen, die sich oft explizit gegen die Wegwerfarchitektur der Jahrzehnte davor richten. Wer die aktuelle Debatte um Bauwende und Suffizienz einordnen will, findet hier ihre architektonischen Positionen.',NULL,NULL,'{}'::text[],'[]'::jsonb,NULL,553),
('xzp2niemals','x',2,'xzp1','Umbauen statt abreißen','Lacaton und Vassal prägen mit ihrer Haltung, wonach bestehende Bausubstanz grundsätzlich erhalten und erweitert statt abgerissen werden soll, eine der einflussreichsten Positionen der letzten Jahre. Ihre Umbauten von Wohnhochhäusern zeigen, dass mehr Fläche, mehr Licht und bessere Wohnqualität oft günstiger zu erreichen sind als über einen Neubau. Die Position hat die Fachdiskussion sichtbar verschoben, vom Neubau als Normalfall hin zum Weiterbauen als erster Option.',NULL,NULL,'{}'::text[],'[]'::jsonb,NULL,554),
('xzp2klima','x',2,'xzp1','Klimagerechtes und ressourcenschonendes Bauen','Graue Energie, Rückbaufähigkeit und CO2-Bilanz werden zu zentralen Entwurfskriterien, die neben Funktion und Gestaltung gleichberechtigt mitgedacht werden müssen. Zeitgenössische Büros experimentieren mit reduziertem Materialeinsatz, wiederverwendeten Bauteilen und einfachen, reparierbaren Konstruktionen, oft bewusst gegen den Trend zu technisch aufwendigen Gebäudehüllen. Diese Haltung verändert nicht nur einzelne Materialentscheidungen, sondern die Grundfrage, was ein gutes Gebäude überhaupt ausmacht.',NULL,NULL,'{}'::text[],'[]'::jsonb,NULL,555);
insert into public.nodes (id,perspective,level,parent_id,title,t1,t2,t3,links,sources,dach,ord) values
('xzp2einfach','x',2,'xzp1','Einfaches und robustes Bauen','Als Gegenbewegung zur komplexen, technisch hochgerüsteten Gebäudehülle setzen manche zeitgenössischen Büros bewusst auf einfache Konstruktionen, robuste Materialien und Räume, die viele Nutzungen erlauben, ohne für jede einzelne maßgeschneidert zu sein. Diese Haltung wird oft mit dem Begriff des einfachen, technisch zurückhaltenden Bauens umschrieben und versteht sich als Kritik an einer Architektur, die technische Komplexität mit Qualität verwechselt. Robustheit und Umnutzbarkeit werden damit selbst zu gestalterischen Zielen.',NULL,NULL,'{}'::text[],'[]'::jsonb,NULL,556),
('xzp2beteilig','x',2,'xzp1','Partizipation und Baugemeinschaften','Zeitgenössische Positionen rücken zunehmend die künftigen Nutzer in den Entwurfsprozess selbst ein, von Baugruppen bis zu offen geplanten Strukturen, die von Bewohnern weiterentwickelt werden. Architektinnen wie Anna Heringer verbinden diesen Ansatz oft mit einfachen, lokal verfügbaren Materialien und Selbstbautechniken, gerade in Projekten außerhalb Mitteleuropas. Der Ansatz stellt die Rolle des Architekten selbst zur Diskussion, vom alleinigen Gestalter zum Moderator eines gemeinsamen Prozesses.',NULL,NULL,'{}'::text[],'[]'::jsonb,NULL,557),
('xzp2sergison','x',2,'xzp1','Die gewöhnliche Stadt als Vorbild','Büros wie Sergison Bates suchen bewusst in der gewöhnlichen, oft unspektakulären Stadt nach Vorbildern, in Reihenhaustypologien, Ziegelfassaden und robusten Grundrissen, statt nach spektakulären Einzelbauten. Diese Haltung würdigt das scheinbar Banale als eigentlichen Träger städtischer Qualität und stellt sich damit gegen eine Architektur der spektakulären Ikonen. Für die Praxis ist das eine Ermutigung, gute Architektur auch dort zu suchen, wo sie nicht auffällt.',NULL,NULL,'{}'::text[],'[]'::jsonb,NULL,558),
('pab1','p',1,NULL,'Projektablauf und Leistungsbild','Ein Bauprojekt verläuft nicht linear, sondern in aufeinander aufbauenden Phasen, von der ersten Idee bis zur Übergabe. Wie diese Phasen heißen, wer welche Leistung erbringt und wie eng Auftraggeber und Planer dabei verzahnt sind, unterscheidet sich zwischen Deutschland, Österreich und der Schweiz erheblich, obwohl die eigentliche Projektlogik überall dieselbe ist. Wer das Leistungsbild kennt, weiß, wofür er beauftragt ist und wofür nicht, das schützt vor Streit ebenso wie vor Lücken.',NULL,NULL,'{}'::text[],'[]'::jsonb,NULL,559),
('pab2phasen','p',2,'pab1','Phasenmodelle im Vergleich','Jedes Land teilt ein Bauprojekt in nummerierte oder benannte Leistungsphasen, doch Zuschnitt und Detailtiefe unterscheiden sich spürbar. Wer über Ländergrenzen hinweg plant oder ein internationales Team koordiniert, muss die Phasenmodelle übersetzen können, nicht nur die Sprache. Die Struktur entscheidet außerdem darüber, wann welches Honorar fällig wird und wann eine Leistung als erbracht gilt.',NULL,NULL,'{}'::text[],'[{"t":"HOAI","stand":"HOAI 2013 i. d. F. der 1. ÄndVO, in Kraft 01.01.2021; Honorartafeln nach EuGH nur Orientierung","u":"https://www.gesetze-im-internet.de/hoai_2013/","geprueft":"2026-08-19"},{"t":"SIA 112 Modell Bauplanung","stand":"Ausgabe 2014","u":"https://shop.sia.ch/normenwerk/ingenieur/112_2014_d/D/Product","geprueft":"2026-08-19"},{"t":"SIA 102 Leistungen und Honorare der Architekten","stand":"Ausgabe 2020","u":"https://shop.sia.ch/normenwerk/architekt/102_2020_d/D/Product","geprueft":"2026-08-19"}]'::jsonb,'{"de":"Die Leistungsphasen 1 bis 9 der HOAI gliedern das Projekt von der Grundlagenermittlung bis zur Objektbetreuung und sind die in Deutschland übliche Referenz für Honorarstufen und Leistungsbeschreibung.","at":"In Österreich strukturieren Leistungsmodelle nach ÖNORM, insbesondere das Leistungsmodell Verfahren und Vertrag (LM.VM), den Ablauf, wobei die Phaseneinteilung freier vereinbart wird als im deutschen System.","ch":"Die Schweiz ordnet Projekte nach dem Phasenmodell der SIA 112, während die zugehörigen Planerleistungen in der SIA 102 beschrieben sind, beide bilden gemeinsam die Referenz für Leistungsbild und Ablauf."}'::jsonb,560),
('pab3grundlagen','p',3,'pab2phasen','Grundlagenermittlung und Bedarfsplanung','Am Anfang steht die Klärung der Aufgabe: Bedarf, Rahmenbedingungen, Budget und Ziele werden erfasst, bevor die erste Linie gezeichnet wird. Diese frühe Phase entscheidet über Machbarkeit und Kosten mehr als jede spätere Detailplanung, wird aber oft zu knapp bemessen. Eine sauber dokumentierte Grundlagenermittlung ist die Versicherung gegen spätere Zielkonflikte.',NULL,NULL,'{}'::text[],'[{"t":"HOAI","stand":"HOAI 2013 i. d. F. der 1. ÄndVO, in Kraft 01.01.2021; Honorartafeln nach EuGH nur Orientierung","u":"https://www.gesetze-im-internet.de/hoai_2013/","geprueft":"2026-08-19"},{"t":"SIA 112 Modell Bauplanung","stand":"Ausgabe 2014","u":"https://shop.sia.ch/normenwerk/ingenieur/112_2014_d/D/Product","geprueft":"2026-08-19"},{"t":"SIA 102 Leistungen und Honorare der Architekten","stand":"Ausgabe 2020","u":"https://shop.sia.ch/normenwerk/architekt/102_2020_d/D/Product","geprueft":"2026-08-19"}]'::jsonb,'{"de":"Grundlagenermittlung und Vorplanung entsprechen den Leistungsphasen 1 und 2 der HOAI und bilden die Honorargrundlage für alle folgenden Phasen.","at":"Die vergleichbaren Leistungen werden in Österreich meist als Grundlagen- und Vorentwurfsphase frei zwischen Planer und Bauherrn vereinbart, ohne festen Phasenkatalog.","ch":"In der Schweiz zählen diese Schritte nach SIA 112 zur strategischen Planung und zum Vorprojekt, mit eigenständiger Honorierung nach SIA 102."}'::jsonb,561),
('pab3vorentwurf','p',3,'pab2phasen','Vorplanung und Entwurfsplanung','In dieser Phase wird aus der Aufgabenstellung ein räumliches und gestalterisches Konzept, das Grundriss, Volumen und Konstruktion erstmals verbindlich festlegt. Änderungen sind hier noch günstig, ab der Genehmigungsplanung werden sie teuer. Der Entwurf ist zugleich die Phase, in der Bauherr und Planer ihr gemeinsames Bild des Projekts endgültig abgleichen müssen.',NULL,NULL,'{}'::text[],'[{"t":"HOAI","stand":"HOAI 2013 i. d. F. der 1. ÄndVO, in Kraft 01.01.2021; Honorartafeln nach EuGH nur Orientierung","u":"https://www.gesetze-im-internet.de/hoai_2013/","geprueft":"2026-08-19"},{"t":"SIA 112 Modell Bauplanung","stand":"Ausgabe 2014","u":"https://shop.sia.ch/normenwerk/ingenieur/112_2014_d/D/Product","geprueft":"2026-08-19"},{"t":"SIA 102 Leistungen und Honorare der Architekten","stand":"Ausgabe 2020","u":"https://shop.sia.ch/normenwerk/architekt/102_2020_d/D/Product","geprueft":"2026-08-19"}]'::jsonb,'{"de":"Diese Phase deckt die Leistungsphasen 2 und 3 der HOAI ab, Vorplanung und Entwurfsplanung, mit jeweils eigenen Teilleistungen und Honoraranteilen.","at":"In Österreich wird dieser Schritt häufig als Vorentwurf und Einreichplanung bezeichnet, wobei die genaue Abgrenzung vertraglich statt normativ festgelegt wird.","ch":"Nach SIA 112 entspricht dies dem Vorprojekt und dem Bauprojekt, deren Leistungsinhalte die SIA 102 beschreibt."}'::jsonb,562),
('pab3genehmigung','p',3,'pab2phasen','Genehmigungsplanung','Die Genehmigungsplanung übersetzt den Entwurf in die Sprache der Behörde: vollständige, prüffähige Unterlagen, die eine Baugenehmigung ermöglichen. Wie viel Detail dafür nötig ist und wie das Verfahren abläuft, regelt nicht das Leistungsbild, sondern das Baurecht des jeweiligen Landes. Wer diese Phase unterschätzt, riskiert Verzögerungen, die sich durch das ganze Projekt ziehen.',NULL,NULL,ARRAY['pba2verfahren']::text[],'[{"t":"HOAI","stand":"HOAI 2013 i. d. F. der 1. ÄndVO, in Kraft 01.01.2021; Honorartafeln nach EuGH nur Orientierung","u":"https://www.gesetze-im-internet.de/hoai_2013/","geprueft":"2026-08-19"},{"t":"OIB-Richtlinien","stand":"Ausgabe 2023, beschlossen 25.05.2023","u":"https://www.oib.or.at/kernaufgaben/oib-richtlinien1/richtlinien/oib-richtlinien-2023/","geprueft":"2026-08-19"},{"t":"SIA 112 Modell Bauplanung","stand":"Ausgabe 2014","u":"https://shop.sia.ch/normenwerk/ingenieur/112_2014_d/D/Product","geprueft":"2026-08-19"}]'::jsonb,'{"de":"Diese Leistung entspricht der Leistungsphase 4 der HOAI und mündet in den Bauantrag nach Landesbauordnung.","at":"In Österreich heißt die vergleichbare Leistung Einreichplanung, die Anforderungen ergeben sich aus den jeweiligen Landesbauordnungen und den OIB-Richtlinien.","ch":"In der Schweiz entspricht dies dem Baubewilligungsverfahren nach kantonalem Baugesetz, das Baugesuch wird auf Basis des Bauprojekts nach SIA 112 eingereicht."}'::jsonb,563),
('pab3ausfuehrung','p',3,'pab2phasen','Ausführungsplanung und Vergabevorbereitung','Nach der Genehmigung folgt die Übersetzung in baubare Details: Pläne, Beschreibungen und Mengen, die eine Baufirma kalkulieren und ausführen kann. Diese Phase bindet die meiste Planungszeit und ist zugleich die Schnittstelle zu Fachplanern und zur Vergabe. Wird hier ungenau gearbeitet, zeigt sich das später als Nachtrag auf der Baustelle.',NULL,NULL,'{}'::text[],'[{"t":"HOAI","stand":"HOAI 2013 i. d. F. der 1. ÄndVO, in Kraft 01.01.2021; Honorartafeln nach EuGH nur Orientierung","u":"https://www.gesetze-im-internet.de/hoai_2013/","geprueft":"2026-08-19"},{"t":"SIA 112 Modell Bauplanung","stand":"Ausgabe 2014","u":"https://shop.sia.ch/normenwerk/ingenieur/112_2014_d/D/Product","geprueft":"2026-08-19"},{"t":"SIA 102 Leistungen und Honorare der Architekten","stand":"Ausgabe 2020","u":"https://shop.sia.ch/normenwerk/architekt/102_2020_d/D/Product","geprueft":"2026-08-19"}]'::jsonb,'{"de":"Ausführungsplanung, Vorbereitung und Mitwirkung bei der Vergabe entsprechen den Leistungsphasen 5 bis 7 der HOAI.","at":"In Österreich folgen Ausführungsplanung und Vergabeverfahren als eigenständige, meist gesondert beauftragte Leistungen.","ch":"Nach SIA 112 zählt dies zur Ausschreibung und zur Ausführungsprojektierung, mit eigener Leistungsbeschreibung in der SIA 102."}'::jsonb,564),
('pab3bauueberw','p',3,'pab2phasen','Bauüberwachung und Objektbetreuung','Die letzte Phase begleitet die eigentliche Bauausführung: Kontrolle der Ausführungsqualität, Termine und Kosten bis zur Abnahme und darüber hinaus. Sie verlangt eine andere Arbeitsweise als das Planen am Zeichentisch, nämlich schnelle Entscheidungen unter Baustellenbedingungen. Wie weit diese Betreuung reicht, ist eine der häufigsten Streitfragen im Leistungsbild.',NULL,NULL,'{}'::text[],'[{"t":"HOAI","stand":"HOAI 2013 i. d. F. der 1. ÄndVO, in Kraft 01.01.2021; Honorartafeln nach EuGH nur Orientierung","u":"https://www.gesetze-im-internet.de/hoai_2013/","geprueft":"2026-08-19"},{"t":"SIA 112 Modell Bauplanung","stand":"Ausgabe 2014","u":"https://shop.sia.ch/normenwerk/ingenieur/112_2014_d/D/Product","geprueft":"2026-08-19"},{"t":"SIA 102 Leistungen und Honorare der Architekten","stand":"Ausgabe 2020","u":"https://shop.sia.ch/normenwerk/architekt/102_2020_d/D/Product","geprueft":"2026-08-19"}]'::jsonb,'{"de":"Diese Phase entspricht den Leistungsphasen 8 und 9 der HOAI, Objektüberwachung und Objektbetreuung.","at":"In Österreich wird die örtliche Bauaufsicht meist als eigene, oft separat vergebene Leistung neben der Planung geführt.","ch":"Nach SIA 112 zählt dies zur Bewirtschaftung und Realisierung, die Bauleitung wird als eigenständige Leistung nach SIA 102 beschrieben."}'::jsonb,565),
('pab2org','p',2,'pab1','Projektorganisation und Rollen','Ein Bauprojekt hat nie nur einen Kopf: Objektplaner, Fachplaner und oft ein separates Projektmanagement teilen sich Verantwortung, die sich in der Praxis überschneidet. Wer welche Entscheidung treffen darf und wer dafür haftet, muss vertraglich geklärt sein, bevor es zum Konflikt kommt. Klare Rollen sind kein Formalismus, sie verhindern, dass am Ende zwei sich zuständig fühlen oder keiner.',NULL,NULL,'{}'::text[],'[{"t":"HOAI","stand":"HOAI 2013 i. d. F. der 1. ÄndVO, in Kraft 01.01.2021; Honorartafeln nach EuGH nur Orientierung","u":"https://www.gesetze-im-internet.de/hoai_2013/","geprueft":"2026-08-19"}]'::jsonb,'{"de":"In Deutschland ordnet die HOAI über ihre Leistungsbilder die Aufgaben der Objektplanung, während Fachplaner eigene Leistungsbilder mit eigener Vergütung haben.","at":"In Österreich regeln Planungsverträge, oft in Anlehnung an Standards der Ziviltechnikerkammer, die Aufgabenteilung zwischen Objektplaner, Fachplanern und einer häufig eigenständigen örtlichen Bauaufsicht.","ch":"In der Schweiz strukturieren die SIA-Ordnungen für Architektur- und Ingenieurleistungen Rollen und Zusammenarbeit, mit der Bauleitung als traditionell eigenständiger Funktion."}'::jsonb,566),
('pab3objektpl','p',3,'pab2org','Objektplaner und Generalplaner','Der Objektplaner führt die Fäden eines Projekts zusammen, koordiniert Fachplaner und trägt die Gesamtverantwortung für Entwurf und Ausführung. Tritt er als Generalplaner auf, bündelt er zusätzlich mehrere Planungsleistungen unter einem Vertrag und einer Haftung. Für den Bauherrn bedeutet das einen Ansprechpartner, aber auch eine Instanz, die entsprechend honoriert werden will.',NULL,NULL,'{}'::text[],'[{"t":"HOAI","stand":"HOAI 2013 i. d. F. der 1. ÄndVO, in Kraft 01.01.2021; Honorartafeln nach EuGH nur Orientierung","u":"https://www.gesetze-im-internet.de/hoai_2013/","geprueft":"2026-08-19"}]'::jsonb,'{"de":"In Deutschland ist der Objektplaner meist der Architekt, dessen koordinierende Rolle die HOAI mit einem eigenen Leistungsbild unterlegt.","at":"In Österreich übernimmt diese Rolle regelmäßig der Ziviltechniker als Objektplaner, die Generalplanung wird vertraglich eigenständig geregelt.","ch":"In der Schweiz ist die Bezeichnung Gesamtleitung gebräuchlich, deren Aufgaben die SIA-Ordnungen beschreiben."}'::jsonb,567),
('pab3fachpl','p',3,'pab2org','Fachplaner und Sonderfachleute','Tragwerksplanung, Technische Ausrüstung, Bauphysik: Je komplexer ein Projekt, desto mehr Fachplaner arbeiten parallel zum Objektplaner und müssen von ihm koordiniert werden. Jede Fachdisziplin hat ein eigenes Leistungsbild und eigene Vertragspartner, die Schnittstellen dazwischen sind die häufigste Fehlerquelle. Gute Koordination entscheidet oft mehr über die Bauqualität als jede Einzelleistung.',NULL,NULL,'{}'::text[],'[{"t":"HOAI","stand":"HOAI 2013 i. d. F. der 1. ÄndVO, in Kraft 01.01.2021; Honorartafeln nach EuGH nur Orientierung","u":"https://www.gesetze-im-internet.de/hoai_2013/","geprueft":"2026-08-19"}]'::jsonb,'{"de":"Die HOAI beschreibt eigene Leistungsbilder für Tragwerksplanung, Technische Ausrüstung und weitere Fachplanungen mit jeweils eigenem Honorar.","at":"In Österreich sind Fachplaner meist als Sonderfachleute eigenständig beauftragt, mit eigener Haftung neben dem Objektplaner.","ch":"In der Schweiz sind die entsprechenden Fachingenieurleistungen in eigenen SIA-Ordnungen geregelt."}'::jsonb,568),
('pab3pm','p',3,'pab2org','Projektsteuerung und Projektmanagement','Projektsteuerung ist keine Planungsleistung, sondern die Organisation von Terminen, Kosten und Qualitäten aus Sicht des Bauherrn, oft von einer eigenen Stelle wahrgenommen. Sie steht zwischen Bauherr und Planern und kann Reibung ebenso abbauen wie erzeugen, je nachdem wie klar ihre Kompetenzen definiert sind. Bei kleineren Projekten übernimmt oft der Objektplaner diese Funktion informell mit.',NULL,NULL,'{}'::text[],'[{"t":"HOAI","stand":"HOAI 2013 i. d. F. der 1. ÄndVO, in Kraft 01.01.2021; Honorartafeln nach EuGH nur Orientierung","u":"https://www.gesetze-im-internet.de/hoai_2013/","geprueft":"2026-08-19"}]'::jsonb,'{"de":"Projektsteuerung ist in Deutschland als eigene, von der Planungsleistung nach HOAI unterschiedene Leistung etabliert und wird gesondert honoriert.","at":"In Österreich wird Projektmanagement zunehmend als eigene Dienstleistung neben der klassischen Planung nachgefragt, ohne einheitliches Leistungsbild.","ch":"In der Schweiz übernimmt häufig die Gesamtleitung projektsteuernde Aufgaben, eigenständiges Projektmanagement ist bei Großprojekten verbreitet."}'::jsonb,569),
('pab3bauherr','p',3,'pab2org','Bauherr und Bauherrenvertretung','Der Bauherr trägt das wirtschaftliche Risiko und die zentralen Entscheidungen, delegiert aber oft an eine Bauherrenvertretung, wenn ihm Erfahrung oder Zeit fehlt. Diese Vertretung kann Chancen und Risiken bündeln, verändert aber auch, wer am Ende wirklich entscheidet. Für Planer ist entscheidend, wer im Zweifel bindend erklären darf, was gilt.',NULL,NULL,'{}'::text[],'[]'::jsonb,'{"de":"Die Bauherrenvertretung ist in Deutschland keine gesetzlich definierte Rolle, sondern wird individuell vertraglich mit Vollmachten ausgestattet.","at":"In Österreich ist die Bauherrenvertretung ebenfalls vertraglich frei gestaltbar, bei öffentlichen Bauherren oft an feste Gremien gebunden.","ch":"In der Schweiz tritt bei institutionellen Bauherren häufig eine eigene Bauherrenberatung auf, deren Kompetenzen projektspezifisch festgelegt werden."}'::jsonb,570);
insert into public.nodes (id,perspective,level,parent_id,title,t1,t2,t3,links,sources,dach,ord) values
('pab2termin','p',2,'pab1','Termin- und Ablaufplanung','Ein Terminplan ist zugleich Organisationswerkzeug und, sobald Fristen vertraglich fixiert werden, ein scharfes Druckmittel zwischen den Parteien. Wie verbindlich Termine sind und was ihre Überschreitung auslöst, unterscheidet sich zwischen den DACH-Ländern deutlich. Wer Terminplanung nur als Excel-Übung versteht, unterschätzt ihre rechtliche Wirkung.',NULL,NULL,ARRAY['pko3steuerung']::text[],'[{"t":"HOAI","stand":"HOAI 2013 i. d. F. der 1. ÄndVO, in Kraft 01.01.2021; Honorartafeln nach EuGH nur Orientierung","u":"https://www.gesetze-im-internet.de/hoai_2013/","geprueft":"2026-08-19"},{"t":"VOB/B (DIN 1961)","stand":"Ausgabe 2016, Bekanntmachung 07.01.2016, ber. 01.04.2016","u":"https://www.verwaltungsvorschriften-im-internet.de/bsvwvbund_07012016_BI78106361.htm","geprueft":"2026-08-19"},{"t":"ÖNORM B 2110 Allgemeine Vertragsbestimmungen","stand":"2023-05-01","u":"https://shop.austrian-standards.at/action/de/public/details/728205/OENORM_B_2110_2023_05_01","geprueft":"2026-08-19"},{"t":"SIA 118 Allgemeine Bedingungen für Bauarbeiten","stand":"Ausgabe 2013","u":"https://shop.sia.ch/normenwerk/ingenieur/118_2013_d/D/Product","geprueft":"2026-08-19"}]'::jsonb,'{"de":"In Deutschland ist die Terminplanung HOAI-Grundleistung, verbindliche Bauzeiten regelt meist zusätzlich die VOB.","at":"In Österreich bildet die ÖNORM B 2110 die vertragliche Grundlage für Fristen und deren Folgen.","ch":"In der Schweiz regelt die SIA 118 Fristen und Verzug im Werkvertrag."}'::jsonb,571),
('pab3terminplan','p',3,'pab2termin','Terminplanarten und Steuerungsebenen','Ein Terminplan ist nie nur einer: Rahmenterminplan, Grobterminplan und Feinterminplan bilden unterschiedliche Steuerungsebenen mit unterschiedlicher Reichweite und Verantwortung. Wer alle Ebenen vermischt, verliert entweder den Überblick oder die Kontrolle über Details. Der Terminplan ist zugleich Vertragsinstrument, sobald Fristen darin verbindlich vereinbart werden.',NULL,NULL,'{}'::text[],'[{"t":"HOAI","stand":"HOAI 2013 i. d. F. der 1. ÄndVO, in Kraft 01.01.2021; Honorartafeln nach EuGH nur Orientierung","u":"https://www.gesetze-im-internet.de/hoai_2013/","geprueft":"2026-08-19"},{"t":"VOB/B (DIN 1961)","stand":"Ausgabe 2016, Bekanntmachung 07.01.2016, ber. 01.04.2016","u":"https://www.verwaltungsvorschriften-im-internet.de/bsvwvbund_07012016_BI78106361.htm","geprueft":"2026-08-19"},{"t":"ÖNORM B 2110 Allgemeine Vertragsbestimmungen","stand":"2023-05-01","u":"https://shop.austrian-standards.at/action/de/public/details/728205/OENORM_B_2110_2023_05_01","geprueft":"2026-08-19"},{"t":"SIA 118 Allgemeine Bedingungen für Bauarbeiten","stand":"Ausgabe 2013","u":"https://shop.sia.ch/normenwerk/ingenieur/118_2013_d/D/Product","geprueft":"2026-08-19"}]'::jsonb,'{"de":"In Deutschland gehört die Terminplanung zu den HOAI-Grundleistungen, verbindliche Bauzeiten werden meist zusätzlich vertraglich, oft über die VOB, geregelt.","at":"In Österreich regelt die ÖNORM B 2110 Fristen und deren Folgen im Bauvertrag, die Terminplanung selbst bleibt Organisationsaufgabe der Beteiligten.","ch":"In der Schweiz bildet die SIA 118 die Grundlage für Fristen und Terminverzug im Werkvertrag."}'::jsonb,572),
('pab3ablauf','p',3,'pab2termin','Ablauf- und Kapazitätsplanung im Bauablauf','Der Bauablauf ordnet Gewerke in eine sinnvolle Reihenfolge und prüft, ob Kapazitäten, Zufahrten und Lagerflächen tatsächlich zusammenpassen. Eine gute Ablaufplanung verhindert, dass sich Gewerke gegenseitig blockieren oder auf der Baustelle im Weg stehen. Sie ist Handwerk und Erfahrungswissen zugleich, kaum normierbar, aber entscheidend für den Bauerfolg.',NULL,NULL,'{}'::text[],'[{"t":"VOB/B (DIN 1961)","stand":"Ausgabe 2016, Bekanntmachung 07.01.2016, ber. 01.04.2016","u":"https://www.verwaltungsvorschriften-im-internet.de/bsvwvbund_07012016_BI78106361.htm","geprueft":"2026-08-19"},{"t":"ÖNORM B 2110 Allgemeine Vertragsbestimmungen","stand":"2023-05-01","u":"https://shop.austrian-standards.at/action/de/public/details/728205/OENORM_B_2110_2023_05_01","geprueft":"2026-08-19"},{"t":"SIA 118 Allgemeine Bedingungen für Bauarbeiten","stand":"Ausgabe 2013","u":"https://shop.sia.ch/normenwerk/ingenieur/118_2013_d/D/Product","geprueft":"2026-08-19"}]'::jsonb,'{"de":"Rechtlich verbindlich wird der Bauablauf in Deutschland meist über die VOB, die auch Regeln zu Behinderung und Verzug enthält.","at":"In Österreich regelt die ÖNORM B 2110 Bauablaufstörungen und deren vertragliche Folgen.","ch":"In der Schweiz bildet die SIA 118 die Grundlage für Ablaufstörungen und deren Geltendmachung."}'::jsonb,573),
('pab3verzug','p',3,'pab2termin','Verzug, Bauzeitverlängerung und Pönale','Gerät der Bau in Verzug, wird der Terminplan zum Streitgegenstand: Wer war verantwortlich, wie lange dauert die berechtigte Verlängerung, greift eine vereinbarte Vertragsstrafe. Sauber geführte Bautagebücher und dokumentierte Behinderungsanzeigen entscheiden hier oft mehr als das gute Recht. Wer erst beim Streit zu dokumentieren beginnt, hat schon verloren.',NULL,NULL,'{}'::text[],'[{"t":"BGB, Bauvertragsrecht (§§ 650a ff.)","stand":"zuletzt geändert 23.07.2026","u":"https://www.gesetze-im-internet.de/bgb/","geprueft":"2026-08-19"},{"t":"VOB/B (DIN 1961)","stand":"Ausgabe 2016, Bekanntmachung 07.01.2016, ber. 01.04.2016","u":"https://www.verwaltungsvorschriften-im-internet.de/bsvwvbund_07012016_BI78106361.htm","geprueft":"2026-08-19"},{"t":"ÖNORM B 2110 Allgemeine Vertragsbestimmungen","stand":"2023-05-01","u":"https://shop.austrian-standards.at/action/de/public/details/728205/OENORM_B_2110_2023_05_01","geprueft":"2026-08-19"},{"t":"SIA 118 Allgemeine Bedingungen für Bauarbeiten","stand":"Ausgabe 2013","u":"https://shop.sia.ch/normenwerk/ingenieur/118_2013_d/D/Product","geprueft":"2026-08-19"},{"t":"Obligationenrecht (SR 220), Werkvertragsrecht","stand":"SR 220; Teilrevision Baumängel 2025","u":"https://www.fedlex.admin.ch/eli/cc/27/317_321_377/de","geprueft":"2026-08-19"}]'::jsonb,'{"de":"In Deutschland regeln BGB und VOB Verzug, Behinderung und Vertragsstrafe, mit unterschiedlichen Fristen- und Anzeigepflichten.","at":"In Österreich regelt die ÖNORM B 2110 Verzug, Pönale und die Voraussetzungen für Fristverlängerungen im Detail.","ch":"In der Schweiz regelt die SIA 118 Verzug und Konventionalstrafe, ergänzt durch das Obligationenrecht."}'::jsonb,574),
('pab2digital','p',2,'pab1','Digitale Methoden','BIM verändert nicht nur das Zeichenwerkzeug, sondern die Zusammenarbeit selbst: Wer welche Information wann liefert, muss vorab festgelegt werden, sonst entstehen unabgestimmte Einzelmodelle statt eines gemeinsamen digitalen Bildes. Die Methodik ist in den DACH-Ländern unterschiedlich weit verbindlich verankert. Digitale Methoden ersetzen kein Leistungsbild, sie brauchen ein eigenes.',NULL,NULL,'{}'::text[],'[]'::jsonb,'{"de":"In Deutschland stützt sich die BIM-Abwicklung öffentlicher Auftraggeber auf Stufenpläne und die VDI-Richtlinienreihe zu BIM, eine flächendeckende gesetzliche Pflicht besteht nicht.","at":"In Österreich entwickelt sich die BIM-Methodik entlang der ÖNORM A 6241-Reihe, die Anwendung ist überwiegend vertraglich statt gesetzlich verankert.","ch":"In der Schweiz bildet die SIA 2051 den anerkannten Rahmen für BIM-Anwendung, Abwicklungspläne und Informationsanforderungen."}'::jsonb,575),
('pab3bim','p',3,'pab2digital','BIM-Abwicklungsplan (BAP)','Der BIM-Abwicklungsplan legt fest, wie ein Projekt digital modelliert, ausgetauscht und geprüft wird, von Modellierrichtlinien bis zu Verantwortlichkeiten je Gewerk. Er übersetzt die Anforderungen des Auftraggebers in ein gemeinsames, prüfbares Vorgehen für alle Beteiligten. Ohne ihn wird BIM schnell zum Sammelsurium unterschiedlich modellierter Einzeldateien.',NULL,NULL,'{}'::text[],'[]'::jsonb,'{"de":"In Deutschland orientiert sich der BAP an den Stufenplänen öffentlicher Auftraggeber und an der VDI-Richtlinienreihe zu BIM.","at":"In Österreich stützt sich die BIM-Abwicklung zunehmend auf die ÖNORM A 6241-Reihe zu BIM-Leistungsbildern.","ch":"In der Schweiz bildet die SIA 2051 den Rahmen für BIM-Anwendung und Abwicklungspläne."}'::jsonb,576),
('pab3aia','p',3,'pab2digital','Auftraggeber-Informationsanforderungen (AIA)','Die AIA formulieren, was der Auftraggeber von einem digitalen Modell erwartet: Zwecke, Detailtiefe, Formate, Zeitpunkte der Übergabe. Sie stehen am Anfang jedes BIM-Projekts und sind die Grundlage, gegen die der Abwicklungsplan später geprüft wird. Unklare AIA sind der häufigste Grund, warum BIM-Projekte im Ergebnis enttäuschen.',NULL,NULL,'{}'::text[],'[]'::jsonb,'{"de":"In Deutschland sind AIA fester Bestandteil öffentlicher BIM-Ausschreibungen und lehnen sich an die VDI-Richtlinienreihe zu BIM an.","at":"In Österreich entwickeln sich Auftraggeber-Informationsanforderungen entlang der ÖNORM A 6241-Reihe.","ch":"In der Schweiz stützen sich Informationsanforderungen auf die SIA 2051 und die zugehörigen Merkblätter."}'::jsonb,577),
('pab3bimrolle','p',3,'pab2digital','BIM-Koordination: Rollen im Projekt','BIM braucht eigene Rollen, die es vorher so nicht gab: BIM-Koordinatoren prüfen und takten die Fachmodelle je Disziplin, ein BIM-Gesamtkoordinator führt sie zusammen. Diese Rollen sind Organisationsarbeit, keine Software-Bedienung, und gehören früh vertraglich verankert. Fehlt die Gesamtkoordination, kollidieren Fachmodelle spätestens auf der Baustelle.',NULL,NULL,'{}'::text[],'[{"t":"HOAI","stand":"HOAI 2013 i. d. F. der 1. ÄndVO, in Kraft 01.01.2021; Honorartafeln nach EuGH nur Orientierung","u":"https://www.gesetze-im-internet.de/hoai_2013/","geprueft":"2026-08-19"}]'::jsonb,'{"de":"In Deutschland werden BIM-Koordinationsleistungen zunehmend als besondere Leistungen neben dem klassischen HOAI-Leistungsbild vereinbart.","at":"In Österreich ist die BIM-Koordination noch selten eigenständig normiert und wird vertraglich individuell geregelt.","ch":"In der Schweiz beschreibt die SIA 2051 auch die Rollen der BIM-Koordination im Projektteam."}'::jsonb,578),
('pho1','p',1,NULL,'Honorar und Vertrag','Wer plant, muss auch wissen, wie er bezahlt wird und wofür er haftet: Honorar und Vertrag bilden das wirtschaftliche und rechtliche Fundament jeder Planungsleistung. Die drei DACH-Länder gehen damit sehr unterschiedlich um, von der einst staatlich verbindlichen Honorarordnung bis zur freien Vereinbarung. Ein unklarer Vertrag kostet am Ende oft mehr als das strittige Honorar selbst.',NULL,NULL,'{}'::text[],'[]'::jsonb,NULL,579),
('pho2honorar','p',2,'pho1','Honorarermittlung','Wie ein Honorar berechnet wird, folgt keiner einheitlichen DACH-Logik: feste Tafelwerke, freie Verhandlung oder Empfehlungswerte stehen nebeneinander. Für Planer entscheidet diese Grundlage darüber, wie viel Verhandlungsspielraum überhaupt besteht. Wer die Systematik seines Landes nicht kennt, verschenkt Honorar oder verspricht zu wenig.',NULL,NULL,ARRAY['pko2gliederung']::text[],'[{"t":"HOAI","stand":"HOAI 2013 i. d. F. der 1. ÄndVO, in Kraft 01.01.2021; Honorartafeln nach EuGH nur Orientierung","u":"https://www.gesetze-im-internet.de/hoai_2013/","geprueft":"2026-08-19"}]'::jsonb,'{"de":"Die HOAI dient nach der Entscheidung des Europäischen Gerichtshofs nur noch als Orientierung, verbindliche Mindest- und Höchstsätze gibt es nicht mehr, das Honorar wird frei vereinbart.","at":"In Österreich ist das Honorar grundsätzlich frei vereinbar, verbindliche Honorarleitlinien der Kammer bestehen kartellrechtlich nicht mehr.","ch":"In der Schweiz dienen die SIA-Ordnungen als kartellrechtlich unverbindliche Empfehlung für die Honorarberechnung."}'::jsonb,580),
('pho3honorarzone','p',3,'pho2honorar','Honorarzonen und Bewertungskriterien','Nicht jedes Gebäude ist gleich anspruchsvoll zu planen: Honorarzonen bewerten die Schwierigkeit eines Projekts anhand von Kriterien wie Komplexität und Integrationsgrad. Je höher die Zone, desto höher der übliche Honorarsatz je Kostengruppe. Die Einstufung ist oft der erste Streitpunkt in der Honorarverhandlung.',NULL,NULL,'{}'::text[],'[{"t":"HOAI","stand":"HOAI 2013 i. d. F. der 1. ÄndVO, in Kraft 01.01.2021; Honorartafeln nach EuGH nur Orientierung","u":"https://www.gesetze-im-internet.de/hoai_2013/","geprueft":"2026-08-19"}]'::jsonb,'{"de":"In Deutschland ordnet die HOAI Objekte anhand von Bewertungsmerkmalen in Honorarzonen, an die sich Honorartafeln als Orientierung anlehnen.","at":"In Österreich gibt es keine verbindliche Zoneneinteilung mehr, vergleichbare Komplexitätsmerkmale fließen in die freie Honorarverhandlung ein.","ch":"In der Schweiz differenzieren die SIA-Ordnungen die Vergütung über Schwierigkeitsgrad und Zeitaufwand statt über feste Zonen."}'::jsonb,581),
('pho3honorarmodelle','p',3,'pho2honorar','Vergütungsmodelle: Pauschal, Zeit, Prozent','Pauschalhonorar, Zeithonorar oder Honorar als Prozentsatz der Baukosten: Jedes Modell verteilt das wirtschaftliche Risiko anders zwischen Planer und Bauherr. Pauschalen belohnen Effizienz, bestrafen aber unterschätzten Aufwand, Zeithonorare sind fair, aber schwer zu budgetieren. Die Wahl des Modells gehört früh und bewusst in den Vertrag, nicht als Formsache am Ende.',NULL,NULL,'{}'::text[],'[{"t":"HOAI","stand":"HOAI 2013 i. d. F. der 1. ÄndVO, in Kraft 01.01.2021; Honorartafeln nach EuGH nur Orientierung","u":"https://www.gesetze-im-internet.de/hoai_2013/","geprueft":"2026-08-19"}]'::jsonb,'{"de":"Deutsche Verträge orientieren sich häufig an der HOAI-Struktur, kombinieren aber zunehmend Pauschal- und Zeithonorare frei.","at":"In Österreich sind Pauschal- und Zeithonorare gleichermaßen üblich, die Wahl folgt reiner Vertragsfreiheit.","ch":"In der Schweiz sind Zeithonorar und Pauschale nach SIA-Ordnung gleichrangige, häufig kombinierte Modelle."}'::jsonb,582),
('pho3nebenkosten','p',3,'pho2honorar','Nebenkosten und Erstattungen','Neben dem eigentlichen Honorar entstehen Nebenkosten für Reisen, Vervielfältigungen oder besondere Leistungen, die separat vereinbart und abgerechnet werden müssen. Wer sie im Vertrag vergisst, trägt sie am Ende selbst. Kleine Position, große Wirkung über die Projektlaufzeit.',NULL,NULL,'{}'::text[],'[{"t":"HOAI","stand":"HOAI 2013 i. d. F. der 1. ÄndVO, in Kraft 01.01.2021; Honorartafeln nach EuGH nur Orientierung","u":"https://www.gesetze-im-internet.de/hoai_2013/","geprueft":"2026-08-19"}]'::jsonb,'{"de":"In Deutschland regelt die HOAI Nebenkosten als eigenen Abrechnungsposten, der pauschal oder nach Nachweis vereinbart werden kann.","at":"In Österreich werden Nebenkosten frei vertraglich geregelt, üblich sind Pauschalsätze auf das Honorar.","ch":"In der Schweiz sehen die SIA-Ordnungen Nebenkosten als gesonderten Vergütungsbestandteil vor."}'::jsonb,583),
('pho3honorarstreit','p',3,'pho2honorar','Honorarstreitigkeiten und Nachweispflicht','Kommt es zum Streit ums Honorar, entscheidet meist, wer die erbrachte Leistung besser dokumentiert hat, nicht wer im Recht zu sein glaubt. Stundennachweise, Leistungsverzeichnisse und Abnahmeprotokolle sind die Munition in solchen Auseinandersetzungen. Vorsorge ist hier billiger als jeder Prozess.',NULL,NULL,'{}'::text[],'[]'::jsonb,'{"de":"In Deutschland ist die Honorarschlussrechnung prüffähig aufzustellen, formale Mängel führen häufig zu Auseinandersetzungen vor Gericht.","at":"In Österreich sind Honorarstreitigkeiten mangels fixer Honorarordnung besonders auf eine klare vertragliche Leistungsbeschreibung angewiesen.","ch":"In der Schweiz bildet die SIA-Ordnung eine anerkannte Auslegungsgrundlage, wenn der Vertrag selbst schweigt."}'::jsonb,584),
('pho2vertrag','p',2,'pho1','Architektenvertrag, Haftung und Urheberrecht','Der Architektenvertrag ist die rechtliche Grundlage der Zusammenarbeit und bestimmt, welche Leistung geschuldet wird, wer für Fehler haftet und wem das geistige Eigentum am Entwurf gehört. Diese drei Themen greifen ineinander: Ein unklarer Leistungsumfang erschwert später auch die Haftungsfrage. Ein guter Vertrag ist die günstigste Versicherung im ganzen Projekt.',NULL,NULL,'{}'::text[],'[{"t":"BGB, Bauvertragsrecht (§§ 650a ff.)","stand":"zuletzt geändert 23.07.2026","u":"https://www.gesetze-im-internet.de/bgb/","geprueft":"2026-08-19"},{"t":"Obligationenrecht (SR 220), Werkvertragsrecht","stand":"SR 220; Teilrevision Baumängel 2025","u":"https://www.fedlex.admin.ch/eli/cc/27/317_321_377/de","geprueft":"2026-08-19"}]'::jsonb,'{"de":"In Deutschland ist der Architektenvertrag rechtlich ein Werkvertrag nach BGB, das Urheberrecht schützt schöpferische Bauwerke eigenständig.","at":"In Österreich gilt der Planungsvertrag überwiegend als Werkvertrag nach ABGB, ergänzt durch das österreichische Urheberrechtsgesetz.","ch":"In der Schweiz ist der Planervertrag werkvertragsähnlich nach Obligationenrecht ausgestaltet, das Urheberrecht schützt die Bauwerke als Werke der Baukunst."}'::jsonb,585);
insert into public.nodes (id,perspective,level,parent_id,title,t1,t2,t3,links,sources,dach,ord) values
('pho3vertragstyp','p',3,'pho2vertrag','Vertragstypen und Vertragsschluss','Nicht jeder Planungsvertrag ist gleich: Werkvertrag, Dienstvertrag oder gemischte Formen unterscheiden sich in Erfolgshaftung und Kündigungsfolgen erheblich. Schon die Einordnung entscheidet, welche gesetzlichen Regeln überhaupt greifen, wenn der Vertrag selbst schweigt. Mündliche Absprachen sind gültig, aber im Streitfall kaum beweisbar.',NULL,NULL,'{}'::text[],'[{"t":"BGB, Bauvertragsrecht (§§ 650a ff.)","stand":"zuletzt geändert 23.07.2026","u":"https://www.gesetze-im-internet.de/bgb/","geprueft":"2026-08-19"},{"t":"Obligationenrecht (SR 220), Werkvertragsrecht","stand":"SR 220; Teilrevision Baumängel 2025","u":"https://www.fedlex.admin.ch/eli/cc/27/317_321_377/de","geprueft":"2026-08-19"}]'::jsonb,'{"de":"Der Architektenvertrag gilt in Deutschland als Werkvertrag nach BGB mit Erfolgshaftung für die geschuldete Planung.","at":"In Österreich wird der Planungsvertrag überwiegend als Werkvertrag nach ABGB eingeordnet, mit vergleichbarer Erfolgshaftung.","ch":"In der Schweiz ist der Planervertrag nach Obligationenrecht meist ein Auftrag mit werkvertraglichen Elementen, die Einordnung im Einzelfall ist rechtlich umstritten."}'::jsonb,586),
('pho3leistungsbild','p',3,'pho2vertrag','Leistungsbild und Leistungsumfang im Vertrag','Das Leistungsbild listet, welche Teilleistungen der Vertrag tatsächlich umfasst, von der Grundlagenermittlung bis zur Objektbetreuung. Wird nur pauschal auf ein Regelwerk verwiesen, bleibt oft unklar, was im Einzelfall wirklich geschuldet ist. Präzise Leistungsbeschreibung ist der wirksamste Schutz vor späterem Streit über Nachträge.',NULL,NULL,'{}'::text[],'[{"t":"HOAI","stand":"HOAI 2013 i. d. F. der 1. ÄndVO, in Kraft 01.01.2021; Honorartafeln nach EuGH nur Orientierung","u":"https://www.gesetze-im-internet.de/hoai_2013/","geprueft":"2026-08-19"},{"t":"SIA 102 Leistungen und Honorare der Architekten","stand":"Ausgabe 2020","u":"https://shop.sia.ch/normenwerk/architekt/102_2020_d/D/Product","geprueft":"2026-08-19"}]'::jsonb,'{"de":"In Deutschland orientieren sich Verträge meist an den Leistungsbildern der HOAI, die als Auslegungshilfe auch ohne verbindliche Honorierung dienen.","at":"In Österreich fehlt ein vergleichbares gesetzliches Leistungsbild, weshalb Musterverträge der Kammer als Orientierung dienen.","ch":"In der Schweiz beschreibt die SIA 102 detailliert die Grundleistungen der Architekten, an denen sich Verträge orientieren."}'::jsonb,587),
('pho3haftung','p',3,'pho2vertrag','Planerhaftung und Mängelhaftung','Planer haften für Fehler in Entwurf, Ausführungsplanung oder Bauüberwachung, auch wenn der Baumangel erst Jahre später sichtbar wird. Die Haftung trifft nicht nur den Architekten, sondern verteilt sich zwischen allen Planungsbeteiligten je nach Verursachungsanteil. Wer diese Verteilung nicht versteht, unterschätzt sein eigenes Risiko systematisch.',NULL,NULL,'{}'::text[],'[{"t":"BGB, Bauvertragsrecht (§§ 650a ff.)","stand":"zuletzt geändert 23.07.2026","u":"https://www.gesetze-im-internet.de/bgb/","geprueft":"2026-08-19"},{"t":"Obligationenrecht (SR 220), Werkvertragsrecht","stand":"SR 220; Teilrevision Baumängel 2025","u":"https://www.fedlex.admin.ch/eli/cc/27/317_321_377/de","geprueft":"2026-08-19"}]'::jsonb,'{"de":"Die Planerhaftung folgt in Deutschland dem Werkvertragsrecht des BGB mit eigenständigen Verjährungsfristen für Bauwerke.","at":"In Österreich regelt das ABGB die Gewährleistung, mit eigenen, kürzeren Fristen als im deutschen Recht.","ch":"In der Schweiz regelt das Obligationenrecht die Werkmängelhaftung des Planers mit eigener Fristensystematik."}'::jsonb,588),
('pho3urheber','p',3,'pho2vertrag','Urheberrecht am Bauwerk und Änderungsbefugnis','Ein Gebäude kann urheberrechtlichen Schutz genießen, wenn es eine ausreichende gestalterische Eigenleistung zeigt, das schützt den Entwurf auch nach der Fertigstellung. Daraus folgt ein heikles Spannungsfeld: Der Eigentümer will sein Haus verändern dürfen, der Architekt sein Werk bewahren. Gerichte wägen hier regelmäßig zwischen Eigentumsrecht und Urheberpersönlichkeitsrecht ab.',NULL,NULL,'{}'::text[],'[]'::jsonb,'{"de":"In Deutschland schützt das Urheberrechtsgesetz Bauwerke mit ausreichender Schöpfungshöhe, Änderungen bedürfen bei Eingriffen in die Werksubstanz der Zustimmung.","at":"In Österreich schützt das Urheberrechtsgesetz vergleichbar gestaltete Bauwerke, mit ähnlicher Abwägung zwischen Eigentümer- und Urheberinteressen.","ch":"In der Schweiz schützt das Urheberrechtsgesetz Bauwerke als Werke der Baukunst, die Änderungsbefugnis des Eigentümers wird ebenfalls im Einzelfall abgewogen."}'::jsonb,589),
('pho2haftpfl','p',2,'pho1','Berufshaftpflicht und Deckung','Weil Planungsfehler oft erst Jahre nach Fertigstellung sichtbar werden, braucht jeder Planer eine Berufshaftpflichtversicherung, die genau diesen Zeitraum abdeckt. Deckungssumme, Selbstbehalt und der räumliche Geltungsbereich der Police entscheiden im Schadenfall über die eigene Existenz. Eine zu knapp bemessene Versicherung ist eine der teuersten Sparmaßnahmen im Planerberuf.',NULL,NULL,'{}'::text[],'[]'::jsonb,'{"de":"In Deutschland ist die Berufshaftpflichtversicherung für Architekten und Ingenieure über die Kammergesetze der Länder verpflichtend vorgeschrieben.","at":"In Österreich schreibt die Ziviltechnikerkammer eine Berufshaftpflichtversicherung mit Mindestdeckungssummen für ihre Mitglieder vor.","ch":"In der Schweiz besteht keine gesetzliche Versicherungspflicht für Architekten, eine Berufshaftpflicht wird aber von Auftraggebern und Verbänden dringend erwartet."}'::jsonb,590),
('pho3deckung','p',3,'pho2haftpfl','Deckungssummen und Versicherungsumfang','Nicht jede Police deckt jedes Risiko: Vermögensschäden, Personenschäden und Sachschäden können unterschiedlich versichert sein, ebenso Auslandstätigkeiten oder besondere Bauaufgaben. Die Deckungssumme sollte sich am tatsächlichen Projektrisiko orientieren, nicht am Mindestmaß der Kammer. Wer ein Großprojekt mit einer Standardpolice betreut, plant seine eigene Unterdeckung mit.',NULL,NULL,'{}'::text[],'[]'::jsonb,'{"de":"Deutsche Kammern schreiben Mindestdeckungssummen vor, viele Büros versichern für größere Projekte deutlich darüber hinaus.","at":"Die österreichische Ziviltechnikerkammer legt ebenfalls Mindestdeckungssummen fest, projektbezogene Zusatzdeckungen sind üblich.","ch":"In der Schweiz wird die Deckungssumme frei zwischen Versicherer und Büro vereinbart, oft orientiert an Auftraggeberanforderungen."}'::jsonb,591),
('pho3schadenfall','p',3,'pho2haftpfl','Schadenfall und Anzeigepflichten','Im Schadenfall zählt zuerst die rechtzeitige Meldung an den Versicherer, verspätete Anzeigen können den Versicherungsschutz gefährden. Parallel beginnt meist eine eigene Beweissicherung, denn spätere Rekonstruktion ist selten überzeugend. Wer den Schaden erst regelt und dann meldet, hat oft schon gegen die Police verstoßen.',NULL,NULL,'{}'::text[],'[]'::jsonb,'{"de":"Deutsche Versicherungsverträge verlangen unverzügliche Schadenmeldung, Verstöße können nach Versicherungsvertragsgesetz zur Leistungskürzung führen.","at":"In Österreich gelten vergleichbare Anzeigepflichten aus dem Versicherungsvertragsgesetz, mit ähnlichen Folgen bei Verspätung.","ch":"In der Schweiz regelt das Versicherungsvertragsgesetz Anzeigepflichten im Schadenfall, die Police konkretisiert die Fristen meist zusätzlich."}'::jsonb,592),
('pho3nachhaft','p',3,'pho2haftpfl','Nachhaftung nach Vertragsende','Die Verantwortung des Planers endet nicht mit der Schlussrechnung: Für Mängel, die erst Jahre später auftreten, haftet er weiterhin bis zum Ablauf der jeweiligen Verjährungsfrist. Deshalb muss die Berufshaftpflicht auch nach Bürowechsel, Pensionierung oder Geschäftsaufgabe weiterlaufen, sogenannte Nachhaftungsdeckung. Wer das vergisst, steht im Schadenfall plötzlich ohne Versicherung da.',NULL,NULL,'{}'::text[],'[{"t":"BGB, Bauvertragsrecht (§§ 650a ff.)","stand":"zuletzt geändert 23.07.2026","u":"https://www.gesetze-im-internet.de/bgb/","geprueft":"2026-08-19"},{"t":"Obligationenrecht (SR 220), Werkvertragsrecht","stand":"SR 220; Teilrevision Baumängel 2025","u":"https://www.fedlex.admin.ch/eli/cc/27/317_321_377/de","geprueft":"2026-08-19"}]'::jsonb,'{"de":"Die Verjährungsfristen für Bauwerksmängel nach BGB verlangen in Deutschland eine entsprechend lange Nachhaftungsdeckung der Berufshaftpflicht.","at":"In Österreich gelten nach ABGB andere, meist kürzere Verjährungsfristen, an denen sich die Nachhaftungsdeckung orientiert.","ch":"In der Schweiz richten sich Nachhaftungsfristen nach den Verjährungsregeln des Obligationenrechts für Werkmängel."}'::jsonb,593),
('pho2wettb','p',2,'pho1','Wettbewerb und Vergabe für Planungsleistungen','Ein Wettbewerb ist für Bauherren die Chance auf mehrere Entwürfe zur Auswahl, für Planer eine Investition ohne Erfolgsgarantie. Faire Verfahren regeln Auslobung, Beurteilung und die Aussicht auf einen Folgeauftrag, damit die Vorleistung nicht ins Leere läuft. Wie ernsthaft ein Verfahren gemeint ist, zeigt sich oft schon an der Qualität der Auslobungsunterlagen.',NULL,NULL,'{}'::text[],'[{"t":"RPW 2013 (Richtlinie für Planungswettbewerbe)","stand":"Bekanntmachung 31.01.2013","u":"https://www.verwaltungsvorschriften-im-internet.de/bsvwvbund_31012013_B10811172.htm","geprueft":"2026-08-19"}]'::jsonb,'{"de":"In Deutschland regelt die Richtlinie für Planungswettbewerbe (RPW) Ablauf, Preisgericht und die Zusage eines Auftrags an Preisträger.","at":"In Österreich orientieren sich Wettbewerbe an den WOA-Standards der Bundeskammer der Ziviltechniker.","ch":"In der Schweiz regeln die SIA 142 für offene Wettbewerbe und die SIA 143 für Studienaufträge das Verfahren."}'::jsonb,594),
('pho3wettbverfahren','p',3,'pho2wettb','Wettbewerbsverfahren und Auslobung','Die Auslobung ist die Verfassung eines Wettbewerbs: Sie legt Aufgabe, Beurteilungskriterien, Teilnahmebedingungen und Preisgeld verbindlich fest. Eine schlampige Auslobung produziert unvergleichbare Entwürfe und einen enttäuschenden Wettbewerb. Für teilnehmende Büros ist sie die einzige verlässliche Grundlage, um Aufwand und Chance abzuschätzen.',NULL,NULL,'{}'::text[],'[{"t":"RPW 2013 (Richtlinie für Planungswettbewerbe)","stand":"Bekanntmachung 31.01.2013","u":"https://www.verwaltungsvorschriften-im-internet.de/bsvwvbund_31012013_B10811172.htm","geprueft":"2026-08-19"}]'::jsonb,'{"de":"In Deutschland gibt die RPW den formalen Rahmen für Auslobung und Verfahren offener und nichtoffener Wettbewerbe vor.","at":"In Österreich strukturieren die WOA-Standards Auslobung und Ablauf von Architekturwettbewerben.","ch":"In der Schweiz regelt die SIA 142 Ablauf und Inhalte der Auslobung bei offenen Wettbewerbsverfahren."}'::jsonb,595),
('pho3preisgericht','p',3,'pho2wettb','Preisgericht und Beurteilung','Das Preisgericht entscheidet über den Wettbewerb, besetzt mit Fach- und Sachpreisrichtern, die Entwürfe anonym beurteilen sollen. Die Zusammensetzung und die Anonymität des Verfahrens sind der eigentliche Qualitätsgarant, nicht die Anzahl der Teilnehmer. Ein einseitig besetztes Preisgericht untergräbt das Vertrauen in das ganze Verfahren.',NULL,NULL,'{}'::text[],'[{"t":"RPW 2013 (Richtlinie für Planungswettbewerbe)","stand":"Bekanntmachung 31.01.2013","u":"https://www.verwaltungsvorschriften-im-internet.de/bsvwvbund_31012013_B10811172.htm","geprueft":"2026-08-19"}]'::jsonb,'{"de":"Die RPW schreibt in Deutschland eine Mehrheit an Fachpreisrichtern und ein anonymes Verfahren bis zur Entscheidung vor.","at":"Die WOA-Standards regeln in Österreich vergleichbar die Zusammensetzung und Anonymität des Preisgerichts.","ch":"In der Schweiz gibt die SIA 142 Regeln für die paritätische Besetzung und die Unabhängigkeit des Preisgerichts vor."}'::jsonb,596),
('pho3realisierung','p',3,'pho2wettb','Realisierungsfolge nach Wettbewerbsgewinn','Ein gewonnener Wettbewerb ist kein automatischer Bauauftrag: Die Zusage weiterer Beauftragung hängt vom Verfahren und von der Bereitschaft des Auslobers ab, den Siegerentwurf auch tatsächlich zu bauen. Zwischen Wettbewerbsentwurf und Ausführung liegt oft eine zweite, härtere Verhandlung. Wer diese Lücke unterschätzt, verliert nach dem gewonnenen Wettbewerb noch das Projekt.',NULL,NULL,'{}'::text[],'[{"t":"RPW 2013 (Richtlinie für Planungswettbewerbe)","stand":"Bekanntmachung 31.01.2013","u":"https://www.verwaltungsvorschriften-im-internet.de/bsvwvbund_31012013_B10811172.htm","geprueft":"2026-08-19"}]'::jsonb,'{"de":"Die RPW empfiehlt in Deutschland die Beauftragung des ersten Preisträgers, verpflichtend ist sie ohne entsprechende vertragliche Zusage nicht.","at":"In Österreich sehen die WOA-Standards eine Empfehlung zur Weiterbeauftragung vor, deren Verbindlichkeit vom Auslober abhängt.","ch":"In der Schweiz regeln SIA 142 und SIA 143 die Aussicht auf Weiterbearbeitung unterschiedlich klar, je nach Verfahrensart."}'::jsonb,597),
('pba1','p',1,NULL,'Baurecht und Genehmigung','Baurecht entscheidet, ob und wie überhaupt gebaut werden darf, bevor irgendeine Entwurfsfrage relevant wird. Es gliedert sich grob in die Frage, was auf einem Grundstück zulässig ist, und die Frage, wie ein konkretes Gebäude beschaffen sein muss. Beide Ebenen sind in Deutschland, Österreich und der Schweiz unterschiedlich organisiert, oft sogar innerhalb eines Landes von Region zu Region.',NULL,NULL,'{}'::text[],'[]'::jsonb,NULL,598),
('pba2planungsr','p',2,'pba1','Bauplanungsrecht','Das Bauplanungsrecht regelt, was auf einem Grundstück grundsätzlich zulässig ist: Nutzungsart, Maß der Bebauung, Erschließung. Es entscheidet vor jeder Entwurfsidee, ob ein Vorhaben überhaupt denkbar ist. Wer diese Ebene übersieht und gleich mit dem Gebäude beginnt, plant möglicherweise am Grundstück vorbei.',NULL,NULL,'{}'::text[],'[{"t":"BauGB (Baugesetzbuch)","stand":"Bekanntmachung 03.11.2017, zuletzt geändert 23.07.2026","u":"https://www.gesetze-im-internet.de/bbaug/","geprueft":"2026-08-19"},{"t":"RPG (Raumplanungsgesetz)","stand":"SR 700, vom 22.06.1979, konsolidiert","u":"https://www.fedlex.admin.ch/eli/cc/1979/1573_1573_1573/de","geprueft":"2026-08-19"}]'::jsonb,'{"de":"In Deutschland regeln das Baugesetzbuch und die Baunutzungsverordnung Bauleitplanung und zulässige Nutzung auf Bundesebene.","at":"In Österreich ist die Raumordnung Landessache, jedes Bundesland hat ein eigenes Raumordnungsgesetz mit eigener Systematik.","ch":"In der Schweiz bildet das Raumplanungsgesetz den Bundesrahmen, konkretisiert durch kantonale Raumplanungs- und Baugesetze."}'::jsonb,599),
('pba3flaechenwid','p',3,'pba2planungsr','Flächenwidmung und Nutzungsplanung','Bevor gebaut wird, legt die Flächenwidmung fest, wofür ein Grundstück überhaupt genutzt werden darf: Wohnen, Gewerbe, Landwirtschaft oder Sonderzweck. Diese Widmung ist die Wurzel jeder weiteren Planungsentscheidung, sie zu ändern ist ein eigenes, oft langwieriges Verfahren. Ein Bauvorhaben, das der Widmung widerspricht, scheitert unabhängig von seiner architektonischen Qualität.',NULL,NULL,'{}'::text[],'[{"t":"BauGB (Baugesetzbuch)","stand":"Bekanntmachung 03.11.2017, zuletzt geändert 23.07.2026","u":"https://www.gesetze-im-internet.de/bbaug/","geprueft":"2026-08-19"},{"t":"RPG (Raumplanungsgesetz)","stand":"SR 700, vom 22.06.1979, konsolidiert","u":"https://www.fedlex.admin.ch/eli/cc/1979/1573_1573_1573/de","geprueft":"2026-08-19"}]'::jsonb,'{"de":"In Deutschland ergibt sich die zulässige Nutzung aus dem Flächennutzungsplan und dem Bebauungsplan nach Baugesetzbuch und Baunutzungsverordnung.","at":"In Österreich weist der Flächenwidmungsplan nach dem jeweiligen Landesraumordnungsgesetz die zulässigen Nutzungen aus.","ch":"In der Schweiz erfolgt die Nutzungszuweisung über die kommunale Nutzungsplanung im Rahmen des Raumplanungsgesetzes."}'::jsonb,600);
insert into public.nodes (id,perspective,level,parent_id,title,t1,t2,t3,links,sources,dach,ord) values
('pba3bebauungspl','p',3,'pba2planungsr','Bebauungsplan und Festsetzungen','Ein Bebauungsplan konkretisiert die Widmung bis auf Maß, Bauweise und Baugrenzen eines einzelnen Grundstücks. Er ist verbindliches Ortsrecht, keine Empfehlung, Abweichungen brauchen ein eigenes Verfahren. Wer einen Bebauungsplan gründlich liest, kennt schon vor dem ersten Entwurf viele Grenzen seines Spielraums.',NULL,NULL,'{}'::text[],'[{"t":"BauGB (Baugesetzbuch)","stand":"Bekanntmachung 03.11.2017, zuletzt geändert 23.07.2026","u":"https://www.gesetze-im-internet.de/bbaug/","geprueft":"2026-08-19"},{"t":"RPG (Raumplanungsgesetz)","stand":"SR 700, vom 22.06.1979, konsolidiert","u":"https://www.fedlex.admin.ch/eli/cc/1979/1573_1573_1573/de","geprueft":"2026-08-19"}]'::jsonb,'{"de":"In Deutschland sind Bebauungspläne nach Baugesetzbuch verbindliche Satzungen der Gemeinde mit unmittelbarer Rechtswirkung.","at":"In Österreich übernimmt der Bebauungsplan nach Landesrecht eine vergleichbare Funktion, oft ergänzt um Bebauungsbestimmungen der Gemeinde.","ch":"In der Schweiz konkretisieren kommunale Bau- und Zonenordnungen im Rahmen des Raumplanungsgesetzes die zulässige Bebauung."}'::jsonb,601),
('pba3innenaussen','p',3,'pba2planungsr','Bauen im Innen- und Außenbereich','Ob ein Grundstück im Innenbereich einer Ortschaft oder im unbeplanten Außenbereich liegt, entscheidet über die Zulässigkeit fast wie ein Schalter: Innen ist bauen meist möglich, außen die Ausnahme. Diese Unterscheidung schützt Landschaft und Freiraum, ist aber für Bauherren oft schwer nachvollziehbar. Gerade am Ortsrand wird diese Grenze zum Streitfall.',NULL,NULL,'{}'::text[],'[{"t":"BauGB (Baugesetzbuch)","stand":"Bekanntmachung 03.11.2017, zuletzt geändert 23.07.2026","u":"https://www.gesetze-im-internet.de/bbaug/","geprueft":"2026-08-19"},{"t":"RPG (Raumplanungsgesetz)","stand":"SR 700, vom 22.06.1979, konsolidiert","u":"https://www.fedlex.admin.ch/eli/cc/1979/1573_1573_1573/de","geprueft":"2026-08-19"}]'::jsonb,'{"de":"Das Baugesetzbuch unterscheidet in Deutschland zwischen unbeplantem Innenbereich, Bebauungsplangebiet und Außenbereich mit jeweils eigenen Zulässigkeitsregeln.","at":"In Österreich regeln die Landesraumordnungsgesetze das Bauen außerhalb gewidmeter Bauflächen sehr restriktiv.","ch":"In der Schweiz trennt das Raumplanungsgesetz Bauzonen streng vom Nichtbaugebiet, Bauten außerhalb der Bauzone sind nur ausnahmsweise zulässig."}'::jsonb,602),
('pba2ordnungsr','p',2,'pba1','Bauordnungsrecht','Während das Planungsrecht klärt, was auf einem Grundstück zulässig ist, regelt das Bauordnungsrecht, wie das konkrete Gebäude beschaffen sein muss: Standsicherheit, Brandschutz, Abstände, Aufenthaltsqualität. Es ist das dichteste Regelwerk im ganzen Bauprozess und unterscheidet sich selbst innerhalb eines Landes regional. Ohne seine Grundzüge zu kennen, lässt sich kein genehmigungsfähiges Gebäude entwerfen.',NULL,NULL,'{}'::text[],'[{"t":"Landesbauordnungen (DE), exemplarisch BauO NRW 2018","stand":"Fassung 2018, zuletzt geändert Juli 2026","u":"https://recht.nrw.de/lmi/owa/br_bes_text?anw_nr=2&bes_id=39224&aufgehoben=N&keyword=landesbauordnung","geprueft":"2026-08-19"},{"t":"OIB-Richtlinien","stand":"Ausgabe 2023, beschlossen 25.05.2023","u":"https://www.oib.or.at/kernaufgaben/oib-richtlinien1/richtlinien/oib-richtlinien-2023/","geprueft":"2026-08-19"}]'::jsonb,'{"de":"Deutschland regelt das Bauordnungsrecht über 16 eigenständige Landesbauordnungen, die sich an der Musterbauordnung orientieren, aber im Detail abweichen.","at":"In Österreich setzen die Landesbauordnungen die OIB-Richtlinien technisch aus, mit landesspezifischen Abweichungen im Verfahren.","ch":"In der Schweiz gelten kantonale Baugesetze, deren technische Anforderungen die interkantonale Vereinbarung IVHB harmonisiert."}'::jsonb,603),
('pba3gebklasse','p',3,'pba2ordnungsr','Gebäudeklassen und Anwendungsbereich','Gebäudeklassen staffeln Anforderungen nach Höhe, Nutzung und Personenzahl: Ein Einfamilienhaus wird anders behandelt als ein Hochhaus. Diese Einstufung entscheidet über nahezu alle weiteren Anforderungen, von Rettungswegen bis Brandschutz. Ein falsch eingestuftes Gebäude plant an den eigentlichen Anforderungen vorbei.',NULL,NULL,'{}'::text[],'[{"t":"Landesbauordnungen (DE), exemplarisch BauO NRW 2018","stand":"Fassung 2018, zuletzt geändert Juli 2026","u":"https://recht.nrw.de/lmi/owa/br_bes_text?anw_nr=2&bes_id=39224&aufgehoben=N&keyword=landesbauordnung","geprueft":"2026-08-19"},{"t":"OIB-Richtlinien","stand":"Ausgabe 2023, beschlossen 25.05.2023","u":"https://www.oib.or.at/kernaufgaben/oib-richtlinien1/richtlinien/oib-richtlinien-2023/","geprueft":"2026-08-19"}]'::jsonb,'{"de":"Die Landesbauordnungen staffeln in Deutschland Gebäude in fünf Gebäudeklassen mit jeweils steigenden Anforderungen.","at":"Österreich staffelt vergleichbar über die OIB-Richtlinien nach Gebäudehöhe und Nutzung, die Umsetzung erfolgt über die Landesbauordnungen.","ch":"Die Schweiz differenziert kantonal, orientiert an durch die IVHB harmonisierten Nutzungs- und Gebäudekategorien."}'::jsonb,604),
('pba3brandabschn','p',3,'pba2ordnungsr','Brandschutzanforderungen der Bauordnung','Brandschutz ist der umfangreichste Einzelbereich des Bauordnungsrechts: Rettungswege, Brandabschnitte, Feuerwiderstand von Bauteilen, alles staffelt sich nach Gebäudeklasse und Nutzung. Anders als bei Statik gibt es hier selten eine einzelne richtige Lösung, sondern ein Gesamtkonzept aus baulichen, technischen und organisatorischen Maßnahmen. Wer Brandschutz erst am Ende mitdenkt, muss das Gebäude oft nachträglich verteuern.',NULL,NULL,ARRAY['k3t30','k3rs','kt2not']::text[],'[{"t":"Landesbauordnungen (DE), exemplarisch BauO NRW 2018","stand":"Fassung 2018, zuletzt geändert Juli 2026","u":"https://recht.nrw.de/lmi/owa/br_bes_text?anw_nr=2&bes_id=39224&aufgehoben=N&keyword=landesbauordnung","geprueft":"2026-08-19"},{"t":"OIB-Richtlinien","stand":"Ausgabe 2023, beschlossen 25.05.2023","u":"https://www.oib.or.at/kernaufgaben/oib-richtlinien1/richtlinien/oib-richtlinien-2023/","geprueft":"2026-08-19"}]'::jsonb,'{"de":"In Deutschland ergeben sich die Brandschutzanforderungen aus den Landesbauordnungen, konkretisiert durch Sonderbauverordnungen und technische Richtlinien.","at":"In Österreich bildet die OIB-Richtlinie 2 die zentrale Grundlage für Brandschutzanforderungen im Hochbau.","ch":"In der Schweiz setzen die Brandschutzvorschriften der Vereinigung Kantonaler Feuerversicherungen (VKF) den technischen Standard, kantonal umgesetzt."}'::jsonb,605),
('pba3stellplatz','p',3,'pba2ordnungsr','Stellplatzpflicht und Erschließung','Wer ein Gebäude errichtet, muss meist auch eine bestimmte Zahl an Stellplätzen nachweisen und die verkehrliche Erschließung sichern. Diese Pflicht wirkt oft banal, entscheidet aber über Grundstücksfläche, Kosten und manchmal über die Machbarkeit eines Projekts überhaupt. Innerstädtisch wird die Stellplatzfrage zunehmend politisch diskutiert und gelockert.',NULL,NULL,'{}'::text[],'[{"t":"Landesbauordnungen (DE), exemplarisch BauO NRW 2018","stand":"Fassung 2018, zuletzt geändert Juli 2026","u":"https://recht.nrw.de/lmi/owa/br_bes_text?anw_nr=2&bes_id=39224&aufgehoben=N&keyword=landesbauordnung","geprueft":"2026-08-19"}]'::jsonb,'{"de":"Die Stellplatzpflicht ist in Deutschland Sache der Landesbauordnungen und kommunaler Stellplatzsatzungen, mit Ablösemöglichkeiten gegen Zahlung.","at":"In Österreich regeln die Landesbauordnungen beziehungsweise eigene Stellplatzverordnungen der Länder die Stellplatzpflicht.","ch":"In der Schweiz legen kantonale und kommunale Vorschriften, teils mit eigenen Normen des Straßen- und Verkehrsingenieurwesens, die Stellplatzzahl fest."}'::jsonb,606),
('pba2verfahren','p',2,'pba1','Genehmigungsverfahren und Bauvorlagen','Das Genehmigungsverfahren ist die formale Brücke zwischen Entwurf und Baurecht: Welche Unterlagen nötig sind, wer sie prüft und wie lange das dauert, unterscheidet sich stark nach Vorhabenart und Bundesland oder Kanton. Ein gut vorbereiteter Antrag verkürzt die Wartezeit oft mehr als jedes Nachfragen bei der Behörde. Verfahrensfehler treffen am Ende immer das Projekt, selten die Behörde.',NULL,NULL,ARRAY['pab3genehmigung']::text[],'[{"t":"Landesbauordnungen (DE), exemplarisch BauO NRW 2018","stand":"Fassung 2018, zuletzt geändert Juli 2026","u":"https://recht.nrw.de/lmi/owa/br_bes_text?anw_nr=2&bes_id=39224&aufgehoben=N&keyword=landesbauordnung","geprueft":"2026-08-19"}]'::jsonb,'{"de":"In Deutschland unterscheiden die Landesbauordnungen genehmigungsfreie, vereinfachte und reguläre Baugenehmigungsverfahren.","at":"In Österreich reichen die Verfahren von der Anzeige bis zur Baubewilligung, gestaffelt nach den jeweiligen Landesbauordnungen.","ch":"In der Schweiz durchläuft ein Bauvorhaben je nach Kanton ein ordentliches oder vereinfachtes Baubewilligungsverfahren."}'::jsonb,607),
('pba3verfahrensart','p',3,'pba2verfahren','Verfahrensarten: frei, vereinfacht, voll','Nicht jedes Bauvorhaben braucht eine volle Baugenehmigung: Kleine Vorhaben sind oft anzeigepflichtig oder sogar verfahrensfrei, größere durchlaufen ein vereinfachtes oder reguläres Verfahren mit voller Prüfung. Welches Verfahren greift, hängt von Größe, Nutzung und Lage ab, nicht vom Wunsch des Bauherrn. Die falsche Einschätzung der Verfahrensart ist ein häufiger Projektverzug am Anfang.',NULL,NULL,'{}'::text[],'[{"t":"Landesbauordnungen (DE), exemplarisch BauO NRW 2018","stand":"Fassung 2018, zuletzt geändert Juli 2026","u":"https://recht.nrw.de/lmi/owa/br_bes_text?anw_nr=2&bes_id=39224&aufgehoben=N&keyword=landesbauordnung","geprueft":"2026-08-19"}]'::jsonb,'{"de":"Die Landesbauordnungen listen in Deutschland verfahrensfreie Vorhaben und unterscheiden vereinfachtes von regulärem Genehmigungsverfahren.","at":"In Österreich reicht die Bandbreite von der bloßen Bauanzeige bis zur vollständigen Baubewilligung nach Landesbauordnung.","ch":"In der Schweiz kennen viele Kantone ein vereinfachtes Meldeverfahren neben dem ordentlichen Baubewilligungsverfahren."}'::jsonb,608),
('pba3bauvorlagen','p',3,'pba2verfahren','Bauvorlagen und Antragsunterlagen','Bauvorlagen sind die geprüfte Sprache der Behörde: Lagepläne, Bauzeichnungen, Berechnungen und Nachweise in vorgeschriebener Form. Fehlt ein Dokument oder stimmt ein Maßstab nicht, wird der Antrag als unvollständig zurückgewiesen, unabhängig von der Qualität des Entwurfs. Vollständigkeit ist hier wichtiger als Eleganz.',NULL,NULL,'{}'::text[],'[{"t":"Landesbauordnungen (DE), exemplarisch BauO NRW 2018","stand":"Fassung 2018, zuletzt geändert Juli 2026","u":"https://recht.nrw.de/lmi/owa/br_bes_text?anw_nr=2&bes_id=39224&aufgehoben=N&keyword=landesbauordnung","geprueft":"2026-08-19"}]'::jsonb,'{"de":"In Deutschland definieren die Bauvorlagenverordnungen der Länder Inhalt und Form der einzureichenden Unterlagen.","at":"In Österreich schreiben die Landesbauordnungen und ergänzende Verordnungen den Umfang der Einreichunterlagen vor.","ch":"In der Schweiz legen kantonale Baugesuchsverordnungen fest, welche Pläne und Nachweise ein Baugesuch enthalten muss."}'::jsonb,609),
('pba3baubeginn','p',3,'pba2verfahren','Baubeginn und Fertigstellungsanzeigen','Auch nach erteilter Genehmigung bleibt das Verfahren nicht stehen: Baubeginn, bestimmte Bauzustände und die Fertigstellung müssen der Behörde angezeigt werden, teils verbunden mit Zwischenabnahmen. Wer diese Anzeigen versäumt, riskiert Baustopp oder Probleme bei der späteren Nutzungsfreigabe. Das Verfahren endet formal erst mit der behördlichen Fertigstellungsanzeige oder Abnahme.',NULL,NULL,'{}'::text[],'[{"t":"Landesbauordnungen (DE), exemplarisch BauO NRW 2018","stand":"Fassung 2018, zuletzt geändert Juli 2026","u":"https://recht.nrw.de/lmi/owa/br_bes_text?anw_nr=2&bes_id=39224&aufgehoben=N&keyword=landesbauordnung","geprueft":"2026-08-19"}]'::jsonb,'{"de":"In Deutschland verlangen die Landesbauordnungen Anzeigen zu Baubeginn und Rohbaufertigstellung, die Nutzung setzt oft eine Fertigstellungsanzeige voraus.","at":"In Österreich sind Baubeginn und Fertigstellung nach Landesbauordnung anzuzeigen, die Benützung folgt teils eigenen Bewilligungen.","ch":"In der Schweiz melden Bauherren Baubeginn und Bauvollendung den kantonalen Behörden, die Bewilligung zur Nutzung schließt das Verfahren ab."}'::jsonb,610),
('pba3nachbarbet','p',3,'pba2verfahren','Nachbarbeteiligung im Verfahren','Nachbarn haben im Genehmigungsverfahren eigene Rechte: Sie können angehört werden und bestimmte Verstöße, etwa gegen Abstandsflächen, rechtlich anfechten. Diese Beteiligung kann ein Verfahren erheblich verzögern, wenn Konflikte nicht früh geklärt werden. Ein informelles Gespräch mit dem Nachbarn vor Antragstellung erspart oft ein förmliches Verfahren später.',NULL,NULL,'{}'::text[],'[{"t":"Landesbauordnungen (DE), exemplarisch BauO NRW 2018","stand":"Fassung 2018, zuletzt geändert Juli 2026","u":"https://recht.nrw.de/lmi/owa/br_bes_text?anw_nr=2&bes_id=39224&aufgehoben=N&keyword=landesbauordnung","geprueft":"2026-08-19"}]'::jsonb,'{"de":"In Deutschland werden Nachbarn nach Landesbauordnung beteiligt und können nachbarschützende Vorschriften, etwa Abstandsflächen, klagend geltend machen.","at":"In Österreich sind Nachbarn nach Landesbauordnung Parteien im Verfahren mit eigenem Einspruchsrecht.","ch":"In der Schweiz können Nachbarn ein Baugesuch während der öffentlichen Auflage einsehen und dagegen Einsprache erheben."}'::jsonb,611),
('pba2abstand','p',2,'pba1','Abstandsflächen und Nachbarrecht','Abstandsflächen sichern Belichtung, Belüftung und Brandschutz zwischen Gebäuden und sind zugleich die häufigste Quelle von Nachbarstreit. Sie werden meist aus der Gebäudehöhe berechnet und wirken sich direkt auf die mögliche Ausnutzung eines Grundstücks aus. Kaum ein anderes Bauordnungsthema wird so oft im Vorentwurf übersehen und im Genehmigungsverfahren zum Problem.',NULL,NULL,'{}'::text[],'[{"t":"Landesbauordnungen (DE), exemplarisch BauO NRW 2018","stand":"Fassung 2018, zuletzt geändert Juli 2026","u":"https://recht.nrw.de/lmi/owa/br_bes_text?anw_nr=2&bes_id=39224&aufgehoben=N&keyword=landesbauordnung","geprueft":"2026-08-19"}]'::jsonb,'{"de":"In Deutschland berechnen die Landesbauordnungen Abstandsflächen meist als Vielfaches der Wandhöhe, mit Sonderregeln für Grenzbebauung.","at":"In Österreich regeln die Landesbauordnungen Bauwiche und Abstände zur Grundgrenze mit jeweils eigener Berechnungslogik.","ch":"In der Schweiz bestimmen kantonale Baugesetze Grenz- und Gebäudeabstände, oft in Abhängigkeit von der Gebäudehöhe."}'::jsonb,612),
('pba3abstandsflberech','p',3,'pba2abstand','Berechnung der Abstandsfläche','Die Abstandsfläche wird meist aus der Wandhöhe abgeleitet und vor die Fassade gelegt, mit Sonderregeln für Dachformen, Erker oder Giebel. Schon kleine Höhenunterschiede in der Berechnung verschieben Baugrenzen spürbar. Diese Berechnung gehört in jede Vorplanung, nicht erst in die Genehmigungsplanung.',NULL,NULL,'{}'::text[],'[{"t":"Landesbauordnungen (DE), exemplarisch BauO NRW 2018","stand":"Fassung 2018, zuletzt geändert Juli 2026","u":"https://recht.nrw.de/lmi/owa/br_bes_text?anw_nr=2&bes_id=39224&aufgehoben=N&keyword=landesbauordnung","geprueft":"2026-08-19"}]'::jsonb,'{"de":"Deutsche Landesbauordnungen berechnen die Abstandsfläche meist als Bruchteil der Wandhöhe, mit unterschiedlichen Faktoren je Bundesland.","at":"Österreichische Landesbauordnungen berechnen den Bauwich ähnlich aus der Gebäudehöhe, mit eigenen Mindestmaßen je Bundesland.","ch":"Kantonale Baugesetze in der Schweiz leiten den Grenzabstand ebenfalls meist aus der Gebäudehöhe ab, die Faktoren variieren kantonal stark."}'::jsonb,613),
('pba3grenzbebauung','p',3,'pba2abstand','Grenzbebauung und Ausnahmen','Manchmal darf direkt an die Grundstücksgrenze gebaut werden, etwa bei Garagen, Nebengebäuden oder in geschlossener Bauweise historischer Ortskerne. Diese Ausnahmen sind eng gefasst und meist an Bedingungen wie Höhe oder Nutzung geknüpft. Wer sie ausreizen will, braucht eine sehr genaue Kenntnis der lokalen Regelung.',NULL,NULL,'{}'::text[],'[{"t":"Landesbauordnungen (DE), exemplarisch BauO NRW 2018","stand":"Fassung 2018, zuletzt geändert Juli 2026","u":"https://recht.nrw.de/lmi/owa/br_bes_text?anw_nr=2&bes_id=39224&aufgehoben=N&keyword=landesbauordnung","geprueft":"2026-08-19"}]'::jsonb,'{"de":"Die Landesbauordnungen erlauben in Deutschland Grenzbebauung unter engen Voraussetzungen, etwa für Garagen bis zu bestimmten Maßen.","at":"In Österreich lassen Landesbauordnungen Grenzbebauung meist nur für Nebengebäude oder in geschlossener Bauweise zu.","ch":"In der Schweiz definieren kantonale Baugesetze Ausnahmen von der Abstandspflicht, häufig eng an Nutzung und Grenzbaurecht des Nachbarn gekoppelt."}'::jsonb,614),
('pba3nachbarzust','p',3,'pba2abstand','Nachbarzustimmung und Nachbarrechtsbehelfe','Wo Abstandsflächen unterschritten werden sollen, kann eine Nachbarzustimmung den Weg öffnen, verweigert der Nachbar sie, bleibt oft nur der Rechtsweg. Nachbarn können sich gegen Verstöße gegen nachbarschützende Vorschriften wehren, selbst wenn die Baugenehmigung bereits erteilt ist. Diese Rechtsbehelfe können ein fertig geplantes Projekt noch spät zu Fall bringen.',NULL,NULL,'{}'::text[],'[{"t":"Landesbauordnungen (DE), exemplarisch BauO NRW 2018","stand":"Fassung 2018, zuletzt geändert Juli 2026","u":"https://recht.nrw.de/lmi/owa/br_bes_text?anw_nr=2&bes_id=39224&aufgehoben=N&keyword=landesbauordnung","geprueft":"2026-08-19"}]'::jsonb,'{"de":"In Deutschland kann eine Abstandsflächenübernahme oder Nachbarzustimmung Unterschreitungen ermöglichen, andernfalls bleibt der Nachbarwiderspruch beziehungsweise die Klage.","at":"In Österreich kann eine Zustimmung des Nachbarn Abweichungen von Abstandsvorschriften ermöglichen, sonst steht ihm der Einspruch im Verfahren offen.","ch":"In der Schweiz kann eine Näherbaurechtsvereinbarung mit dem Nachbarn Grenzabstände unterschreiten, andernfalls bleibt die Einsprachemöglichkeit."}'::jsonb,615);
insert into public.nodes (id,perspective,level,parent_id,title,t1,t2,t3,links,sources,dach,ord) values
('pba2sonder','p',2,'pba1','Sonderbauten und Abweichungen','Sonderbauten wie Versammlungsstätten, Hochhäuser oder Krankenhäuser folgen nicht den Standardanforderungen der Bauordnung, sondern eigenen, meist strengeren Regeln, weil ihr Gefährdungspotenzial höher ist. Für sie braucht es oft ein eigenständiges Brandschutzkonzept statt der Regelanforderung. Wo die Bauordnung nicht ausreicht, ermöglichen Abweichungen und Ausnahmen im Einzelfall trotzdem ein Bauvorhaben.',NULL,NULL,'{}'::text[],'[{"t":"Landesbauordnungen (DE), exemplarisch BauO NRW 2018","stand":"Fassung 2018, zuletzt geändert Juli 2026","u":"https://recht.nrw.de/lmi/owa/br_bes_text?anw_nr=2&bes_id=39224&aufgehoben=N&keyword=landesbauordnung","geprueft":"2026-08-19"},{"t":"OIB-Richtlinien","stand":"Ausgabe 2023, beschlossen 25.05.2023","u":"https://www.oib.or.at/kernaufgaben/oib-richtlinien1/richtlinien/oib-richtlinien-2023/","geprueft":"2026-08-19"}]'::jsonb,'{"de":"In Deutschland definieren die Landesbauordnungen Sonderbauten, konkretisiert durch Sonderbauverordnungen wie Versammlungsstätten- oder Verkaufsstättenverordnungen.","at":"In Österreich regeln die OIB-Richtlinien besondere Anforderungen an bestimmte Nutzungsklassen, die Landesbauordnungen ergänzen sie.","ch":"In der Schweiz gelten für Sonderbauten erhöhte Anforderungen der VKF-Brandschutzvorschriften, kantonal umgesetzt."}'::jsonb,616),
('pba3sonderbautypen','p',3,'pba2sonder','Typen von Sonderbauten','Hochhaus, Versammlungsstätte, Verkaufsstätte, Krankenhaus: Jeder Sonderbautyp bringt ein eigenes Gefährdungsprofil mit und damit eigene, oft deutlich strengere Anforderungen als der Standardbau. Schon die Einstufung als Sonderbau verändert Genehmigungsverfahren und benötigte Nachweise grundlegend. Wer einen Sonderbau wie ein Standardgebäude plant, muss spätestens im Verfahren nachbessern.',NULL,NULL,'{}'::text[],'[{"t":"Landesbauordnungen (DE), exemplarisch BauO NRW 2018","stand":"Fassung 2018, zuletzt geändert Juli 2026","u":"https://recht.nrw.de/lmi/owa/br_bes_text?anw_nr=2&bes_id=39224&aufgehoben=N&keyword=landesbauordnung","geprueft":"2026-08-19"},{"t":"OIB-Richtlinien","stand":"Ausgabe 2023, beschlossen 25.05.2023","u":"https://www.oib.or.at/kernaufgaben/oib-richtlinien1/richtlinien/oib-richtlinien-2023/","geprueft":"2026-08-19"}]'::jsonb,'{"de":"Deutsche Landesbauordnungen listen Sonderbautypen und verweisen für viele davon auf eigene Sonderbauverordnungen der Länder.","at":"Österreichische OIB-Richtlinien unterscheiden Nutzungsklassen mit erhöhten Anforderungen für bestimmte Sonderbautypen.","ch":"Die Schweiz stuft Sonderbauten über die VKF-Brandschutzvorschriften in erhöhte Risikokategorien ein."}'::jsonb,617),
('pba3abweichung','p',3,'pba2sonder','Abweichungen, Ausnahmen und Befreiungen','Wo eine Regel im Einzelfall unangemessen wäre, sehen Bauordnungen Abweichungen, Ausnahmen oder Befreiungen vor, meist an eine Abwägung mit den Schutzzielen der Vorschrift gebunden. Sie sind kein Freifahrtschein, sondern verlangen eine nachvollziehbare Begründung und oft Kompensationsmaßnahmen. Gute Abweichungsanträge argumentieren mit dem Schutzziel, nicht mit dem Wunsch des Bauherrn.',NULL,NULL,'{}'::text[],'[{"t":"Landesbauordnungen (DE), exemplarisch BauO NRW 2018","stand":"Fassung 2018, zuletzt geändert Juli 2026","u":"https://recht.nrw.de/lmi/owa/br_bes_text?anw_nr=2&bes_id=39224&aufgehoben=N&keyword=landesbauordnung","geprueft":"2026-08-19"}]'::jsonb,'{"de":"Die Landesbauordnungen erlauben in Deutschland Abweichungen, wenn das Schutzziel der Vorschrift auf andere Weise gleichwertig erreicht wird.","at":"In Österreich können Landesbauordnungen Ausnahmen zulassen, sofern die dahinterstehenden Schutzinteressen gewahrt bleiben.","ch":"In der Schweiz erlauben kantonale Baugesetze Ausnahmebewilligungen, wenn wichtige Gründe vorliegen und öffentliche Interessen nicht überwiegen."}'::jsonb,618),
('pba3brandschutzkonz','p',3,'pba2sonder','Brandschutzkonzept bei Sonderbauten','Für Sonderbauten reicht die Regelanforderung der Bauordnung meist nicht aus, gefordert wird ein individuelles Brandschutzkonzept, das Rettungswege, Kompartimentierung und Anlagentechnik als Gesamtsystem nachweist. Es wird von einer eigenen Fachplanung erstellt und ist Teil der Genehmigungsunterlagen. Ein gutes Konzept denkt Nutzung und Gebäude zusammen, nicht nur Vorschrift für Vorschrift.',NULL,NULL,ARRAY['k3t30']::text[],'[{"t":"OIB-Richtlinien","stand":"Ausgabe 2023, beschlossen 25.05.2023","u":"https://www.oib.or.at/kernaufgaben/oib-richtlinien1/richtlinien/oib-richtlinien-2023/","geprueft":"2026-08-19"}]'::jsonb,'{"de":"In Deutschland verlangen viele Sonderbauverordnungen ein eigenständiges Brandschutzkonzept, geprüft von Sachverständigen oder Prüfingenieuren.","at":"In Österreich wird das Brandschutzkonzept meist auf Basis der OIB-Richtlinie 2 erstellt und von der Behörde geprüft.","ch":"In der Schweiz erstellen Brandschutzfachleute das Konzept nach den VKF-Brandschutzvorschriften, mit kantonaler Prüfung."}'::jsonb,619),
('pko1','p',1,NULL,'Kosten','Baukosten entstehen nicht am Ende, sondern werden von der ersten Skizze an mitgeplant: Jede Entwurfsentscheidung hat einen Preis, auch wenn er erst später sichtbar wird. Wie Kosten gegliedert, ermittelt und über die Projektphasen fortgeschrieben werden, folgt in Deutschland, Österreich und der Schweiz unterschiedlichen, aber strukturell verwandten Systemen. Wer Kosten erst am Ende zählt, hat sie längst nicht mehr im Griff.',NULL,NULL,'{}'::text[],'[]'::jsonb,NULL,620),
('pko2gliederung','p',2,'pko1','Kostenplanung und Gliederung','Bevor Kosten geplant werden können, müssen sie gegliedert werden: in Bauwerk, Technik, Außenanlagen, Nebenkosten und mehr, sonst bleibt jede Summe unvergleichbar. Diese Gliederung ist die gemeinsame Sprache zwischen Planer, Bauherr und Kostenplaner. Jedes DACH-Land hat dafür ein eigenes, aber ähnlich aufgebautes System.',NULL,NULL,ARRAY['pho2honorar']::text[],'[{"t":"DIN 276 Kosten im Bauwesen","stand":"2018-12","u":"https://www.dinmedia.de/de/norm/din-276/293154016","geprueft":"2026-08-19"},{"t":"ÖNORM B 1801-1 Objekterrichtung (Kosten)","stand":"2022-03-01","u":"https://shop.austrian-standards.at/action/de/public/details/1165987/OENORM_B_1801-1_2022_03_01","geprueft":"2026-08-19"},{"t":"eBKP-H Baukostenplan Hochbau (SN 506 511), CRB","stand":"Ausgabe 2020","u":"https://www.crb.ch/de/normen-standards/baukostenplane/baukostenplan-hochbau-ebkp-h","geprueft":"2026-08-19"}]'::jsonb,'{"de":"In Deutschland gliedert die DIN 276 Baukosten in Kostengruppen von der Grundstücksbeschaffung bis zu den Baunebenkosten.","at":"In Österreich übernimmt die ÖNORM B 1801 eine vergleichbare Gliederungsfunktion für Kostenermittlung und Kostenverfolgung.","ch":"In der Schweiz strukturiert der eBKP-H, der Baukostenplan Hochbau, Kosten nach Bauteilen statt nach Gewerken."}'::jsonb,621),
('pko3kostengruppen','p',3,'pko2gliederung','Kostengruppen und Gliederungstiefe','Kostengruppen fassen ähnliche Kostenanteile zusammen, etwa Baukonstruktion oder Technische Anlagen, und lassen sich je nach Planungstiefe grober oder feiner gliedern. Am Anfang genügt eine grobe Einteilung, später wird bis auf einzelne Bauteile heruntergebrochen. Wer zu früh zu fein gliedert, verliert Zeit an Zahlen, die sich noch ändern.',NULL,NULL,'{}'::text[],'[{"t":"DIN 276 Kosten im Bauwesen","stand":"2018-12","u":"https://www.dinmedia.de/de/norm/din-276/293154016","geprueft":"2026-08-19"},{"t":"ÖNORM B 1801-1 Objekterrichtung (Kosten)","stand":"2022-03-01","u":"https://shop.austrian-standards.at/action/de/public/details/1165987/OENORM_B_1801-1_2022_03_01","geprueft":"2026-08-19"},{"t":"eBKP-H Baukostenplan Hochbau (SN 506 511), CRB","stand":"Ausgabe 2020","u":"https://www.crb.ch/de/normen-standards/baukostenplane/baukostenplan-hochbau-ebkp-h","geprueft":"2026-08-19"}]'::jsonb,'{"de":"Die DIN 276 gliedert in Deutschland Kosten in Kostengruppen erster bis dritter Ebene, von grob bis detailliert.","at":"Die ÖNORM B 1801 gliedert in Österreich vergleichbar nach Kostengruppen mit zunehmender Detailtiefe über die Projektphasen.","ch":"Der eBKP-H gliedert in der Schweiz nach Bauteilen und Elementen statt nach klassischen Gewerkegruppen."}'::jsonb,622),
('pko3systematikvgl','p',3,'pko2gliederung','Nationale Gliederungssysteme im Vergleich','DIN 276, ÖNORM B 1801 und eBKP-H sortieren Kosten nach unterschiedlicher Logik, die einen nach Gewerken, die anderen nach Bauteilen, das erschwert direkte Vergleiche zwischen Ländern. Für internationale Projekte oder Benchmarks braucht es eine bewusste Übersetzung zwischen den Systemen. Ein Kostenkennwert ohne Angabe der Gliederungssystematik ist im Grunde wertlos.',NULL,NULL,'{}'::text[],'[{"t":"DIN 276 Kosten im Bauwesen","stand":"2018-12","u":"https://www.dinmedia.de/de/norm/din-276/293154016","geprueft":"2026-08-19"},{"t":"ÖNORM B 1801-1 Objekterrichtung (Kosten)","stand":"2022-03-01","u":"https://shop.austrian-standards.at/action/de/public/details/1165987/OENORM_B_1801-1_2022_03_01","geprueft":"2026-08-19"},{"t":"eBKP-H Baukostenplan Hochbau (SN 506 511), CRB","stand":"Ausgabe 2020","u":"https://www.crb.ch/de/normen-standards/baukostenplane/baukostenplan-hochbau-ebkp-h","geprueft":"2026-08-19"}]'::jsonb,'{"de":"Die DIN 276 gliedert überwiegend gewerkeorientiert entlang des klassischen deutschen Bauablaufs.","at":"Die ÖNORM B 1801 orientiert sich strukturell an der DIN 276, mit eigenständigen Kostengruppen und Begriffen.","ch":"Der eBKP-H gliedert bauteilorientiert nach Elementen, was Vergleiche mit gewerkeorientierten Systemen erschwert."}'::jsonb,623),
('pko3kostenrahmen','p',3,'pko2gliederung','Kostenrahmen und Budgetstruktur','Der Kostenrahmen steckt zu Beginn eines Projekts die finanzielle Obergrenze ab, oft noch bevor ein Entwurf existiert. Er sollte eine Reserve für Unvorhergesehenes enthalten, die mit fortschreitender Planung planmäßig abschmilzt. Ein Kostenrahmen ohne Reserve ist ein Versprechen, das selten eingehalten wird.',NULL,NULL,'{}'::text[],'[{"t":"DIN 276 Kosten im Bauwesen","stand":"2018-12","u":"https://www.dinmedia.de/de/norm/din-276/293154016","geprueft":"2026-08-19"},{"t":"ÖNORM B 1801-1 Objekterrichtung (Kosten)","stand":"2022-03-01","u":"https://shop.austrian-standards.at/action/de/public/details/1165987/OENORM_B_1801-1_2022_03_01","geprueft":"2026-08-19"},{"t":"eBKP-H Baukostenplan Hochbau (SN 506 511), CRB","stand":"Ausgabe 2020","u":"https://www.crb.ch/de/normen-standards/baukostenplane/baukostenplan-hochbau-ebkp-h","geprueft":"2026-08-19"}]'::jsonb,'{"de":"In Deutschland wird der Kostenrahmen meist grob nach DIN 276 strukturiert und dient als erste Budgetgrundlage der Bedarfsplanung.","at":"In Österreich bildet ein grober Kostenrahmen nach vergleichbarer Logik zur ÖNORM B 1801 die erste Budgetorientierung.","ch":"In der Schweiz dient ein grober eBKP-H-Rahmen als frühe Kostenorientierung vor dem Vorprojekt."}'::jsonb,624),
('pko2ermittlung','p',2,'pko1','Kostenschätzung, -berechnung und -steuerung','Kosten werden nicht einmal ermittelt, sondern mit zunehmender Planungstiefe immer genauer fortgeschrieben, von der groben Schätzung bis zur exakten Abrechnung. Jede Stufe hat eine eigene erlaubte Ungenauigkeit, die dem Bauherrn kommuniziert werden muss. Wer eine frühe Schätzung wie eine spätere Abrechnung behandelt, weckt Erwartungen, die das Projekt nicht halten kann.',NULL,NULL,'{}'::text[],'[{"t":"DIN 276 Kosten im Bauwesen","stand":"2018-12","u":"https://www.dinmedia.de/de/norm/din-276/293154016","geprueft":"2026-08-19"},{"t":"ÖNORM B 1801-1 Objekterrichtung (Kosten)","stand":"2022-03-01","u":"https://shop.austrian-standards.at/action/de/public/details/1165987/OENORM_B_1801-1_2022_03_01","geprueft":"2026-08-19"},{"t":"eBKP-H Baukostenplan Hochbau (SN 506 511), CRB","stand":"Ausgabe 2020","u":"https://www.crb.ch/de/normen-standards/baukostenplane/baukostenplan-hochbau-ebkp-h","geprueft":"2026-08-19"}]'::jsonb,'{"de":"In Deutschland unterscheidet die DIN 276 Kostenschätzung, Kostenberechnung, Kostenanschlag und Kostenfeststellung als aufeinanderfolgende Genauigkeitsstufen.","at":"In Österreich folgt die ÖNORM B 1801 einer vergleichbaren Stufenfolge von Kostenschätzung bis Kostenfeststellung.","ch":"In der Schweiz durchläuft die Kostenermittlung nach eBKP-H ähnliche Stufen von Kostenschätzung bis Bauabrechnung."}'::jsonb,625),
('pko3schaetzung','p',3,'pko2ermittlung','Kostenschätzung in der Vorplanung','Die Kostenschätzung ist die erste belastbare Zahl, meist auf Basis von Flächen- und Rauminhaltswerten früherer Projekte ermittelt, noch ohne detaillierte Mengen. Sie trägt entsprechend große Unsicherheit und sollte nie ohne Bandbreite kommuniziert werden. Diese frühe Zahl prägt trotzdem oft die ganze weitere Erwartungshaltung des Bauherrn.',NULL,NULL,'{}'::text[],'[{"t":"DIN 276 Kosten im Bauwesen","stand":"2018-12","u":"https://www.dinmedia.de/de/norm/din-276/293154016","geprueft":"2026-08-19"},{"t":"ÖNORM B 1801-1 Objekterrichtung (Kosten)","stand":"2022-03-01","u":"https://shop.austrian-standards.at/action/de/public/details/1165987/OENORM_B_1801-1_2022_03_01","geprueft":"2026-08-19"},{"t":"eBKP-H Baukostenplan Hochbau (SN 506 511), CRB","stand":"Ausgabe 2020","u":"https://www.crb.ch/de/normen-standards/baukostenplane/baukostenplan-hochbau-ebkp-h","geprueft":"2026-08-19"}]'::jsonb,'{"de":"Die Kostenschätzung nach DIN 276 basiert in Deutschland meist auf groben Kennwerten wie Bruttorauminhalt oder Bruttogrundfläche.","at":"Die vergleichbare Kostenschätzung nach ÖNORM B 1801 stützt sich in Österreich ebenfalls auf grobe Flächen- und Rauminhaltswerte.","ch":"In der Schweiz erfolgt die frühe Kostenschätzung nach eBKP-H häufig anhand von Kennwerten pro Geschossfläche."}'::jsonb,626),
('pko3berechnung','p',3,'pko2ermittlung','Kostenberechnung in der Entwurfsplanung','Mit dem Entwurf wird die Kostenberechnung genauer: Sie stützt sich auf tatsächliche Mengen aus Grundriss und Konstruktion, nicht mehr nur auf Kennwerte. Diese Zahl ist meist die Grundlage für die endgültige Finanzierungsentscheidung des Bauherrn. Weicht die spätere Ausführungsplanung stark davon ab, war entweder der Entwurf unklar oder die Berechnung zu grob.',NULL,NULL,'{}'::text[],'[{"t":"DIN 276 Kosten im Bauwesen","stand":"2018-12","u":"https://www.dinmedia.de/de/norm/din-276/293154016","geprueft":"2026-08-19"},{"t":"ÖNORM B 1801-1 Objekterrichtung (Kosten)","stand":"2022-03-01","u":"https://shop.austrian-standards.at/action/de/public/details/1165987/OENORM_B_1801-1_2022_03_01","geprueft":"2026-08-19"},{"t":"eBKP-H Baukostenplan Hochbau (SN 506 511), CRB","stand":"Ausgabe 2020","u":"https://www.crb.ch/de/normen-standards/baukostenplane/baukostenplan-hochbau-ebkp-h","geprueft":"2026-08-19"}]'::jsonb,'{"de":"Die Kostenberechnung nach DIN 276 basiert in Deutschland auf den Mengen der Entwurfsplanung und ist deutlich genauer als die Kostenschätzung.","at":"Die Kostenberechnung nach ÖNORM B 1801 stützt sich in Österreich ebenfalls auf entwurfsbasierte Mengenermittlung.","ch":"In der Schweiz beruht die Kostenberechnung nach eBKP-H auf den Mengen des Bauprojekts."}'::jsonb,627),
('pko3anschlag','p',3,'pko2ermittlung','Kostenanschlag und Kostenfeststellung','Der Kostenanschlag entsteht aus tatsächlichen Angeboten und Verträgen, die Kostenfeststellung erst nach Abrechnung aller Leistungen, sie ist die einzige wirklich belastbare Zahl im Projekt. Zwischen früher Schätzung und finaler Feststellung liegt oft eine erhebliche Lernkurve. Der Vergleich beider Zahlen ist die wichtigste Rückmeldung für die nächste Kostenschätzung.',NULL,NULL,'{}'::text[],'[{"t":"DIN 276 Kosten im Bauwesen","stand":"2018-12","u":"https://www.dinmedia.de/de/norm/din-276/293154016","geprueft":"2026-08-19"},{"t":"ÖNORM B 1801-1 Objekterrichtung (Kosten)","stand":"2022-03-01","u":"https://shop.austrian-standards.at/action/de/public/details/1165987/OENORM_B_1801-1_2022_03_01","geprueft":"2026-08-19"},{"t":"eBKP-H Baukostenplan Hochbau (SN 506 511), CRB","stand":"Ausgabe 2020","u":"https://www.crb.ch/de/normen-standards/baukostenplane/baukostenplan-hochbau-ebkp-h","geprueft":"2026-08-19"}]'::jsonb,'{"de":"Kostenanschlag und Kostenfeststellung nach DIN 276 bilden in Deutschland die vertrags- beziehungsweise abrechnungsbasierten Endstufen der Kostenermittlung.","at":"In Österreich schließen Kostenanschlag und Kostenfeststellung nach ÖNORM B 1801 die Kostenermittlung ab.","ch":"In der Schweiz entspricht dem die Bauabrechnung nach eBKP-H als endgültige Kostenfeststellung."}'::jsonb,628),
('pko3steuerung','p',3,'pko2ermittlung','Kostensteuerung und Abweichungsmanagement','Kostensteuerung heißt, laufend zu vergleichen, was geplant und was tatsächlich gebunden wurde, und bei Abweichungen frühzeitig gegenzulenken. Wer nur am Ende addiert, kann nicht mehr steuern, nur noch feststellen. Ein funktionierendes Kostencontrolling ist deshalb kein Kosten-, sondern ein Zeitfaktor, es muss parallel zur Planung laufen.',NULL,NULL,ARRAY['pab2termin']::text[],'[{"t":"DIN 276 Kosten im Bauwesen","stand":"2018-12","u":"https://www.dinmedia.de/de/norm/din-276/293154016","geprueft":"2026-08-19"},{"t":"HOAI","stand":"HOAI 2013 i. d. F. der 1. ÄndVO, in Kraft 01.01.2021; Honorartafeln nach EuGH nur Orientierung","u":"https://www.gesetze-im-internet.de/hoai_2013/","geprueft":"2026-08-19"},{"t":"ÖNORM B 1801-1 Objekterrichtung (Kosten)","stand":"2022-03-01","u":"https://shop.austrian-standards.at/action/de/public/details/1165987/OENORM_B_1801-1_2022_03_01","geprueft":"2026-08-19"},{"t":"eBKP-H Baukostenplan Hochbau (SN 506 511), CRB","stand":"Ausgabe 2020","u":"https://www.crb.ch/de/normen-standards/baukostenplane/baukostenplan-hochbau-ebkp-h","geprueft":"2026-08-19"},{"t":"SIA 112 Modell Bauplanung","stand":"Ausgabe 2014","u":"https://shop.sia.ch/normenwerk/ingenieur/112_2014_d/D/Product","geprueft":"2026-08-19"}]'::jsonb,'{"de":"Kostensteuerung ist in Deutschland keine eigene DIN-276-Stufe, sondern ergänzende Leistung, oft im Rahmen der HOAI-Leistungsphasen vereinbart.","at":"In Österreich ist Kostensteuerung meist als gesonderte, laufend zu erbringende Leistung neben der Kostenermittlung nach ÖNORM B 1801 vereinbart.","ch":"In der Schweiz begleitet das Kostenmanagement nach eBKP-H die Projektsteuerung über alle Phasen der SIA 112."}'::jsonb,629),
('pko2benchmark','p',2,'pko1','Benchmarks und Kostenkennwerte','Kostenkennwerte erlauben es, ein Projekt früh grob einzuschätzen, ohne dass ein Entwurf existiert, indem sie Erfahrungswerte vergleichbarer Bauten heranziehen. Sie sind nur so gut wie ihre Vergleichbarkeit, ein falsch übertragener Kennwert wird schnell zur Fehlprognose. Benchmarks ersetzen keine Berechnung, sie sind ihr erster, grober Anker.',NULL,NULL,'{}'::text[],'[{"t":"DIN 276 Kosten im Bauwesen","stand":"2018-12","u":"https://www.dinmedia.de/de/norm/din-276/293154016","geprueft":"2026-08-19"},{"t":"ÖNORM B 1801-1 Objekterrichtung (Kosten)","stand":"2022-03-01","u":"https://shop.austrian-standards.at/action/de/public/details/1165987/OENORM_B_1801-1_2022_03_01","geprueft":"2026-08-19"},{"t":"eBKP-H Baukostenplan Hochbau (SN 506 511), CRB","stand":"Ausgabe 2020","u":"https://www.crb.ch/de/normen-standards/baukostenplane/baukostenplan-hochbau-ebkp-h","geprueft":"2026-08-19"}]'::jsonb,'{"de":"In Deutschland veröffentlichen Institutionen wie das Baukosteninformationszentrum Kennwerte nach DIN-276-Kostengruppen und Gebäudetyp.","at":"In Österreich existieren vergleichbare Kennwertsammlungen, häufig kammer- oder verbandsgestützt, nach ÖNORM-B-1801-Systematik.","ch":"In der Schweiz veröffentlicht unter anderem das Bundesamt für Statistik regionale Kennwerte nach eBKP-H."}'::jsonb,630);
insert into public.nodes (id,perspective,level,parent_id,title,t1,t2,t3,links,sources,dach,ord) values
('pko3kennwerte','p',3,'pko2benchmark','Kostenkennwerte je Flächen und Rauminhalt','Kosten je Quadratmeter Bruttogrundfläche oder je Kubikmeter Bruttorauminhalt sind die gängigsten Kennwerte, weil sie schnell zu berechnen und leicht zu kommunizieren sind. Sie verschweigen aber viel: Gebäudeform, Ausstattungsstandard und Grundstückslage schlagen sich kaum in einer einzigen Zahl nieder. Wer nur mit dem Quadratmeterpreis plant, übersieht die eigentlichen Kostentreiber.',NULL,NULL,'{}'::text[],'[{"t":"DIN 276 Kosten im Bauwesen","stand":"2018-12","u":"https://www.dinmedia.de/de/norm/din-276/293154016","geprueft":"2026-08-19"},{"t":"ÖNORM B 1801-1 Objekterrichtung (Kosten)","stand":"2022-03-01","u":"https://shop.austrian-standards.at/action/de/public/details/1165987/OENORM_B_1801-1_2022_03_01","geprueft":"2026-08-19"},{"t":"eBKP-H Baukostenplan Hochbau (SN 506 511), CRB","stand":"Ausgabe 2020","u":"https://www.crb.ch/de/normen-standards/baukostenplane/baukostenplan-hochbau-ebkp-h","geprueft":"2026-08-19"}]'::jsonb,'{"de":"In Deutschland werden Kennwerte meist als Kosten je Bruttogrundfläche oder Bruttorauminhalt nach DIN 276 angegeben.","at":"In Österreich sind vergleichbare Flächen- und Rauminhaltskennwerte nach ÖNORM B 1801 gebräuchlich.","ch":"In der Schweiz werden Kennwerte meist je Geschossfläche nach eBKP-H und SIA-Flächendefinitionen angegeben."}'::jsonb,631),
('pko3indexierung','p',3,'pko2benchmark','Baupreisindex und regionale Anpassung','Ein Kennwert von vor mehreren Jahren ist heute wenig wert, wenn er nicht mit dem Baupreisindex fortgeschrieben wird, Baupreise schwanken stärker als viele andere Wirtschaftsbereiche. Zusätzlich unterscheiden sich Baukosten regional erheblich, zwischen Ballungsraum und ländlicher Lage oft um ein Vielfaches. Wer beides ignoriert, rechnet mit einer Illusion statt mit einem realistischen Budget.',NULL,NULL,'{}'::text[],'[]'::jsonb,'{"de":"In Deutschland veröffentlicht das Statistische Bundesamt den Baupreisindex zur Fortschreibung von Kennwerten über die Zeit.","at":"In Österreich veröffentlicht die Statistik Austria einen vergleichbaren Baukostenindex zur zeitlichen Anpassung von Kennwerten.","ch":"In der Schweiz erhebt das Bundesamt für Statistik den Baupreisindex, regionale Unterschiede werden zusätzlich gesondert ausgewiesen."}'::jsonb,632),
('pko3vergleichbark','p',3,'pko2benchmark','Vergleichbarkeit von Kostenkennwerten','Zwei Kennwerte sind nur vergleichbar, wenn sie nach derselben Gliederungssystematik, demselben Bezugsjahr und derselben Flächendefinition ermittelt wurden, das wird in der Praxis oft übersehen. Schon ob Baunebenkosten enthalten sind oder nicht, verändert einen Kennwert erheblich. Seriöses Benchmarking beginnt deshalb mit der Frage, was in der Zahl überhaupt steckt.',NULL,NULL,'{}'::text[],'[{"t":"DIN 276 Kosten im Bauwesen","stand":"2018-12","u":"https://www.dinmedia.de/de/norm/din-276/293154016","geprueft":"2026-08-19"},{"t":"ÖNORM B 1801-1 Objekterrichtung (Kosten)","stand":"2022-03-01","u":"https://shop.austrian-standards.at/action/de/public/details/1165987/OENORM_B_1801-1_2022_03_01","geprueft":"2026-08-19"},{"t":"eBKP-H Baukostenplan Hochbau (SN 506 511), CRB","stand":"Ausgabe 2020","u":"https://www.crb.ch/de/normen-standards/baukostenplane/baukostenplan-hochbau-ebkp-h","geprueft":"2026-08-19"}]'::jsonb,'{"de":"Kennwerte nach DIN 276 sind in Deutschland nur vergleichbar, wenn Kostengruppenumfang und Bezugsgröße übereinstimmen.","at":"Kennwerte nach ÖNORM B 1801 sind in Österreich ebenso nur bei gleicher Kostengruppenabgrenzung vergleichbar.","ch":"Kennwerte nach eBKP-H sind in der Schweiz nur vergleichbar, wenn dieselbe Elementgliederung und Flächendefinition zugrunde liegt."}'::jsonb,633),
('pko2lebenszyklus','p',2,'pko1','Lebenszykluskosten','Ein Gebäude kostet nicht nur beim Bauen, sondern über Jahrzehnte im Betrieb, oft übersteigen die Nutzungskosten die Erstellungskosten deutlich. Wer nur die Investition optimiert, verschiebt Kosten häufig nur in die Zukunft, etwa durch billige, aber wartungsintensive Bauteile. Lebenszykluskosten zwingen dazu, ein Gebäude über seine ganze Lebensdauer zu denken, nicht nur bis zur Schlussrechnung.',NULL,NULL,'{}'::text[],'[{"t":"DIN 18960 Nutzungskosten im Hochbau","stand":"2020-11","u":"https://www.dinmedia.de/de/norm/din-18960/327360380","geprueft":"2026-08-19"},{"t":"DIN 276 Kosten im Bauwesen","stand":"2018-12","u":"https://www.dinmedia.de/de/norm/din-276/293154016","geprueft":"2026-08-19"},{"t":"ÖNORM B 1801-1 Objekterrichtung (Kosten)","stand":"2022-03-01","u":"https://shop.austrian-standards.at/action/de/public/details/1165987/OENORM_B_1801-1_2022_03_01","geprueft":"2026-08-19"},{"t":"eBKP-H Baukostenplan Hochbau (SN 506 511), CRB","stand":"Ausgabe 2020","u":"https://www.crb.ch/de/normen-standards/baukostenplane/baukostenplan-hochbau-ebkp-h","geprueft":"2026-08-19"}]'::jsonb,'{"de":"In Deutschland ordnet die DIN 18960 Nutzungskosten von Gebäuden, ergänzend zur Investitionskostengliederung der DIN 276.","at":"In Österreich fasst die ÖNORM B 1801 auch Folgekosten der Nutzung in ihrer Gliederung mit, wenn auch weniger detailliert als die Investitionskosten.","ch":"In der Schweiz erfasst der eBKP-H primär Erstellungskosten, Betriebskosten werden ergänzend nach eigenen SIA-Grundlagen betrachtet."}'::jsonb,634),
('pko3investnutzung','p',3,'pko2lebenszyklus','Investitions- und Nutzungskosten','Investitionskosten fallen einmalig an, Nutzungskosten laufend, über zwanzig oder dreißig Jahre kann Letzteres die Erstellung finanziell weit übertreffen. Diese Gegenüberstellung verändert oft die Bewertung einer scheinbar teuren Entwurfsentscheidung: Eine bessere Gebäudehülle rechnet sich meist erst im Betrieb. Wer nur die Baukosten vergleicht, vergleicht die falsche Zahl.',NULL,NULL,'{}'::text[],'[{"t":"DIN 276 Kosten im Bauwesen","stand":"2018-12","u":"https://www.dinmedia.de/de/norm/din-276/293154016","geprueft":"2026-08-19"},{"t":"DIN 18960 Nutzungskosten im Hochbau","stand":"2020-11","u":"https://www.dinmedia.de/de/norm/din-18960/327360380","geprueft":"2026-08-19"},{"t":"ÖNORM B 1801-1 Objekterrichtung (Kosten)","stand":"2022-03-01","u":"https://shop.austrian-standards.at/action/de/public/details/1165987/OENORM_B_1801-1_2022_03_01","geprueft":"2026-08-19"},{"t":"eBKP-H Baukostenplan Hochbau (SN 506 511), CRB","stand":"Ausgabe 2020","u":"https://www.crb.ch/de/normen-standards/baukostenplane/baukostenplan-hochbau-ebkp-h","geprueft":"2026-08-19"}]'::jsonb,'{"de":"In Deutschland stehen sich Investitionskosten nach DIN 276 und Nutzungskosten nach DIN 18960 als getrennt gegliederte, aber zusammengehörige Größen gegenüber.","at":"In Österreich werden Investitions- und Folgekosten innerhalb der ÖNORM-B-1801-Systematik gemeinsam betrachtet, wenn auch mit Schwerpunkt auf der Investition.","ch":"In der Schweiz stehen Erstellungskosten nach eBKP-H und Betriebskosten nach SIA-Grundlagen ebenfalls als getrennte, aber verglichene Größen nebeneinander."}'::jsonb,635),
('pko3nutzungskost','p',3,'pko2lebenszyklus','Nutzungskosten und Betriebskostensystematik','Nutzungskosten umfassen Betrieb, Instandhaltung, Verwaltung und Versorgung, alles, was ein Gebäude laufend kostet, nachdem der Bauherr die Schlüssel erhalten hat. Sie werden oft grob geschätzt, obwohl sie langfristig entscheidender sind als die Baukosten. Eine saubere Nutzungskostenplanung beginnt idealerweise schon im Entwurf, nicht erst nach dem Einzug.',NULL,NULL,'{}'::text[],'[{"t":"DIN 18960 Nutzungskosten im Hochbau","stand":"2020-11","u":"https://www.dinmedia.de/de/norm/din-18960/327360380","geprueft":"2026-08-19"}]'::jsonb,'{"de":"Die DIN 18960 gliedert in Deutschland Nutzungskosten in Kapital-, Betriebs- und Instandsetzungskosten von Gebäuden.","at":"In Österreich fehlt eine eigenständige Nutzungskostennorm, Betriebskosten werden meist gebäudetypspezifisch nach eigener Praxis erfasst.","ch":"In der Schweiz strukturieren SIA-Grundlagen zur Lebenszykluskostenrechnung die Betriebs- und Unterhaltskosten von Gebäuden."}'::jsonb,636),
('pko3lebenszyklusanalyse','p',3,'pko2lebenszyklus','Lebenszyklusanalyse als Entscheidungshilfe','Eine Lebenszyklusanalyse rechnet Investitions- und Nutzungskosten über einen definierten Betrachtungszeitraum zu einer vergleichbaren Kennzahl zusammen und macht so unterschiedliche Entwurfsvarianten wirtschaftlich vergleichbar. Sie braucht Annahmen zu Zinssatz, Nutzungsdauer und künftigen Preisen, die jede Berechnung unsicher machen. Trotzdem ist sie oft das einzige Argument, das teurere, aber langfristig wirtschaftlichere Lösungen gegen den Bauherren-Reflex verteidigen kann.',NULL,NULL,'{}'::text[],'[{"t":"DIN 18960 Nutzungskosten im Hochbau","stand":"2020-11","u":"https://www.dinmedia.de/de/norm/din-18960/327360380","geprueft":"2026-08-19"},{"t":"ÖNORM B 1801-1 Objekterrichtung (Kosten)","stand":"2022-03-01","u":"https://shop.austrian-standards.at/action/de/public/details/1165987/OENORM_B_1801-1_2022_03_01","geprueft":"2026-08-19"}]'::jsonb,'{"de":"In Deutschland orientieren sich Lebenszyklusanalysen an DIN 18960 für Nutzungskosten, ergänzt um Verfahren der VDI-Richtlinienreihe zur Wirtschaftlichkeitsberechnung.","at":"In Österreich existiert kein eigenständiges Normwerk für Lebenszyklusanalysen, die Praxis orientiert sich an internationalen Verfahren und der ÖNORM-B-1801-Kostenbasis.","ch":"In der Schweiz stützen sich Lebenszyklusanalysen auf SIA-Grundlagen zur Lebenszykluskostenrechnung im Bauwesen."}'::jsonb,637),
('pav1','p',1,NULL,'Ausschreibung und Vergabe','Zwischen fertigem Entwurf und Baustelle liegt ein Übersetzungsschritt: Die Leistungsbeschreibung macht aus Plänen eindeutige, vergleichbare Positionen, die Vergabe wählt daraus den passenden Auftragnehmer nach einem nachvollziehbaren Verfahren. Wer hier ungenau bleibt, zahlt später in Nachträgen und Streit. Dieser Ast begleitet den Weg von der Leistungsbeschreibung über die Vertragsordnung und das Vergabeverfahren bis zum Umgang mit Änderungen im Bauablauf.',NULL,NULL,ARRAY['pbl1']::text[],'[]'::jsonb,NULL,638),
('pav2lb','p',2,'pav1','Leistungsbeschreibung und LV','Das Leistungsverzeichnis, kurz LV, gliedert ein Bauvorhaben in einzeln beschriebene, mengen und einheitspreisbezogene Positionen und ist damit die Grundlage jedes Angebotsvergleichs. Seine Qualität entscheidet, ob Angebote überhaupt vergleichbar sind oder ob jeder Bieter etwas anderes anbietet. Eine gute Leistungsbeschreibung ist so eindeutig, dass zwei Firmen unabhängig voneinander dasselbe kalkulieren.',NULL,NULL,'{}'::text[],'[]'::jsonb,'{"de":"Ausschreibungstexte stützen sich meist auf VOB/C mit standardisierten Leistungsbeschreibungstexten als Formulierungshilfe.","at":"Die standardisierte Leistungsbeschreibung nach ÖNORM A 2063 liefert vergleichbare Textbausteine für öffentliche und private Vergaben.","ch":"Das Baukostenplan und Positionssystem NPK strukturiert Leistungsverzeichnisse einheitlich nach Bauteilen und Arbeitsgattungen."}'::jsonb,639),
('pav3funk','p',3,'pav2lb','Funktional oder detailliert ausschreiben','Ein Leistungsverzeichnis kann jede Position einzeln vorgeben, detailliert, oder nur das gewünschte Ergebnis beschreiben und die Lösung dem Bieter überlassen, funktional. Detaillierte Ausschreibung schafft Vergleichbarkeit und Kostensicherheit, funktionale Ausschreibung nutzt das Know how der ausführenden Firmen, verlangt dafür aber eine sehr klare Beschreibung der Anforderungen statt der Lösung.',NULL,NULL,'{}'::text[],'[{"t":"VOB/A","stand":"Ausgabe 2016, Bekanntmachung 07.01.2016","u":"https://www.verwaltungsvorschriften-im-internet.de/bsvwvbund_07012016_BI78106361.htm","geprueft":"2026-08-19"}]'::jsonb,'{"de":"Neben der klassischen detaillierten Leistungsbeschreibung erlaubt die VOB/A auch das Leistungsprogramm als funktionale Variante, etwa bei Generalunternehmervergaben.","at":"Standardisierte Leistungsbeschreibungen nach ÖNORM A 2063 sind überwiegend detailliert aufgebaut, funktionale Ausschreibungen bleiben die Ausnahme.","ch":"Das NPK System ist grundsätzlich auf detaillierte Positionen ausgelegt, funktionale Leistungsbeschreibungen etablieren sich vor allem bei Totalunternehmermodellen."}'::jsonb,640),
('pav3pos','p',3,'pav2lb','Positionen, Mengen und Vordersätze','Jede LV Position besteht aus einem beschreibenden Text und einer Menge, dem sogenannten Vordersatz, gegen die der Bieter seinen Einheitspreis anbietet. Ungenaue oder falsch ermittelte Mengen sind eine der häufigsten Nachtragsquellen überhaupt, weil sich reale und ausgeschriebene Menge dann unterscheiden. Sorgfältige Mengenermittlung aus dem Plan ist deshalb keine Nebensache, sondern Kernarbeit der Ausschreibung.',NULL,NULL,'{}'::text[],'[]'::jsonb,'{"de":"Standardisierte Texte aus dem STLB Bau erleichtern die Formulierung, ersetzen aber nicht die projektbezogene Mengenermittlung.","at":"Das Standardleistungsverzeichnis liefert vorformulierte Positionen, die Mengenermittlung bleibt Aufgabe der Planung.","ch":"Der NPK gliedert Positionen nach Bauteilen und Arbeitsgattungen und schafft damit eine einheitliche Struktur für Mengenermittlung und Vergleich."}'::jsonb,641),
('pav3gaa','p',3,'pav2lb','Gewerkeaufteilung und Vergabeeinheiten','Bevor ausgeschrieben wird, ist zu entscheiden, wie das Projekt in Lose zerschnitten wird: viele Einzelgewerke mit direkter Steuerung durch die Bauleitung oder wenige große Pakete bis hin zum Generalunternehmer mit weniger Koordinationsaufwand, aber weniger Einfluss auf Details. Diese Entscheidung prägt Vergabeverfahren, Bauleitungsaufwand und Risikoverteilung für den Rest des Projekts.',NULL,NULL,'{}'::text[],'[{"t":"BVergG 2018 (Bundesvergabegesetz)","stand":"BGBl. I Nr. 100/2018, konsolidierte Fassung im RIS","u":"https://www.ris.bka.gv.at/GeltendeFassung.wxe?Abfrage=Bundesnormen&Gesetzesnummer=20010295","geprueft":"2026-08-19"},{"t":"BöB (Bundesgesetz über das öffentliche Beschaffungswesen)","stand":"SR 172.056.1, vom 21.06.2019, in Kraft 01.01.2021","u":"https://www.fedlex.admin.ch/eli/cc/2020/126/de","geprueft":"2026-08-19"}]'::jsonb,'{"de":"Öffentliche Auftraggeber sind über den Grundsatz der Fach und Teillosvergabe gehalten, mittelständische Betriebe durch kleinere Lose zu beteiligen.","at":"Das Bundesvergabegesetz verankert ebenfalls den Grundsatz der Losaufteilung zugunsten kleinerer und mittlerer Unternehmen.","ch":"Beschaffungsrecht auf Bund und Kantonsebene sieht eine Losaufteilung vor, wo dies wirtschaftlich und technisch sinnvoll ist."}'::jsonb,642),
('pav3lv30','p',3,'pav2lb','Sonderfall Brandschutztüren im LV','Zugelassene Bauteile wie Brandschutztüren dürfen im Leistungsverzeichnis nicht bis ins letzte Detail vorgeschrieben werden, weil die Ausführung an die jeweilige Zulassung des Herstellers gebunden ist. Ausgeschrieben wird deshalb die geforderte Leistungsklasse, nicht ein Konstruktionsdetail, sonst widerspricht die Ausschreibung am Ende der tatsächlich lieferbaren, zugelassenen Ware.',NULL,NULL,ARRAY['k3kombi','k4t30z']::text[],'[{"t":"OIB-Richtlinien","stand":"Ausgabe 2023, beschlossen 25.05.2023","u":"https://www.oib.or.at/kernaufgaben/oib-richtlinien1/richtlinien/oib-richtlinien-2023/","geprueft":"2026-08-19"}]'::jsonb,'{"de":"Ausgeschrieben wird die Feuerwiderstandsklasse mit Verweis auf die erforderliche bauaufsichtliche Zulassung, nicht ein konkretes Konstruktionsdetail des Herstellers.","at":"Die Leistungsbeschreibung nennt die geforderte Klassifizierung und die Kennzeichnungspflicht nach den einschlägigen OIB Vorgaben, die Ausführung bleibt der Zulassung des Produkts vorbehalten.","ch":"Ausgeschrieben wird die geforderte Feuerwiderstandsklasse mit Bezug auf die VKF Anerkennung des Produkts, die konkrete Konstruktion liegt in der Verantwortung des Herstellers."}'::jsonb,643),
('pav2vertrag','p',2,'pav1','Bauvertragsordnungen','Über dem allgemeinen Vertragsrecht liegt im Bauwesen meist eine spezielle Vertragsordnung, die Fristen, Zahlung, Mängel und Kündigung baupraxisnah regelt und damit Streit vorbeugen soll. Wird sie nicht ausdrücklich vereinbart, gilt allein das allgemeine Zivilrecht, das für die Besonderheiten einer Baustelle oft zu grob geschnitten ist. Welche Ordnung gilt, ist deshalb eine der ersten Fragen jedes Bauvertrags.',NULL,NULL,'{}'::text[],'[{"t":"VOB/B (DIN 1961)","stand":"Ausgabe 2016, Bekanntmachung 07.01.2016, ber. 01.04.2016","u":"https://www.verwaltungsvorschriften-im-internet.de/bsvwvbund_07012016_BI78106361.htm","geprueft":"2026-08-19"},{"t":"BGB, Bauvertragsrecht (§§ 650a ff.)","stand":"zuletzt geändert 23.07.2026","u":"https://www.gesetze-im-internet.de/bgb/","geprueft":"2026-08-19"},{"t":"ÖNORM B 2110 Allgemeine Vertragsbestimmungen","stand":"2023-05-01","u":"https://shop.austrian-standards.at/action/de/public/details/728205/OENORM_B_2110_2023_05_01","geprueft":"2026-08-19"},{"t":"SIA 118 Allgemeine Bedingungen für Bauarbeiten","stand":"Ausgabe 2013","u":"https://shop.sia.ch/normenwerk/ingenieur/118_2013_d/D/Product","geprueft":"2026-08-19"}]'::jsonb,'{"de":"Die VOB/B als vereinbartes Klauselwerk ergänzt das allgemeine Bauvertragsrecht des BGB um baupraktische Regelungen zu Fristen, Vergütung und Mängeln.","at":"Die ÖNORM B 2110 ist die verbreitete Vertragsgrundlage für Bauleistungen und regelt das Verhältnis zwischen Auftraggeber und Auftragnehmer detailliert.","ch":"Die SIA Norm 118 bildet die Allgemeinen Bedingungen für Bauarbeiten und wird durch ausdrückliche Vereinbarung Vertragsbestandteil."}'::jsonb,644),
('pav3preis','p',3,'pav2vertrag','Vergütungsarten im Vergleich','Der Einheitspreisvertrag rechnet nach tatsächlich ausgeführter Menge ab und verteilt das Mengenrisiko zwischen den Parteien, der Pauschalvertrag fixiert einen Festpreis für eine definierte Leistung und verlagert das Mengenrisiko zum Auftragnehmer, der Stundenlohnvertrag eignet sich für schwer kalkulierbare Kleinleistungen. Die Wahl der Vergütungsart ist eine Risikoentscheidung, keine reine Formsache.',NULL,NULL,'{}'::text[],'[{"t":"VOB/B (DIN 1961)","stand":"Ausgabe 2016, Bekanntmachung 07.01.2016, ber. 01.04.2016","u":"https://www.verwaltungsvorschriften-im-internet.de/bsvwvbund_07012016_BI78106361.htm","geprueft":"2026-08-19"},{"t":"ÖNORM B 2110 Allgemeine Vertragsbestimmungen","stand":"2023-05-01","u":"https://shop.austrian-standards.at/action/de/public/details/728205/OENORM_B_2110_2023_05_01","geprueft":"2026-08-19"},{"t":"SIA 118 Allgemeine Bedingungen für Bauarbeiten","stand":"Ausgabe 2013","u":"https://shop.sia.ch/normenwerk/ingenieur/118_2013_d/D/Product","geprueft":"2026-08-19"}]'::jsonb,'{"de":"Neben dem klassischen Einheitspreisvertrag kennt die VOB/B auch Pauschalvertrag und Stundenlohnarbeiten mit jeweils eigener Abrechnungslogik.","at":"Die ÖNORM B 2110 unterscheidet ebenfalls Einheitspreis und Pauschalvertrag und regelt die jeweiligen Anpassungsmechanismen bei Mengenabweichungen.","ch":"Die SIA 118 kennt Einheitspreis, Pauschalpreis und Globalpreis als Vergütungsarten mit unterschiedlicher Risikoverteilung."}'::jsonb,645);
insert into public.nodes (id,perspective,level,parent_id,title,t1,t2,t3,links,sources,dach,ord) values
('pav3frist','p',3,'pav2vertrag','Fristen, Verzug und Behinderung','Bauzeitpläne sind Vertragsbestandteil, ihre Überschreitung kann Verzug auslösen, aber auch der Auftragnehmer kann durch fehlende Mitwirkung des Auftraggebers behindert sein. Entscheidend ist, wer eine Behinderung wann und wie anzeigt, denn ohne rechtzeitige Anzeige verliert man oft den Anspruch auf Fristverlängerung. Diese Anzeigepflicht ist eine der meistübersehenen Formalien am Bau.',NULL,NULL,'{}'::text[],'[{"t":"VOB/B (DIN 1961)","stand":"Ausgabe 2016, Bekanntmachung 07.01.2016, ber. 01.04.2016","u":"https://www.verwaltungsvorschriften-im-internet.de/bsvwvbund_07012016_BI78106361.htm","geprueft":"2026-08-19"},{"t":"BGB, Bauvertragsrecht (§§ 650a ff.)","stand":"zuletzt geändert 23.07.2026","u":"https://www.gesetze-im-internet.de/bgb/","geprueft":"2026-08-19"},{"t":"ÖNORM B 2110 Allgemeine Vertragsbestimmungen","stand":"2023-05-01","u":"https://shop.austrian-standards.at/action/de/public/details/728205/OENORM_B_2110_2023_05_01","geprueft":"2026-08-19"},{"t":"SIA 118 Allgemeine Bedingungen für Bauarbeiten","stand":"Ausgabe 2013","u":"https://shop.sia.ch/normenwerk/ingenieur/118_2013_d/D/Product","geprueft":"2026-08-19"}]'::jsonb,'{"de":"Die VOB/B verlangt eine unverzügliche Behinderungsanzeige als Voraussetzung für spätere Fristverlängerung, das BGB regelt Verzug allgemeiner.","at":"Die ÖNORM B 2110 sieht eigene Regeln zur Anzeige von Behinderungen und zur Anpassung der Leistungsfrist vor.","ch":"Die SIA 118 verpflichtet den Unternehmer zur unverzüglichen Anzeige von Hindernissen, sonst drohen Ansprüche zu verfallen."}'::jsonb,646),
('pav3zahlung','p',3,'pav2vertrag','Zahlungsplan und Sicherheiten','Abschlagszahlungen nach Baufortschritt halten den Auftragnehmer liquide, ein Sicherheitseinbehalt oder eine Bürgschaft schützt den Auftraggeber vor Mängeln, die erst später sichtbar werden. Wie hoch der Einbehalt ausfällt und wodurch er abgelöst werden kann, gehört früh in den Vertrag, nicht erst in die Schlussrechnung.',NULL,NULL,'{}'::text[],'[{"t":"VOB/B (DIN 1961)","stand":"Ausgabe 2016, Bekanntmachung 07.01.2016, ber. 01.04.2016","u":"https://www.verwaltungsvorschriften-im-internet.de/bsvwvbund_07012016_BI78106361.htm","geprueft":"2026-08-19"},{"t":"ÖNORM B 2110 Allgemeine Vertragsbestimmungen","stand":"2023-05-01","u":"https://shop.austrian-standards.at/action/de/public/details/728205/OENORM_B_2110_2023_05_01","geprueft":"2026-08-19"},{"t":"SIA 118 Allgemeine Bedingungen für Bauarbeiten","stand":"Ausgabe 2013","u":"https://shop.sia.ch/normenwerk/ingenieur/118_2013_d/D/Product","geprueft":"2026-08-19"}]'::jsonb,'{"de":"Abschlagszahlungen nach Leistungsstand sind über die VOB/B üblich, ein Sicherheitseinbehalt lässt sich meist durch eine Gewährleistungsbürgschaft ablösen.","at":"Die ÖNORM B 2110 kennt Teilrechnungen und einen Deckungsrücklass, der ebenfalls durch eine Bankgarantie abgelöst werden kann.","ch":"Nach SIA 118 erfolgen Akontozahlungen nach Baufortschritt, Garantien sichern spätere Gewährleistungsansprüche."}'::jsonb,647),
('pav3kuend','p',3,'pav2vertrag','Kündigung und vorzeitige Vertragsbeendigung','Bauverträge lassen sich, anders als viele andere Verträge, oft auch ohne wichtigen Grund kündigen, dann aber gegen Vergütung der bereits erbrachten und teils auch der entgangenen Leistung. Daneben steht die Kündigung aus wichtigem Grund, etwa bei gravierenden Mängeln oder Zahlungsverzug. Beide Wege unterscheiden sich stark in ihren finanziellen Folgen.',NULL,NULL,'{}'::text[],'[{"t":"BGB, Bauvertragsrecht (§§ 650a ff.)","stand":"zuletzt geändert 23.07.2026","u":"https://www.gesetze-im-internet.de/bgb/","geprueft":"2026-08-19"},{"t":"VOB/B (DIN 1961)","stand":"Ausgabe 2016, Bekanntmachung 07.01.2016, ber. 01.04.2016","u":"https://www.verwaltungsvorschriften-im-internet.de/bsvwvbund_07012016_BI78106361.htm","geprueft":"2026-08-19"},{"t":"ÖNORM B 2110 Allgemeine Vertragsbestimmungen","stand":"2023-05-01","u":"https://shop.austrian-standards.at/action/de/public/details/728205/OENORM_B_2110_2023_05_01","geprueft":"2026-08-19"},{"t":"SIA 118 Allgemeine Bedingungen für Bauarbeiten","stand":"Ausgabe 2013","u":"https://shop.sia.ch/normenwerk/ingenieur/118_2013_d/D/Product","geprueft":"2026-08-19"}]'::jsonb,'{"de":"Das BGB erlaubt die freie Kündigung gegen Vergütung, die VOB/B ergänzt eigene Kündigungsgründe für besondere Bausituationen.","at":"Die ÖNORM B 2110 regelt die Auflösung des Vertrags aus wichtigem Grund und die Abrechnung bei vorzeitiger Beendigung eigenständig.","ch":"Die SIA 118 kennt den Rücktritt des Bauherrn und die Auflösung aus wichtigem Grund mit jeweils eigener Abrechnungsregel."}'::jsonb,648),
('pav2verg','p',2,'pav1','Öffentliche Vergabe','Öffentliche Auftraggeber dürfen Bauleistungen nicht frei nach Sympathie vergeben, sondern müssen ein geregeltes Verfahren durchlaufen, das Transparenz, Gleichbehandlung und Wirtschaftlichkeit sichert. Oberhalb bestimmter Auftragswerte greift zusätzlich europäisches Vergaberecht. Für Planende bedeutet das: Verfahren, Fristen und Dokumentation sind so verbindlich wie die Bauausführung selbst.',NULL,NULL,'{}'::text[],'[{"t":"VgV (Vergabeverordnung)","stand":"vom 12.04.2016, zuletzt geändert 12.05.2026","u":"https://www.gesetze-im-internet.de/vgv_2016/","geprueft":"2026-08-19"},{"t":"BVergG 2018 (Bundesvergabegesetz)","stand":"BGBl. I Nr. 100/2018, konsolidierte Fassung im RIS","u":"https://www.ris.bka.gv.at/GeltendeFassung.wxe?Abfrage=Bundesnormen&Gesetzesnummer=20010295","geprueft":"2026-08-19"},{"t":"BöB (Bundesgesetz über das öffentliche Beschaffungswesen)","stand":"SR 172.056.1, vom 21.06.2019, in Kraft 01.01.2021","u":"https://www.fedlex.admin.ch/eli/cc/2020/126/de","geprueft":"2026-08-19"}]'::jsonb,'{"de":"Oberhalb der EU Schwellenwerte gilt die Vergabeverordnung VgV, darunter die Unterschwellenvergabeordnung UVgO der Länder und Kommunen.","at":"Das Bundesvergabegesetz BVergG bildet den einheitlichen Rahmen für öffentliche Vergaben unabhängig vom Schwellenwert.","ch":"Das Beschaffungswesen des Bundes richtet sich nach dem BöB, Kantone und Gemeinden nach der interkantonalen Vereinbarung IVöB."}'::jsonb,649),
('pav3verfahren','p',3,'pav2verg','Vergabeverfahren im Überblick','Das offene Verfahren lädt unbeschränkt zur Angebotsabgabe ein, das nicht offene und das Verhandlungsverfahren schränken den Bieterkreis vorab ein oder erlauben Nachverhandlung. Welches Verfahren zulässig ist, hängt vom Auftragswert und von sachlichen Gründen ab, es ist keine freie Wahl des Auftraggebers.',NULL,NULL,'{}'::text[],'[{"t":"VgV (Vergabeverordnung)","stand":"vom 12.04.2016, zuletzt geändert 12.05.2026","u":"https://www.gesetze-im-internet.de/vgv_2016/","geprueft":"2026-08-19"},{"t":"BVergG 2018 (Bundesvergabegesetz)","stand":"BGBl. I Nr. 100/2018, konsolidierte Fassung im RIS","u":"https://www.ris.bka.gv.at/GeltendeFassung.wxe?Abfrage=Bundesnormen&Gesetzesnummer=20010295","geprueft":"2026-08-19"},{"t":"BöB (Bundesgesetz über das öffentliche Beschaffungswesen)","stand":"SR 172.056.1, vom 21.06.2019, in Kraft 01.01.2021","u":"https://www.fedlex.admin.ch/eli/cc/2020/126/de","geprueft":"2026-08-19"}]'::jsonb,'{"de":"VgV und UVgO unterscheiden offenes Verfahren, nicht offenes Verfahren, Verhandlungsverfahren und weitere Sonderformen mit jeweils eigenen Zulässigkeitsvoraussetzungen.","at":"Das BVergG kennt ebenfalls offenes, nicht offenes und Verhandlungsverfahren sowie die Direktvergabe für kleinere Aufträge.","ch":"BöB und IVöB unterscheiden offenes, selektives und Einladungsverfahren sowie den freihändigen Zuschlag für geringe Auftragswerte."}'::jsonb,650),
('pav3eign','p',3,'pav2verg','Eignung und Zuschlagskriterien','Vergabeverfahren trennen zwei Fragen strikt: Ist der Bieter überhaupt geeignet, fachkundig, leistungsfähig, zuverlässig, und welches der geeigneten Angebote bekommt den Zuschlag. Der Zuschlag muss nicht zwingend an das billigste Angebot gehen, sondern an das wirtschaftlichste, in das auch Qualität und Ausführungskonzept einfließen können.',NULL,NULL,'{}'::text[],'[{"t":"VgV (Vergabeverordnung)","stand":"vom 12.04.2016, zuletzt geändert 12.05.2026","u":"https://www.gesetze-im-internet.de/vgv_2016/","geprueft":"2026-08-19"},{"t":"BVergG 2018 (Bundesvergabegesetz)","stand":"BGBl. I Nr. 100/2018, konsolidierte Fassung im RIS","u":"https://www.ris.bka.gv.at/GeltendeFassung.wxe?Abfrage=Bundesnormen&Gesetzesnummer=20010295","geprueft":"2026-08-19"},{"t":"BöB (Bundesgesetz über das öffentliche Beschaffungswesen)","stand":"SR 172.056.1, vom 21.06.2019, in Kraft 01.01.2021","u":"https://www.fedlex.admin.ch/eli/cc/2020/126/de","geprueft":"2026-08-19"}]'::jsonb,'{"de":"Nach VgV wird zwischen Eignungsprüfung und Zuschlag nach dem wirtschaftlichsten Angebot unterschieden, das reine Preiskriterium ist die Ausnahme.","at":"Das BVergG trennt ebenso Eignung und Angebotsbewertung und lässt neben dem Preis weitere Zuschlagskriterien ausdrücklich zu.","ch":"BöB und IVöB verlangen eine Eignungsprüfung vor der Bewertung und öffnen die Zuschlagskriterien ausdrücklich für Qualität neben dem Preis."}'::jsonb,651),
('pav3schwell','p',3,'pav2verg','Schwellenwerte und Losgrenzen','Ob ein Auftrag europaweit oder nur national ausgeschrieben werden muss, entscheidet sein geschätzter Wert im Vergleich zu festgelegten Schwellenwerten. Wird ein Vorhaben künstlich in kleinere Lose zerlegt, um darunter zu bleiben, ist das unzulässig und als Umgehung angreifbar.',NULL,NULL,'{}'::text[],'[{"t":"VgV (Vergabeverordnung)","stand":"vom 12.04.2016, zuletzt geändert 12.05.2026","u":"https://www.gesetze-im-internet.de/vgv_2016/","geprueft":"2026-08-19"},{"t":"BVergG 2018 (Bundesvergabegesetz)","stand":"BGBl. I Nr. 100/2018, konsolidierte Fassung im RIS","u":"https://www.ris.bka.gv.at/GeltendeFassung.wxe?Abfrage=Bundesnormen&Gesetzesnummer=20010295","geprueft":"2026-08-19"},{"t":"BöB (Bundesgesetz über das öffentliche Beschaffungswesen)","stand":"SR 172.056.1, vom 21.06.2019, in Kraft 01.01.2021","u":"https://www.fedlex.admin.ch/eli/cc/2020/126/de","geprueft":"2026-08-19"}]'::jsonb,'{"de":"Oberhalb der EU Schwellenwerte greift die VgV, unterhalb regeln Länder und Kommunen die Vergabe meist über die UVgO.","at":"Das BVergG differenziert zwischen Ober und Unterschwellenbereich mit jeweils eigenen Verfahrensanforderungen.","ch":"BöB und IVöB legen eigene Schwellenwerte fest, ab denen das offene oder selektive Verfahren zwingend wird."}'::jsonb,652),
('pav3nachpr','p',3,'pav2verg','Nachprüfung und Vergaberechtsschutz','Fühlt sich ein Bieter benachteiligt, kann er das Verfahren rügen und notfalls von einer Nachprüfungsinstanz überprüfen lassen. Wer zu spät rügt, verliert dieses Recht meist unabhängig davon, ob die Rüge inhaltlich berechtigt gewesen wäre. Für Auftraggeber heißt das: sauber dokumentieren, von der ersten Bekanntmachung an.',NULL,NULL,'{}'::text[],'[{"t":"BVergG 2018 (Bundesvergabegesetz)","stand":"BGBl. I Nr. 100/2018, konsolidierte Fassung im RIS","u":"https://www.ris.bka.gv.at/GeltendeFassung.wxe?Abfrage=Bundesnormen&Gesetzesnummer=20010295","geprueft":"2026-08-19"}]'::jsonb,'{"de":"Vergabekammern prüfen auf Antrag die Rechtmäßigkeit eines Verfahrens, eine unverzügliche Rüge ist meist Voraussetzung dafür.","at":"Das Bundesverwaltungsgericht entscheidet über Nachprüfungsanträge im Vergaberecht, auch hier gilt eine Rügeobliegenheit.","ch":"Beschwerdeinstanzen von Bund und Kantonen prüfen Vergabeentscheide auf Antrag innerhalb kurzer Fristen."}'::jsonb,653),
('pav2nachtrag','p',2,'pav1','Nachtragsmanagement','Kaum ein Bauvertrag kommt ohne Nachträge aus, weil sich Planung, Bestand und Bauablauf während der Ausführung fast immer verändern. Entscheidend ist nicht, Nachträge zu verhindern, sondern sie sauber zu erkennen, zu prüfen und zeitnah zu vereinbaren, bevor sie sich zu einem unübersichtlichen Streitpaket auftürmen. Gute Nachtragskultur beginnt mit einer präzisen Ursprungsausschreibung.',NULL,NULL,'{}'::text[],'[{"t":"VOB/B (DIN 1961)","stand":"Ausgabe 2016, Bekanntmachung 07.01.2016, ber. 01.04.2016","u":"https://www.verwaltungsvorschriften-im-internet.de/bsvwvbund_07012016_BI78106361.htm","geprueft":"2026-08-19"},{"t":"BGB, Bauvertragsrecht (§§ 650a ff.)","stand":"zuletzt geändert 23.07.2026","u":"https://www.gesetze-im-internet.de/bgb/","geprueft":"2026-08-19"},{"t":"ÖNORM B 2110 Allgemeine Vertragsbestimmungen","stand":"2023-05-01","u":"https://shop.austrian-standards.at/action/de/public/details/728205/OENORM_B_2110_2023_05_01","geprueft":"2026-08-19"},{"t":"SIA 118 Allgemeine Bedingungen für Bauarbeiten","stand":"Ausgabe 2013","u":"https://shop.sia.ch/normenwerk/ingenieur/118_2013_d/D/Product","geprueft":"2026-08-19"}]'::jsonb,'{"de":"Anspruchsgrundlage für Nachträge sind meist geänderte oder zusätzliche Leistungen im Sinn der VOB/B beziehungsweise die Regeln des BGB Bauvertragsrechts.","at":"Die ÖNORM B 2110 regelt Mehr und Minderleistungen sowie deren Preisermittlung als eigenständiges Kapitel des Vertrags.","ch":"Die SIA 118 enthält eigene Bestimmungen zu Zusatzleistungen und deren Vergütung, die von den ursprünglich vereinbarten Preisen ausgehen."}'::jsonb,654),
('pav3ursache','p',3,'pav2nachtrag','Typische Nachtragsursachen','Die häufigsten Auslöser sind Planänderungen während der Ausführung, Abweichungen zwischen Bestand und Planungsannahme sowie ein gestörter, verzögerter Bauablauf mit Folgekosten für alle Beteiligten. Wer diese drei Ursachen kennt, erkennt Nachtragspotenzial schon in der Ausschreibung, nicht erst auf der Rechnung.',NULL,NULL,'{}'::text[],'[{"t":"VOB/B (DIN 1961)","stand":"Ausgabe 2016, Bekanntmachung 07.01.2016, ber. 01.04.2016","u":"https://www.verwaltungsvorschriften-im-internet.de/bsvwvbund_07012016_BI78106361.htm","geprueft":"2026-08-19"},{"t":"ÖNORM B 2110 Allgemeine Vertragsbestimmungen","stand":"2023-05-01","u":"https://shop.austrian-standards.at/action/de/public/details/728205/OENORM_B_2110_2023_05_01","geprueft":"2026-08-19"},{"t":"SIA 118 Allgemeine Bedingungen für Bauarbeiten","stand":"Ausgabe 2013","u":"https://shop.sia.ch/normenwerk/ingenieur/118_2013_d/D/Product","geprueft":"2026-08-19"}]'::jsonb,'{"de":"Rechtlich wird meist zwischen geänderten Leistungen, zusätzlichen Leistungen und Folgen gestörten Bauablaufs unterschieden, mit jeweils eigener Anspruchsgrundlage nach VOB/B.","at":"Die ÖNORM B 2110 unterscheidet Mehrleistungen, geänderte Leistungen und Behinderungsfolgen mit eigenen Regeln zur Anspruchsermittlung.","ch":"Die SIA 118 differenziert Zusatzleistungen von Folgen gestörten Bauablaufs, beides mit eigener Nachweispflicht des Unternehmers."}'::jsonb,655),
('pav3anspr','p',3,'pav2nachtrag','Anspruch dem Grunde und der Höhe nach','Ein Nachtrag wird in zwei Schritten geprüft: Besteht überhaupt ein Anspruch, dem Grunde nach, und wenn ja, in welcher Höhe. Wer beide Fragen vermischt, verhandelt am Ende über Zahlen, obwohl der Grund noch strittig ist. Saubere Nachtragsprüfung trennt diese Schritte konsequent.',NULL,NULL,'{}'::text[],'[{"t":"VOB/B (DIN 1961)","stand":"Ausgabe 2016, Bekanntmachung 07.01.2016, ber. 01.04.2016","u":"https://www.verwaltungsvorschriften-im-internet.de/bsvwvbund_07012016_BI78106361.htm","geprueft":"2026-08-19"},{"t":"ÖNORM B 2110 Allgemeine Vertragsbestimmungen","stand":"2023-05-01","u":"https://shop.austrian-standards.at/action/de/public/details/728205/OENORM_B_2110_2023_05_01","geprueft":"2026-08-19"},{"t":"SIA 118 Allgemeine Bedingungen für Bauarbeiten","stand":"Ausgabe 2013","u":"https://shop.sia.ch/normenwerk/ingenieur/118_2013_d/D/Product","geprueft":"2026-08-19"}]'::jsonb,'{"de":"Die Prüfung folgt der VOB/B Systematik aus Anspruchsgrund und Preisermittlung, oft anhand der Urkalkulation des Auftragnehmers.","at":"Nach ÖNORM B 2110 ist zunächst die vertragliche Grundlage des Mehranspruchs zu klären, erst danach die Preisfindung.","ch":"Die SIA 118 verlangt ebenfalls den Nachweis der Berechtigung, bevor über die Höhe der Vergütung verhandelt wird."}'::jsonb,656),
('pav3preisfort','p',3,'pav2nachtrag','Preisfortschreibung bei Änderungen','Für geänderte Leistungen wird kein neuer Preis frei erfunden, sondern aus der ursprünglichen Kalkulation des Auftragnehmers fortgeschrieben, damit das ursprüngliche Preisniveau erhalten bleibt. Genau deshalb ist die Urkalkulation, so lästig ihre frühzeitige Anforderung erscheint, im Streitfall Gold wert.',NULL,NULL,'{}'::text[],'[{"t":"VOB/B (DIN 1961)","stand":"Ausgabe 2016, Bekanntmachung 07.01.2016, ber. 01.04.2016","u":"https://www.verwaltungsvorschriften-im-internet.de/bsvwvbund_07012016_BI78106361.htm","geprueft":"2026-08-19"},{"t":"ÖNORM B 2110 Allgemeine Vertragsbestimmungen","stand":"2023-05-01","u":"https://shop.austrian-standards.at/action/de/public/details/728205/OENORM_B_2110_2023_05_01","geprueft":"2026-08-19"},{"t":"SIA 118 Allgemeine Bedingungen für Bauarbeiten","stand":"Ausgabe 2013","u":"https://shop.sia.ch/normenwerk/ingenieur/118_2013_d/D/Product","geprueft":"2026-08-19"}]'::jsonb,'{"de":"Die VOB/B verlangt die Fortschreibung der Preise aus der Urkalkulation, um das ursprünglich vereinbarte Preisniveau fortzuführen.","at":"Die ÖNORM B 2110 stützt die Preisfindung bei Mehrleistungen auf die vereinbarten Einheitspreise und deren Kalkulationsgrundlagen.","ch":"Nach SIA 118 werden Nachtragspreise grundsätzlich aus den vertraglich vereinbarten Ansätzen abgeleitet."}'::jsonb,657),
('pav3streit','p',3,'pav2nachtrag','Umgang mit strittigen Nachträgen','Nicht jeder Nachtrag lässt sich einvernehmlich klären, gerade wenn der Anspruch dem Grunde nach umstritten ist. Wichtig ist, weiterzubauen und parallel sauber zu dokumentieren, statt die Baustelle wegen eines einzelnen Nachtrags stillstehen zu lassen. Eskalation in klar gestuften Schritten schützt Termine und Beziehung gleichermaßen.',NULL,NULL,'{}'::text[],'[{"t":"ÖNORM B 2110 Allgemeine Vertragsbestimmungen","stand":"2023-05-01","u":"https://shop.austrian-standards.at/action/de/public/details/728205/OENORM_B_2110_2023_05_01","geprueft":"2026-08-19"},{"t":"SIA 118 Allgemeine Bedingungen für Bauarbeiten","stand":"Ausgabe 2013","u":"https://shop.sia.ch/normenwerk/ingenieur/118_2013_d/D/Product","geprueft":"2026-08-19"}]'::jsonb,'{"de":"Bleibt eine Einigung aus, folgt meist der Weg über Schiedsgutachten oder ordentliche Gerichte, eine förmliche Schlichtungsstelle fehlt im Regelfall.","at":"Die ÖNORM B 2110 sieht eine eigene Schlichtungsstelle als vorgeschaltete Instanz vor der Klage vor.","ch":"Die SIA 118 empfiehlt Schlichtungsverfahren, bevor ein Streit vor ein staatliches Gericht oder Schiedsgericht gebracht wird."}'::jsonb,658),
('pbl1','p',1,NULL,'Bauleitung und Qualität','Mit Baubeginn wechselt die Aufgabe von der Ausschreibung zur Aufsicht: Bauleitung heißt, Termine, Kosten und Ausführungsqualität parallel zu steuern und am Ende eine Leistung förmlich abzunehmen. Von dieser Abnahme hängen Gewährleistung und Verjährung ab, weshalb sie einer der folgenreichsten Momente im ganzen Projekt ist. Dieser Ast begleitet Überwachung, Abnahme, Gewährleistung und Mängelmanagement als zusammenhängende Kette.',NULL,NULL,ARRAY['pav1']::text[],'[]'::jsonb,NULL,659),
('pbl2bau','p',2,'pbl1','Bauüberwachung und Dokumentation','Bauüberwachung heißt, die Ausführung fortlaufend mit Plan und Vertrag abzugleichen, Fehler früh zu erkennen statt sie nach Fertigstellung aufzudecken. Ohne durchgehende Dokumentation, Bautagebuch, Protokolle, Fotos, ist im Streitfall kaum zu beweisen, was wann auf der Baustelle tatsächlich geschah. Wer schlecht dokumentiert, verliert im Zweifel auch dann, wenn er inhaltlich recht hatte.',NULL,NULL,'{}'::text[],'[{"t":"VOB/B (DIN 1961)","stand":"Ausgabe 2016, Bekanntmachung 07.01.2016, ber. 01.04.2016","u":"https://www.verwaltungsvorschriften-im-internet.de/bsvwvbund_07012016_BI78106361.htm","geprueft":"2026-08-19"},{"t":"ÖNORM B 2110 Allgemeine Vertragsbestimmungen","stand":"2023-05-01","u":"https://shop.austrian-standards.at/action/de/public/details/728205/OENORM_B_2110_2023_05_01","geprueft":"2026-08-19"},{"t":"SIA 118 Allgemeine Bedingungen für Bauarbeiten","stand":"Ausgabe 2013","u":"https://shop.sia.ch/normenwerk/ingenieur/118_2013_d/D/Product","geprueft":"2026-08-19"}]'::jsonb,'{"de":"Die Objektüberwachung entspricht der Leistungsphase 8, ihr Umfang wird über das Honorarrecht der Planenden mitgeprägt, die Anordnungsbefugnis regelt die VOB/B.","at":"Die örtliche Bauaufsicht ist Ländersache und wird durch Landesbauordnungen sowie durch die ÖNORM B 2110 im Vertragsverhältnis konkretisiert.","ch":"Die Bauleitung zählt zu den Grundleistungen nach SIA Ordnung, ihre vertraglichen Befugnisse regelt die SIA 118."}'::jsonb,660);
insert into public.nodes (id,perspective,level,parent_id,title,t1,t2,t3,links,sources,dach,ord) values
('pbl3tageb','p',3,'pbl2bau','Bautagebuch und Baustellendokumentation','Das Bautagebuch hält Wetter, Personal, Geräte, besondere Vorkommnisse und Baufortschritt tagesgenau fest und wird oft erst Monate später wichtig, wenn ein Nachtrag oder ein Bauzeitstreit belegt werden muss. Konsequent geführt ist es das billigste Beweismittel, das eine Baustelle hat.',NULL,NULL,'{}'::text[],'[{"t":"VOB/B (DIN 1961)","stand":"Ausgabe 2016, Bekanntmachung 07.01.2016, ber. 01.04.2016","u":"https://www.verwaltungsvorschriften-im-internet.de/bsvwvbund_07012016_BI78106361.htm","geprueft":"2026-08-19"},{"t":"ÖNORM B 2110 Allgemeine Vertragsbestimmungen","stand":"2023-05-01","u":"https://shop.austrian-standards.at/action/de/public/details/728205/OENORM_B_2110_2023_05_01","geprueft":"2026-08-19"},{"t":"SIA 118 Allgemeine Bedingungen für Bauarbeiten","stand":"Ausgabe 2013","u":"https://shop.sia.ch/normenwerk/ingenieur/118_2013_d/D/Product","geprueft":"2026-08-19"}]'::jsonb,'{"de":"Eine Formvorschrift für das Bautagebuch gibt es nicht, in der Praxis hat es sich als Beweismittel im Rahmen der VOB/B Abwicklung fest etabliert.","at":"Bautagebücher werden häufig nach standardisierten Formularen geführt, die sich an der ÖNORM B 2110 orientieren.","ch":"Nach SIA 118 gehört die Führung eines Bauprotokolls zu den üblichen Pflichten der Bauleitung."}'::jsonb,661),
('pbl3besprech','p',3,'pbl2bau','Baubesprechung und Protokollführung','Regelmäßige Baubesprechungen sind der Ort, an dem Entscheidungen fallen, oft mündlich und unter Zeitdruck. Erst das Protokoll macht diese Entscheidungen belastbar, deshalb sollte es zeitnah verteilt werden und ein Widerspruchsrecht mit klarer Frist enthalten, sonst gilt am Ende, was zuletzt unwidersprochen im Protokoll stand.',NULL,NULL,'{}'::text[],'[{"t":"VOB/B (DIN 1961)","stand":"Ausgabe 2016, Bekanntmachung 07.01.2016, ber. 01.04.2016","u":"https://www.verwaltungsvorschriften-im-internet.de/bsvwvbund_07012016_BI78106361.htm","geprueft":"2026-08-19"},{"t":"ÖNORM B 2110 Allgemeine Vertragsbestimmungen","stand":"2023-05-01","u":"https://shop.austrian-standards.at/action/de/public/details/728205/OENORM_B_2110_2023_05_01","geprueft":"2026-08-19"},{"t":"SIA 118 Allgemeine Bedingungen für Bauarbeiten","stand":"Ausgabe 2013","u":"https://shop.sia.ch/normenwerk/ingenieur/118_2013_d/D/Product","geprueft":"2026-08-19"}]'::jsonb,'{"de":"Eine gesetzliche Pflicht zur Protokollierung besteht nicht, üblich ist eine Widerspruchsfrist, die sich an der VOB/B Praxis orientiert.","at":"Die ÖNORM B 2110 sieht ausdrücklich vor, wie Besprechungsprotokolle zu behandeln sind und wann ihnen widersprochen werden kann.","ch":"Nach SIA 118 gilt ein Bauprotokoll als Vertragsdokument, sobald es unwidersprochen bleibt."}'::jsonb,662),
('pbl3anordnung','p',3,'pbl2bau','Anordnungsrecht und Bedenkenanzeige','Die Bauleitung darf Anordnungen zur Ausführung treffen, die ausführende Firma muss diesen grundsätzlich folgen, darf und muss aber Bedenken anmelden, wenn sie Fehler in Plan oder Vorleistung erkennt. Diese Bedenkenanzeige schützt beide Seiten: die Firma vor Haftung, die Bauleitung vor einem übersehenen Fehler.',NULL,NULL,'{}'::text[],'[{"t":"VOB/B (DIN 1961)","stand":"Ausgabe 2016, Bekanntmachung 07.01.2016, ber. 01.04.2016","u":"https://www.verwaltungsvorschriften-im-internet.de/bsvwvbund_07012016_BI78106361.htm","geprueft":"2026-08-19"},{"t":"ÖNORM B 2110 Allgemeine Vertragsbestimmungen","stand":"2023-05-01","u":"https://shop.austrian-standards.at/action/de/public/details/728205/OENORM_B_2110_2023_05_01","geprueft":"2026-08-19"},{"t":"SIA 118 Allgemeine Bedingungen für Bauarbeiten","stand":"Ausgabe 2013","u":"https://shop.sia.ch/normenwerk/ingenieur/118_2013_d/D/Product","geprueft":"2026-08-19"}]'::jsonb,'{"de":"Die VOB/B gibt dem Auftraggeber ein Anordnungsrecht und verpflichtet den Auftragnehmer im Gegenzug zur unverzüglichen Bedenkenanzeige.","at":"Die ÖNORM B 2110 kennt vergleichbare Anzeigepflichten des Auftragnehmers bei erkannten Mängeln der Vorgaben.","ch":"Die SIA 118 verpflichtet den Unternehmer zur Anzeige erkannter Mängel an Plänen oder Vorleistungen, bevor er weiterbaut."}'::jsonb,663),
('pbl3qualsich','p',3,'pbl2bau','Bemusterung und Prüfpläne','Bemusterung legt vorab fest, wie eine Ausführung konkret aussehen und sich anfühlen soll, Prüfpläne legen fest, was während der Ausführung wann kontrolliert wird. Beides verhindert, dass Qualität erst am fertigen Bauteil diskutiert wird, wenn eine Korrektur schon teuer ist. Besonders bei sicherheitsrelevanten oder zugelassenen Bauteilen gehört die Kontrolle auf der Baustelle selbst dazu, nicht nur die Abnahme am Ende.',NULL,NULL,ARRAY['k4t30z','kt3nutz']::text[],'[{"t":"ÖNORM B 2110 Allgemeine Vertragsbestimmungen","stand":"2023-05-01","u":"https://shop.austrian-standards.at/action/de/public/details/728205/OENORM_B_2110_2023_05_01","geprueft":"2026-08-19"},{"t":"SIA 118 Allgemeine Bedingungen für Bauarbeiten","stand":"Ausgabe 2013","u":"https://shop.sia.ch/normenwerk/ingenieur/118_2013_d/D/Product","geprueft":"2026-08-19"}]'::jsonb,'{"de":"Für zugelassene Bauteile gehört die Kontrolle des Kennzeichnungsschilds zur laufenden Bauüberwachung, unabhängig von der allgemeinen VOB/B Abwicklung.","at":"Bemusterungen werden häufig im Bauzeitplan verankert und über die ÖNORM B 2110 vertraglich eingefordert.","ch":"Prüfpläne und Bemusterungen sind übliche Instrumente der Bauleitung nach SIA 118, ihre Ergebnisse werden protokolliert."}'::jsonb,664),
('pbl2abnahme','p',2,'pbl1','Abnahme und ihre Rechtsfolgen','Die Abnahme ist der Moment, in dem der Auftraggeber die Leistung als im Wesentlichen vertragsgemäß anerkennt, und sie ist ein Wendepunkt mit weitreichenden Folgen: Gefahr und Beweislast wechseln, die Vergütung wird fällig, die Gewährleistungsfrist beginnt zu laufen. Wer eine mangelhafte Leistung ohne Vorbehalt abnimmt, verschlechtert seine eigene Position erheblich.',NULL,NULL,ARRAY['pav2vertrag']::text[],'[{"t":"BGB, Bauvertragsrecht (§§ 650a ff.)","stand":"zuletzt geändert 23.07.2026","u":"https://www.gesetze-im-internet.de/bgb/","geprueft":"2026-08-19"},{"t":"VOB/B (DIN 1961)","stand":"Ausgabe 2016, Bekanntmachung 07.01.2016, ber. 01.04.2016","u":"https://www.verwaltungsvorschriften-im-internet.de/bsvwvbund_07012016_BI78106361.htm","geprueft":"2026-08-19"},{"t":"ÖNORM B 2110 Allgemeine Vertragsbestimmungen","stand":"2023-05-01","u":"https://shop.austrian-standards.at/action/de/public/details/728205/OENORM_B_2110_2023_05_01","geprueft":"2026-08-19"},{"t":"SIA 118 Allgemeine Bedingungen für Bauarbeiten","stand":"Ausgabe 2013","u":"https://shop.sia.ch/normenwerk/ingenieur/118_2013_d/D/Product","geprueft":"2026-08-19"}]'::jsonb,'{"de":"Die Abnahme regeln BGB und VOB/B, sie kann förmlich, durch schlüssiges Verhalten oder unter bestimmten Voraussetzungen auch fiktiv erfolgen.","at":"Der vergleichbare Vorgang heißt Übernahme und wird nach ÖNORM B 2110 förmlich mit Protokoll durchgeführt.","ch":"Die SIA 118 kennt die förmliche Abnahme sowie die Vermutung der Abnahme bei vorbehaltloser Ingebrauchnahme des Werks."}'::jsonb,665),
('pbl3form','p',3,'pbl2abnahme','Abnahmeformen: förmlich, konkludent, fiktiv','Neben der klassischen, mit Termin und Protokoll durchgeführten Abnahme gibt es die stillschweigende Abnahme durch schlüssiges Verhalten, etwa Nutzung ohne Beanstandung, und in manchen Konstellationen sogar eine fiktive Abnahme allein durch Zeitablauf. Wer eine förmliche Abnahme will, sollte das im Vertrag ausdrücklich vereinbaren, statt es dem Zufall zu überlassen.',NULL,NULL,'{}'::text[],'[{"t":"VOB/B (DIN 1961)","stand":"Ausgabe 2016, Bekanntmachung 07.01.2016, ber. 01.04.2016","u":"https://www.verwaltungsvorschriften-im-internet.de/bsvwvbund_07012016_BI78106361.htm","geprueft":"2026-08-19"},{"t":"BGB, Bauvertragsrecht (§§ 650a ff.)","stand":"zuletzt geändert 23.07.2026","u":"https://www.gesetze-im-internet.de/bgb/","geprueft":"2026-08-19"},{"t":"ÖNORM B 2110 Allgemeine Vertragsbestimmungen","stand":"2023-05-01","u":"https://shop.austrian-standards.at/action/de/public/details/728205/OENORM_B_2110_2023_05_01","geprueft":"2026-08-19"},{"t":"SIA 118 Allgemeine Bedingungen für Bauarbeiten","stand":"Ausgabe 2013","u":"https://shop.sia.ch/normenwerk/ingenieur/118_2013_d/D/Product","geprueft":"2026-08-19"}]'::jsonb,'{"de":"Neben der förmlichen Abnahme nach VOB/B kennt das BGB die stillschweigende und unter Voraussetzungen die fiktive Abnahme.","at":"Die ÖNORM B 2110 sieht primär die förmliche Übernahme mit Protokoll vor, daneben ist auch eine Zwischenfeststellung möglich.","ch":"Nach SIA 118 gilt eine förmliche Abnahme als Regelfall, die widerspruchslose Ingebrauchnahme kann als Abnahme gewertet werden."}'::jsonb,666),
('pbl3vorbehalt','p',3,'pbl2abnahme','Mängelvorbehalt bei der Abnahme','Ein bei der Abnahme bereits bekannter Mangel muss ausdrücklich vorbehalten werden, sonst drohen dafür später Ansprüche zu entfallen oder sich zumindest deutlich zu verschlechtern. Deshalb gehört zu jeder Abnahmebegehung eine sorgfältige, schriftliche Mängelliste, nicht nur ein Kopfnicken vor Ort.',NULL,NULL,'{}'::text[],'[{"t":"VOB/B (DIN 1961)","stand":"Ausgabe 2016, Bekanntmachung 07.01.2016, ber. 01.04.2016","u":"https://www.verwaltungsvorschriften-im-internet.de/bsvwvbund_07012016_BI78106361.htm","geprueft":"2026-08-19"},{"t":"ÖNORM B 2110 Allgemeine Vertragsbestimmungen","stand":"2023-05-01","u":"https://shop.austrian-standards.at/action/de/public/details/728205/OENORM_B_2110_2023_05_01","geprueft":"2026-08-19"},{"t":"SIA 118 Allgemeine Bedingungen für Bauarbeiten","stand":"Ausgabe 2013","u":"https://shop.sia.ch/normenwerk/ingenieur/118_2013_d/D/Product","geprueft":"2026-08-19"}]'::jsonb,'{"de":"Nimmt der Auftraggeber einen bekannten Mangel ohne Vorbehalt ab, gefährdet das nach VOB/B Systematik spätere Ansprüche wegen genau dieses Mangels.","at":"Die ÖNORM B 2110 verlangt die Aufnahme bekannter Mängel in das Übernahmeprotokoll, sonst drohen Rechtsnachteile.","ch":"Nach SIA 118 sind erkennbare Mängel bei der Abnahme zu rügen, ansonsten gelten sie als genehmigt."}'::jsonb,667),
('pbl3rechtsfolgen','p',3,'pbl2abnahme','Rechtsfolgen der Abnahme','Mit der Abnahme kippt die Beweislast: Vorher muss der Auftragnehmer die Mangelfreiheit beweisen, danach der Auftraggeber den Mangel. Gleichzeitig geht die Gefahr des zufälligen Untergangs über, die Vergütung wird fällig und die Verjährung von Mängelansprüchen beginnt zu laufen. Diese vier Folgen zusammen machen die Abnahme zum wichtigsten Stichtag eines Bauvertrags.',NULL,NULL,'{}'::text[],'[{"t":"VOB/B (DIN 1961)","stand":"Ausgabe 2016, Bekanntmachung 07.01.2016, ber. 01.04.2016","u":"https://www.verwaltungsvorschriften-im-internet.de/bsvwvbund_07012016_BI78106361.htm","geprueft":"2026-08-19"},{"t":"BGB, Bauvertragsrecht (§§ 650a ff.)","stand":"zuletzt geändert 23.07.2026","u":"https://www.gesetze-im-internet.de/bgb/","geprueft":"2026-08-19"},{"t":"ÖNORM B 2110 Allgemeine Vertragsbestimmungen","stand":"2023-05-01","u":"https://shop.austrian-standards.at/action/de/public/details/728205/OENORM_B_2110_2023_05_01","geprueft":"2026-08-19"},{"t":"SIA 118 Allgemeine Bedingungen für Bauarbeiten","stand":"Ausgabe 2013","u":"https://shop.sia.ch/normenwerk/ingenieur/118_2013_d/D/Product","geprueft":"2026-08-19"}]'::jsonb,'{"de":"Gefahrübergang, Beweislastumkehr und Fälligkeit der Vergütung treten nach VOB/B und BGB gleichermaßen mit der Abnahme ein.","at":"Nach ÖNORM B 2110 setzt die Übernahme vergleichbare Wirkungen in Gang, insbesondere den Beginn der Gewährleistungsfrist.","ch":"Die SIA 118 knüpft an die Abnahme ebenfalls Gefahrübergang und den Beginn der Garantiefrist."}'::jsonb,668),
('pbl3teilabnahme','p',3,'pbl2abnahme','Teilabnahme und Zwischenabnahmen','Bei langen oder in Bauabschnitte gegliederten Projekten lässt sich die Abnahme aufteilen, sodass fertige Teile schon vor Gesamtfertigstellung förmlich abgenommen werden. Das setzt für diese Teile bereits Fristen und Rechtsfolgen in Gang und kann sinnvoll sein, wenn ein Bauabschnitt genutzt werden soll, während andere noch laufen.',NULL,NULL,'{}'::text[],'[{"t":"VOB/B (DIN 1961)","stand":"Ausgabe 2016, Bekanntmachung 07.01.2016, ber. 01.04.2016","u":"https://www.verwaltungsvorschriften-im-internet.de/bsvwvbund_07012016_BI78106361.htm","geprueft":"2026-08-19"},{"t":"ÖNORM B 2110 Allgemeine Vertragsbestimmungen","stand":"2023-05-01","u":"https://shop.austrian-standards.at/action/de/public/details/728205/OENORM_B_2110_2023_05_01","geprueft":"2026-08-19"},{"t":"SIA 118 Allgemeine Bedingungen für Bauarbeiten","stand":"Ausgabe 2013","u":"https://shop.sia.ch/normenwerk/ingenieur/118_2013_d/D/Product","geprueft":"2026-08-19"}]'::jsonb,'{"de":"Teilabnahmen sind über die VOB/B möglich, sofern in sich abgeschlossene Teile der Leistung vorliegen und dies vereinbart wurde.","at":"Die ÖNORM B 2110 erlaubt Teilübernahmen für abgrenzbare Leistungsteile mit eigenen Rechtsfolgen.","ch":"Nach SIA 118 können Teile eines Werks vorzeitig abgenommen werden, wenn sie selbständig nutzbar sind."}'::jsonb,669),
('pbl2gewaehr','p',2,'pbl1','Gewährleistung und Verjährungsfristen','Nach der Abnahme beginnt die Zeit, in der der Auftragnehmer für Mängel einzustehen hat, doch Dauer, Beginn und Systematik dieser Frist unterscheiden sich zwischen den drei Ländern spürbar. Wer grenzüberschreitend oder länderübergreifend berät, darf hier keine Systematik unbesehen übertragen. Diese Frist zu kennen gehört zur Grundausstattung jeder Projektsteuerung.',NULL,NULL,'{}'::text[],'[{"t":"BGB, Bauvertragsrecht (§§ 650a ff.)","stand":"zuletzt geändert 23.07.2026","u":"https://www.gesetze-im-internet.de/bgb/","geprueft":"2026-08-19"},{"t":"VOB/B (DIN 1961)","stand":"Ausgabe 2016, Bekanntmachung 07.01.2016, ber. 01.04.2016","u":"https://www.verwaltungsvorschriften-im-internet.de/bsvwvbund_07012016_BI78106361.htm","geprueft":"2026-08-19"},{"t":"ÖNORM B 2110 Allgemeine Vertragsbestimmungen","stand":"2023-05-01","u":"https://shop.austrian-standards.at/action/de/public/details/728205/OENORM_B_2110_2023_05_01","geprueft":"2026-08-19"},{"t":"Obligationenrecht (SR 220), Werkvertragsrecht","stand":"SR 220; Teilrevision Baumängel 2025","u":"https://www.fedlex.admin.ch/eli/cc/27/317_321_377/de","geprueft":"2026-08-19"},{"t":"SIA 118 Allgemeine Bedingungen für Bauarbeiten","stand":"Ausgabe 2013","u":"https://shop.sia.ch/normenwerk/ingenieur/118_2013_d/D/Product","geprueft":"2026-08-19"}]'::jsonb,'{"de":"Die Gewährleistung folgt dem BGB Werkvertragsrecht beziehungsweise der VOB/B, mit eigener Systematik für bewegliche und feste Bauteile.","at":"Das österreichische Recht trennt Gewährleistung wegen Sachmängeln und Schadenersatz als zwei eigenständige Anspruchssysteme, die ÖNORM B 2110 konkretisiert die Vertragspraxis.","ch":"Das Obligationenrecht bildet die gesetzliche Grundlage, die SIA 118 ergänzt eigene Garantiefristen und eine strenge Rügeobliegenheit."}'::jsonb,670),
('pbl3frist','p',3,'pbl2gewaehr','Regelfristen im Vergleich','Alle drei Länder kennen mehrjährige Fristen für Baumängel, doch die Systematik dahinter unterscheidet sich: mal eine einzige Regelfrist, mal getrennte Fristen für Sachmängel und Schadenersatz, mal unterschiedliche Fristen für bewegliche und fest verbundene Teile. Die konkrete Frist eines Projekts lässt sich deshalb nur im jeweiligen Vertrag und Rechtssystem verlässlich bestimmen, nie pauschal.',NULL,NULL,'{}'::text[],'[{"t":"BGB, Bauvertragsrecht (§§ 650a ff.)","stand":"zuletzt geändert 23.07.2026","u":"https://www.gesetze-im-internet.de/bgb/","geprueft":"2026-08-19"},{"t":"VOB/B (DIN 1961)","stand":"Ausgabe 2016, Bekanntmachung 07.01.2016, ber. 01.04.2016","u":"https://www.verwaltungsvorschriften-im-internet.de/bsvwvbund_07012016_BI78106361.htm","geprueft":"2026-08-19"},{"t":"ÖNORM B 2110 Allgemeine Vertragsbestimmungen","stand":"2023-05-01","u":"https://shop.austrian-standards.at/action/de/public/details/728205/OENORM_B_2110_2023_05_01","geprueft":"2026-08-19"},{"t":"Obligationenrecht (SR 220), Werkvertragsrecht","stand":"SR 220; Teilrevision Baumängel 2025","u":"https://www.fedlex.admin.ch/eli/cc/27/317_321_377/de","geprueft":"2026-08-19"},{"t":"SIA 118 Allgemeine Bedingungen für Bauarbeiten","stand":"Ausgabe 2013","u":"https://shop.sia.ch/normenwerk/ingenieur/118_2013_d/D/Product","geprueft":"2026-08-19"}]'::jsonb,'{"de":"Das BGB kennt eine Regelfrist für Bauwerke, die VOB/B erlaubt davon abweichende, meist kürzere vertragliche Fristen.","at":"Das österreichische Gewährleistungsrecht und das Schadenersatzrecht laufen mit eigener Fristensystematik nebeneinander, die ÖNORM B 2110 konkretisiert die vertragliche Anwendung.","ch":"Das Obligationenrecht und die SIA 118 kennen eigene, vom deutschen und österreichischen System abweichende Garantiefristen."}'::jsonb,671),
('pbl3ruege','p',3,'pbl2gewaehr','Rügeobliegenheit und Anzeigefristen','Wer einen Mangel entdeckt, muss ihn anzeigen, und zwar in manchen Rechtssystemen sehr rasch, sonst verliert er seine Ansprüche unabhängig davon, wie gravierend der Mangel ist. Diese Rügeobliegenheit trifft besonders im gewerblichen Verkehr hart und wird in der Praxis regelmäßig unterschätzt.',NULL,NULL,'{}'::text[],'[{"t":"VOB/B (DIN 1961)","stand":"Ausgabe 2016, Bekanntmachung 07.01.2016, ber. 01.04.2016","u":"https://www.verwaltungsvorschriften-im-internet.de/bsvwvbund_07012016_BI78106361.htm","geprueft":"2026-08-19"},{"t":"ÖNORM B 2110 Allgemeine Vertragsbestimmungen","stand":"2023-05-01","u":"https://shop.austrian-standards.at/action/de/public/details/728205/OENORM_B_2110_2023_05_01","geprueft":"2026-08-19"},{"t":"Obligationenrecht (SR 220), Werkvertragsrecht","stand":"SR 220; Teilrevision Baumängel 2025","u":"https://www.fedlex.admin.ch/eli/cc/27/317_321_377/de","geprueft":"2026-08-19"},{"t":"SIA 118 Allgemeine Bedingungen für Bauarbeiten","stand":"Ausgabe 2013","u":"https://shop.sia.ch/normenwerk/ingenieur/118_2013_d/D/Product","geprueft":"2026-08-19"}]'::jsonb,'{"de":"Im Verbraucherbau ist die Rügeobliegenheit milder ausgestaltet als im gewerblichen Bereich, wo die VOB/B strengere Anzeigepflichten kennt.","at":"Die ÖNORM B 2110 verlangt eine Anzeige von Mängeln innerhalb angemessener Frist nach Entdeckung.","ch":"Das Obligationenrecht und die SIA 118 verlangen eine unverzügliche Mängelrüge, verspätete Rügen lassen Ansprüche regelmäßig entfallen."}'::jsonb,672),
('pbl3verjaehr','p',3,'pbl2gewaehr','Verjährungsbeginn und Hemmung','Die Uhr der Gewährleistungsfrist beginnt regelmäßig mit der Abnahme zu laufen, kann aber durch eine Mängelrüge oder eine laufende Nachbesserung gehemmt werden, sodass sich die Frist entsprechend verlängert. Wer das nicht dokumentiert, verliert im Streitfall den Nachweis, dass die Frist tatsächlich gehemmt war.',NULL,NULL,'{}'::text[],'[{"t":"BGB, Bauvertragsrecht (§§ 650a ff.)","stand":"zuletzt geändert 23.07.2026","u":"https://www.gesetze-im-internet.de/bgb/","geprueft":"2026-08-19"},{"t":"VOB/B (DIN 1961)","stand":"Ausgabe 2016, Bekanntmachung 07.01.2016, ber. 01.04.2016","u":"https://www.verwaltungsvorschriften-im-internet.de/bsvwvbund_07012016_BI78106361.htm","geprueft":"2026-08-19"},{"t":"ÖNORM B 2110 Allgemeine Vertragsbestimmungen","stand":"2023-05-01","u":"https://shop.austrian-standards.at/action/de/public/details/728205/OENORM_B_2110_2023_05_01","geprueft":"2026-08-19"},{"t":"SIA 118 Allgemeine Bedingungen für Bauarbeiten","stand":"Ausgabe 2013","u":"https://shop.sia.ch/normenwerk/ingenieur/118_2013_d/D/Product","geprueft":"2026-08-19"}]'::jsonb,'{"de":"Nach BGB und VOB/B beginnt die Verjährung mit Abnahme, eine Nacherfüllung kann die Verjährung neu in Gang setzen oder hemmen.","at":"Die Gewährleistungsfrist beginnt mit der Übernahme nach ÖNORM B 2110, Verbesserungsversuche können den Fristlauf beeinflussen.","ch":"Nach SIA 118 beginnt die Garantiefrist mit der Abnahme, eine Nachbesserung kann für den nachgebesserten Teil eine neue Frist auslösen."}'::jsonb,673),
('pbl3sicherh','p',3,'pbl2gewaehr','Gewährleistungssicherheit und Einbehalt','Damit Mängel, die erst nach Jahren sichtbar werden, nicht am fehlenden Geld scheitern, wird oft ein Teil der Vergütung einbehalten oder durch eine Bürgschaft ersetzt, die über die gesamte Gewährleistungsfrist läuft. Für den Auftragnehmer bindet das Kapital, für den Auftraggeber ist es die wichtigste Sicherheit nach der Abnahme.',NULL,NULL,'{}'::text[],'[{"t":"VOB/B (DIN 1961)","stand":"Ausgabe 2016, Bekanntmachung 07.01.2016, ber. 01.04.2016","u":"https://www.verwaltungsvorschriften-im-internet.de/bsvwvbund_07012016_BI78106361.htm","geprueft":"2026-08-19"},{"t":"ÖNORM B 2110 Allgemeine Vertragsbestimmungen","stand":"2023-05-01","u":"https://shop.austrian-standards.at/action/de/public/details/728205/OENORM_B_2110_2023_05_01","geprueft":"2026-08-19"},{"t":"SIA 118 Allgemeine Bedingungen für Bauarbeiten","stand":"Ausgabe 2013","u":"https://shop.sia.ch/normenwerk/ingenieur/118_2013_d/D/Product","geprueft":"2026-08-19"}]'::jsonb,'{"de":"Üblich ist eine Gewährleistungsbürgschaft, die den sonst fälligen Sicherheitseinbehalt nach VOB/B ablöst.","at":"Nach ÖNORM B 2110 wird häufig ein Haftrücklass vereinbart, der durch eine Bankgarantie ersetzt werden kann.","ch":"Die SIA 118 sieht einen Garantierückbehalt vor, der ebenfalls gegen eine Garantie ausgetauscht werden kann."}'::jsonb,674),
('pbl2maengel','p',2,'pbl1','Mängelmanagement','Ein Mangel wird erst durch den Umgang mit ihm zum Problem oder zur Routine: sauber rügen, angemessene Frist zur Nachbesserung setzen, erst danach eskalieren. Die Reihenfolge der Rechte ist in allen drei Ländern ähnlich gestuft, aber nicht identisch, und wer sie überspringt, riskiert eigene Ansprüche zu verlieren.',NULL,NULL,'{}'::text[],'[{"t":"VOB/B (DIN 1961)","stand":"Ausgabe 2016, Bekanntmachung 07.01.2016, ber. 01.04.2016","u":"https://www.verwaltungsvorschriften-im-internet.de/bsvwvbund_07012016_BI78106361.htm","geprueft":"2026-08-19"},{"t":"BGB, Bauvertragsrecht (§§ 650a ff.)","stand":"zuletzt geändert 23.07.2026","u":"https://www.gesetze-im-internet.de/bgb/","geprueft":"2026-08-19"},{"t":"ÖNORM B 2110 Allgemeine Vertragsbestimmungen","stand":"2023-05-01","u":"https://shop.austrian-standards.at/action/de/public/details/728205/OENORM_B_2110_2023_05_01","geprueft":"2026-08-19"},{"t":"SIA 118 Allgemeine Bedingungen für Bauarbeiten","stand":"Ausgabe 2013","u":"https://shop.sia.ch/normenwerk/ingenieur/118_2013_d/D/Product","geprueft":"2026-08-19"}]'::jsonb,'{"de":"Die VOB/B und das BGB sehen den Vorrang der Nacherfüllung vor Minderung oder Selbstvornahme vor, jeweils nach angemessener Fristsetzung.","at":"Die ÖNORM B 2110 räumt dem Auftragnehmer ein Recht zur Verbesserung ein, bevor der Auftraggeber zur Preisminderung greifen kann.","ch":"Die SIA 118 stellt das Nachbesserungsrecht des Unternehmers ebenfalls vor andere Mängelrechte des Bauherrn."}'::jsonb,675);
insert into public.nodes (id,perspective,level,parent_id,title,t1,t2,t3,links,sources,dach,ord) values
('pbl3ruegeform','p',3,'pbl2maengel','Mängelrüge: Form, Frist, Beweissicherung','Eine wirksame Mängelrüge beschreibt den Mangel konkret, nennt eine angemessene Frist zur Beseitigung und wird so dokumentiert, dass sich Zugang und Zeitpunkt später beweisen lassen. Fotos, Datum und ein nachweisbarer Versand sind dabei wichtiger als die juristische Eleganz der Formulierung.',NULL,NULL,'{}'::text[],'[{"t":"ÖNORM B 2110 Allgemeine Vertragsbestimmungen","stand":"2023-05-01","u":"https://shop.austrian-standards.at/action/de/public/details/728205/OENORM_B_2110_2023_05_01","geprueft":"2026-08-19"},{"t":"SIA 118 Allgemeine Bedingungen für Bauarbeiten","stand":"Ausgabe 2013","u":"https://shop.sia.ch/normenwerk/ingenieur/118_2013_d/D/Product","geprueft":"2026-08-19"}]'::jsonb,'{"de":"Eine gesetzliche Formvorschrift für die Mängelrüge besteht nicht, aus Beweisgründen empfiehlt sich Schriftform mit nachweisbarem Zugang.","at":"Die ÖNORM B 2110 verlangt eine Anzeige innerhalb angemessener Frist, die Praxis empfiehlt auch hier Schriftform.","ch":"Nach SIA 118 muss die Rüge unverzüglich und in nachvollziehbarer Form erfolgen, sonst drohen Ansprüche zu verfallen."}'::jsonb,676),
('pbl3nacherf','p',3,'pbl2maengel','Nacherfüllung, Selbstvornahme, Minderung','Der Auftraggeber muss dem Auftragnehmer zunächst Gelegenheit zur Nachbesserung geben, erst wenn diese ausbleibt oder scheitert, kommen Selbstvornahme auf Kosten des Auftragnehmers oder eine Minderung der Vergütung infrage. Diese Stufenfolge zu respektieren ist Voraussetzung dafür, dass die eigenen Ansprüche später Bestand haben.',NULL,NULL,'{}'::text[],'[{"t":"VOB/B (DIN 1961)","stand":"Ausgabe 2016, Bekanntmachung 07.01.2016, ber. 01.04.2016","u":"https://www.verwaltungsvorschriften-im-internet.de/bsvwvbund_07012016_BI78106361.htm","geprueft":"2026-08-19"},{"t":"BGB, Bauvertragsrecht (§§ 650a ff.)","stand":"zuletzt geändert 23.07.2026","u":"https://www.gesetze-im-internet.de/bgb/","geprueft":"2026-08-19"},{"t":"ÖNORM B 2110 Allgemeine Vertragsbestimmungen","stand":"2023-05-01","u":"https://shop.austrian-standards.at/action/de/public/details/728205/OENORM_B_2110_2023_05_01","geprueft":"2026-08-19"},{"t":"SIA 118 Allgemeine Bedingungen für Bauarbeiten","stand":"Ausgabe 2013","u":"https://shop.sia.ch/normenwerk/ingenieur/118_2013_d/D/Product","geprueft":"2026-08-19"}]'::jsonb,'{"de":"VOB/B und BGB räumen dem Auftragnehmer ein Recht zur Nacherfüllung ein, erst danach sind Selbstvornahme oder Minderung möglich.","at":"Die ÖNORM B 2110 sieht ebenfalls vorrangig die Verbesserung durch den Auftragnehmer vor, bevor weitergehende Rechte greifen.","ch":"Die SIA 118 stellt die Nachbesserung durch den Unternehmer voran, erst danach kommen Ersatzvornahme oder Minderung in Betracht."}'::jsonb,677),
('pbl3vorrecht','p',3,'pbl2maengel','Nachbesserungsrecht des Unternehmers','In allen drei Ländern hat der Auftragnehmer das Recht, einen Mangel zunächst selbst zu beheben, bevor der Auftraggeber zu anderen Mitteln greift. Dieses Recht schützt vor vorschnellem Fremdvergabe Ärger, setzt aber eine klare Fristsetzung voraus, sonst lässt sich später schwer nachweisen, dass die Chance zur Nachbesserung überhaupt bestand.',NULL,NULL,'{}'::text[],'[{"t":"VOB/B (DIN 1961)","stand":"Ausgabe 2016, Bekanntmachung 07.01.2016, ber. 01.04.2016","u":"https://www.verwaltungsvorschriften-im-internet.de/bsvwvbund_07012016_BI78106361.htm","geprueft":"2026-08-19"},{"t":"BGB, Bauvertragsrecht (§§ 650a ff.)","stand":"zuletzt geändert 23.07.2026","u":"https://www.gesetze-im-internet.de/bgb/","geprueft":"2026-08-19"},{"t":"ÖNORM B 2110 Allgemeine Vertragsbestimmungen","stand":"2023-05-01","u":"https://shop.austrian-standards.at/action/de/public/details/728205/OENORM_B_2110_2023_05_01","geprueft":"2026-08-19"},{"t":"SIA 118 Allgemeine Bedingungen für Bauarbeiten","stand":"Ausgabe 2013","u":"https://shop.sia.ch/normenwerk/ingenieur/118_2013_d/D/Product","geprueft":"2026-08-19"}]'::jsonb,'{"de":"Nach VOB/B und BGB steht dem Auftragnehmer grundsätzlich ein Recht zur zweiten Andienung zu, gebunden an eine angemessene Frist.","at":"Die ÖNORM B 2110 räumt das Verbesserungsrecht besonders deutlich als vorrangiges Recht des Auftragnehmers ein.","ch":"Die SIA 118 gewährt dem Unternehmer ausdrücklich den Vorrang der Nachbesserung vor anderen Mängelrechten des Bauherrn."}'::jsonb,678),
('pbl3fluchtweg','p',3,'pbl2maengel','Mängel an sicherheitsrelevanten Bauteilen','Ein Mangel an einer Brandschutztür oder an einem Fluchtweg ist kein gewöhnlicher Baumangel, sondern ein Sicherheitsrisiko, das die Nutzung des Gebäudes infrage stellen kann. Hier gilt die übliche Frist zur Nachbesserung nicht uneingeschränkt: Bauaufsicht oder Nutzer können schnelleres Handeln verlangen, unabhängig vom sonst üblichen Ablauf des Mängelmanagements.',NULL,NULL,ARRAY['kt2not','kt3nutz','k4t30z']::text[],'[{"t":"VOB/B (DIN 1961)","stand":"Ausgabe 2016, Bekanntmachung 07.01.2016, ber. 01.04.2016","u":"https://www.verwaltungsvorschriften-im-internet.de/bsvwvbund_07012016_BI78106361.htm","geprueft":"2026-08-19"},{"t":"ÖNORM B 2110 Allgemeine Vertragsbestimmungen","stand":"2023-05-01","u":"https://shop.austrian-standards.at/action/de/public/details/728205/OENORM_B_2110_2023_05_01","geprueft":"2026-08-19"},{"t":"SIA 118 Allgemeine Bedingungen für Bauarbeiten","stand":"Ausgabe 2013","u":"https://shop.sia.ch/normenwerk/ingenieur/118_2013_d/D/Product","geprueft":"2026-08-19"}]'::jsonb,'{"de":"Sicherheitsrelevante Mängel können eine Nutzungsuntersagung durch die Bauaufsicht nach Landesbauordnung auslösen, unabhängig vom zivilrechtlichen Mängelverfahren nach VOB/B.","at":"Bei Gefährdung kann die Übernahme nach ÖNORM B 2110 verweigert oder eingeschränkt werden, zusätzlich greifen bauordnungsrechtliche Vorgaben der Länder.","ch":"Sicherheitsmängel unterliegen einer Meldepflicht nach kantonalem Baurecht, unabhängig von der vertraglichen Mängelabwicklung nach SIA 118."}'::jsonb,679),
('pna1','p',1,NULL,'Nachhaltigkeit und Förderung','Nachhaltigkeit ist längst kein Zusatzwunsch mehr, sondern eine eigene Planungsebene neben Kosten, Terminen und Qualität: Zertifizierungssysteme bewerten Gebäude, das Energierecht setzt verbindliche Mindeststandards, Förderprogramme steuern über Geld, was ökologisch gewünscht ist. Wer diese drei Ebenen nicht früh zusammendenkt, verschenkt entweder Fördergeld oder verbaut sich spätere Zertifizierungsoptionen. Dieser Ast schließt mit dem wachsenden Feld der Zirkularität, dem Bauen mit dem, was schon da ist.',NULL,NULL,ARRAY['pav1']::text[],'[]'::jsonb,NULL,680),
('pna2zert','p',2,'pna1','Zertifizierungssysteme','Gebäudezertifikate bewerten ein Bauwerk nach einem festen Kriterienraster, meist entlang Ökologie, Ökonomie, sozialer und funktionaler Qualität sowie Planungs und Bauprozess. Sie sind kein Selbstzweck, sondern ein Kommunikationsmittel, das Nachhaltigkeit für Investoren, Nutzer und Fördergeber vergleichbar macht. Wie viel ein Label über die tatsächliche Qualität eines Gebäudes aussagt, hängt stark davon ab, wie ernst die zugrunde liegenden Kriterien genommen wurden.',NULL,NULL,'{}'::text[],'[{"t":"DGNB Zertifizierungssystem (weiterführend)","u":"https://www.dgnb.de/en/certification/buildings/new-construction","geprueft":"2026-08-19"},{"t":"QNG Qualitätssiegel Nachhaltiges Gebäude (BMWSB, weiterführend)","u":"https://www.qng.info/","geprueft":"2026-08-19"},{"t":"klimaaktiv Gebäudestandard","stand":"Kriterienkatalog 2025","u":"https://www.klimaaktiv.at/fachpersonen/energie-bau/gebaeudedeklaration/kriterienkatalog-2025","geprueft":"2026-08-19"},{"t":"Minergie (weiterführend)","u":"https://www.minergie.ch/de/standards/neubau/","geprueft":"2026-08-19"},{"t":"SNBS Hochbau (NNBS, weiterführend)","stand":"Version 2023.1","u":"https://nnbs.ch/standards-und-labels/","geprueft":"2026-08-19"}]'::jsonb,'{"de":"Verbreitet sind die Zertifizierung der DGNB und das staatliche Qualitätssiegel Nachhaltiges Gebäude QNG, das häufig an Förderprogramme gekoppelt ist.","at":"Klimaaktiv als staatliche Initiative und die Zertifizierung der ÖGNI sind die etablierten Systeme im österreichischen Markt.","ch":"Minergie ist das bekannteste Schweizer Label, der Standard Nachhaltiges Bauen Schweiz SNBS deckt eine breitere Nachhaltigkeitsdefinition ab."}'::jsonb,681),
('pna3kriterien','p',3,'pna2zert','Kriteriengruppen und Bewertungslogik','Die meisten Systeme wiegen ökologische, ökonomische und soziokulturelle Qualität sowie Prozess und technische Qualität gegeneinander ab und aggregieren das Ergebnis zu einer Gesamtnote oder einem Zertifizierungslevel. Wer früh weiß, welche Kriteriengruppe im Projekt am schwersten wiegt, kann Entwurfsentscheidungen gezielt darauf ausrichten, statt am Ende nachzubessern.',NULL,NULL,'{}'::text[],'[{"t":"DGNB Zertifizierungssystem (weiterführend)","u":"https://www.dgnb.de/en/certification/buildings/new-construction","geprueft":"2026-08-19"},{"t":"QNG Qualitätssiegel Nachhaltiges Gebäude (BMWSB, weiterführend)","u":"https://www.qng.info/","geprueft":"2026-08-19"},{"t":"klimaaktiv Gebäudestandard","stand":"Kriterienkatalog 2025","u":"https://www.klimaaktiv.at/fachpersonen/energie-bau/gebaeudedeklaration/kriterienkatalog-2025","geprueft":"2026-08-19"},{"t":"Minergie (weiterführend)","u":"https://www.minergie.ch/de/standards/neubau/","geprueft":"2026-08-19"},{"t":"SNBS Hochbau (NNBS, weiterführend)","stand":"Version 2023.1","u":"https://nnbs.ch/standards-und-labels/","geprueft":"2026-08-19"}]'::jsonb,'{"de":"Die DGNB gewichtet mehrere Themenfelder etwa gleich stark, das QNG konzentriert sich stärker auf ökologische und energetische Mindestkriterien.","at":"Klimaaktiv legt den Schwerpunkt auf Energie und Ökologie, die ÖGNI orientiert sich stärker an einer breiten Nachhaltigkeitsbetrachtung.","ch":"Minergie fokussiert auf Energieeffizienz, der SNBS bewertet zusätzlich Gesellschaft und Wirtschaft gleichrangig."}'::jsonb,682),
('pna3koppel','p',3,'pna2zert','Kopplung an Förderung','In allen drei Ländern hängt ein Teil der Fördermittel an einem Nachweis über ein Zertifikat oder einen vergleichbaren Standard, sodass die Entscheidung für oder gegen eine Zertifizierung auch eine Entscheidung über Fördergeld ist. Wird das erst spät im Projekt bedacht, ist der günstigste Zeitpunkt für kostenwirksame Weichenstellungen meist schon verstrichen.',NULL,NULL,ARRAY['pna2foerder']::text[],'[{"t":"QNG Qualitätssiegel Nachhaltiges Gebäude (BMWSB, weiterführend)","u":"https://www.qng.info/","geprueft":"2026-08-19"},{"t":"klimaaktiv Gebäudestandard","stand":"Kriterienkatalog 2025","u":"https://www.klimaaktiv.at/fachpersonen/energie-bau/gebaeudedeklaration/kriterienkatalog-2025","geprueft":"2026-08-19"},{"t":"Minergie (weiterführend)","u":"https://www.minergie.ch/de/standards/neubau/","geprueft":"2026-08-19"},{"t":"SNBS Hochbau (NNBS, weiterführend)","stand":"Version 2023.1","u":"https://nnbs.ch/standards-und-labels/","geprueft":"2026-08-19"}]'::jsonb,'{"de":"Das Qualitätssiegel Nachhaltiges Gebäude QNG ist Voraussetzung für bestimmte Förderkredite der Bundesförderung effiziente Gebäude.","at":"Landesförderungen setzen teils eine Zertifizierung nach klimaaktiv oder vergleichbaren Standards voraus.","ch":"Kantonale Förderprogramme im Rahmen des Gebäudeprogramms verlangen teils den Nachweis nach Minergie oder SNBS."}'::jsonb,683),
('pna3aufwand','p',3,'pna2zert','Zertifizierungsaufwand im Projektablauf','Ein Zertifikat verlangt Nachweise, Berechnungen und Dokumentation über den gesamten Planungs und Bauprozess, nicht nur am Ende. Wer die Zertifizierungsentscheidung erst nach der Entwurfsplanung trifft, muss oft Nachweise nachträglich beschaffen, die viel günstiger gleich mitgelaufen wären. Der Dokumentationsaufwand überschneidet sich stark mit der ohnehin nötigen Bauüberwachung.',NULL,NULL,ARRAY['pbl2bau']::text[],'[{"t":"QNG Qualitätssiegel Nachhaltiges Gebäude (BMWSB, weiterführend)","u":"https://www.qng.info/","geprueft":"2026-08-19"},{"t":"DGNB Zertifizierungssystem (weiterführend)","u":"https://www.dgnb.de/en/certification/buildings/new-construction","geprueft":"2026-08-19"},{"t":"klimaaktiv Gebäudestandard","stand":"Kriterienkatalog 2025","u":"https://www.klimaaktiv.at/fachpersonen/energie-bau/gebaeudedeklaration/kriterienkatalog-2025","geprueft":"2026-08-19"},{"t":"Minergie (weiterführend)","u":"https://www.minergie.ch/de/standards/neubau/","geprueft":"2026-08-19"},{"t":"SNBS Hochbau (NNBS, weiterführend)","stand":"Version 2023.1","u":"https://nnbs.ch/standards-und-labels/","geprueft":"2026-08-19"}]'::jsonb,'{"de":"Für das QNG und die DGNB Zertifizierung sind Nachweise über weite Teile der Leistungsphasen zu führen, nicht nur zur Abnahme.","at":"Klimaaktiv und ÖGNI verlangen Nachweise, die parallel zur örtlichen Bauaufsicht dokumentiert werden müssen.","ch":"Minergie und SNBS Nachweise entstehen begleitend zur Bauleitung nach SIA Ordnung, nicht als nachträgliche Zusammenstellung."}'::jsonb,684),
('pna3systemvergl','p',3,'pna2zert','Systemvergleich: Substanz statt Label','Kein Zertifikat ist per se besser, jedes setzt eigene Schwerpunkte, und ein Label allein sagt noch nichts über die tatsächliche Aufenthaltsqualität oder den realen Energieverbrauch eines Gebäudes aus. Die Empfehlung lautet deshalb, das Zertifizierungsziel aus den echten Projektzielen abzuleiten, nicht aus dem, was gerade am prominentesten vermarktet wird.',NULL,NULL,'{}'::text[],'[{"t":"DGNB Zertifizierungssystem (weiterführend)","u":"https://www.dgnb.de/en/certification/buildings/new-construction","geprueft":"2026-08-19"},{"t":"QNG Qualitätssiegel Nachhaltiges Gebäude (BMWSB, weiterführend)","u":"https://www.qng.info/","geprueft":"2026-08-19"},{"t":"klimaaktiv Gebäudestandard","stand":"Kriterienkatalog 2025","u":"https://www.klimaaktiv.at/fachpersonen/energie-bau/gebaeudedeklaration/kriterienkatalog-2025","geprueft":"2026-08-19"},{"t":"Minergie (weiterführend)","u":"https://www.minergie.ch/de/standards/neubau/","geprueft":"2026-08-19"},{"t":"SNBS Hochbau (NNBS, weiterführend)","stand":"Version 2023.1","u":"https://nnbs.ch/standards-und-labels/","geprueft":"2026-08-19"}]'::jsonb,'{"de":"DGNB und QNG verfolgen unterschiedliche Schwerpunkte, ein pauschaler Vergleich ohne Blick auf das konkrete Projektziel führt selten weiter.","at":"Klimaaktiv und ÖGNI unterscheiden sich in Reichweite und Detailtiefe, die Wahl sollte sich am jeweiligen Förderkontext orientieren.","ch":"Minergie und SNBS beantworten unterschiedliche Fragen, Energieeffizienz allein ist nicht dasselbe wie umfassende Nachhaltigkeit."}'::jsonb,685),
('pna2energie','p',2,'pna1','Energierecht','Das Energierecht setzt Mindeststandards für die energetische Qualität von Gebäuden und greift damit unmittelbar in Entwurf und Konstruktion ein, von der Dämmstärke bis zur Anlagentechnik. Anders als eine Zertifizierung ist es keine freiwillige Kür, sondern eine bauordnungsrechtlich durchsetzbare Pflicht. Wer Energieeffizienz erst nach der Entwurfsplanung mitdenkt, verbaut sich fast immer die günstigsten Lösungen.',NULL,NULL,'{}'::text[],'[{"t":"GEG (Gebäudeenergiegesetz)","stand":"vom 08.08.2020, zuletzt geändert 23.07.2026","u":"https://www.gesetze-im-internet.de/geg/","geprueft":"2026-08-19"},{"t":"OIB-Richtlinie 6 Energieeinsparung und Wärmeschutz","stand":"Ausgabe 2023","u":"https://www.oib.or.at/kernaufgaben/oib-richtlinien1/richtlinien/oib-richtlinien-2023/","geprueft":"2026-08-19"}]'::jsonb,'{"de":"Das Gebäudeenergiegesetz GEG bündelt Anforderungen an Neubau und Bestand sowie an die Anlagentechnik in einem Regelwerk.","at":"Die OIB Richtlinie 6 setzt den fachlichen Rahmen, ihre bauordnungsrechtliche Umsetzung liegt bei den Bundesländern.","ch":"Die Mustervorschriften der Kantone im Energiebereich, kurz MuKEn, bilden die Vorlage, die jeder Kanton eigenständig umsetzt."}'::jsonb,686),
('pna3anforderung','p',3,'pna2energie','Anforderungsniveau: Neubau vs. Bestand','Neubauten müssen ein deutlich höheres energetisches Niveau erreichen als Sanierungen im Bestand, wo oft nur bei größeren Eingriffen überhaupt Anforderungen greifen. Diese Abstufung ist bewusst gewählt, weil eine Vollsanierung auf Neubauniveau technisch und wirtschaftlich nicht immer machbar ist, doch sie verleitet auch dazu, energetische Chancen bei kleineren Eingriffen zu übersehen.',NULL,NULL,'{}'::text[],'[{"t":"GEG (Gebäudeenergiegesetz)","stand":"vom 08.08.2020, zuletzt geändert 23.07.2026","u":"https://www.gesetze-im-internet.de/geg/","geprueft":"2026-08-19"},{"t":"OIB-Richtlinie 6 Energieeinsparung und Wärmeschutz","stand":"Ausgabe 2023","u":"https://www.oib.or.at/kernaufgaben/oib-richtlinien1/richtlinien/oib-richtlinien-2023/","geprueft":"2026-08-19"}]'::jsonb,'{"de":"Das GEG unterscheidet Anforderungen an Neubauten von Nachrüst und Ersatzpflichten im Bestand, die meist an bestimmte Bauteile anknüpfen.","at":"Die OIB Richtlinie 6 unterscheidet ebenfalls Neubau und Bestand, die konkrete Anwendung obliegt den Landesbauordnungen.","ch":"Die MuKEn Systematik der Kantone kennt eigene, meist mildere Anforderungen für Sanierungen gegenüber Neubauten."}'::jsonb,687),
('pna3nachweis','p',3,'pna2energie','Energieausweis und Nachweisverfahren','Der Energieausweis dokumentiert die energetische Qualität eines Gebäudes und wird bei Verkauf oder Vermietung Pflicht, oft lange bevor die eigentliche Sanierung geplant ist. Für Planende ist er weniger ein Formular als ein Werkzeug, um frühzeitig Schwachstellen der Gebäudehülle sichtbar zu machen.',NULL,NULL,'{}'::text[],'[{"t":"GEG (Gebäudeenergiegesetz)","stand":"vom 08.08.2020, zuletzt geändert 23.07.2026","u":"https://www.gesetze-im-internet.de/geg/","geprueft":"2026-08-19"},{"t":"OIB-Richtlinie 6 Energieeinsparung und Wärmeschutz","stand":"Ausgabe 2023","u":"https://www.oib.or.at/kernaufgaben/oib-richtlinien1/richtlinien/oib-richtlinien-2023/","geprueft":"2026-08-19"}]'::jsonb,'{"de":"Das GEG unterscheidet Bedarfs und Verbrauchsausweis als zwei methodisch unterschiedliche Nachweisformen.","at":"Der Energieausweis nach OIB Richtlinie 6 ist bundesweit einheitlich methodisch geregelt, seine Ausstellung ist Ländersache.","ch":"Der Gebäudeenergieausweis der Kantone, kurz GEAK, ist das schweizerische Pendant mit eigener Bewertungsskala."}'::jsonb,688),
('pna3anlagentech','p',3,'pna2energie','Pflichten zu erneuerbaren Energien','Beim Neubau und zunehmend auch beim Heizungstausch im Bestand ist ein Mindestanteil erneuerbarer Energie an der Wärmeversorgung vorgeschrieben, mit unterschiedlichen Wegen, wie dieser Anteil nachgewiesen werden darf. Für die Planung heißt das, Anlagentechnik nicht erst am Ende, sondern parallel zur Gebäudehülle zu entwickeln.',NULL,NULL,'{}'::text[],'[{"t":"GEG (Gebäudeenergiegesetz)","stand":"vom 08.08.2020, zuletzt geändert 23.07.2026","u":"https://www.gesetze-im-internet.de/geg/","geprueft":"2026-08-19"},{"t":"OIB-Richtlinie 6 Energieeinsparung und Wärmeschutz","stand":"Ausgabe 2023","u":"https://www.oib.or.at/kernaufgaben/oib-richtlinien1/richtlinien/oib-richtlinien-2023/","geprueft":"2026-08-19"}]'::jsonb,'{"de":"Das GEG verlangt beim Heizungstausch einen Mindestanteil erneuerbarer Energien mit mehreren zulässigen Erfüllungsoptionen.","at":"Erneuerbaren Pflichten variieren je nach Bundesland und werden über die Landesbauordnungen in Verbindung mit der OIB Richtlinie 6 durchgesetzt.","ch":"Die kantonalen MuKEn Module verlangen bei Heizungsersatz häufig einen Anteil erneuerbarer Wärme, die genaue Ausgestaltung bleibt kantonal."}'::jsonb,689),
('pna3klimaschutz','p',3,'pna2energie','Schnittstelle zu Klimaschutzgesetzen','Über dem gebäudebezogenen Energierecht liegt in allen drei Ländern eine übergeordnete Klimaschutzgesetzgebung mit Sektorzielen, die das Energierecht regelmäßig verschärft. Für die Praxis heißt das, heutige Anforderungen als Zwischenstand zu verstehen, nicht als Endpunkt, und robuste, nachrüstbare Lösungen zu bevorzugen.',NULL,NULL,'{}'::text[],'[{"t":"GEG (Gebäudeenergiegesetz)","stand":"vom 08.08.2020, zuletzt geändert 23.07.2026","u":"https://www.gesetze-im-internet.de/geg/","geprueft":"2026-08-19"},{"t":"OIB-Richtlinie 6 Energieeinsparung und Wärmeschutz","stand":"Ausgabe 2023","u":"https://www.oib.or.at/kernaufgaben/oib-richtlinien1/richtlinien/oib-richtlinien-2023/","geprueft":"2026-08-19"}]'::jsonb,'{"de":"Klimaschutzgesetzgebung auf Bundesebene setzt Sektorziele, an denen sich Verschärfungen des GEG orientieren.","at":"Klimaschutzrecht wirkt über Bund und Länder auf die OIB Richtlinien und deren bauordnungsrechtliche Umsetzung zurück.","ch":"CO2 Gesetzgebung auf Bundesebene beeinflusst die Weiterentwicklung der kantonalen MuKEn Module."}'::jsonb,690);
insert into public.nodes (id,perspective,level,parent_id,title,t1,t2,t3,links,sources,dach,ord) values
('pna2foerder','p',2,'pna1','Förderlandschaft','Förderprogramme können über die Wirtschaftlichkeit eines nachhaltigen Bauvorhabens entscheiden, ändern sich aber häufig und unterscheiden sich stark zwischen Bund, Ländern und einzelnen Regionen. ArchiPedia behandelt deshalb die Systematik, nicht die tagesaktuellen Konditionen, die vor jedem Projekt neu geprüft werden müssen. Wer Förderung erst nach Baubeginn beantragt, hat sie in der Regel schon verloren.',NULL,NULL,'{}'::text[],'[{"t":"Das Gebäudeprogramm (CH, weiterführend)","u":"https://www.dasgebaeudeprogramm.ch/de/geforderte-massnahmen/","geprueft":"2026-08-19"}]'::jsonb,'{"de":"Die Bundesförderung effiziente Gebäude BEG wird über KfW und BAFA abgewickelt und bündelt Zuschüsse und Kredite.","at":"Wohnbauförderung ist Landessache, jedes Bundesland betreibt eigene Programme mit eigenen Konditionen.","ch":"Das Gebäudeprogramm von Bund und Kantonen bildet das Rückgrat, ergänzt um eigenständige kantonale Zusatzprogramme."}'::jsonb,691),
('pna3foerderarten','p',3,'pna2foerder','Förderarten: Zuschuss, Kredit, Steuervorteil','Förderung kommt in unterschiedlicher Form: als direkter Zuschuss, als zinsvergünstigter Kredit oder als steuerliche Entlastung, mit jeweils eigener Wirkung auf Liquidität und Wirtschaftlichkeitsrechnung. Für die Beratung ist wichtig, diese Formen nicht zu vermischen, wenn sie unterschiedliche Zeitpunkte im Projekt betreffen.',NULL,NULL,'{}'::text[],'[{"t":"Das Gebäudeprogramm (CH, weiterführend)","u":"https://www.dasgebaeudeprogramm.ch/de/geforderte-massnahmen/","geprueft":"2026-08-19"}]'::jsonb,'{"de":"Die BEG kombiniert Zuschüsse und zinsgünstige Kredite über KfW und BAFA, steuerliche Förderung ergänzt dies für Sanierungen im Bestand.","at":"Die Wohnbauförderung der Länder setzt überwiegend auf Zuschüsse und geförderte Darlehen mit unterschiedlicher Ausgestaltung.","ch":"Das Gebäudeprogramm arbeitet primär mit Förderbeiträgen, steuerliche Abzüge ergänzen dies auf Bundes und Kantonsebene."}'::jsonb,692),
('pna3foerderweg','p',3,'pna2foerder','Antragsweg und Zeitpunkt im Projekt','Der klassische Fehler ist, zuerst zu bauen und dann Förderung zu beantragen, dabei setzen fast alle Programme voraus, dass der Antrag vor Maßnahmenbeginn gestellt wird. Diese Reihenfolge gehört so früh wie möglich in die Projektsteuerung, am besten schon in der Kostenplanung berücksichtigt.',NULL,NULL,'{}'::text[],'[{"t":"Das Gebäudeprogramm (CH, weiterführend)","u":"https://www.dasgebaeudeprogramm.ch/de/geforderte-massnahmen/","geprueft":"2026-08-19"}]'::jsonb,'{"de":"Die Antragstellung bei KfW oder BAFA muss vor Beginn der geförderten Maßnahme erfolgen, ein rückwirkender Antrag ist ausgeschlossen.","at":"Die Länderprogramme verlangen überwiegend eine Antragstellung vor Baubeginn, die genauen Fristen unterscheiden sich je Bundesland.","ch":"Kantonale Programme im Rahmen des Gebäudeprogramms setzen eine Anmeldung vor Ausführungsbeginn voraus."}'::jsonb,693),
('pna3kombi','p',3,'pna2foerder','Kombination und Kumulierung von Förderungen','Bundes, Landes und kommunale Programme lassen sich teils kombinieren, teils schließen sie sich gegenseitig aus oder begrenzen die Gesamtförderhöhe. Ohne einen Überblick über diese Kumulierungsregeln wird leicht Geld verschenkt oder ein Antrag im Nachhinein zurückgefordert.',NULL,NULL,'{}'::text[],'[{"t":"Das Gebäudeprogramm (CH, weiterführend)","u":"https://www.dasgebaeudeprogramm.ch/de/geforderte-massnahmen/","geprueft":"2026-08-19"}]'::jsonb,'{"de":"Die BEG lässt sich unter Bedingungen mit Landes und Kommunalprogrammen kombinieren, Doppelförderung derselben Maßnahme ist meist ausgeschlossen.","at":"Bundes und Landesförderung lassen sich teils kumulieren, die einzelnen Wohnbauförderungen der Länder regeln dies unterschiedlich.","ch":"Bundesbeiträge aus dem Gebäudeprogramm lassen sich mit kantonalen Zusatzprogrammen verbinden, die Regeln dazu variieren kantonal."}'::jsonb,694),
('pna3risiko','p',3,'pna2foerder','Förderrisiko und Rückforderung','Wird eine geförderte Anforderung im Nachhinein nicht eingehalten, etwa weil ein Zertifikat scheitert oder ein Wert nicht erreicht wird, drohen Rückforderungen, die ein knapp kalkuliertes Projekt in Schieflage bringen können. Sauber dokumentierte Zielwerte während der gesamten Bauzeit sind deshalb keine Bürokratie, sondern Risikovorsorge.',NULL,NULL,ARRAY['pna2zert']::text[],'[{"t":"Das Gebäudeprogramm (CH, weiterführend)","u":"https://www.dasgebaeudeprogramm.ch/de/geforderte-massnahmen/","geprueft":"2026-08-19"}]'::jsonb,'{"de":"Werden Fördervoraussetzungen der BEG nachträglich nicht erfüllt, kann die KfW gewährte Mittel zurückfordern.","at":"Landesförderstellen können bei Nichteinhaltung zugesicherter Standards Fördermittel zurückverlangen.","ch":"Das Gebäudeprogramm kann Beiträge kürzen oder zurückfordern, wenn zugesicherte Werte nicht nachgewiesen werden."}'::jsonb,695),
('pna2zirk','p',2,'pna1','Zirkularität, Rückbau, Wiederverwendung','Zirkuläres Bauen denkt ein Gebäude vom Ende her: trennbar konstruiert, dokumentiert, sodass Bauteile später zerlegt statt zerkleinert werden können. Das ist noch kein Mainstream, aber der Bereich, in dem sich künftige Anforderungen am schnellsten verschärfen dürften, weil Ressourcenschonung neben Energieeffizienz zum zweiten großen Nachhaltigkeitsthema wird.',NULL,NULL,'{}'::text[],'[{"t":"DGNB Zertifizierungssystem (weiterführend)","u":"https://www.dgnb.de/en/certification/buildings/new-construction","geprueft":"2026-08-19"},{"t":"QNG Qualitätssiegel Nachhaltiges Gebäude (BMWSB, weiterführend)","u":"https://www.qng.info/","geprueft":"2026-08-19"},{"t":"klimaaktiv Gebäudestandard","stand":"Kriterienkatalog 2025","u":"https://www.klimaaktiv.at/fachpersonen/energie-bau/gebaeudedeklaration/kriterienkatalog-2025","geprueft":"2026-08-19"}]'::jsonb,'{"de":"Das Kreislaufwirtschaftsgesetz setzt den abfallrechtlichen Rahmen, freiwillige Systeme wie DGNB und QNG honorieren Rückbaubarkeit zusätzlich.","at":"Das Abfallwirtschaftsgesetz bildet den rechtlichen Rahmen, Zertifizierungssysteme wie klimaaktiv setzen zusätzliche freiwillige Anreize.","ch":"SIA Empfehlungen zu Rückbau und Entsorgung ergänzen das kantonale Abfallrecht als anerkannte Regel der Technik."}'::jsonb,696),
('pna3design','p',3,'pna2zirk','Trennbarkeit als Entwurfsprinzip','Design for Disassembly bedeutet, Verbindungen von vornherein lösbar zu planen, geschraubt statt geklebt, geschichtet statt verbundstoffvermischt, damit ein Gebäude am Ende seines Lebens in sortenreine Bestandteile zerlegt werden kann. Diese Entscheidung fällt im Entwurf, nicht erst beim Rückbau, und lässt sich später kaum nachrüsten.',NULL,NULL,'{}'::text[],'[]'::jsonb,'{"de":"Eine eigenständige gesetzliche Pflicht zur trennbaren Bauweise besteht nicht, das Kreislaufwirtschaftsgesetz setzt aber Anreize über die Abfallhierarchie.","at":"Vergleichbare Anreize entstehen über das Abfallwirtschaftsgesetz und über freiwillige Zertifizierungskriterien.","ch":"SIA Empfehlungen zur Rückbaubarkeit gelten als anerkannte Regel der Technik, eine gesetzliche Pflicht besteht nicht durchgängig."}'::jsonb,697),
('pna3passport','p',3,'pna2zirk','Materialpass und Rückbaudokumentation','Ein Materialpass listet auf, welche Materialien und Bauteile in welcher Menge und Verbindung verbaut wurden, damit ein späterer Rückbau nicht erst mühsam erkunden muss, was überhaupt vorhanden ist. Je früher diese Dokumentation beginnt, desto vollständiger und günstiger wird sie.',NULL,NULL,'{}'::text[],'[{"t":"DGNB Zertifizierungssystem (weiterführend)","u":"https://www.dgnb.de/en/certification/buildings/new-construction","geprueft":"2026-08-19"},{"t":"QNG Qualitätssiegel Nachhaltiges Gebäude (BMWSB, weiterführend)","u":"https://www.qng.info/","geprueft":"2026-08-19"},{"t":"klimaaktiv Gebäudestandard","stand":"Kriterienkatalog 2025","u":"https://www.klimaaktiv.at/fachpersonen/energie-bau/gebaeudedeklaration/kriterienkatalog-2025","geprueft":"2026-08-19"},{"t":"SNBS Hochbau (NNBS, weiterführend)","stand":"Version 2023.1","u":"https://nnbs.ch/standards-und-labels/","geprueft":"2026-08-19"}]'::jsonb,'{"de":"Materialpässe sind freiwillig, werden aber im Rahmen von DGNB und QNG Zertifizierungen zunehmend honoriert oder vorausgesetzt.","at":"Vergleichbare freiwillige Systeme entstehen im Umfeld von klimaaktiv, eine flächendeckende Pflicht besteht nicht.","ch":"Materialpässe werden im Kontext von SNBS Zertifizierungen und kantonalen Vorgaben zunehmend nachgefragt."}'::jsonb,698),
('pna3rueckbau','p',3,'pna2zirk','Rückbau statt Abriss: Verwertungsquote','Selektiver Rückbau trennt Materialien vor Ort nach Wiederverwendbarkeit und Wertstoffart, statt alles gemeinsam abzureißen und zu entsorgen. Das kostet zunächst mehr Zeit, senkt aber Entsorgungskosten und ermöglicht erst die Wiederverwendung einzelner Bauteile.',NULL,NULL,'{}'::text[],'[]'::jsonb,'{"de":"Das Kreislaufwirtschaftsgesetz verlangt eine Verwertung vor Beseitigung von Bauabfällen, sofern technisch und wirtschaftlich zumutbar.","at":"Das Abfallwirtschaftsgesetz setzt eine vergleichbare Verwertungshierarchie für Bauabfälle voraus.","ch":"SIA Normen zur Entsorgung von Bauabfällen und kantonale Vorschriften regeln die Trennung und Verwertung auf der Baustelle."}'::jsonb,699),
('pna3wiederverw','p',3,'pna2zirk','Wiederverwendung von Bauteilen','Fenster, Türen, Träger oder Fassadenelemente aus dem Rückbau lassen sich wiederverwenden, wenn Qualität, Maße und Nachweise stimmen, doch Logistik und Verfügbarkeit sind bisher der Flaschenhals, nicht der Wille. Wer wiederverwendete Bauteile einplant, sollte das früh im Entwurf offenlassen und erst mit realer Verfügbarkeit verbindlich festlegen.',NULL,NULL,'{}'::text[],'[]'::jsonb,'{"de":"Wiederverwendete Bauteile benötigen im Einzelfall einen Verwendbarkeitsnachweis, da die ursprüngliche Zulassung meist nicht automatisch fortgilt.","at":"Auch in Österreich ist für tragende oder sicherheitsrelevante wiederverwendete Bauteile ein eigener Nachweis erforderlich.","ch":"Die Wiederverwendung wird in der Schweiz zunehmend durch SIA Empfehlungen begleitet, ein Nachweis der Eigenschaften bleibt Voraussetzung."}'::jsonb,700);